const _bootLimiter = { map: new Map(), MAX_PER_SEC: 30, WINDOW_MS: 1000 };
const _bootPayloadCheck = (body) => {
  if (!body) return { safe: true };
  const s = JSON.stringify(body);
  if (s.length > 10000) return { safe: false, threat: 'BOOT_PAYLOAD_TOO_LARGE' };
  if (/<script|javascript:|on\w+\s*=/i.test(s)) return { safe: false, threat: 'BOOT_XSS_PATTERN' };
  if (/(\bunion\s+select|\bdrop\s+table|--\s*$)/i.test(s)) return { safe: false, threat: 'BOOT_SQL_PATTERN' };
  return { safe: true };
};

// ── SECURITY MIDDLEWARE (Angriffs-Abwehr) ──────────────────────────────────
app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress || 'unknown';

  // AUDFIX_028: Fail-secure — wenn SelfHeal noch nicht da, Bootstrap-Limiter aktiv
  if (typeof SelfHeal !== 'undefined') {
    if (!SelfHeal.checkRateLimit(ip)) {
      return res.status(429).json({ error:'Too many requests', blocked:true });
    }
    if (['POST','PATCH','PUT'].includes(req.method)) {
      const check = SelfHeal.checkPayload(req.body);
      if (!check.safe) {
        SelfHeal.attackLog.unshift({ ts:Date.now(), ip, type:check.threat, path:req.path });
        Log.warn('SECURITY', `${check.threat} von ${ip} auf ${req.path}`);
        return res.status(400).json({ error:'Invalid request', threat:check.threat });
      }
    }
  } else {
    // Bootstrap-Phase: pragmatischer Limiter + Basic Payload-Check
    const now = Date.now();
    const entry = _bootLimiter.map.get(ip) || { count: 0, windowStart: now };
    if (now - entry.windowStart > _bootLimiter.WINDOW_MS) {
      entry.count = 0; entry.windowStart = now;
    }
    entry.count++;
    _bootLimiter.map.set(ip, entry);
    if (entry.count > _bootLimiter.MAX_PER_SEC) {
      return res.status(429).json({ error:'Too many requests (boot)', blocked:true, phase:'bootstrap' });
    }
    if (['POST','PATCH','PUT'].includes(req.method)) {
      const check = _bootPayloadCheck(req.body);
      if (!check.safe) {
        return res.status(400).json({ error:'Invalid request (boot)', threat:check.threat });
      }
    }
  }

  // Security Headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('X-Bot', 'NEXUS-V9-ULTIMATE');
  next();
});

