// B.5 [14.05.2026] ML-MODEL-ARCHIVER (Versioning + History + Rollback)
const MLModelArchiver = {
  saveWithHistory(modelId, modelType, payload, accuracy, trainedOn, trainedAt, symbol, meta) {
    let newVersion = 1;
    try {
      const old = DB.db.prepare('SELECT * FROM ml_models WHERE model_id=?').get(modelId);
      if (old) {
        const oldVer = old.version || 1;
        DB.db.prepare(
          'INSERT INTO ml_models_history (model_id, version, model_type, payload, accuracy, trained_on, trained_at, symbol, meta, archived_at) ' +
          'VALUES (?,?,?,?,?,?,?,?,?,?)'
        ).run(old.model_id, oldVer, old.model_type, old.payload, old.accuracy,
              old.trained_on, old.trained_at, old.symbol, old.meta, Date.now());
        newVersion = oldVer + 1;
      }
    } catch(e) {
      try { Log.warn('MLArchiver', 'history archive failed: ' + e.message); } catch(_){}
    }
    try {
      DB.saveModel.run(modelId, modelType, payload, accuracy, trainedOn, trainedAt, symbol, meta);
      DB.db.prepare('UPDATE ml_models SET version=? WHERE model_id=?').run(newVersion, modelId);
    } catch(e) {
      try { Log.warn('MLArchiver', 'saveModel failed: ' + e.message); } catch(_){}
    }
    return newVersion;
  },

  listVersions(modelId) {
    try {
      const current = DB.db.prepare(
        'SELECT model_id, version, model_type, accuracy, trained_on, trained_at, symbol FROM ml_models WHERE model_id=?'
      ).get(modelId);
      const history = DB.db.prepare(
        'SELECT model_id, version, model_type, accuracy, trained_on, trained_at, symbol, archived_at FROM ml_models_history WHERE model_id=? ORDER BY version DESC'
      ).all(modelId);
      return { current, history };
    } catch(e) {
      return { error: e.message };
    }
  },

  rollback(modelId, targetVersion) {
    try {
      const target = DB.db.prepare(
        'SELECT * FROM ml_models_history WHERE model_id=? AND version=?'
      ).get(modelId, targetVersion);
      if (!target) return { ok: false, error: 'version not found' };

      // Archive aktuell-Version vor Rollback
      const current = DB.db.prepare('SELECT * FROM ml_models WHERE model_id=?').get(modelId);
      if (current) {
        DB.db.prepare(
          'INSERT INTO ml_models_history (model_id, version, model_type, payload, accuracy, trained_on, trained_at, symbol, meta, archived_at) ' +
          'VALUES (?,?,?,?,?,?,?,?,?,?)'
        ).run(current.model_id, current.version || 1, current.model_type, current.payload,
              current.accuracy, current.trained_on, current.trained_at, current.symbol, current.meta, Date.now());
      }
      DB.saveModel.run(target.model_id, target.model_type, target.payload, target.accuracy,
        target.trained_on, target.trained_at, target.symbol, target.meta);
      const newCurrentVer = current ? (current.version || 1) + 1 : targetVersion;
      DB.db.prepare('UPDATE ml_models SET version=? WHERE model_id=?').run(newCurrentVer, modelId);
      try { Log.boot(`MLArchiver: rolled back ${modelId} to version ${targetVersion} (new current version ${newCurrentVer})`); } catch(_){}
      return { ok: true, model_id: modelId, restored_version: targetVersion, new_current_version: newCurrentVer };
    } catch(e) {
      return { ok: false, error: e.message };
    }
  },
};

// B.4 [14.05.2026] EVENT-LOOP-HEALTH-MONITOR
// Light-Variant: misst event-loop-delay (perf_hooks). Full Worker-Refactor deferred.
// Alert bei p99 > 200ms (block), Telegram bei p99 > 500ms (severe).
//
// P5 [2026-06-03]: EVENT_LOOP_BLOCK Telegram-Coalescing.
//   - Direkter TelegramAlarm.alert('WARN', 'EVENT_LOOP_BLOCK', ...) im Einzel-Sample ENTFERNT.
//   - Interne Logs (Log.warn + stats.alerts) bleiben UNVERÄNDERT — Diagnose intakt.
//   - Telegram nur noch als 30-Minuten-Summary (Key: EVENT_LOOP_BLOCK_30M_SUMMARY).
//   - Buffer-Cap 1000 Samples (Schutz gegen Speicher-Wachstum bei Spike-Bursts).
//   - CRITICAL/EMERGENCY-Alerts an anderen Codestellen UNBERÜHRT.
const EventLoopHealthMonitor = {
  histogram: null,
  enabled:   true,
  intervalMs: 10000,
  timer:     null,
  lastSample: null,
  thresholds: { warnP99Ms: 200, alertP99Ms: 500 },
  stats: { samples: 0, warnings: 0, alerts: 0, telegramSummariesSent: 0, telegramSummariesSuppressed: 0 },
  // P5 Coalesce-Buffer
  COALESCE_MS: 30 * 60 * 1000,         // 30 min
  BUFFER_CAP: 1000,                    // Spike-Burst-Schutz
  _coalesceWindow: { startTs: 0, samples: [], overflowCount: 0 },

  start() {
    if (this.timer || this.histogram) return;
    try {
      this.histogram = monitorEventLoopDelay({ resolution: 10 });
      this.histogram.enable();
      this.timer = setInterval(() => this.sample(), this.intervalMs);
      try { Log.boot('EventLoopHealthMonitor started (10s interval, perf_hooks) · P5 Telegram-Coalescing 30min aktiv'); } catch(_){}
    } catch(e) {
      try { Log.warn('EventLoop', 'start failed: ' + e.message); } catch(_){}
    }
  },

  stop() {
    if (this.timer) { clearInterval(this.timer); this.timer = null; }
    if (this.histogram) { try { this.histogram.disable(); } catch(_){} this.histogram = null; }
  },

  sample() {
    if (!this.histogram) return;
    try {
      const p50 = Math.round(this.histogram.percentile(50) / 1e6);
      const p95 = Math.round(this.histogram.percentile(95) / 1e6);
      const p99 = Math.round(this.histogram.percentile(99) / 1e6);
      const max = Math.round(this.histogram.max / 1e6);
      const mean = Math.round(this.histogram.mean / 1e6);
      this.lastSample = { ts: Date.now(), p50, p95, p99, max, mean };
      this.stats.samples++;

      if (p99 >= this.thresholds.alertP99Ms) {
        this.stats.alerts++;
        try { Log.warn('EventLoop', `SEVERE block p99=${p99}ms p95=${p95}ms max=${max}ms`); } catch(_){}
        // P5 [2026-06-03]: KEIN direkter TelegramAlarm.alert mehr fuer EVENT_LOOP_BLOCK.
        // Sample in Coalesce-Fenster sammeln; Telegram als 30-min-Summary via _flushCoalesce().
        try { this._pushCoalesce({ ts: Date.now(), p99, p95, max }); } catch(_){}
      } else if (p99 >= this.thresholds.warnP99Ms) {
        this.stats.warnings++;
      }
      // P5: Fenster-Flush separat pruefen (passiert auch wenn aktuelles Sample unter Threshold ist)
      try { this._checkFlush(); } catch(_){}
      this.histogram.reset();
    } catch(e) {
      try { Log.warn('EventLoop', 'sample err: ' + e.message); } catch(_){}
    }
  },

  // P5 [2026-06-03]: Coalesce-Buffer-Push mit Overflow-Schutz.
  _pushCoalesce(s) {
    const w = this._coalesceWindow;
    if (!w.startTs) w.startTs = s.ts;
    if (w.samples.length >= this.BUFFER_CAP) {
      // Overflow: zaehlen, aber kein neuer Push (Statistik bleibt valide auf erste BUFFER_CAP Samples)
      w.overflowCount++;
      return;
    }
    w.samples.push(s);
  },

  // P5: Flush ausloesen wenn Fenster >= 30min UND mindestens 1 Sample
  _checkFlush() {
    const w = this._coalesceWindow;
    if (!w.startTs || w.samples.length === 0) return;
    if (Date.now() - w.startTs >= this.COALESCE_MS) {
      this._flushCoalesce();
    }
  },

  // P5: Einen einzigen Summary-Telegram pro Fenster senden, dann Fenster reset.
  _flushCoalesce() {
    const w = this._coalesceWindow;
    if (!w.startTs || w.samples.length === 0) {
      this._coalesceWindow = { startTs: 0, samples: [], overflowCount: 0 };
      return;
    }
    try {
      const samples = w.samples.slice();
      samples.sort((a, b) => a.p99 - b.p99);
      const count = samples.length;
      const maxP99 = samples[count - 1].p99;
      const medP99 = samples[Math.floor(count / 2)].p99;
      const maxBlock = samples.reduce((m, s) => s.max > m ? s.max : m, 0);
      const fromStr = new Date(w.startTs).toISOString().substr(11, 8);
      const toStr = new Date().toISOString().substr(11, 8);
      const overflowNote = w.overflowCount > 0 ? ` (+${w.overflowCount} samples capped)` : '';
      if (typeof TelegramAlarm !== 'undefined' && TelegramAlarm.alert) {
        TelegramAlarm.alert('WARN', 'EVENT_LOOP_BLOCK_30M_SUMMARY',
          `EventLoop-Blocks ${fromStr}–${toStr} UTC: count=${count} max_p99=${maxP99}ms median_p99=${medP99}ms max_block=${maxBlock}ms${overflowNote}`);
        this.stats.telegramSummariesSent++;
      } else {
        this.stats.telegramSummariesSuppressed++;
      }
    } catch(e) {
      try { Log.warn('EventLoop', 'flush err: ' + e.message); } catch(_){}
    } finally {
      this._coalesceWindow = { startTs: 0, samples: [], overflowCount: 0 };
    }
  },

  snapshot() {
    return {
      enabled: this.enabled,
      lastSample: this.lastSample,
      thresholds: { ...this.thresholds },
      stats: { ...this.stats },
      coalesce: {
        windowOpen: !!this._coalesceWindow.startTs,
        windowStartTs: this._coalesceWindow.startTs,
        bufferedSamples: this._coalesceWindow.samples.length,
        overflowCount: this._coalesceWindow.overflowCount,
        coalesceMs: this.COALESCE_MS,
        bufferCap: this.BUFFER_CAP,
      },
    };
  },
};

