// G — Trading Session Filter (Asian/EU/US/Overlap)
const SessionFilter = {
  enabled: false,  // Default OFF — Shadow-Mode bis Recherche/Tests bestätigt
  getCurrentSession() {
    const h = new Date().getUTCHours();
    // ASIAN: 23-08 UTC, EU: 07-16, US: 13-22, Overlap-Bands berücksichtigt
    if (h >= 0 && h < 7)   return { session: 'ASIAN',     name: 'Asian Session' };
    if (h >= 7 && h < 13)  return { session: 'EU',        name: 'European Session' };
    if (h >= 13 && h < 16) return { session: 'EU_US',     name: 'EU-US Overlap' };  // best liquidity
    if (h >= 16 && h < 22) return { session: 'US',        name: 'US Session' };
    return { session: 'OFF_HOURS', name: 'Off-Hours' };
  },
  getMultiplier() {
    if (!this.enabled) return 1.0;
    const s = this.getCurrentSession().session;
    // empirisch: EU_US Overlap = beste Liquidität, OFF_HOURS = vorsichtiger
    if (s === 'EU_US')     return 1.10;
    if (s === 'US')        return 1.00;
    if (s === 'EU')        return 1.00;
    if (s === 'ASIAN')     return 0.90;
    if (s === 'OFF_HOURS') return 0.80;
    return 1.0;
  },
  snapshot() {
    return {
      enabled: this.enabled,
      current: this.getCurrentSession(),
      multiplier: this.getMultiplier(),
      utcHour: new Date().getUTCHours(),
    };
  },
};

// Y2 — Prometheus-Format Metrics-Endpoint (Eigenbau, kein npm-Modul nötig)
const MetricsExport = {
  build() {
    const lines = [];
    const ts = Date.now();
    try {
      const w = (typeof DemoEngine !== 'undefined' && DemoEngine.wallet) ? DemoEngine.wallet : null;
      const pos = (typeof DemoEngine !== 'undefined' && DemoEngine.positions) ? Object.keys(DemoEngine.positions).length : 0;
      const pmR = (typeof process !== 'undefined') ? process.uptime() : 0;
      lines.push('# HELP bot_wallet_total Wallet total in USDT');
      lines.push('# TYPE bot_wallet_total gauge');
      lines.push(`bot_wallet_total ${w ? w.total : 0}`);
      lines.push('# HELP bot_daily_pnl Daily realized PnL in USDT');
      lines.push('# TYPE bot_daily_pnl gauge');
      lines.push(`bot_daily_pnl ${w ? w.dailyPnl : 0}`);
      lines.push('# HELP bot_total_pnl Total realized PnL in USDT');
      lines.push('# TYPE bot_total_pnl gauge');
      lines.push(`bot_total_pnl ${w ? w.pnl : 0}`);
      lines.push('# HELP bot_active_positions Count of open positions');
      lines.push('# TYPE bot_active_positions gauge');
      lines.push(`bot_active_positions ${pos}`);
      lines.push('# HELP bot_uptime_seconds Bot uptime in seconds');
      lines.push('# TYPE bot_uptime_seconds counter');
      lines.push(`bot_uptime_seconds ${pmR.toFixed(0)}`);
      // Recon-State
      let reconConsistent = 1, drift = 0;
      try {
        const recon = DB.db.prepare('SELECT * FROM trades WHERE state=?').all('POSITION_ACTIVE');
        const activeSizes = recon.reduce((s, t) => s + (t.size || 0), 0);
        const expectedTrading = (w ? w.total : 0) - (w ? w.reserve : 0) - activeSizes;
        drift = w ? Math.abs(expectedTrading - w.trading) : 0;
        reconConsistent = drift < 0.5 ? 1 : 0;
      } catch(_) {}
      lines.push('# HELP bot_recon_consistent 1 if reconciliation OK, 0 if drift');
      lines.push('# TYPE bot_recon_consistent gauge');
      lines.push(`bot_recon_consistent ${reconConsistent}`);
      lines.push('# HELP bot_recon_drift_usdt Reconciliation drift in USDT');
      lines.push('# TYPE bot_recon_drift_usdt gauge');
      lines.push(`bot_recon_drift_usdt ${drift.toFixed(4)}`);
      // Notbremse
      const nbTrig = (typeof DailyLossEmergencyStop !== 'undefined') ? DailyLossEmergencyStop.stats.triggers : 0;
      lines.push('# HELP bot_notbremse_triggers Auto-notbremse triggers today');
      lines.push('# TYPE bot_notbremse_triggers counter');
      lines.push(`bot_notbremse_triggers ${nbTrig}`);
    } catch(e) {
      lines.push('# error: ' + e.message);
    }
    return lines.join('\n') + '\n';
  },
};

// F (Phase 2) [15.05.2026] PROFIT-LOCK HWM (Portfolio-Drawdown-SizeReduction)
// // DEMO=LIVE: identisch in beiden Modi (WalletProvider routet Source).
const ProfitLockHWM = {
  enabled: true,
  _hwm: null,           // in-memory current HWM
  _hwmAt: null,
  _lastDDPct: 0,
  _active: false,       // true wenn DD-Threshold gerissen

  // Beim Start: lade HWM aus bot_settings
  start() {
    try {
      const row = DB.db.prepare("SELECT value FROM bot_settings WHERE key='profitlock_hwm'").get();
      if (row && row.value) {
        const obj = JSON.parse(row.value);
        this._hwm = Number(obj.hwm) || null;
        this._hwmAt = Number(obj.ts) || null;
        try { Log.boot(`ProfitLockHWM: HWM=${this._hwm} (loaded from DB)`); } catch(_) {}
      } else {
        // Erst-Init aus aktuellem Wallet-Total
        const w = (typeof WalletProvider !== 'undefined') ? WalletProvider.total() : 0;
        if (w > 0) { this._hwm = w; this._persistHWM(); }
      }
    } catch(_) {}
  },

  _persistHWM() {
    try {
      DB.db.prepare("INSERT OR REPLACE INTO bot_settings (key, value, updated_at) VALUES ('profitlock_hwm', ?, ?)")
        .run(JSON.stringify({ hwm: this._hwm, ts: Date.now() }), Date.now());
      this._hwmAt = Date.now();
    } catch(e) { try { Log.warn('HWM_PERSIST', 'persistHWM fail: ' + e.message); } catch(_) {} }  // FIX 49 [Block D]
  },

  // Wird periodisch aus DemoEngine.cycle oder externe Quelle aufgerufen
  updateFromWallet() {
    if (!this.enabled) return;
    try {
      const total = (typeof WalletProvider !== 'undefined') ? WalletProvider.total() : 0;
      if (!total || total <= 0) return;
      if (!this._hwm || total > this._hwm) {
        this._hwm = total;
        this._persistHWM();
      }
      this._lastDDPct = this._hwm > 0 ? (this._hwm - total) / this._hwm : 0;
      const thresh = CFG.PROFIT_LOCK_DD_THRESHOLD || 0.10;
      this._active = this._lastDDPct > thresh;
    } catch(_) {}
  },

  // Liefert Size-Multiplier für RiskSizing
  getSizeMult() {
    if (!this.enabled) return 1.0;
    this.updateFromWallet();
    return this._active ? (CFG.PROFIT_LOCK_SIZE_REDUCTION || 0.70) : 1.0;
  },

  snapshot() {
    this.updateFromWallet();
    return {
      enabled: this.enabled,
      hwm: this._hwm,
      hwmAt: this._hwmAt,
      currentTotal: (typeof WalletProvider !== 'undefined') ? WalletProvider.total() : null,
      ddPct: Number((this._lastDDPct * 100).toFixed(2)),
      active: this._active,
      sizeMult: this.getSizeMult(),
      threshold: CFG.PROFIT_LOCK_DD_THRESHOLD || 0.10,
      reduction: CFG.PROFIT_LOCK_SIZE_REDUCTION || 0.70,
    };
  },
};

// X2 [15.05.2026] STRATEGY ROTATION — Meta-Layer (read-only v1)
// Liest strategy_performance, computed Rolling-Sharpe pro Strategie,
// empfiehlt aktive Strategie mit 10% Hysterese + 7-Tage Min-Hold.
// v1: compute-only (CFG.STRATEGY_ROTATION_ACTIVE_SWITCH=false), kein Effekt auf Trades.
// Sources: arxiv 2511.12120 (Ensemble-Sharpe-Selection), QuantStart Chap.15 Strategy-Optim
const StrategyRotation = {
  enabled: () => CFG.STRATEGY_ROTATION_ENABLED !== false,
  _active: null,            // { strategy, since, sharpe }
  _lastEval: 0,
  _lastSnapshot: null,
  _history: [],             // [{ ts, from, to, fromSharpe, toSharpe, reason }]
  _interval: null,

  start() {
    if (!this.enabled()) return;
    try {
      const row = DB.db.prepare("SELECT value FROM bot_settings WHERE key='strategy_rotation_state'").get();
      if (row && row.value) {
        const obj = JSON.parse(row.value);
        this._active = obj.active || null;
        this._history = Array.isArray(obj.history) ? obj.history.slice(-100) : [];
      }
    } catch(_) {}
    try { this.evaluate(); } catch(_) {}
    if (this._interval) { try { clearInterval(this._interval); } catch(_) {} }
    this._interval = setInterval(() => { try { this.evaluate(); } catch(_) {} }, CFG.STRATEGY_ROTATION_EVAL_MS || 300000);
    try { Log.boot(`StrategyRotation: enabled (window=${CFG.STRATEGY_ROTATION_WINDOW_TRADES}, hyst=${CFG.STRATEGY_ROTATION_HYSTERESIS}, minHold=${CFG.STRATEGY_ROTATION_MIN_HOLD_DAYS}d)`); } catch(_) {}
  },

  stop() {
    if (this._interval) { try { clearInterval(this._interval); this._interval = null; } catch(_) {} }
  },

  _persist() {
    try {
      DB.db.prepare("INSERT OR REPLACE INTO bot_settings (key, value, updated_at) VALUES ('strategy_rotation_state', ?, ?)")
        .run(JSON.stringify({ active: this._active, history: this._history.slice(-100) }), Date.now());
    } catch(_) {}
  },

  // Compute Sharpe für eine Strategie aus letzten N Trades.
  // Sharpe = mean(pnl) / std(pnl) * sqrt(N) — vereinfacht, da Trade-Returns nicht zeitnormiert.
  computeSharpe(strategy, windowTrades) {
    try {
      const win = Number(windowTrades) || (CFG.STRATEGY_ROTATION_WINDOW_TRADES || 50);
      const rows = DB.db.prepare(
        "SELECT pnl FROM strategy_performance WHERE strategy=? AND COALESCE(is_backtest,0)=0 ORDER BY ts DESC LIMIT ?"
      ).all(strategy, win);
      if (!rows || rows.length === 0) return { strategy, trades: 0, sharpe: null, mean: 0, std: 0 };
      const pnls = rows.map(r => Number(r.pnl) || 0);
      const n = pnls.length;
      const mean = pnls.reduce((a,b) => a+b, 0) / n;
      const variance = pnls.reduce((a,b) => a + (b-mean)*(b-mean), 0) / Math.max(1, n-1);
      const std = Math.sqrt(variance);
      const sharpe = std > 0 ? (mean / std) * Math.sqrt(n) : null;
      return { strategy, trades: n, sharpe, mean, std };
    } catch(e) {
      return { strategy, trades: 0, sharpe: null, mean: 0, std: 0, error: e.message };
    }
  },

  // Listet alle Strategies in strategy_performance + per-Strategy-Sharpe
  computeAll() {
    try {
      const minTrades = CFG.STRATEGY_ROTATION_MIN_TRADES || 20;
      const strategies = DB.db.prepare(
        "SELECT strategy, COUNT(*) as n FROM strategy_performance WHERE COALESCE(is_backtest,0)=0 GROUP BY strategy"
      ).all() || [];
      const results = strategies.map(s => {
        const m = this.computeSharpe(s.strategy);
        return { ...m, totalTrades: s.n, eligible: m.trades >= minTrades && m.sharpe !== null };
      });
      results.sort((a,b) => {
        if (a.eligible !== b.eligible) return a.eligible ? -1 : 1;
        return (b.sharpe || -Infinity) - (a.sharpe || -Infinity);
      });
      return results;
    } catch(e) {
      return [];
    }
  },

  // Evaluiert + entscheidet ob Switch nötig (mit Hysterese + Min-Hold)
  evaluate() {
    if (!this.enabled()) return null;
    const all = this.computeAll();
    const eligible = all.filter(r => r.eligible);
    const best = eligible[0] || null;
    const now = Date.now();
    this._lastEval = now;

    let recommendation = null;
    let switchReason = null;

    if (!best) {
      // Noch keine Strategie hat genug Daten
      recommendation = { type: 'NO_ELIGIBLE_STRATEGY', count: all.length };
    } else if (!this._active) {
      // Initial-Pick
      this._active = { strategy: best.strategy, since: now, sharpe: best.sharpe };
      this._history.push({ ts: now, from: null, to: best.strategy, fromSharpe: null, toSharpe: best.sharpe, reason: 'INITIAL' });
      this._persist();
      recommendation = { type: 'INITIAL_PICK', strategy: best.strategy };
    } else {
      const minHoldMs = (CFG.STRATEGY_ROTATION_MIN_HOLD_DAYS || 7) * 24 * 60 * 60 * 1000;
      const holdElapsed = now - (this._active.since || now);
      const hyst = CFG.STRATEGY_ROTATION_HYSTERESIS || 0.10;

      if (best.strategy === this._active.strategy) {
        // Aktuelle Strategie bleibt #1 → nur Sharpe-Refresh
        this._active.sharpe = best.sharpe;
        recommendation = { type: 'HOLD', strategy: this._active.strategy };
      } else if (holdElapsed < minHoldMs) {
        recommendation = { type: 'HOLD_MIN_HOLD', strategy: this._active.strategy, daysLeft: ((minHoldMs - holdElapsed)/86400000).toFixed(2) };
      } else {
        const currentActive = eligible.find(r => r.strategy === this._active.strategy);
        const currSharpe = currentActive ? currentActive.sharpe : -Infinity;
        const requiredSharpe = currSharpe + Math.abs(currSharpe) * hyst;
        if (best.sharpe > requiredSharpe) {
          switchReason = `SHARPE_${best.sharpe.toFixed(3)}_BEATS_${currSharpe.toFixed(3)}_+${(hyst*100).toFixed(0)}%`;
          if (CFG.STRATEGY_ROTATION_ACTIVE_SWITCH === true) {
            this._history.push({ ts: now, from: this._active.strategy, to: best.strategy, fromSharpe: currSharpe, toSharpe: best.sharpe, reason: switchReason });
            this._active = { strategy: best.strategy, since: now, sharpe: best.sharpe };
            this._persist();
            recommendation = { type: 'SWITCHED', from: this._history[this._history.length-1].from, to: best.strategy, reason: switchReason };
          } else {
            recommendation = { type: 'WOULD_SWITCH_LOG_ONLY', from: this._active.strategy, to: best.strategy, reason: switchReason };
          }
        } else {
          recommendation = { type: 'HOLD_HYSTERESIS', strategy: this._active.strategy, currSharpe, bestSharpe: best.sharpe, requiredSharpe };
        }
      }
    }

    this._lastSnapshot = {
      ts: now,
      enabled: this.enabled(),
      activeSwitch: CFG.STRATEGY_ROTATION_ACTIVE_SWITCH === true,
      active: this._active,
      best: best ? { strategy: best.strategy, sharpe: best.sharpe, trades: best.trades } : null,
      eligibleCount: eligible.length,
      totalStrategies: all.length,
      recommendation,
      strategies: all,
      historyTail: this._history.slice(-10),
      cfg: {
        window: CFG.STRATEGY_ROTATION_WINDOW_TRADES,
        minTrades: CFG.STRATEGY_ROTATION_MIN_TRADES,
        minHoldDays: CFG.STRATEGY_ROTATION_MIN_HOLD_DAYS,
        hysteresis: CFG.STRATEGY_ROTATION_HYSTERESIS,
      },
    };
    return this._lastSnapshot;
  },

  snapshot() {
    if (!this._lastSnapshot) { try { this.evaluate(); } catch(_) {} }
    return this._lastSnapshot || { enabled: this.enabled(), error: 'NO_SNAPSHOT_YET' };
  },

  // Helper für andere Module: liefert aktuelle "active strategy" oder null
  getActiveStrategy() {
    if (!this.enabled()) return null;
    return this._active ? this._active.strategy : null;
  },
};

// Phase 6 Teil X1 [15.05.2026] LSTM SHADOW — ONNX Runtime + Statistical Fallback
// v2: onnxruntime-node 1.26.0 lädt models/lstm_crypto_v1.onnx (LSTM 1→8 + Dense 8→1).
//     Model untrained, deterministische Init via seed=42. Demonstriert E2E-Pipeline.
//     v3 = trainiertes Modell via Python+PyTorch+torch.onnx.export.
// Fallback: AR(2)+EMA-Momentum bei Inferenz-Fehler oder Latenz > 200ms.
// Sources: onnxruntime-node npm v1.26.0, ONNX LSTM op spec, SC4RECOIN/LSTM-Crypto-Price-Prediction
let ort_mod = null;
let ort_loadError = null;
try { ort_mod = require('onnxruntime-node'); }
catch(e) { ort_loadError = e.message; }

const LSTMShadow = {
  enabled: () => CFG.LSTM_SHADOW_ENABLED !== false,
  _interval: null,
  _bootDelay: 60000,
  _session: null,
  _sessionLoadError: null,
  _modelPath: 'models/lstm_crypto_v1.onnx',
  _onnxLatencies: [],            // ring buffer für stats
  _onnxLatencyCap: 200,
  _SEQ_LEN: 60,
  _lastInferenceMethod: 'none',  // 'onnx' | 'surrogate' | 'none'

  async _loadModel() {
    if (this._session) return true;
    if (!ort_mod) { this._sessionLoadError = ort_loadError || 'ort_mod missing'; return false; }
    try {
      const fs = require('fs');
      if (!fs.existsSync(this._modelPath)) {
        this._sessionLoadError = `model file missing: ${this._modelPath}`;
        return false;
      }
      this._session = await ort_mod.InferenceSession.create(this._modelPath);
      return true;
    } catch(e) {
      this._sessionLoadError = e.message;
      try { Log.warn('LSTM_ONNX', 'model load failed: ' + e.message); } catch(_) {}
      return false;
    }
  },

  // Bereitet Input vor: letzte SEQ_LEN log-returns, normalisiert
  _prepareInput(closes) {
    if (closes.length < this._SEQ_LEN + 1) return null;
    const seq = closes.slice(-this._SEQ_LEN - 1);
    const returns = new Float32Array(this._SEQ_LEN);
    for (let i = 1; i <= this._SEQ_LEN; i++) {
      const r = (seq[i] - seq[i-1]) / seq[i-1];
      returns[i-1] = Math.max(-0.05, Math.min(0.05, r));  // clip extreme returns
    }
    return returns;
  },

  async _predictOnnx(closes) {
    const t0 = Date.now();
    if (!await this._loadModel()) return null;
    const inputData = this._prepareInput(closes);
    if (!inputData) return null;
    try {
      const tensor = new ort_mod.Tensor('float32', inputData, [1, this._SEQ_LEN, 1]);
      const out = await this._session.run({ input: tensor });
      const predictedReturn = Number(out.output.data[0]);
      const latency = Date.now() - t0;
      this._onnxLatencies.push(latency);
      if (this._onnxLatencies.length > 100) this._onnxLatencies = this._onnxLatencies.slice(-100);
      if (latency > (CFG.LSTM_SHADOW_LATENCY_LIMIT_MS || 200)) {
        try { Log.warn('LSTM_ONNX', `latency ${latency}ms exceeded cap ${CFG.LSTM_SHADOW_LATENCY_LIMIT_MS}ms — fallback to surrogate`); } catch(_) {}
        return { fallback: true };
      }
      const last = closes[closes.length - 1];
      const prediction = last * (1 + predictedReturn);
      this._lastInferenceMethod = 'onnx';
      return { ok: true, prediction, last, predictedReturn, latency, model: 'lstm_crypto_v1_onnx' };
    } catch(e) {
      try { Log.warn('LSTM_ONNX', 'inference failed: ' + e.message); } catch(_) {}
      return null;
    }
  },

  _predictSurrogate(closes) {
    const t0 = Date.now();
    const last = closes[closes.length - 1];
    const r1 = (closes[closes.length-1] - closes[closes.length-2]) / closes[closes.length-2];
    const r2 = (closes[closes.length-2] - closes[closes.length-3]) / closes[closes.length-3];
    const arNext = 0.6 * r1 + 0.3 * r2;
    let ema = closes[closes.length - 20];
    const k = 2 / 21;
    for (let i = closes.length - 19; i < closes.length; i++) ema = closes[i] * k + ema * (1 - k);
    const trend = (last - ema) / ema;
    const blended = 0.7 * arNext + 0.3 * trend * 0.1;
    const prediction = last * (1 + blended);
    const latency = Date.now() - t0;
    this._lastInferenceMethod = 'surrogate';
    return { ok: true, prediction, last, predictedReturn: blended, latency, model: 'AR2_EMA_fallback' };
  },

  async _predictAsync(candles) {
    if (!candles || candles.length < 30) return { ok: false, latency: 0, error: 'INSUFFICIENT_CANDLES' };
    const closes = candles.map(c => +c.close || +c[4] || 0).filter(c => c > 0);
    if (closes.length < 30) return { ok: false, latency: 0, error: 'INSUFFICIENT_CLOSES' };
    // Versuche ONNX zuerst, falls verfügbar + genug Daten
    if (ort_mod && closes.length >= this._SEQ_LEN + 1) {
      const onnxResult = await this._predictOnnx(closes);
      if (onnxResult && onnxResult.ok) return onnxResult;
      // bei fallback === true → surrogate
    }
    return this._predictSurrogate(closes);
  },

  async predictAndLog(symbol) {
    if (!this.enabled()) return { ok: false, error: 'DISABLED' };
    const candles = await Bitget.fetchCandles(symbol, '1h', 100).catch(()=>null);
    if (!candles || candles.length < 30) return { ok: false, error: 'NO_CANDLES' };
    const p = await this._predictAsync(candles);
    if (!p.ok) return p;
    try {
      DB.db.prepare('INSERT INTO lstm_shadow (ts,symbol,prediction,latency_ms,model) VALUES (?,?,?,?,?)')
        .run(Date.now(), symbol, p.prediction, p.latency, p.model);
    } catch(_) {}
    return p;
  },

  // Vergleicht eine alte Prediction gegen aktuellen Preis
  async backCompare(maxAgeMs = 3600000) {
    const now = Date.now();
    const cutoff = now - maxAgeMs;
    const rows = DB.db.prepare("SELECT * FROM lstm_shadow WHERE actual IS NULL AND ts < ? LIMIT 50").all(cutoff);
    let updated = 0;
    for (const row of rows) {
      try {
        const t = await Bitget.fetchTicker ? Bitget.fetchTicker(row.symbol).catch(()=>null) : null;
        const actual = t && (t.last || t.lastPr) ? Number(t.last || t.lastPr) : null;
        if (actual && actual > 0) {
          const errPct = Math.abs((row.prediction - actual) / actual) * 100;
          DB.db.prepare('UPDATE lstm_shadow SET actual=?,actual_ts=?,error_pct=? WHERE id=?')
            .run(actual, now, errPct, row.id);
          updated++;
        }
      } catch(_) {}
    }
    return { ok: true, updated };
  },

  snapshot() {
    const total = DB.db.prepare('SELECT COUNT(*) as n FROM lstm_shadow').get()?.n || 0;
    const evaluated = DB.db.prepare('SELECT COUNT(*) as n FROM lstm_shadow WHERE actual IS NOT NULL').get()?.n || 0;
    const recent = DB.db.prepare('SELECT * FROM lstm_shadow ORDER BY ts DESC LIMIT 10').all();
    const meanErr = DB.db.prepare('SELECT AVG(error_pct) as avg FROM lstm_shadow WHERE error_pct IS NOT NULL').get()?.avg || null;
    const lat = this._onnxLatencies;
    const latAvg = lat.length ? lat.reduce((a,b)=>a+b,0)/lat.length : null;
    const latMax = lat.length ? Math.max(...lat) : null;
    return {
      ts: Date.now(),
      enabled: this.enabled(),
      activePrediction: CFG.LSTM_SHADOW_ACTIVE_PREDICTION === true,
      latencyLimitMs: CFG.LSTM_SHADOW_LATENCY_LIMIT_MS,
      ort_loaded: !!ort_mod,
      ort_load_error: ort_loadError,
      ort_version: ort_mod ? require('onnxruntime-node/package.json').version : null,
      model_path: this._modelPath,
      session_loaded: !!this._session,
      session_load_error: this._sessionLoadError,
      last_method: this._lastInferenceMethod,
      onnx_latency_avg_ms: latAvg ? Number(latAvg.toFixed(2)) : null,
      onnx_latency_max_ms: latMax,
      onnx_predictions_total: this._onnxLatencies.length,
      total, evaluated, meanErrorPct: meanErr,
      recent: recent.slice(0, 10),
      note: 'ONNX-Pfad untrained (seed=42 init). v3 = trainiertes Modell via torch.onnx.export. Surrogate als Fallback.',
    };
  },

  async start() {
    if (!this.enabled()) return;
    if (ort_mod) {
      const ok = await this._loadModel();
      try { Log.boot(`LSTMShadow: enabled (ort=${require('onnxruntime-node/package.json').version}, session=${ok?'OK':'FAILED'}, latencyCap=${CFG.LSTM_SHADOW_LATENCY_LIMIT_MS}ms)`); } catch(_) {}
    } else {
      try { Log.boot(`LSTMShadow: ort_mod nicht geladen (${ort_loadError}) — Surrogate-only`); } catch(_) {}
    }
  },
};

// Phase 6 Teil X6 [15.05.2026] RL SHADOW + Auto-Activation Gate
// Erweitert existierenden RLAgent (Z.17461) um Shadow-Decision-Logging + 500-Trigger.
// Sources: Baeldung Epsilon-Greedy, ApxML Q-Learning, Reward-Based-Epsilon-Decay
const RLShadow = {
  enabled: () => CFG.RL_SHADOW_ENABLED !== false,

  // Logging-Hook: nach jeder RL-Decision aufrufen
  logDecision(symbol, decision) {
    if (!this.enabled() || !decision) return;
    try {
      DB.db.prepare('INSERT INTO rl_shadow_decisions (ts,symbol,state_key,action,confidence,mode) VALUES (?,?,?,?,?,?)')
        .run(Date.now(), symbol, decision.state || null, decision.action || null, decision.confidence || null, decision.mode || null);
    } catch(_) {}
  },

  count() {
    try { return DB.db.prepare('SELECT COUNT(*) as n FROM rl_shadow_decisions').get()?.n || 0; }
    catch(_) { return 0; }
  },

  isReadyForActivation() {
    return this.count() >= (CFG.RL_AUTO_ACTIVATE_AFTER || 500);
  },

  snapshot() {
    const count = this.count();
    const threshold = CFG.RL_AUTO_ACTIVATE_AFTER || 500;
    const ready = count >= threshold;
    const recent = DB.db.prepare('SELECT * FROM rl_shadow_decisions ORDER BY ts DESC LIMIT 20').all();
    let actionStats = { BUY: 0, SELL: 0, HOLD: 0 };
    try {
      DB.db.prepare("SELECT action, COUNT(*) as n FROM rl_shadow_decisions WHERE ts > strftime('%s','now','-7 day')*1000 GROUP BY action").all()
        .forEach(r => { actionStats[r.action] = r.n; });
    } catch(_) {}
    return {
      ts: Date.now(),
      enabled: this.enabled(),
      activeDecisionMaking: CFG.RL_ACTIVE_DECISION_MAKING === true,
      shadowCount: count,
      autoActivateThreshold: threshold,
      readyForActivation: ready,
      progressPct: Number(((count / threshold) * 100).toFixed(1)),
      actionStats7d: actionStats,
      recent: recent.slice(0, 10),
      qTableSize: (typeof RLAgent !== 'undefined' && RLAgent.qTable) ? Object.keys(RLAgent.qTable).length : 0,
      epsilon: (typeof RLAgent !== 'undefined') ? RLAgent.epsilon : null,
      episodes: (typeof RLAgent !== 'undefined') ? RLAgent.episodes : null,
      note: `Shadow-only until count>=${threshold} AND explicit Christian-F2 to set CFG.RL_ACTIVE_DECISION_MAKING=true`,
    };
  },
};

// Phase 6 Teil 8 [15.05.2026] DEFI WATCHER — Read-Only ETH-Balance via Public RPC
// KEINE Private-Keys. KEINE Signaturen. Nur eth_getBalance + eth_blockNumber.
// Sources: PublicNode/Cloudflare ETH-Gateway, Whale-Alert (read-only model), Debank (entity-track)
const DefiWatcher = {
  enabled: () => CFG.DEFI_WATCHER_ENABLED !== false,

  // Strict address validation
  _isValidAddress(addr) {
    return typeof addr === 'string' && /^0x[a-fA-F0-9]{40}$/.test(addr);
  },

  async _rpc(method, params, fallback = false) {
    const url = fallback ? (CFG.DEFI_RPC_FALLBACK_URL || 'https://cloudflare-eth.com') : (CFG.DEFI_RPC_URL || 'https://ethereum.publicnode.com');
    try {
      const r = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }),
        signal: AbortSignal.timeout(6000),
      });
      if (!r.ok) {
        if (!fallback) return this._rpc(method, params, true);
        return { ok: false, error: `HTTP_${r.status}` };
      }
      const j = await r.json();
      if (j.error) return { ok: false, error: j.error.message || 'RPC_ERROR' };
      return { ok: true, result: j.result };
    } catch(e) {
      if (!fallback) return this._rpc(method, params, true);
      return { ok: false, error: e.name || e.message };
    }
  },

  _weiToEth(weiHex) {
    if (!weiHex || typeof weiHex !== 'string') return 0;
    try {
      const big = BigInt(weiHex);
      // 1 ETH = 10^18 wei
      const ethWhole = Number(big / 1000000000000000000n);
      const ethFrac = Number(big % 1000000000000000000n) / 1e18;
      return ethWhole + ethFrac;
    } catch(_) { return 0; }
  },

  async getBalance(address) {
    if (!this.enabled()) return { ok: false, error: 'DISABLED' };
    if (!this._isValidAddress(address)) return { ok: false, error: 'INVALID_ADDRESS' };
    const balRes = await this._rpc('eth_getBalance', [address, 'latest']);
    if (!balRes.ok) return balRes;
    const blockRes = await this._rpc('eth_blockNumber', []);
    return {
      ok: true,
      address,
      balance_wei: balRes.result,
      balance_eth: this._weiToEth(balRes.result),
      block_number: blockRes.ok ? parseInt(blockRes.result, 16) : null,
      ts: Date.now(),
    };
  },

  async watchAddress(address, label, notes) {
    if (!this._isValidAddress(address)) return { ok: false, error: 'INVALID_ADDRESS' };
    const now = Date.now();
    const existing = DB.db.prepare('SELECT address FROM defi_watchlist WHERE address=?').get(address);
    if (!existing) {
      DB.db.prepare('INSERT INTO defi_watchlist (address,label,chain,added_at,notes) VALUES (?,?,?,?,?)')
        .run(address, label || null, 'eth', now, notes || null);
    } else {
      DB.db.prepare('UPDATE defi_watchlist SET label=?,notes=? WHERE address=?').run(label || null, notes || null, address);
    }
    // Initial balance fetch
    const bal = await this.getBalance(address);
    if (bal.ok) {
      DB.db.prepare('UPDATE defi_watchlist SET last_check_ts=?,last_balance_wei=?,last_eth=? WHERE address=?')
        .run(now, bal.balance_wei, bal.balance_eth, address);
    }
    return { ok: true, address, balance: bal };
  },

  unwatch(address) {
    if (!this._isValidAddress(address)) return { ok: false, error: 'INVALID_ADDRESS' };
    const res = DB.db.prepare('DELETE FROM defi_watchlist WHERE address=?').run(address);
    return { ok: true, removed: res.changes };
  },

  listWatched() {
    return DB.db.prepare('SELECT * FROM defi_watchlist ORDER BY added_at DESC').all();
  },

  async refreshAll() {
    const rows = this.listWatched();
    const out = [];
    for (const r of rows) {
      const bal = await this.getBalance(r.address);
      if (bal.ok) {
        const now = Date.now();
        DB.db.prepare('UPDATE defi_watchlist SET last_check_ts=?,last_balance_wei=?,last_eth=? WHERE address=?')
          .run(now, bal.balance_wei, bal.balance_eth, r.address);
        out.push({ address: r.address, label: r.label, eth: bal.balance_eth, delta: r.last_eth !== null ? bal.balance_eth - r.last_eth : null });
      } else {
        out.push({ address: r.address, label: r.label, error: bal.error });
      }
    }
    return { ok: true, refreshed: out.length, results: out };
  },

  snapshot() {
    const watched = this.listWatched();
    return {
      ts: Date.now(),
      enabled: this.enabled(),
      private_key_handling: false,  // permanent off
      rpc_url: CFG.DEFI_RPC_URL,
      rpc_fallback: CFG.DEFI_RPC_FALLBACK_URL,
      chain_id: CFG.DEFI_CHAIN_ID || 1,
      watchedCount: watched.length,
      watched: watched.slice(0, 50),
      note: 'READ-ONLY v1. No private keys, no signing, no transactions.',
    };
  },
};

// Phase 6 Teil 7 [15.05.2026] CUSTOM SCRIPTING — Security-Audit-Modul + safe-mode
// Audit-Verdict: FAIL für Real-JS-Eval. Begründung dokumentiert in cfg.CUSTOM_SCRIPT_AUDIT_REASON
// Safe Alternative: JSON-DSL aus Teil 2 (StrategyEvalEngine, /api/strategybuilder)
// Sources: vm2 CVE-2023-29017/-37466/-37903 + CVE-2026-22709, isolated-vm GitHub (no memory limit),
//   SandboxJS (whitelist-prototype), Snyk JS-sandbox-security
// isolated-vm safe-require: bot benötigt --no-node-snapshot (Node20 quirk).
// Wenn Flag fehlt, segfault beim Isolate-Create. Wir laden lazy + catchen.
let ivm = null;
let ivmLoadError = null;
try { ivm = require('isolated-vm'); }
catch(e) { ivmLoadError = e.message; }

const CustomScripting = {
  isReady() {
    return !!ivm && CFG.CUSTOM_SCRIPT_ENABLED === true;
  },

  audit() {
    return {
      verdict: CFG.CUSTOM_SCRIPT_AUDIT_PASSED ? 'PASSED' : 'PENDING',
      reason: CFG.CUSTOM_SCRIPT_AUDIT_REASON,
      eval_enabled: CFG.CUSTOM_SCRIPT_ENABLED === true,
      ivm_loaded: !!ivm,
      ivm_load_error: ivmLoadError,
      sandbox_library: ivm ? `isolated-vm v${require('isolated-vm/package.json').version}` : null,
      limits: ivm ? {
        memoryMB: CFG.CUSTOM_SCRIPT_MEMORY_MB || 50,
        timeoutMs: CFG.CUSTOM_SCRIPT_TIMEOUT_MS || 100,
      } : null,
      historical_cves_avoided: [
        'CVE-2023-29017 (vm2 sandbox escape via host exception)',
        'CVE-2023-37466 (vm2 nesting:true bypass)',
        'CVE-2023-37903 (vm2 inspect-function RCE)',
        'CVE-2026-22709 (vm2 Promise callback sanitization gap)',
      ],
      sources: [
        'isolated-vm GitHub (laverdet/isolated-vm)',
        'Snyk JS-sandbox-security',
        'Temporal Blog Introduction to isolated-vm',
        'LogRocket isolated-vm Leetcode evaluator guide',
      ],
    };
  },

  // Erstellt frische Isolate pro Eval — kein cross-script-State, kein Resident-Memory-Leak
  _newSandbox() {
    const memoryMB = CFG.CUSTOM_SCRIPT_MEMORY_MB || 16;
    const iso = new ivm.Isolate({
      memoryLimit: Math.max(8, memoryMB),
      onCatastrophicError: (msg) => {
        try { Log.warn('SCRIPT_SANDBOX', 'CATASTROPHIC: ' + msg); } catch(_) {}
        // KEIN process.abort() — wir wollen Bot am Leben halten.
        // Isolate-Heap-Exhaustion soll nur das Isolate killen, nicht den Host.
      },
    });
    const ctx = iso.createContextSync();
    const jail = ctx.global;
    // Kein require/process/global/Buffer/setTimeout durchstellen — der Context startet leer
    // Nur ausgewählte read-only Bot-Helper injizieren:
    try {
      const readOnlyBotState = {
        ts: Date.now(),
        regime: (typeof Regime !== 'undefined' ? (Regime.regime || 'NEUTRAL') : 'NEUTRAL'),
        walletTotal: (typeof WalletProvider !== 'undefined' ? Number(WalletProvider.total() || 0) : 0),
        symbols: (CFG.DEFAULT_SYMBOLS || []).slice(0, 10),
      };
      jail.setSync('bot', new ivm.ExternalCopy(readOnlyBotState).copyInto({ release: true, transferIn: true }));
    } catch(_) {}
    return { iso, ctx };
  },

  // Executes user code in isolated sandbox.
  // Returns { ok, result|error, latencyMs, kind }
  execute(code, opts = {}) {
    if (!ivm) {
      return { ok: false, error: 'IVM_NOT_LOADED', detail: ivmLoadError, kind: 'LIB_MISSING' };
    }
    if (CFG.CUSTOM_SCRIPT_ENABLED !== true) {
      return { ok: false, error: 'CUSTOM_SCRIPT_DISABLED_IN_CFG', kind: 'DISABLED' };
    }
    if (typeof code !== 'string' || code.length === 0) {
      return { ok: false, error: 'CODE_REQUIRED', kind: 'BAD_REQUEST' };
    }
    if (code.length > (CFG.CUSTOM_SCRIPT_MAX_LEN || 4000)) {
      return { ok: false, error: 'CODE_TOO_LONG', maxLen: CFG.CUSTOM_SCRIPT_MAX_LEN || 4000, kind: 'BAD_REQUEST' };
    }
    const timeoutMs = opts.timeoutMs || (CFG.CUSTOM_SCRIPT_TIMEOUT_MS || 100);
    let sb = null;
    const t0 = Date.now();
    try {
      sb = this._newSandbox();
      const result = sb.ctx.evalSync(code, { timeout: timeoutMs });
      const latencyMs = Date.now() - t0;
      // Coerce nicht-primitive zu String, damit Externe sich nicht verschlucken
      let safe = result;
      if (result !== null && typeof result === 'object') {
        try { safe = JSON.parse(JSON.stringify(result)); } catch(_) { safe = String(result); }
      }
      return { ok: true, result: safe, latencyMs, kind: 'OK' };
    } catch (e) {
      const latencyMs = Date.now() - t0;
      const msg = String(e && e.message || e);
      let kind = 'EVAL_ERROR';
      if (/Script execution timed out/i.test(msg)) kind = 'TIMEOUT';
      else if (/Array buffer allocation failed|out of memory/i.test(msg)) kind = 'MEMORY';
      else if (/is not defined/i.test(msg)) kind = 'REFERENCE_ERROR';
      else if (/SyntaxError/i.test(msg)) kind = 'SYNTAX_ERROR';
      return { ok: false, error: msg, kind, latencyMs };
    } finally {
      if (sb) {
        try { sb.iso.dispose(); } catch(_) {}
      }
    }
  },

  // Persistiert + nutzt user_scripts-Tabelle
  save(name, code, owner) {
    if (typeof name !== 'string' || name.length < 1 || name.length > 80) return { ok: false, error: 'INVALID_NAME' };
    if (typeof code !== 'string' || code.length < 1) return { ok: false, error: 'INVALID_CODE' };
    const now = Date.now();
    const existing = DB.db.prepare('SELECT id FROM user_scripts WHERE name=?').get(name);
    if (existing) {
      DB.db.prepare('UPDATE user_scripts SET code=?, updated_at=? WHERE id=?').run(code, now, existing.id);
      return { ok: true, id: existing.id, updated: true };
    }
    const r = DB.db.prepare('INSERT INTO user_scripts (name,code,owner,created_at,updated_at,run_count) VALUES (?,?,?,?,?,0)')
      .run(name, code, owner || null, now, now);
    return { ok: true, id: r.lastInsertRowid, created: true };
  },

  list() {
    return DB.db.prepare('SELECT id,name,owner,created_at,updated_at,run_count,last_run FROM user_scripts ORDER BY id DESC').all();
  },

  load(id) {
    return DB.db.prepare('SELECT * FROM user_scripts WHERE id=?').get(id);
  },

  delete(id) {
    DB.db.prepare('DELETE FROM user_scripts WHERE id=?').run(id);
    return { ok: true };
  },

  run(id) {
    const row = this.load(id);
    if (!row) return { ok: false, error: 'NOT_FOUND' };
    const result = this.execute(row.code);
    try {
      DB.db.prepare('UPDATE user_scripts SET last_run=?, run_count=run_count+1 WHERE id=?').run(Date.now(), id);
    } catch(_) {}
    return { ...result, scriptId: id, scriptName: row.name };
  },

  // 8 Security-Tests — werden im Boot-Hook ausgeführt + via /api/scripts/security_audit triggerbar
  runSecurityAudit() {
    if (!ivm) {
      return { ok: false, error: 'IVM_NOT_LOADED', detail: ivmLoadError };
    }
    const tests = [
      { id: 1, name: 'infinite-loop-timeout',  code: 'while(true){}', expectKind: 'TIMEOUT' },
      // Bomb-Test: viele kleine String-Allocs in tight loop. Isolate (16MB) terminiert via memory-limit ODER timeout (100ms).
      // Avoids host-OOM weil V8 isolate sub-heap hat, kein Sprung in host.
      { id: 2, name: 'memory-bomb',            code: 'let s=""; while(true){s+="x".repeat(1024)} s.length;', expectKindAny: ['MEMORY','TIMEOUT','EVAL_ERROR'] },
      { id: 3, name: 'require-blocked',        code: 'require("fs")', expectKind: 'REFERENCE_ERROR' },
      { id: 4, name: 'process-blocked',        code: 'process.exit(0)', expectKind: 'REFERENCE_ERROR' },
      { id: 5, name: 'globalThis-escape',      code: 'globalThis.constructor.constructor("return process")()', expectKindAny: ['REFERENCE_ERROR','EVAL_ERROR'] },
      { id: 6, name: 'this-escape',            code: '(function(){return this.constructor.constructor("return process")()})()', expectKindAny: ['REFERENCE_ERROR','EVAL_ERROR'] },
      { id: 7, name: 'import-blocked',         code: 'import("fs")', expectKindAny: ['SYNTAX_ERROR','EVAL_ERROR','REFERENCE_ERROR'] },
      { id: 8, name: 'eval-process',           code: 'eval("process.exit()")', expectKindAny: ['REFERENCE_ERROR','EVAL_ERROR'] },
    ];
    const wasEnabled = CFG.CUSTOM_SCRIPT_ENABLED;
    CFG.CUSTOM_SCRIPT_ENABLED = true;  // temporär für Audit
    const results = tests.map(t => {
      const r = this.execute(t.code, { timeoutMs: CFG.CUSTOM_SCRIPT_TIMEOUT_MS || 100 });
      const okExpected = (!r.ok) && (
        (t.expectKind && r.kind === t.expectKind) ||
        (t.expectKindAny && t.expectKindAny.includes(r.kind))
      );
      return {
        id: t.id, name: t.name, code: t.code,
        gotKind: r.kind, gotError: r.error, latencyMs: r.latencyMs,
        pass: okExpected,
      };
    });
    CFG.CUSTOM_SCRIPT_ENABLED = wasEnabled;
    const passed = results.filter(r => r.pass).length;
    return { ok: passed === results.length, passed, total: results.length, results, ts: Date.now() };
  },
};

// Phase 6 Teil Y1 [15.05.2026] EXCHANGE FAILOVER DETECTION — health-check + log_only switchover
// Pingt jeden enabled Exchange alle 30s; 3-strike DEGRADED, 5-strike DOWN, 2-OK Recovery.
// Priorität laut CFG.EXCHANGE_FAILOVER_PRIORITY. Bei Bitget-DOWN: log "WOULD_FAILOVER_TO=binance".
// Sources: Aerospike Failover-Detection-Switching-Recovery, Vantixs Exchange-Outage-Handling, BoK Circuit-Breaker (Bithumb 2026)
const ExchangeFailoverDetector = {
  enabled: () => CFG.EXCHANGE_FAILOVER_ENABLED !== false,
  _state: new Map(),  // exchange -> { status:'HEALTHY'|'DEGRADED'|'DOWN', failStreak:0, okStreak:0, lastCheck, lastLatencyMs }
  _interval: null,
  _history: [],       // [{ ts, exchange, fromStatus, toStatus, reason }]

  start() {
    if (!this.enabled()) return;
    const priority = CFG.EXCHANGE_FAILOVER_PRIORITY || ['bitget','binance','kraken','coinbase'];
    priority.forEach(ex => {
      if (!this._state.has(ex)) this._state.set(ex, { status: 'UNKNOWN', failStreak: 0, okStreak: 0, lastCheck: null, lastLatencyMs: null });
    });
    if (this._interval) { try { clearInterval(this._interval); } catch(_) {} }
    setTimeout(() => { try { this.checkAll(); } catch(_) {} }, 2000);
    this._interval = setInterval(() => { try { this.checkAll(); } catch(_) {} }, CFG.EXCHANGE_FAILOVER_INTERVAL_MS || 30000);
    try { Log.boot(`ExchangeFailoverDetector: enabled (interval=${CFG.EXCHANGE_FAILOVER_INTERVAL_MS}ms, priority=${priority.join('>')})`); } catch(_) {}
  },

  stop() { if (this._interval) { try { clearInterval(this._interval); this._interval = null; } catch(_) {} }},

  async _pingExchange(exchange) {
    const start = Date.now();
    try {
      let url;
      switch (exchange) {
        case 'bitget':   url = 'https://api.bitget.com/api/v2/public/time'; break;
        case 'binance':  url = 'https://api.binance.com/api/v3/ping'; break;
        case 'kraken':   url = 'https://api.kraken.com/0/public/Time'; break;
        case 'coinbase': url = 'https://api.exchange.coinbase.com/time'; break;
        default: return { ok: false, latencyMs: 0, error: 'unknown_exchange' };
      }
      const r = await fetch(url, { signal: AbortSignal.timeout(5000) });
      const latencyMs = Date.now() - start;
      if (!r.ok) return { ok: false, latencyMs, error: `HTTP_${r.status}` };
      return { ok: true, latencyMs };
    } catch(e) {
      return { ok: false, latencyMs: Date.now() - start, error: e.name || e.message };
    }
  },

  async checkAll() {
    if (!this.enabled()) return;
    const priority = CFG.EXCHANGE_FAILOVER_PRIORITY || [];
    const failThresh = CFG.EXCHANGE_FAILOVER_FAIL_THRESHOLD || 3;
    const downThresh = CFG.EXCHANGE_FAILOVER_DOWN_THRESHOLD || 5;
    const recThresh  = CFG.EXCHANGE_FAILOVER_RECOVER_THRESHOLD || 2;
    const now = Date.now();

    const results = await Promise.allSettled(priority.map(ex => this._pingExchange(ex)));
    priority.forEach((ex, i) => {
      const r = results[i].status === 'fulfilled' ? results[i].value : { ok: false, latencyMs: 0, error: 'promise_rejected' };
      const s = this._state.get(ex);
      const prevStatus = s.status;
      s.lastCheck = now;
      s.lastLatencyMs = r.latencyMs;
      if (r.ok) {
        s.okStreak++;
        s.failStreak = 0;
        if (s.status !== 'HEALTHY' && s.okStreak >= recThresh) {
          s.status = 'HEALTHY';
        } else if (s.status === 'UNKNOWN') {
          s.status = 'HEALTHY';
        }
      } else {
        s.failStreak++;
        s.okStreak = 0;
        s.lastError = r.error;
        if (s.failStreak >= downThresh) s.status = 'DOWN';
        else if (s.failStreak >= failThresh) s.status = 'DEGRADED';
      }
      if (s.status !== prevStatus) {
        this._history.push({ ts: now, exchange: ex, fromStatus: prevStatus, toStatus: s.status, reason: r.ok ? 'OK_STREAK' : `FAIL_${s.failStreak}_${r.error||'?'}` });
        if (this._history.length > 200) this._history = this._history.slice(-200);
        // Log critical transitions
        try {
          if (s.status === 'DOWN') {
            const alt = priority.find(p => p !== ex && this._state.get(p) && this._state.get(p).status === 'HEALTHY');
            const action = CFG.EXCHANGE_FAILOVER_ACTIVE_SWITCH === true ? 'FAILOVER_APPLIED' : 'WOULD_FAILOVER_TO';
            Log.warn('FAILOVER', `${ex} DOWN (streak=${s.failStreak}) → ${action}=${alt || 'NO_HEALTHY_ALT'}`);
          } else if (s.status === 'DEGRADED') {
            Log.warn('FAILOVER', `${ex} DEGRADED (streak=${s.failStreak} fails)`);
          } else if (s.status === 'HEALTHY' && prevStatus !== 'UNKNOWN') {
            Log.info('FAILOVER', `${ex} RECOVERED → HEALTHY`);
          }
        } catch(_) {}
      }
    });
  },

  snapshot() {
    const states = {};
    this._state.forEach((s, ex) => { states[ex] = { ...s }; });
    const priority = CFG.EXCHANGE_FAILOVER_PRIORITY || [];
    let activePrimary = null;
    for (const ex of priority) {
      if (states[ex] && states[ex].status === 'HEALTHY') { activePrimary = ex; break; }
    }
    return {
      ts: Date.now(),
      enabled: this.enabled(),
      activeSwitch: CFG.EXCHANGE_FAILOVER_ACTIVE_SWITCH === true,
      mode: CFG.EXCHANGE_FAILOVER_ACTIVE_SWITCH === true ? 'APPLY' : 'LOG_ONLY',
      priority,
      states,
      activePrimary,
      configuredPrimary: priority[0] || null,
      activeMatchesConfigured: activePrimary === priority[0],
      historyTail: this._history.slice(-20),
      cfg: {
        intervalMs: CFG.EXCHANGE_FAILOVER_INTERVAL_MS,
        failThreshold: CFG.EXCHANGE_FAILOVER_FAIL_THRESHOLD,
        downThreshold: CFG.EXCHANGE_FAILOVER_DOWN_THRESHOLD,
        recoverThreshold: CFG.EXCHANGE_FAILOVER_RECOVER_THRESHOLD,
      },
    };
  },
};

// Phase 6 Teil 6 [15.05.2026] MULTI-EXCHANGE-REGISTRY — Public-Ticker-Compare (READ-ONLY)
// Vergleicht Bitget-Preise gegen Binance/Kraken/Coinbase über öffentliche REST-Endpoints.
// Keine SDK-Deps (kein ccxt-Install). Reine Read-Only Best-Execution-Vorbereitung.
// Sources: Kraken Public Ticker Docs, Binance/Coinbase public REST, ccxt-Manual public/private split
// Phase LIVE-Readiness [15.05.2026] DRY_LIVE PREFLIGHT
// Validates Bitget connectivity ohne ANY order-send.
// Sources: 3Commas Troubleshooting, Coin-Bureau bot-mistakes, Vantixs preflight-checks
const LivePreflight = {
  async run() {
    const ts0 = Date.now();
    const checks = [];

    // Check 1 — Public time (latency baseline, no auth)
    const t1 = Date.now();
    try {
      const r = await Bitget.publicGet('/api/v2/public/time').catch(e => null);
      const lat = Date.now() - t1;
      const serverTime = r && r.data ? Number(r.data.serverTime) : null;
      const drift = serverTime ? Math.abs(Date.now() - serverTime) : null;
      checks.push({
        id: 1, name: 'public-time-and-drift',
        pass: !!serverTime && drift !== null && drift < 5000,
        latencyMs: lat, serverTime, driftMs: drift,
        threshold: 'drift<5000ms', note: drift && drift >= 5000 ? 'CRITICAL: clock skew breaks order signing' : 'ok',
      });
    } catch(e) { checks.push({ id:1, name:'public-time-and-drift', pass:false, error:e.message }); }

    // Check 2 — Auth-Connectivity (read-only spot/account/assets, KEINE Orders)
    const t2 = Date.now();
    try {
      if (!CFG.API_KEY) {
        checks.push({ id:2, name:'auth-account-assets', pass:false, error:'NO_API_KEY_IN_CFG', latencyMs: 0 });
      } else {
        const r = await Bitget.get('/api/v2/spot/account/assets').catch(e => ({ _err: e.message }));
        const lat = Date.now() - t2;
        const ok = r && r.code === '00000';
        checks.push({
          id: 2, name: 'auth-account-assets',
          pass: !!ok, latencyMs: lat,
          code: r && r.code, assetCount: ok ? (r.data || []).length : 0,
          error: r && r._err, msg: r && r.msg,
          note: ok ? 'auth ok, READ-ONLY query succeeded' : 'auth failed — keys invalid or signing wrong',
        });
      }
    } catch(e) { checks.push({ id:2, name:'auth-account-assets', pass:false, error:e.message }); }

    // Check 3 — Symbol-Info-Check (read-only public)
    const t3 = Date.now();
    try {
      const r = await Bitget.publicGet('/api/v2/spot/public/symbols').catch(e => null);
      const lat = Date.now() - t3;
      const symbols = r && r.data ? r.data : [];
      const btcusdt = symbols.find(s => s.symbol === 'BTCUSDT');
      checks.push({
        id: 3, name: 'symbols-info',
        pass: symbols.length > 100 && !!btcusdt,
        latencyMs: lat, symbolCount: symbols.length,
        btcusdt_present: !!btcusdt,
        btcusdt_minTradeUSDT: btcusdt && btcusdt.minTradeUSDT,
        note: btcusdt ? `BTCUSDT minTrade=${btcusdt.minTradeUSDT} USDT` : 'no BTCUSDT in symbols list',
      });
    } catch(e) { checks.push({ id:3, name:'symbols-info', pass:false, error:e.message }); }

    // Check 4 — Min-Order-Size für DEFAULT_SYMBOLS
    const t4 = Date.now();
    try {
      const r = await Bitget.publicGet('/api/v2/spot/public/symbols').catch(e => null);
      const lat = Date.now() - t4;
      const symbols = r && r.data ? r.data : [];
      const wanted = CFG.DEFAULT_SYMBOLS || ['BTCUSDT','ETHUSDT','SOLUSDT','XRPUSDT'];
      const mins = {};
      for (const sym of wanted) {
        const s = symbols.find(x => x.symbol === sym);
        if (s) mins[sym] = { minTradeUSDT: s.minTradeUSDT, status: s.status };
        else mins[sym] = { missing: true };
      }
      const allPresent = wanted.every(s => mins[s] && !mins[s].missing);
      checks.push({
        id: 4, name: 'min-order-sizes',
        pass: allPresent, latencyMs: lat, mins,
        note: allPresent ? 'all default symbols tradeable' : 'some default symbols missing from exchange',
      });
    } catch(e) { checks.push({ id:4, name:'min-order-sizes', pass:false, error:e.message }); }

    // Check 5 — Rate-Limit-Test (1 GET, schauen ob 429)
    const t5 = Date.now();
    try {
      const r = await Bitget.publicGet('/api/v2/public/time').catch(e => ({ _err: e.message, _code: e.response?.status }));
      const lat = Date.now() - t5;
      const code = r && r._code;
      checks.push({
        id: 5, name: 'rate-limit-probe',
        pass: !code || code !== 429,
        latencyMs: lat, httpCode: code || 200,
        note: code === 429 ? 'RATE_LIMITED — already throttled' : 'no 429 on single probe',
      });
    } catch(e) { checks.push({ id:5, name:'rate-limit-probe', pass:false, error:e.message }); }

    // Check 6 — WebSocket-Connectivity (kurzer Subscribe, 5 ticks, Unsubscribe)
    const t6 = Date.now();
    try {
      const wsResult = await new Promise((resolve) => {
        let tickCount = 0;
        let resolved = false;
        try {
          const ws = new WebSocket('wss://ws.bitget.com/v2/ws/public');
          const timeout = setTimeout(() => {
            if (!resolved) { resolved = true; try { ws.close(); } catch(_) {} resolve({ ok: tickCount > 0, ticks: tickCount, timeout: true }); }
          }, 8000);
          ws.on('open', () => {
            ws.send(JSON.stringify({ op: 'subscribe', args: [{ instType: 'SPOT', channel: 'ticker', instId: 'BTCUSDT' }] }));
          });
          ws.on('message', (raw) => {
            try {
              const msg = JSON.parse(raw.toString());
              if (msg.action === 'snapshot' || msg.action === 'update') tickCount++;
              if (tickCount >= 5 && !resolved) {
                resolved = true;
                clearTimeout(timeout);
                ws.send(JSON.stringify({ op: 'unsubscribe', args: [{ instType: 'SPOT', channel: 'ticker', instId: 'BTCUSDT' }] }));
                setTimeout(() => { try { ws.close(); } catch(_) {} resolve({ ok: true, ticks: tickCount }); }, 100);
              }
            } catch(_) {}
          });
          ws.on('error', (e) => { if (!resolved) { resolved = true; clearTimeout(timeout); resolve({ ok: false, error: e.message, ticks: tickCount }); }});
        } catch(e) { resolve({ ok: false, error: e.message }); }
      });
      checks.push({
        id: 6, name: 'websocket-connectivity',
        pass: wsResult.ok, latencyMs: Date.now() - t6,
        ticks: wsResult.ticks, error: wsResult.error,
        note: wsResult.ok ? `received ${wsResult.ticks} ticks before clean unsubscribe` : 'WS failed or timeout',
      });
    } catch(e) { checks.push({ id:6, name:'websocket-connectivity', pass:false, error:e.message }); }

    const passed = checks.filter(c => c.pass).length;
    const allPass = passed === checks.length;
    return {
      ts: Date.now(),
      durationMs: Date.now() - ts0,
      deployMode: CFG.DEPLOY_MODE,
      auth_keys_present: !!CFG.API_KEY,
      passed, total: checks.length,
      verdict: allPass ? 'LIVE_READY' : 'NOT_READY',
      checks,
      note: 'READ-ONLY preflight. KEINE Orders abgeschickt. KEINE DEPLOY_MODE-Änderung.',
    };
  },
};

const ExchangePriceCompare = {
  enabled: () => CFG.MULTI_EXCHANGE_ENABLED !== false,
  _cache: new Map(),         // symbol -> { ts, prices: {exchange: price} }
  _cacheTtlMs: 10000,

  // Symbol-Mapping pro Exchange (USDT-Paare)
  _mapSymbol(exchange, symbol) {
    const base = symbol.replace(/USDT$/, '');
    switch (exchange) {
      case 'binance': return symbol; // BTCUSDT
      case 'kraken': {
        const krakenBase = base === 'BTC' ? 'XBT' : base;
        return `${krakenBase}USDT`;
      }
      case 'coinbase': return `${base}-USDT`;
      case 'bitget': return symbol;
      default: return symbol;
    }
  },

  async _fetchBinance(symbol) {
    try {
      const r = await fetch(`https://api.binance.com/api/v3/ticker/price?symbol=${this._mapSymbol('binance', symbol)}`, { signal: AbortSignal.timeout(4000) });
      if (!r.ok) return null;
      const j = await r.json();
      return j && j.price ? Number(j.price) : null;
    } catch(_) { return null; }
  },

  async _fetchKraken(symbol) {
    try {
      const sym = this._mapSymbol('kraken', symbol);
      const r = await fetch(`https://api.kraken.com/0/public/Ticker?pair=${sym}`, { signal: AbortSignal.timeout(4000) });
      if (!r.ok) return null;
      const j = await r.json();
      if (!j || !j.result) return null;
      const k = Object.keys(j.result)[0];
      const t = j.result[k];
      return t && t.c && t.c[0] ? Number(t.c[0]) : null;
    } catch(_) { return null; }
  },

  async _fetchCoinbase(symbol) {
    try {
      const r = await fetch(`https://api.exchange.coinbase.com/products/${this._mapSymbol('coinbase', symbol)}/ticker`, { signal: AbortSignal.timeout(4000) });
      if (!r.ok) return null;
      const j = await r.json();
      return j && j.price ? Number(j.price) : null;
    } catch(_) { return null; }
  },

  async _fetchBitget(symbol) {
    try {
      if (typeof Bitget !== 'undefined' && Bitget.fetchTicker) {
        const t = await Bitget.fetchTicker(symbol).catch(()=>null);
        return t && (t.last || t.lastPr) ? Number(t.last || t.lastPr) : null;
      }
      return null;
    } catch(_) { return null; }
  },

  // Holt Preise aller Exchanges parallel, mit 10s-Cache
  async getPrices(symbol) {
    if (!this.enabled()) return { ok: false, error: 'DISABLED' };
    const cached = this._cache.get(symbol);
    const now = Date.now();
    if (cached && (now - cached.ts) < this._cacheTtlMs) {
      return { ok: true, symbol, prices: cached.prices, ts: cached.ts, cached: true };
    }
    const results = await Promise.allSettled([
      this._fetchBitget(symbol),
      this._fetchBinance(symbol),
      this._fetchKraken(symbol),
      this._fetchCoinbase(symbol),
    ]);
    const prices = {};
    const labels = ['bitget','binance','kraken','coinbase'];
    results.forEach((r,i) => {
      if (r.status === 'fulfilled' && r.value !== null) prices[labels[i]] = r.value;
    });
    this._cache.set(symbol, { ts: now, prices });
    return { ok: true, symbol, prices, ts: now, cached: false };
  },

  // Best-Execution-Analyse: cheapest BUY, highest SELL, spread
  async analyzePrices(symbol) {
    const data = await this.getPrices(symbol);
    if (!data.ok || Object.keys(data.prices).length === 0) return { ok: false, error: 'NO_PRICES' };
    const entries = Object.entries(data.prices).filter(([k,v]) => typeof v === 'number' && v > 0);
    if (entries.length === 0) return { ok: false, error: 'NO_VALID_PRICES' };
    const sorted = entries.sort((a,b) => a[1] - b[1]);
    const cheapest = sorted[0];
    const highest  = sorted[sorted.length - 1];
    const spreadPct = ((highest[1] - cheapest[1]) / cheapest[1]) * 100;
    return {
      ok: true,
      symbol,
      ts: data.ts,
      cached: data.cached,
      cheapestExchange: cheapest[0],
      cheapestPrice: cheapest[1],
      highestExchange: highest[0],
      highestPrice: highest[1],
      spreadPct: Number(spreadPct.toFixed(4)),
      prices: data.prices,
      recommendation: spreadPct > 0.1
        ? `BUY on ${cheapest[0]} (${cheapest[1]}), SELL on ${highest[0]} (${highest[1]}) — spread ${spreadPct.toFixed(3)}%`
        : 'Spread<0.1% — no significant arbitrage opportunity',
    };
  },

  // Phase 6 Teil 6 LIVE-READY [15.05.2026]
  // Fee-Tabelle (Spot Taker base, ohne Discount-Token — Stand 2026 per Recherche)
  //   bitget:   0.0010 (0.1%)  // bei BGB-Discount bis 0.0002
  //   binance:  0.0010 (0.1%)  // bei BNB-Discount bis 0.00075
  //   kraken:   0.0026 (0.26%)
  //   coinbase: 0.0060 (0.6%)  // entry tier; volume-tiered
  // Quelle: bitget.com/academy/maker-taker-fees, homecryptoinvest 2026
  _feeTable: {
    bitget:   0.0010,
    binance:  0.0010,
    kraken:   0.0026,
    coinbase: 0.0060,
  },

  // Best-Execution: für gegebene Side wählt günstigste Exchange (preis + fee).
  // BUY  → günstigster effektiver Kaufpreis (price * (1+fee))
  // SELL → höchster effektiver Verkaufspreis (price * (1-fee))
  async findBestExecution(symbol, side, sizeUsdt = 0) {
    const data = await this.getPrices(symbol);
    if (!data.ok || Object.keys(data.prices).length === 0) return { ok: false, error: 'NO_PRICES' };
    const sideU = String(side || '').toUpperCase();
    if (sideU !== 'BUY' && sideU !== 'SELL') return { ok: false, error: 'INVALID_SIDE' };
    const candidates = Object.entries(data.prices)
      .filter(([_, p]) => typeof p === 'number' && p > 0)
      .map(([ex, p]) => {
        const fee = this._feeTable[ex] || 0.001;
        const effective = sideU === 'BUY' ? p * (1 + fee) : p * (1 - fee);
        return { exchange: ex, price: p, fee, effectivePrice: effective, sizeUsdt };
      });
    if (candidates.length === 0) return { ok: false, error: 'NO_VALID_PRICES' };
    candidates.sort((a, b) => sideU === 'BUY' ? a.effectivePrice - b.effectivePrice : b.effectivePrice - a.effectivePrice);
    const best = candidates[0];
    const baseline = candidates.find(c => c.exchange === 'bitget') || candidates[candidates.length - 1];
    const savedPct = ((Math.abs(best.effectivePrice - baseline.effectivePrice) / baseline.effectivePrice) * 100);
    return {
      ok: true,
      symbol, side: sideU, sizeUsdt,
      chosen: best.exchange,
      chosenPrice: best.price,
      chosenFee: best.fee,
      effectivePrice: best.effectivePrice,
      baselineExchange: baseline.exchange,
      baselineEffective: baseline.effectivePrice,
      savedPctVsBitget: Number(savedPct.toFixed(4)),
      candidates,
      ts: Date.now(),
    };
  },

  // PlaceBestExecutionOrder — RouterStub mit kategorischer Sicherheitsschranke.
  // KEIN echter Order-Send v1. Drei Schranken halten den Pfad geschlossen:
  //   1. CFG.MULTI_EXCHANGE_ROUTING_ENABLED muss true sein (default false)
  //   2. CFG.DEPLOY_MODE muss in ['LIVE_RESTRICTED','LIVE_FULL']
  //   3. Bitget bleibt always-fallback (kein Drittparty-Routing solange CCXT nicht eingebunden)
  // Sources: ccxt manual create_order, Vantixs Exchange-Outage-Handling (retry+backoff),
  //          Astralane fast-execution
  async placeBestExecutionOrder(symbol, side, sizeUsdt, opts = {}) {
    const decision = await this.findBestExecution(symbol, side, sizeUsdt);
    if (!decision.ok) return { ok: false, error: decision.error, ts: Date.now() };

    // Schranke 1 — Routing-Feature-Toggle
    if (CFG.MULTI_EXCHANGE_ROUTING_ENABLED !== true) {
      return {
        ok: true, dryRun: true, reason: 'MULTI_EXCHANGE_ROUTING_DISABLED_CFG',
        wouldExecuteOn: decision.chosen,
        wouldEffectivePrice: decision.effectivePrice,
        savedPctVsBitget: decision.savedPctVsBitget,
        decision,
      };
    }
    // Schranke 2 — DEPLOY_MODE muss LIVE-Variante sein
    if (!['LIVE_RESTRICTED','LIVE_FULL'].includes(CFG.DEPLOY_MODE)) {
      return {
        ok: true, dryRun: true, reason: 'DEPLOY_MODE_NOT_LIVE',
        currentDeployMode: CFG.DEPLOY_MODE,
        wouldExecuteOn: decision.chosen,
        decision,
      };
    }
    // Schranke 3 — Implementation-Stub: Real-Send via CCXT noch nicht eingebunden
    return {
      ok: false, error: 'NOT_IMPLEMENTED_NEEDS_CCXT',
      wouldExecuteOn: decision.chosen,
      decision,
      note: 'Phase 6 Teil 6 v2: ccxt-SDK Integration + per-Exchange-Auth (API-Keys getrennt pro Exchange)',
    };
  },

  snapshot() {
    return {
      enabled: this.enabled(),
      exchanges: ['bitget','binance','kraken','coinbase'],
      cacheSize: this._cache.size,
      cacheTtlMs: this._cacheTtlMs,
      routingEnabled: CFG.MULTI_EXCHANGE_ROUTING_ENABLED === true,
      deployMode: CFG.DEPLOY_MODE,
      feeTable: this._feeTable,
      note: 'Read-only price compare + best-execution analyzer; placeBestExecutionOrder DRY-RUN solange CFG.MULTI_EXCHANGE_ROUTING_ENABLED=false (default).',
    };
  },
};

// Phase 6 Teil 5 [15.05.2026] TRADING FARM — Sub-Bot-Registry + Symbol-Locks (v1)
// Control-plane für mehrere logische Bots (in-process v1, später PM2-Cluster).
// Lock-Mechanismus mit Preferred-Token + TTL (auto-expire 60s default).
// Sources: HFT-Symbol-Partitioning, Freqtrade Multi-Instance, Blue Prism Lock-Tokens
const SubBotRegistry = {
  enabled: () => CFG.TRADING_FARM_ENABLED !== false,
  _bots: new Map(),         // bot_id -> { name, role, symbols, ... }
  _lockTtlMs: 60000,

  start() {
    if (!this.enabled()) return;
    try {
      const rows = DB.db.prepare('SELECT * FROM sub_bots').all();
      this._bots.clear();
      rows.forEach(r => this._bots.set(r.bot_id, {
        bot_id: r.bot_id, name: r.name, role: r.role,
        symbols: r.symbols_csv ? r.symbols_csv.split(',').map(s=>s.trim()).filter(Boolean) : [],
        strategy_id: r.strategy_id, enabled: !!r.enabled,
        created_at: r.created_at, updated_at: r.updated_at, last_heartbeat: r.last_heartbeat,
      }));
      // expire stale locks at boot
      this.expireStaleLocks();
      try { Log.boot(`SubBotRegistry: ${this._bots.size} sub-bots loaded`); } catch(_) {}
    } catch(e) { try { Log.warn('FARM', 'start err: ' + e.message); } catch(_) {} }
  },

  register(bot_id, name, opts = {}) {
    if (!bot_id || !name) throw new Error('bot_id + name required');
    const now = Date.now();
    const existing = DB.db.prepare('SELECT bot_id FROM sub_bots WHERE bot_id=?').get(bot_id);
    if (existing) {
      DB.db.prepare('UPDATE sub_bots SET name=?,role=?,symbols_csv=?,strategy_id=?,enabled=?,updated_at=? WHERE bot_id=?')
        .run(name, opts.role || null, (opts.symbols||[]).join(','), opts.strategy_id || null, opts.enabled ? 1 : 0, now, bot_id);
    } else {
      DB.db.prepare('INSERT INTO sub_bots (bot_id,name,role,symbols_csv,strategy_id,enabled,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)')
        .run(bot_id, name, opts.role || null, (opts.symbols||[]).join(','), opts.strategy_id || null, opts.enabled ? 1 : 0, now, now);
    }
    this._bots.set(bot_id, {
      bot_id, name, role: opts.role || null, symbols: opts.symbols || [],
      strategy_id: opts.strategy_id || null, enabled: !!opts.enabled,
      created_at: existing ? null : now, updated_at: now, last_heartbeat: null,
    });
    return this._bots.get(bot_id);
  },

  unregister(bot_id) {
    DB.db.prepare('DELETE FROM symbol_locks WHERE bot_id=?').run(bot_id);
    DB.db.prepare('DELETE FROM sub_bots WHERE bot_id=?').run(bot_id);
    this._bots.delete(bot_id);
    return true;
  },

  heartbeat(bot_id) {
    const now = Date.now();
    DB.db.prepare('UPDATE sub_bots SET last_heartbeat=? WHERE bot_id=?').run(now, bot_id);
    const b = this._bots.get(bot_id);
    if (b) b.last_heartbeat = now;
    return now;
  },

  list() {
    return Array.from(this._bots.values());
  },

  // Symbol-Lock: claim für bot_id mit Token; auto-expire nach TTL
  claimLock(bot_id, symbol, ttlMs = null) {
    if (!bot_id || !symbol) throw new Error('bot_id + symbol required');
    this.expireStaleLocks();
    const existing = DB.db.prepare('SELECT bot_id, locked_at, ttl_ms FROM symbol_locks WHERE symbol=?').get(symbol);
    if (existing && existing.bot_id !== bot_id) {
      return { ok: false, error: 'LOCKED_BY_OTHER', owner: existing.bot_id, locked_at: existing.locked_at };
    }
    const now = Date.now();
    const token = `${bot_id}-${now}-${Math.random().toString(36).slice(2,8)}`;
    const ttl = ttlMs || this._lockTtlMs;
    DB.db.prepare('INSERT OR REPLACE INTO symbol_locks (symbol,bot_id,locked_at,ttl_ms,token) VALUES (?,?,?,?,?)')
      .run(symbol, bot_id, now, ttl, token);
    return { ok: true, symbol, bot_id, token, ttl_ms: ttl, locked_at: now };
  },

  releaseLock(bot_id, symbol, force = false) {
    const existing = DB.db.prepare('SELECT bot_id FROM symbol_locks WHERE symbol=?').get(symbol);
    if (!existing) return { ok: true, released: false, reason: 'NOT_LOCKED' };
    if (existing.bot_id !== bot_id && !force) return { ok: false, error: 'NOT_OWNER', owner: existing.bot_id };
    DB.db.prepare('DELETE FROM symbol_locks WHERE symbol=?').run(symbol);
    return { ok: true, released: true, symbol };
  },

  expireStaleLocks() {
    try {
      const now = Date.now();
      const stale = DB.db.prepare('SELECT symbol,bot_id,locked_at,ttl_ms FROM symbol_locks').all()
        .filter(r => now - r.locked_at > (r.ttl_ms || this._lockTtlMs));
      stale.forEach(r => DB.db.prepare('DELETE FROM symbol_locks WHERE symbol=?').run(r.symbol));
      return stale.length;
    } catch(_) { return 0; }
  },

  listLocks() {
    return DB.db.prepare('SELECT * FROM symbol_locks ORDER BY locked_at DESC').all();
  },

  snapshot() {
    this.expireStaleLocks();
    return {
      ts: Date.now(),
      enabled: this.enabled(),
      bots: this.list(),
      locks: this.listLocks(),
      botsCount: this._bots.size,
    };
  },
};

// Phase 6 Teil 2 [15.05.2026] STRATEGY BUILDER — JSON-DSL Eval-Engine (v1 backend)
// User definiert Strategien als JSON-Conditions-Tree:
//   { op:'AND'|'OR', conditions:[ {indicator,period,op,value}|nested ] }
// Indicators: rsi, ema, macd_hist, bb_pct, vol_z, atr, price
// Ops: '<','>','<=','>=','==','crosses_above','crosses_below'
// DEMO=LIVE: pure-eval gegen Candle-State, kein Side-Effect auf Trade-Pfad (v1)
// Sources: TradersPost JSON DSL, NinjaTrader Condition Builder, Cryptohopper Strategy Designer
const StrategyEvalEngine = {
  _allowedIndicators: ['rsi','ema','sma','macd_hist','bb_pct','vol_z','atr','price','momentum'],
  _allowedOps: ['<','>','<=','>=','==','!=','crosses_above','crosses_below'],

  // Validiert JSON-Definition strikt — verhindert beliebige Strings/eval
  validate(def) {
    const errors = [];
    if (!def || typeof def !== 'object') { errors.push('def must be object'); return { ok:false, errors }; }
    const validateNode = (node, path) => {
      if (!node || typeof node !== 'object') { errors.push(`${path}: not object`); return; }
      if (node.op && (node.op === 'AND' || node.op === 'OR' || node.op === 'NOT')) {
        if (!Array.isArray(node.conditions)) { errors.push(`${path}: conditions[] required for op=${node.op}`); return; }
        if (node.op === 'NOT' && node.conditions.length !== 1) { errors.push(`${path}: NOT needs exactly 1 condition`); }
        if ((node.op === 'AND' || node.op === 'OR') && node.conditions.length < 1) { errors.push(`${path}: ${node.op} needs >=1 conditions`); }
        node.conditions.forEach((c,i) => validateNode(c, `${path}.conditions[${i}]`));
      } else if (node.indicator) {
        if (!this._allowedIndicators.includes(node.indicator)) { errors.push(`${path}: indicator '${node.indicator}' not allowed`); }
        if (!this._allowedOps.includes(node.op)) { errors.push(`${path}: op '${node.op}' not allowed`); }
        if (typeof node.value !== 'number' && typeof node.value !== 'string') { errors.push(`${path}: value must be number or string`); }
        if (node.period !== undefined && (typeof node.period !== 'number' || node.period < 1 || node.period > 500)) { errors.push(`${path}: period must be 1-500`); }
      } else {
        errors.push(`${path}: missing op (AND/OR/NOT) or indicator`);
      }
    };
    validateNode(def, 'root');
    return { ok: errors.length === 0, errors };
  },

  // Berechnet Indicator-Wert für Candles
  _getIndicator(name, period, candles) {
    if (!Array.isArray(candles) || candles.length === 0) return null;
    const closes = candles.map(c => +c.close || +c[4] || 0);
    const highs  = candles.map(c => +c.high  || +c[2] || 0);
    const lows   = candles.map(c => +c.low   || +c[3] || 0);
    const vols   = candles.map(c => +c.volume|| +c[5] || 0);
    try {
      if (name === 'price') return closes[closes.length-1];
      if (name === 'rsi' && typeof Ind !== 'undefined') return Ind.rsi(closes, period || 14);
      if (name === 'ema' && typeof Ind !== 'undefined') return Ind.ema(closes, period || 20);
      if (name === 'sma' && typeof Ind !== 'undefined') {
        const p = period || 20;
        if (closes.length < p) return null;
        const slice = closes.slice(-p);
        return slice.reduce((a,b)=>a+b,0)/p;
      }
      if (name === 'macd_hist' && typeof Ind !== 'undefined') {
        const m = Ind.macd(closes);
        return m && m.histogram !== undefined ? m.histogram : null;
      }
      if (name === 'bb_pct' && typeof Ind !== 'undefined') {
        const bb = Ind.bb(closes, period || 20);
        return bb && bb.pct !== undefined ? bb.pct : null;
      }
      if (name === 'atr' && typeof Ind !== 'undefined') {
        return Ind.atr(highs, lows, closes, period || 14);
      }
      if (name === 'vol_z') {
        const p = period || 20;
        if (vols.length < p) return null;
        const slice = vols.slice(-p);
        const m = slice.reduce((a,b)=>a+b,0)/p;
        const v = slice.reduce((a,b)=>a+(b-m)*(b-m),0)/p;
        const s = Math.sqrt(v);
        return s > 0 ? (vols[vols.length-1] - m) / s : 0;
      }
      if (name === 'momentum') {
        const p = period || 10;
        if (closes.length <= p) return null;
        return (closes[closes.length-1] - closes[closes.length-1-p]) / closes[closes.length-1-p];
      }
    } catch(_) {}
    return null;
  },

  _evalLeaf(node, candles) {
    const v = this._getIndicator(node.indicator, node.period, candles);
    if (v === null || v === undefined || isNaN(v)) return { ok: false, reason: 'no_indicator_data' };
    const tgt = Number(node.value);
    if (isNaN(tgt) && (node.op === 'crosses_above' || node.op === 'crosses_below')) {
      // Crossover-Ops: nicht im pure-state-eval — v1 vereinfachen auf jüngsten vs vorletzten Wert
      return { ok: false, reason: 'crossover_v1_unsupported' };
    }
    let r = false;
    switch (node.op) {
      case '<': r = v < tgt; break;
      case '>': r = v > tgt; break;
      case '<=': r = v <= tgt; break;
      case '>=': r = v >= tgt; break;
      case '==': r = v === tgt; break;
      case '!=': r = v !== tgt; break;
      default: return { ok: false, reason: 'op_unsupported_v1' };
    }
    return { ok: true, result: r, value: v, op: node.op, target: tgt };
  },

  _evalNode(node, candles) {
    if (node.op === 'AND' || node.op === 'OR' || node.op === 'NOT') {
      const results = node.conditions.map(c => this._evalNode(c, candles));
      const allOk = results.every(r => r.ok);
      if (!allOk) return { ok: false, reason: 'sub_eval_failed', sub: results };
      const bools = results.map(r => r.result);
      let agg = false;
      if (node.op === 'AND') agg = bools.every(b => b === true);
      else if (node.op === 'OR') agg = bools.some(b => b === true);
      else if (node.op === 'NOT') agg = !bools[0];
      return { ok: true, result: agg, op: node.op, sub: results };
    }
    return this._evalLeaf(node, candles);
  },

  // Eval gegen aktuelle Candles eines Symbols
  evaluate(jsonDef, candles) {
    const v = this.validate(jsonDef);
    if (!v.ok) return { ok: false, error: 'VALIDATION_FAILED', errors: v.errors };
    if (!Array.isArray(candles) || candles.length === 0) return { ok: false, error: 'NO_CANDLES' };
    const result = this._evalNode(jsonDef, candles);
    return { ok: result.ok, signal: result.ok ? result.result : null, trace: result, ts: Date.now() };
  },
};

// VISION Stufe 2 [16.05.2026] METABRAIN — Regime → Strategy Mapping
// Liest Markt-Signale, klassifiziert Markt-Phase, wählt passende Strategie.
// Performance-Feedback pro (regime, strategy) → SelectorBias bei Re-Decision.
// Read-only Aufruf in DemoEngine-Cycle vor _executeTrade.
// Sources: arxiv 2511.12120 Ensemble-Strategy-Selection, Markov-Switching Regime Models,
//   xbto.com Crypto-Portfolio-Allocation 2026
const MetaBrain = {
  enabled: () => CFG.METABRAIN_ENABLED !== false,
  _lastClassification: null,
  _classificationCache: new Map(),  // symbol → {ts, regime, strategy}
  _cacheTtlMs: 60000,

  // Erweiterte Regime-Klassen aus existierenden Indikatoren + Volatility-Sub-Tier
  // G1+G3+G4 [23.05.2026]: HMM-State-Override für CRASH/RECOVERY, sonst klassisches Regime
  _classifyRegime(symbol, scores, regime, volRegime) {
    // HMM-State zuerst prüfen (kann CRASH/RECOVERY/BEAR override)
    try {
      if (typeof _HMMRegime !== 'undefined' && _HMMRegime.getCurrentRegime) {
        const hmm = _HMMRegime.getCurrentRegime();
        if (hmm && hmm.confidence >= 0.65) {
          if (hmm.state === 'CRASH')    return 'CRASH';
          if (hmm.state === 'RECOVERY') return 'RECOVERY';
          // BEAR/BULL nicht überrunden — klassisches Regime hat trend+adx-Filter
        }
      }
    } catch(_) {}
    const trend = (typeof Regime !== 'undefined') ? (Regime.trend || 0) : 0;
    const vol = (typeof Regime !== 'undefined') ? (Regime.volatility || 0) : 0;
    const adx = (typeof Regime !== 'undefined') ? (Regime.adx || 0) : 0;
    const sharpe = scores?.sharpe?.score || 0;
    if (vol > 0.15 || volRegime === 'EXTREME') return 'EXTREME_VOL';
    if (trend > 0.025 && adx > 25 && sharpe >= 0) return 'BULL_STRONG';
    if (trend > 0.01 && adx > 18) return 'BULL_WEAK';
    if (trend < -0.025 && adx > 25) return 'BEAR_STRONG';
    if (trend < -0.01 && adx > 18) return 'BEAR_WEAK';
    // G1 [23.05.2026] erweiterte RANGING-Erkennung: hoher adx + schwacher trend → seitwärts mit Bewegung
    if ((adx < 15 && vol < 0.04) || (adx > 30 && Math.abs(trend) < 0.01)) return 'RANGING';
    if (regime === 'SQUEEZE') return 'SQUEEZE';
    return 'NEUTRAL';
  },

  // Strategy-Selector: Regime → primäre Strategie (post-Backtest-tuning 16.05.)
  // Mapping basiert auf 6-Jahre-Backtest-Resultaten (siehe backtest_vision_results.csv).
  // STRATEGY_WHITELIST: aktive Strategien
  // STRATEGY_SYMBOL_LIMIT: pro Strategy welche Symbole erlaubt sind (leer = alle)
  STRATEGY_WHITELIST: ['BREAKOUT_HUNT', 'TREND_FOLLOW', 'MEAN_REVERT', 'CONSERVATIVE'],
  // BOTTOM_PICK aus Whitelist entfernt (Backtest -16%/-13%/-9% alle Symbole)
  STRATEGY_SYMBOL_LIMIT: {
    'MEAN_REVERT': ['BTCUSDT'],  // Backtest +86% BTC, aber -44%/-49% ETH/SOL
  },

  // ── Multi-BotType G [16.05.2026]: Regime → BotType Mapping ──
  // Christians Vision: jeder Markt-Phase ihr passender Bot-Typ.
  BOTTYPE_WHITELIST: ['SINGLE', 'GRID', 'DCA', 'INFGRID', 'CONSERVATIVE'],
  REGIME_TO_BOTTYPE: {
    'BULL_STRONG':  'SINGLE',         // Trend-Mitlaufen mit Single + BREAKOUT_HUNT
    'BULL_WEAK':    'INFGRID',        // Steigender Markt mit Schwankungen → Trailing-Grid
    'NEUTRAL':      'CONSERVATIVE',
    'RANGING':      'GRID',           // Range-Bound → klassischer Grid
    'SQUEEZE':      'SINGLE',         // Pre-Breakout → Single mit BREAKOUT_HUNT
    'BEAR_WEAK':    'DCA',            // Langsamer Bear → akkumulieren
    'BEAR_STRONG':  'CONSERVATIVE',   // Defensiv
    'EXTREME_VOL':  'CONSERVATIVE',
    // G1+G3+G4 [23.05.2026] HMM-State-Mappings
    'CRASH':        'SINGLE',         // SHORT-SINGLE im Crash + Auto-Close-LONG
    'RECOVERY':     'DCA',            // aggressives LONG-DCA nach Crash
  },
  // G1 [23.05.2026] Direction-Override: bei hoher Brain-Conf + passender Direction → SINGLE
  // Egal welcher botType original gemappt war
  // G1 Schwellen kalibriert auf D7-Damping (typische conf 0.05-0.15 nach 4h-Acc + per-dir + symMul)
  DIRECTION_OVERRIDE_REGIMES: {
    'BEAR_STRONG':  { brainDir: 'SELL', minConf: 0.06, override: 'SINGLE' },
    'BEAR_WEAK':    { brainDir: 'SELL', minConf: 0.08, override: 'SINGLE' },
    'BULL_STRONG':  { brainDir: 'BUY',  minConf: 0.06, override: 'SINGLE' },
    'BULL_WEAK':    { brainDir: 'BUY',  minConf: 0.08, override: 'SINGLE' },
    'CRASH':        { brainDir: 'SELL', minConf: 0.05, override: 'SINGLE' },
    'RECOVERY':     { brainDir: 'BUY',  minConf: 0.05, override: 'SINGLE' },
    'SQUEEZE':      { brainDir: 'ANY',  minConf: 0.10, override: 'SINGLE' },
  },
  // UI Pipeline E [16.05.2026] Fix: BotType-Selection INDEPENDENT von Strategy.
  // Vor dem Fix: strategy=CONSERVATIVE → bot_type=CONSERVATIVE (BEAR_WEAK landete auch dort).
  // Nach Fix: Regime → BotType direkt; Strategy ist separate Achse. BEAR_WEAK ergibt DCA.
  _selectBotType(metaRegime, strategy) {
    const bt = this.REGIME_TO_BOTTYPE[metaRegime] || 'SINGLE';
    if (!this.BOTTYPE_WHITELIST.includes(bt)) return 'SINGLE';
    return bt;
  },
  _getBotTypePerformanceBias(metaRegime) {
    try {
      const rows = DB.db.prepare(`
        SELECT bot_type, regime,
          COUNT(*) as trades,
          AVG(CASE WHEN pnl>0 THEN 1.0 ELSE 0.0 END) as win_rate,
          AVG(pnl) as avg_pnl,
          SUM(pnl) as total_pnl
        FROM strategy_performance
        WHERE is_backtest=0 AND regime = ? AND bot_type IS NOT NULL
        GROUP BY bot_type
        HAVING COUNT(*) >= 20
        ORDER BY win_rate DESC, avg_pnl DESC
      `).all(metaRegime);
      if (!rows.length) return null;
      return { best: rows[0].bot_type, winRate: rows[0].win_rate, n: rows[0].trades };
    } catch(_) { return null; }
  },
  _selectStrategy(metaRegime, symbol) {
    const PRIMARY_MAP = {
      'BULL_STRONG':  'BREAKOUT_HUNT',  // war TREND_FOLLOW; Backtest zeigt BH besser
      'BULL_WEAK':    'TREND_FOLLOW',
      'BEAR_STRONG':  'CONSERVATIVE',   // war BOTTOM_PICK; Backtest zeigt BP verliert
      'BEAR_WEAK':    'CONSERVATIVE',   // dito
      'RANGING':      'MEAN_REVERT',    // BTC-only (sonst CONSERVATIVE per SYMBOL_LIMIT)
      'SQUEEZE':      'BREAKOUT_HUNT',
      'EXTREME_VOL':  'CONSERVATIVE',
      'NEUTRAL':      'CONSERVATIVE',
    };
    let primary = PRIMARY_MAP[metaRegime] || 'CONSERVATIVE';

    // Symbol-Limit-Check: wenn Strategy für dieses Symbol nicht erlaubt → fallback CONSERVATIVE
    const limit = this.STRATEGY_SYMBOL_LIMIT[primary];
    if (limit && symbol && !limit.includes(symbol)) {
      const fallback = 'CONSERVATIVE';
      return { strategy: fallback, primary, override: false, symbolFiltered: true, originalLimit: limit, bias: { bestStrategy: null, confidence: 0, tradeCount: 0 } };
    }
    // Whitelist-Check
    if (!this.STRATEGY_WHITELIST.includes(primary)) {
      primary = 'CONSERVATIVE';
    }
    const bias = this._getPerformanceBias(metaRegime);
    if (bias.bestStrategy && bias.bestStrategy !== primary
        && this.STRATEGY_WHITELIST.includes(bias.bestStrategy)
        && bias.confidence > 0.65 && bias.tradeCount >= 10) {
      // Performance-Override: empirisch andere Strategy besser in diesem Regime
      return { strategy: bias.bestStrategy, primary, override: true, bias };
    }
    return { strategy: primary, primary, override: false, bias };
  },

  // Liest performance pro regime aus strategy_performance (lifetime aggregate)
  _getPerformanceBias(metaRegime) {
    try {
      const rows = DB.db.prepare(`
        SELECT strategy, regime,
          COUNT(*) as trades,
          AVG(CASE WHEN pnl>0 THEN 1.0 ELSE 0.0 END) as win_rate,
          AVG(pnl) as avg_pnl,
          SUM(pnl) as total_pnl
        FROM strategy_performance
        WHERE is_backtest=0 AND regime = ?
        GROUP BY strategy
        HAVING COUNT(*) >= 5
        ORDER BY win_rate DESC, avg_pnl DESC
      `).all(metaRegime);
      if (rows.length === 0) return { bestStrategy: null, confidence: 0, tradeCount: 0 };
      const top = rows[0];
      return {
        bestStrategy: top.strategy,
        winRate: top.win_rate,
        avgPnl: top.avg_pnl,
        totalPnl: top.total_pnl,
        tradeCount: top.trades,
        confidence: Math.min(1.0, top.trades / 20),  // ramps to 1.0 at 20+ trades
        allStrategies: rows.slice(0, 5).map(r => ({ s: r.strategy, wr: r.win_rate, n: r.trades })),
      };
    } catch(_) {
      return { bestStrategy: null, confidence: 0, tradeCount: 0 };
    }
  },

  // Haupt-Decide: für Symbol → MetaRegime + Strategy
  async decide(symbol, scores, unifiedDirection, opts = {}) {
    if (!this.enabled()) return { active: false, reason: 'METABRAIN_DISABLED' };
    const now = Date.now();
    const cached = this._classificationCache.get(symbol);
    if (cached && (now - cached.ts) < this._cacheTtlMs) {
      return { ...cached.payload, cached: true };
    }
    const regime = (typeof Regime !== 'undefined') ? Regime.regime : 'UNKNOWN';
    const volRegime = scores?.volatility?.regime || 'NORMAL';
    const metaRegime = this._classifyRegime(symbol, scores, regime, volRegime);
    const sel = this._selectStrategy(metaRegime, symbol);
    // Multi-BotType G: BotType-Selektor (additiv zu strategy).
    let botType = this._selectBotType(metaRegime, sel.strategy);
    // Performance-Override falls genug Daten: bevorzuge empirisch besseren BotType
    const btBias = this._getBotTypePerformanceBias(metaRegime);
    let botTypeOverride = false;
    if (btBias && btBias.best && btBias.best !== botType && this.BOTTYPE_WHITELIST.includes(btBias.best)
        && btBias.winRate > 0.55 && btBias.n >= 20) {
      botType = btBias.best;
      botTypeOverride = true;
    }
    // G1 [23.05.2026] DIRECTION-OVERRIDE: wenn Brain-Conf hoch & Direction passt zu Regime
    // → SINGLE (LONG oder SHORT), bypassed CONSERVATIVE-Skip und DCA-LONG-only-Falle
    let directionOverride = null;
    const dirRule = this.DIRECTION_OVERRIDE_REGIMES[metaRegime];
    if (dirRule && opts && opts.brainConfidence && opts.brainDirection) {
      const brainDir = String(opts.brainDirection).toUpperCase();
      const brainConf = Number(opts.brainConfidence) || 0;
      const dirMatch = dirRule.brainDir === 'ANY' || brainDir === dirRule.brainDir;
      if (dirMatch && brainConf >= dirRule.minConf) {
        botType = dirRule.override;
        directionOverride = { applied: true, brainDir, brainConf, rule: dirRule };
      }
    }
    const payload = {
      active: true,
      symbol,
      metaRegime,
      strategy: sel.strategy,
      primary: sel.primary,
      override: sel.override,
      bias: sel.bias,
      // Multi-BotType G
      botType,
      botTypeOverride,
      botTypeBias: btBias,
      regimeBase: regime,
      // G1 [23.05.2026]
      directionOverride,
      ts: now,
    };
    this._classificationCache.set(symbol, { ts: now, payload });
    this._lastClassification = payload;
    return payload;
  },

  snapshot() {
    const recent = [];
    this._classificationCache.forEach((v, k) => {
      recent.push({ symbol: k, ...v.payload, ageMs: Date.now() - v.ts });
    });
    return {
      ts: Date.now(),
      enabled: this.enabled(),
      version: 'v1.0',
      lastClassification: this._lastClassification,
      cacheSize: this._classificationCache.size,
      classifications: recent.slice(-10),
      note: 'Stufe 2 Vision: MetaBrain - Regime-Classifier + Strategy-Selector + Performance-Feedback',
    };
  },
};

// ═════════════════════════════════════════════════════════════════════════════
// StrategySequence — MEGA-KOMBI E (17.05.2026)
// Superalgos-Pattern: sequential strategy evaluation, single active per symbol.
// Pro Symbol pro Cycle: iteriere Sequence (priority asc), erste trigger-fähige
// übernimmt. Cooldown 15-60 min zwischen Switches.
//
// Schichtet sich ÜBER MetaBrain.decide. Greift NICHT in AladdinBrain ein.
// (AladdinBrain läuft VOR diesem Layer im Cycle und kann jeden Trade blocken.)
//
// Quellen:
// - Superalgos Trading System Hierarchy (sequential precedence)
// - Hedge-Fund Regime-Switching (rapid-flip-avoidance via cooldown)
// - 6J-Backtest-Daten (Default-Sequence-Reihenfolge)
// ═════════════════════════════════════════════════════════════════════════════
const StrategySequence = {
  enabled: () => CFG.STRATEGY_SEQUENCE_ENABLED !== false,

  // Cache: vermeidet DB-Hit pro Cycle
  _seqCache: null,
  _seqCacheTs: 0,
  _SEQ_CACHE_MS: 10000,

  _getSequence() {
    const now = Date.now();
    if (this._seqCache && (now - this._seqCacheTs) < this._SEQ_CACHE_MS) return this._seqCache;
    try {
      this._seqCache = DB.listEnabledSequence.all() || [];
      this._seqCacheTs = now;
    } catch(_) { this._seqCache = []; }
    return this._seqCache;
  },
  invalidateCache() { this._seqCache = null; this._seqCacheTs = 0; },

  _regimeMatches(strat, regime) {
    if (!strat.required_regimes) return true;  // null = any
    const allowed = String(strat.required_regimes).split(',').map(s => s.trim()).filter(Boolean);
    return allowed.includes(regime);
  },
  _symbolMatches(strat, symbol) {
    if (!strat.symbol_filter) return true;
    const allowed = String(strat.symbol_filter).split(',').map(s => s.trim()).filter(Boolean);
    return allowed.includes(symbol);
  },

  // Haupt-Entscheidung: pro Symbol durch Sequence iterieren.
  // input: { regime, unifiedConf, brainConf, brainDecision }
  // returns: { strategy, botType, switched, allowed, reason, cooldownRemainingMin }
  evaluate(symbol, input) {
    if (!this.enabled()) {
      // Sequence disabled: alle erlaubt, kein Override
      return { strategy: null, botType: null, switched: false, allowed: true, reason: 'SEQUENCE_DISABLED' };
    }

    const sequence = this._getSequence();
    if (!sequence.length) {
      return { strategy: 'CONSERVATIVE', botType: 'CONSERVATIVE', switched: false, allowed: false, reason: 'EMPTY_SEQUENCE' };
    }

    const state = DB.getSequenceState.get(symbol) || null;
    const now = Date.now();
    const sinceLastSwitchMin = state && state.last_switch_ts
      ? (now - state.last_switch_ts) / 60000
      : 999999;

    let chosenStrat = null;
    let cooldownBlocked = null;
    const evaluated = [];

    for (const strat of sequence) {
      // 1. Regime-Gate
      if (!this._regimeMatches(strat, input.regime)) {
        evaluated.push(`${strat.strategy_name}:regime_mismatch(${input.regime})`);
        continue;
      }
      // 2. Symbol-Filter
      if (!this._symbolMatches(strat, symbol)) {
        evaluated.push(`${strat.strategy_name}:symbol_excluded`);
        continue;
      }
      // 3. Score/Conf-Gates
      if ((input.unifiedConf || 0) < (strat.min_unified_conf || 0)) {
        evaluated.push(`${strat.strategy_name}:unified_conf_low(${(input.unifiedConf||0).toFixed(3)}<${strat.min_unified_conf})`);
        continue;
      }
      if ((input.brainConf || 0) < (strat.min_brain_conf || 0)) {
        evaluated.push(`${strat.strategy_name}:brain_conf_low(${(input.brainConf||0).toFixed(3)}<${strat.min_brain_conf})`);
        continue;
      }
      // 4. Cooldown-Check (nur wenn Switch zu ANDERER Strategy)
      if (state && state.active_strategy && state.active_strategy !== strat.strategy_name) {
        if (sinceLastSwitchMin < (strat.cooldown_minutes || 0)) {
          cooldownBlocked = { strategy: strat.strategy_name, remaining: (strat.cooldown_minutes - sinceLastSwitchMin).toFixed(1) };
          evaluated.push(`${strat.strategy_name}:cooldown(${cooldownBlocked.remaining}min)`);
          continue;
        }
      }
      // ✅ Strategy gewählt
      chosenStrat = strat;
      break;
    }

    if (!chosenStrat) {
      // Fallback: nutze CONSERVATIVE-Entry aus Sequence (typ. priority 7)
      const fallback = sequence.find(s => s.strategy_name === 'CONSERVATIVE') || { strategy_name: 'CONSERVATIVE', bot_type: 'CONSERVATIVE' };
      chosenStrat = fallback;
    }

    const switched = !state || state.active_strategy !== chosenStrat.strategy_name;
    const newSwitchTs = switched ? now : (state?.last_switch_ts || now);
    const newSwitches = (state?.switches_total || 0) + (switched ? 1 : 0);
    const reason = switched
      ? `SWITCH to ${chosenStrat.strategy_name} (regime=${input.regime}, evaluated=${evaluated.length})`
      : `CONTINUE ${chosenStrat.strategy_name}`;

    try {
      DB.upsertSequenceState.run(
        symbol, chosenStrat.strategy_name, chosenStrat.bot_type,
        newSwitchTs, now, input.regime || null, reason, newSwitches
      );
    } catch(e) {
      try { Log.warn('StrategySequence', `state-upsert err ${symbol}: ${e.message}`); } catch(_){}
    }

    const allowed = chosenStrat.bot_type !== 'CONSERVATIVE';
    return {
      strategy: chosenStrat.strategy_name,
      botType: chosenStrat.bot_type,
      switched,
      allowed,
      reason,
      cooldownBlocked,
      evaluated,
      sinceLastSwitchMin: Math.round(sinceLastSwitchMin),
    };
  },

  snapshot() {
    const sequence = this._getSequence();
    let states = [];
    try { states = DB.listSequenceStates.all() || []; } catch(_){}
    return {
      enabled: this.enabled(),
      version: 'v1.0',
      sequence_config: sequence,
      states: states.map(s => ({
        ...s,
        switch_age_min: s.last_switch_ts ? Math.round((Date.now() - s.last_switch_ts) / 60000) : null,
        eval_age_sec: s.last_evaluation_ts ? Math.round((Date.now() - s.last_evaluation_ts) / 1000) : null,
      })),
      note: 'Superalgos-Pattern: sequential evaluation, single active strategy per symbol, cooldown 15-60min',
    };
  }
};

// VISION Stufe 3 [16.05.2026] STRATEGY-LIBRARY — 5 isolierte Strategie-Module
// Jede Strategy implementiert: name, regimeAffinity, evaluate(candles, scores)
// evaluate returns: { signal:'BUY'|'SELL'|'HOLD', confidence:0..1, reason:string }
// Performance-Tracking pro Strategy via existierende strategy_performance Tabelle.
// Sources: TrendFollower/MeanReversion klassische Pattern, Bollinger-Bands Mean-Revert,
//   ATR-Trail-Stop, Hammer/Doji Pattern-Recognition
const Strategies5 = {
  enabled: () => CFG.STRATEGIES5_ENABLED !== false,

  // Strategy 1: TREND_FOLLOW
  // Trigger: ADX > 25, EMA20 > EMA50 (BUY) oder < EMA50 (SELL)
  // Entry: Pullback zu EMA20 + RSI > 50 (für BUY)
  TREND_FOLLOW: {
    name: 'TREND_FOLLOW',
    regimeAffinity: ['BULL_STRONG', 'BULL_WEAK', 'BEAR_STRONG'],
    evaluate(candles, scores) {
      if (!candles || candles.length < 60) return { signal:'HOLD', confidence:0, reason:'NO_CANDLES' };
      const closes = candles.map(c => +c.close);
      const ema20 = Ind.ema(closes, 20);
      const ema50 = Ind.ema(closes, 50);
      const rsi = Ind.rsi(closes, 14);
      const adxObj = Ind.adx(candles, 14);
      const adx = adxObj?.adx || 0;
      const last = closes[closes.length - 1];
      if (adx < 25) return { signal:'HOLD', confidence:0, reason:`ADX_LOW(${adx.toFixed(0)})` };
      if (ema20 > ema50 && last > ema20 * 0.995 && last < ema20 * 1.005 && rsi > 50 && rsi < 70) {
        return { signal:'BUY', confidence: Math.min(0.85, 0.4 + (adx - 25) * 0.02), reason:`TREND_UP pullback (ADX=${adx.toFixed(0)} RSI=${rsi.toFixed(0)})` };
      }
      if (ema20 < ema50 && last > ema20 * 0.995 && last < ema20 * 1.005 && rsi < 50 && rsi > 30) {
        return { signal:'SELL', confidence: Math.min(0.85, 0.4 + (adx - 25) * 0.02), reason:`TREND_DOWN pullback (ADX=${adx.toFixed(0)} RSI=${rsi.toFixed(0)})` };
      }
      return { signal:'HOLD', confidence:0, reason:`NO_PULLBACK (ema20=${ema20?.toFixed(0)} last=${last.toFixed(0)})` };
    },
  },

  // Strategy 2: MEAN_REVERT
  // Trigger: ADX < 20 (Range), Bollinger-Bands eng
  // Entry: Lower Band touch → BUY; Upper Band touch → SELL
  MEAN_REVERT: {
    name: 'MEAN_REVERT',
    regimeAffinity: ['RANGING', 'NEUTRAL'],
    evaluate(candles, scores) {
      if (!candles || candles.length < 30) return { signal:'HOLD', confidence:0, reason:'NO_CANDLES' };
      const closes = candles.map(c => +c.close);
      const bb = Ind.bb(closes, 20);
      const rsi = Ind.rsi(closes, 14);
      const adxObj = Ind.adx(candles, 14);
      const adx = adxObj?.adx || 0;
      const last = closes[closes.length - 1];
      if (adx > 25) return { signal:'HOLD', confidence:0, reason:`ADX_HIGH(${adx.toFixed(0)}) - not ranging` };
      if (!bb || bb.upper == null) return { signal:'HOLD', confidence:0, reason:'NO_BB' };
      const bandWidth = (bb.upper - bb.lower) / bb.middle;
      if (bandWidth > 0.06) return { signal:'HOLD', confidence:0, reason:`BANDS_WIDE(${(bandWidth*100).toFixed(1)}%)` };
      if (last <= bb.lower * 1.005 && rsi < 40) {
        return { signal:'BUY', confidence:0.65, reason:`BB_LOWER_TOUCH (rsi=${rsi.toFixed(0)})` };
      }
      if (last >= bb.upper * 0.995 && rsi > 60) {
        return { signal:'SELL', confidence:0.65, reason:`BB_UPPER_TOUCH (rsi=${rsi.toFixed(0)})` };
      }
      return { signal:'HOLD', confidence:0, reason:'BB_MIDDLE' };
    },
  },

  // Strategy 3: BOTTOM_PICK
  // Trigger: RSI < 30 + Volume-Spike + Hammer/Doji Pattern
  BOTTOM_PICK: {
    name: 'BOTTOM_PICK',
    regimeAffinity: ['BEAR_STRONG', 'BEAR_WEAK', 'EXTREME_VOL'],
    evaluate(candles, scores) {
      if (!candles || candles.length < 30) return { signal:'HOLD', confidence:0, reason:'NO_CANDLES' };
      const closes = candles.map(c => +c.close);
      const vols = candles.map(c => +c.vol);  // STRATEGIES5_VOL_FIX [22.05.2026]: candle_cache-Spalte heißt "vol"
      const rsi = Ind.rsi(closes, 14);
      if (rsi > 30) return { signal:'HOLD', confidence:0, reason:`RSI_NOT_OS(${rsi.toFixed(0)})` };
      // Volume Z-Score letzten Candle vs 20er Average
      const last = candles[candles.length - 1];
      const recentVols = vols.slice(-20);
      const avgVol = recentVols.reduce((s,v)=>s+v,0) / recentVols.length;
      const volZ = avgVol > 0 ? (+last.vol - avgVol) / avgVol : 0;  // STRATEGIES5_VOL_FIX [22.05.2026]
      if (volZ < 1.0) return { signal:'HOLD', confidence:0, reason:`VOL_NOT_SPIKE(z=${volZ.toFixed(2)})` };
      // Hammer/Doji: small body, lower shadow > 2× body
      const body = Math.abs(last.close - last.open);
      const lowerShadow = Math.min(last.close, last.open) - last.low;
      const upperShadow = last.high - Math.max(last.close, last.open);
      const isHammer = lowerShadow > 2 * body && upperShadow < body * 0.5;
      const isDoji = body / (last.high - last.low + 1e-9) < 0.1;
      if (!isHammer && !isDoji) return { signal:'HOLD', confidence:0, reason:`NO_REVERSAL_CANDLE` };
      // Bayesian-Bull-Bias als Bestätigung (von scores)
      const bayConf = (scores?.bayesian?.direction === 'BUY' && scores?.bayesian?.confidence > 0.5) ? 0.15 : 0;
      return { signal:'BUY', confidence: 0.60 + bayConf, reason:`BOTTOM_PICK rsi=${rsi.toFixed(0)} volZ=${volZ.toFixed(1)} ${isHammer?'HAMMER':'DOJI'}` };
    },
  },

  // Strategy 4: BREAKOUT_HUNT
  // Trigger: Bollinger-Expansion + Volume > 2× avg + Break über Range-High
  BREAKOUT_HUNT: {
    name: 'BREAKOUT_HUNT',
    regimeAffinity: ['SQUEEZE'],
    evaluate(candles, scores) {
      if (!candles || candles.length < 30) return { signal:'HOLD', confidence:0, reason:'NO_CANDLES' };
      const closes = candles.map(c => +c.close);
      const highs = candles.map(c => +c.high);
      const vols = candles.map(c => +c.vol);  // STRATEGIES5_VOL_FIX [22.05.2026]: candle_cache-Spalte heißt "vol"
      const bb = Ind.bb(closes, 20);
      const last = closes[closes.length - 1];
      const range20High = Math.max(...highs.slice(-20, -1));
      const recentVol = vols[vols.length - 1];
      const avgVol = vols.slice(-20).reduce((s,v)=>s+v,0) / 20;
      const volRatio = avgVol > 0 ? recentVol / avgVol : 0;
      if (volRatio < 2.0) return { signal:'HOLD', confidence:0, reason:`VOL_LOW(x${volRatio.toFixed(1)})` };
      // BB-Expansion: jüngste Band-Breite > 20-Periode-Avg-Band-Breite
      const bbWidth = bb ? (bb.upper - bb.lower) / bb.middle : 0;
      if (bbWidth < 0.04) return { signal:'HOLD', confidence:0, reason:`BB_NOT_EXPANDED(${(bbWidth*100).toFixed(1)}%)` };
      // Breakout über Range-High mit Volume
      if (last > range20High * 1.002) {
        return { signal:'BUY', confidence: 0.70, reason:`BREAKOUT_UP volRatio=${volRatio.toFixed(1)} above ${range20High.toFixed(0)}` };
      }
      const range20Low = Math.min(...candles.slice(-20, -1).map(c => +c.low));
      if (last < range20Low * 0.998) {
        return { signal:'SELL', confidence: 0.70, reason:`BREAKOUT_DOWN volRatio=${volRatio.toFixed(1)} below ${range20Low.toFixed(0)}` };
      }
      return { signal:'HOLD', confidence:0, reason:'NO_BREAKOUT' };
    },
  },

  // Strategy 5: CONSERVATIVE_HOLD
  // Trigger: unklare Phase (Regime-Switching > 3× in 4h) ODER EXTREME_VOL
  // Action: kein neuer Trade
  CONSERVATIVE: {
    name: 'CONSERVATIVE',
    regimeAffinity: ['EXTREME_VOL', 'NEUTRAL'],
    evaluate(candles, scores) {
      return { signal:'HOLD', confidence:0, reason:'CONSERVATIVE - no new trades in unclear phase' };
    },
  },

  // Wrapper: evaluiert NACH MetaBrain.decide ausgewählter Strategy
  evaluateStrategy(strategyName, candles, scores) {
    const strat = this[strategyName];
    if (!strat) return { signal:'HOLD', confidence:0, reason:`UNKNOWN_STRATEGY:${strategyName}` };
    try { return { ...strat.evaluate(candles, scores), strategy: strategyName }; }
    catch(e) { return { signal:'HOLD', confidence:0, reason:`STRATEGY_ERROR:${e.message}`, strategy: strategyName }; }
  },

  snapshot() {
    const list = ['TREND_FOLLOW', 'MEAN_REVERT', 'BOTTOM_PICK', 'BREAKOUT_HUNT', 'CONSERVATIVE'];
    return {
      ts: Date.now(),
      enabled: this.enabled(),
      strategies: list.map(name => ({
        name,
        regimeAffinity: this[name].regimeAffinity,
      })),
      note: 'Stufe 3 Vision: 5 isolierte Strategien (TF/MR/BP/BH/CH)',
    };
  },
};

// ─────────────────────────────────────────────────────────────────────────────
// GridBotMBT — DB-persistente Multi-BotType-Grid-Engine (16.05.2026)
// (existierender `GridBot` weiter oben in der File ist die legacy in-memory
//  Adaptive-Variante mit /api/grid/* — DIESER hier ist die MetaBrain-getriebene
//  Range-Grid-Engine mit /api/gridmbt/* + DB-Tabellen grid_instances/grid_orders.)
// DEMO=LIVE: Logik identisch in beiden Modi (Order-Send-Adapter pluggable).
// Range_low/range_high statisch; Range-Break (>=5% Out) schließt Grid.
// ─────────────────────────────────────────────────────────────────────────────
const GridBotMBT = {
  CFG: {
    NUM_LEVELS_DEFAULT: 10,
    RANGE_BREAK_PCT:    0.05,
    MIN_LEVEL_USDT:     2.5,
  },
  _genId() { return `GRID_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,8)}`; },

  // Erstellt Grid mit numLevels Stützpunkten zwischen range_low..range_high
  // Hälfte BUY (untere Hälfte), Hälfte SELL (obere Hälfte).
  create({ symbol, range_low, range_high, num_levels, capital_pool, dry_run, mid_price }) {
    if (range_low >= range_high) throw new Error('range_low must be < range_high');
    const n = Math.max(4, Math.min(50, num_levels | 0 || this.CFG.NUM_LEVELS_DEFAULT));
    const cap = Math.max(0, +capital_pool || 0);
    const perLevel = cap / n;
    if (perLevel < this.CFG.MIN_LEVEL_USDT) {
      throw new Error(`per_level ${perLevel.toFixed(2)} < MIN_LEVEL_USDT ${this.CFG.MIN_LEVEL_USDT}`);
    }
    const grid_id = this._genId();
    const now = Date.now();
    const mid = +mid_price || ((range_low + range_high) / 2);
    const stepBase = (range_high - range_low) / (n + 1);
    const meta = { dry_run: !!dry_run, mid_at_create: mid };

    if (!dry_run) {
      DB.insertGridInstance.run(grid_id, 'GRID', symbol, range_low, range_high, n, cap, perLevel,
        'OPEN', 0, 0, 0, JSON.stringify(meta), now, now);
    }

    // Levels: 1..n. Levels mit Preis < mid → BUY, > mid → SELL
    // PUNKT 2 [25.05.2026]: MATH-FIX — size war als perLevel (=USDT) gespeichert,
    // aber Fill-Logic (Z.9090) behandelt size als COIN-Quantity. Konsequenz:
    // profit_acc 234x überschätzt bei ETH. Quote-Geometric-Pattern (Hummingbot/NautilusTrader/Bybit):
    // size_coins = quote_usdt / level_price. Quelle: Bybit Spot Grid Docs, Hummingbot Grid Strike.
    const levels = [];
    for (let i = 1; i <= n; i++) {
      const price = range_low + stepBase * i;
      const side = price < mid ? 'BUY' : 'SELL';
      const size = perLevel / price;  // FIX: USDT/Level → Coin-Quantity (war: size = perLevel)
      levels.push({ level: i, side, price, size });
      if (!dry_run) {
        DB.insertGridOrder.run(grid_id, i, side, price, size, 0, null, null, now);
      }
    }
    return { grid_id, symbol, range_low, range_high, num_levels: n, capital_pool: cap, per_level: perLevel, levels, dry_run: !!dry_run };
  },

  // Wird bei Preisticks aufgerufen. Prüft Fills + Range-Break.
  onPriceUpdate(grid_id, price) {
    const g = DB.getGridInstance.get(grid_id);
    if (!g || g.status !== 'OPEN') return null;
    // MBT-UI D [16.05.2026]: paused = keine neuen Fills
    if ((g.paused | 0) === 1) return { grid_id, status: 'PAUSED' };

    // P1 [2026-06-03]: Router operation-aware.
    // TICK_MAINTENANCE = nur Hard-Safety-Check; Strategy-Veto greift NICHT (sonst Zombie-Grid).
    // BUY_FILL wird unten separat mit operation='BUY_FILL' geprüft.
    if (typeof _FinalRouter !== 'undefined' && _FinalRouter) {
      try {
        const _gate = _FinalRouter.gateExecution({
          sourceBot:'GRID', symbol:g.symbol, direction:'BUY',
          selectedStrategy:'GRID', operation:'TICK_MAINTENANCE',
          db:(DB && DB.db) ? DB.db : null,
        });
        if (!_gate.ok) {
          // Hard-Safety (z.B. NOT_IN_TRADING_UNIVERSE) → hier wirklich Stop
          try { Log.warn('FINAL_VETO', _gate.logLine); } catch(_){}
          return { grid_id, status:'BLOCKED', reason:_gate.vetoReason, fillCount:0 };
        }
      } catch(_){}
    }

    // Range-Break-Check zuerst (EXIT-Pfad — kein Strategy-Veto)
    const breakHi = g.range_high * (1 + this.CFG.RANGE_BREAK_PCT);
    const breakLo = g.range_low  * (1 - this.CFG.RANGE_BREAK_PCT);
    if (price > breakHi || price < breakLo) {
      return this.closeGrid(grid_id, `RANGE_BROKEN price=${price} hi=${breakHi.toFixed(2)} lo=${breakLo.toFixed(2)}`);
    }

    // Fills prüfen
    const fills = [];
    let profitDelta = 0;
    let fillCount = 0;

    // P1: BUY-Fill = neue Long-Exposition → operation='BUY_FILL' (Strategy-Veto greift)
    let _buyFillAllowed = true;
    if (typeof _FinalRouter !== 'undefined' && _FinalRouter) {
      try {
        const _gateBuy = _FinalRouter.gateExecution({
          sourceBot:'GRID', symbol:g.symbol, direction:'BUY',
          selectedStrategy:'GRID', operation:'BUY_FILL',
          db:(DB && DB.db) ? DB.db : null,
        });
        if (!_gateBuy.ok) {
          _buyFillAllowed = false;
          try { Log.warn('FINAL_VETO', _gateBuy.logLine); } catch(_){}
        }
      } catch(_){}
    }
    // BUY-Order füllt wenn price <= order.price — nur wenn Router erlaubt
    const buy = _buyFillAllowed ? DB.getNextUnfilledBuy.get(grid_id, price) : null;
    if (buy) {
      DB.updateGridOrderFill.run(Date.now(), price, buy.id);
      fills.push({ ...buy, fill_price: price, type: 'BUY_FILL' });
      fillCount++;
      // FIX-WALLET C [17.05.2026]: Ledger-Eintrag (defensiv: before=after)
      // E.3 [23.05.2026] mode-aware via WalletProvider._mode()
      try {
        const _mode = (typeof WalletProvider !== 'undefined' && WalletProvider._mode) ? WalletProvider._mode() : 'DEMO';
        const curT = WalletProvider ? WalletProvider.trading() : ((DemoEngine?.wallet?.trading) || 0);
        const curTot = WalletProvider ? WalletProvider.total() : ((DemoEngine?.wallet?.total) || 0);
        DB.insertLedger.run(Date.now(), 'GRID_BUY', buy.size * price,
          `GRID ${g.symbol} L${buy.level} BUY @ ${price.toFixed(4)}`,
          grid_id, curT, curT, curTot, curTot, _mode);
      } catch(_){}
      // gegenüberliegende SELL auf nächstem Level höher erstellen (wenn Level < num_levels)
      if (buy.level < g.num_levels) {
        const step = (g.range_high - g.range_low) / (g.num_levels + 1);
        const newLvl = buy.level + 1;
        const newPrice = g.range_low + step * newLvl;
        DB.insertGridOrder.run(grid_id, newLvl, 'SELL', newPrice, buy.size, 0, null, null, Date.now());
      }
    }
    // SELL-Order füllt wenn price >= order.price
    const sell = DB.getNextUnfilledSell.get(grid_id, price);
    if (sell) {
      DB.updateGridOrderFill.run(Date.now(), price, sell.id);
      fills.push({ ...sell, fill_price: price, type: 'SELL_FILL' });
      fillCount++;
      // FIX-WALLET C [17.05.2026]: Ledger-Eintrag (defensiv)
      // E.3 [23.05.2026] mode-aware via WalletProvider._mode()
      try {
        const _mode = (typeof WalletProvider !== 'undefined' && WalletProvider._mode) ? WalletProvider._mode() : 'DEMO';
        const curT = WalletProvider ? WalletProvider.trading() : ((DemoEngine?.wallet?.trading) || 0);
        const curTot = WalletProvider ? WalletProvider.total() : ((DemoEngine?.wallet?.total) || 0);
        DB.insertLedger.run(Date.now(), 'GRID_SELL', sell.size * price,
          `GRID ${g.symbol} L${sell.level} SELL @ ${price.toFixed(4)}`,
          grid_id, curT, curT, curTot, curTot, _mode);
      } catch(_){}
      // FEE_WAHRHEIT [20.05.2026]: echte Preis-Differenz BUY↔SELL minus Round-Trip-Fees
      // Vorher: profitDelta = sell.size * (step / sell.price) — Approximation OHNE Fee
      // Jetzt: korrespondierende BUY-Order 1 Level tiefer, Net = Gross − 2× Taker-Fee
      const step = (g.range_high - g.range_low) / (g.num_levels + 1);
      const _buyPriceGrid = Math.max(0, sell.price - step);
      const _grossProfitGrid = sell.size * (sell.price - _buyPriceGrid);
      const _feesGrid = sell.size * sell.price * 2 * CFG.TAKER_FEE;
      profitDelta += (_grossProfitGrid - _feesGrid);
      if (sell.level > 1) {
        const newLvl = sell.level - 1;
        const newPrice = g.range_low + step * newLvl;
        DB.insertGridOrder.run(grid_id, newLvl, 'BUY', newPrice, sell.size, 0, null, null, Date.now());
      }
    }

    if (fillCount > 0) {
      const newProfit = (g.profit_acc || 0) + profitDelta;
      const newFills  = (g.fills_acc  || 0) + fillCount;
      DB.updateGridInstance.run('OPEN', newProfit, newFills, g.range_breaks, g.range_low, g.range_high,
        g.meta, Date.now(), grid_id);
      // FIX 3 [25.05.2026]: 70/30-Split per Fill-Cycle (analog SINGLE/DCA-TP).
      // Quellen-Befund: Nautilus realized_pnls per-instrument bei Fill, LEAN UnsettledCashBook settled bei Fill.
      // Wallet bleibt real-time akkurat; Force-Kill verliert keine Profits mehr.
      if (Math.abs(profitDelta) > 0.01) {
        try {
          if (typeof WalletProvider !== 'undefined' && WalletProvider.applyPnL) {
            const r = WalletProvider.applyPnL(profitDelta, grid_id);
            if (r && !r.ok) { try { Log.warn('GRID_PNL', `${g.symbol} applyPnL fail: ${r.reason}`); } catch(_) {} }
          }
        } catch(e) { try { Log.warn('GRID_PNL', `${g.symbol} applyPnL err: ${e.message}`); } catch(_) {} }
      }
      // REGIME_HOOK [20.05.2026]: strategy_regime_performance bei sinnvoll-grossem profitDelta loggen.
      // Schwelle 0.01 USDT verhindert Mikro-Spam, MBT-Bots fillen 100+/h.
      if (Math.abs(profitDelta) > 0.01) {
        try {
          const _reg = (typeof Regime !== 'undefined' && Regime.regime) ? Regime.regime : 'UNKNOWN';
          const _durMin = Math.round((Date.now() - (g.created_at || Date.now())) / 60000);
          DB.db.prepare(`INSERT INTO strategy_regime_performance (ts, bot_type, regime, trade_id, pnl_usdt, duration_minutes, win) VALUES (?, ?, ?, ?, ?, ?, ?)`)
            .run(Date.now(), 'GRID', _reg, grid_id, profitDelta, _durMin, profitDelta > 0 ? 1 : 0);
        } catch(_) {}
      }
    }
    return { grid_id, fills, fillCount, profitDelta, status: 'OPEN' };
  },

  closeGrid(grid_id, reason) {
    const g = DB.getGridInstance.get(grid_id);
    if (!g) return null;
    const meta = JSON.stringify({ ...(g.meta ? JSON.parse(g.meta) : {}), close_reason: reason });
    const newBreaks = (g.range_breaks || 0) + (reason && reason.startsWith('RANGE_BROKEN') ? 1 : 0);
    DB.updateGridInstance.run('CLOSED', g.profit_acc, g.fills_acc, newBreaks, g.range_low, g.range_high, meta, Date.now(), grid_id);
    return { grid_id, status: 'CLOSED', reason };
  },

  getPerformance(grid_id) {
    const g = DB.getGridInstance.get(grid_id);
    if (!g) return null;
    const orders = DB.listGridOrders.all(grid_id);
    const filledCount = orders.filter(o => o.filled).length;
    return {
      grid_id, symbol: g.symbol, status: g.status,
      profit_acc: g.profit_acc, fills_acc: g.fills_acc,
      range_breaks: g.range_breaks,
      range_low: g.range_low, range_high: g.range_high,
      total_orders: orders.length, filled_orders: filledCount,
      range_stability: g.range_breaks === 0 ? 1.0 : (1 / (1 + g.range_breaks))
    };
  },

  countActive(botType='GRID') {
    return DB.countGridsOpen.get(botType)?.n || 0;
  },

  snapshot() {
    const open = DB.listGridsOpen.all(20);
    return {
      ok: true,
      open_grids: open.length,
      grids: open.map(g => ({ grid_id: g.grid_id, symbol: g.symbol, range:[g.range_low,g.range_high], levels: g.num_levels, profit: g.profit_acc, fills: g.fills_acc }))
    };
  }
};

// ─────────────────────────────────────────────────────────────────────────────
// DCABotMBT — Dollar-Cost-Averaging (Multi-BotType D, 16.05.2026)
// Zeit-getriggerte Käufe, Take-Profit auf Gesamt-Position, Max-DD-Stopp.
// Existierender `DCABot` (legacy adaptive) unverändert weiter unten.
// DEMO=LIVE: Logik identisch in beiden Modi.
// ─────────────────────────────────────────────────────────────────────────────
const DCABotMBT = {
  // Phase 5 [25.05.2026]: Datenbasiert aus Forensik der 6 closed DCA-Instances:
  //   4/6 = MAX_ITERATIONS_REACHED (8 Iter, TP 6% nicht hit)
  //   2/6 = MANUAL · 1/6 = CLOSED_TP (SUIUSDT, 4 Iter, +$4.69)
  // Patch: TP 6% → 3% (Industry-Standard für RANGING/Spot-DCA-Bots), MAX_ITER 8 → 12.
  // Erwartung: höhere TP-Hit-Rate, mehr Realized-PnL pro DCA.
  CFG: {
    MIN_CAPITAL_PER_BUY: 2.5,
    DEFAULT_INTERVAL_H:  6,
    DEFAULT_MAX_ITER:    12,     // Phase 5: war 8 — 4/6 closed wegen MAX_ITER vor TP-Hit
    DEFAULT_TP_PCT:      0.03,   // Phase 5: war 0.06 — TP 6% in RANGING-Markt selten erreicht (1/6 = 17%)
    DEFAULT_MAX_DD:      0.20,   // 20% Drawdown vom avg_buy_price → STOP weitere Käufe
  },
  _genId() { return `DCA_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,8)}`; },

  create({ symbol, capital_per_buy, interval_hours, max_iterations, target_profit_pct, max_dd_pct, dry_run }) {
    const cpb = +capital_per_buy || this.CFG.MIN_CAPITAL_PER_BUY;
    if (cpb < this.CFG.MIN_CAPITAL_PER_BUY) throw new Error(`capital_per_buy < MIN ${this.CFG.MIN_CAPITAL_PER_BUY}`);
    const ih  = +interval_hours || this.CFG.DEFAULT_INTERVAL_H;
    const mi  = (max_iterations | 0) || this.CFG.DEFAULT_MAX_ITER;
    const tp  = +target_profit_pct || this.CFG.DEFAULT_TP_PCT;
    const mdd = +max_dd_pct || this.CFG.DEFAULT_MAX_DD;
    const dca_id = this._genId();
    const now = Date.now();
    const nextBuy = now;  // erster Kauf sofort beim ersten Tick
    const meta = { dry_run: !!dry_run };

    if (!dry_run) {
      DB.insertDcaInstance.run(dca_id, symbol, cpb, ih, mi, tp, mdd,
        0, 0, 0, 0, 'OPEN', nextBuy, null, JSON.stringify(meta), now, now);
    }
    return { dca_id, symbol, capital_per_buy: cpb, interval_hours: ih, max_iterations: mi,
      target_profit_pct: tp, max_dd_pct: mdd, dry_run: !!dry_run };
  },

  // Wird vom Scheduler/Cycle aufgerufen — führt fälligen DCA-Kauf aus.
  scheduledBuy(dca_id, currentPrice) {
    const d = DB.getDcaInstance.get(dca_id);
    if (!d || d.status !== 'OPEN') return null;

    // P1 [2026-06-03]: MAX_ITERATIONS-Close ist EXIT — VOR Strategy-Veto.
    if (d.iteration >= d.max_iterations) {
      return this._close(dca_id, 'MAX_ITERATIONS_REACHED', d);
    }

    // P1: scheduledBuy = DCA_BUY (neue Iteration) → operation='DCA_BUY' (Strategy-Veto greift)
    // P1.1 [2026-06-03]: Router-Block-Reason persistieren, damit UI nicht stale ANOMALY zeigt.
    if (typeof _FinalRouter !== 'undefined' && _FinalRouter) {
      try {
        const _gate = _FinalRouter.gateExecution({
          sourceBot:'DCA', symbol:d.symbol, direction:'BUY',
          selectedStrategy:'DCA', operation:'DCA_BUY',
          db:(DB && DB.db) ? DB.db : null,
        });
        if (!_gate.ok) {
          try { Log.warn('FINAL_VETO', _gate.logLine); } catch(_){}
          // P1.1: persistiere echten aktuellen Blockreason (überschreibt ggf. stale ANOMALY)
          try { DB.setDcaBlock.run(_gate.vetoReason || 'ROUTER_BLOCKED', null, Date.now(), dca_id); } catch(_){}
          return { ok:false, blocked:true, reason:_gate.vetoReason };
        } else {
          // P1.1: Wenn vorher Router/Strategy-Block: clearen (Router lässt jetzt durch)
          try {
            const dCur = DB.getDcaInstance.get(dca_id);
            const prev = dCur?.last_block_reason ? String(dCur.last_block_reason) : '';
            if (prev.startsWith('STRATEGY_') || prev.startsWith('ROUTER_') ||
                prev === 'ANALYSIS_ONLY' || prev === 'PAIR_REQUIRED' || prev === 'NOT_IN_TRADING_UNIVERSE') {
              DB.clearDcaBlock.run(dca_id);
            }
          } catch(_){}
        }
      } catch(_){}
    }
    const price = +currentPrice;
    if (!price || price <= 0) return { ok: false, reason: 'NO_PRICE' };

    // DD-Check: wenn aktueller Preis stark unter avg_buy_price → BLOCK weitere Käufe
    let dd = 0;
    if (d.avg_buy_price > 0) {
      dd = Math.max(0, (d.avg_buy_price - price) / d.avg_buy_price);
      if (dd > d.max_dd_pct) {
        // STOP weitere Käufe — Position halten bis TP oder manueller Close
        const meta = JSON.stringify({ ...(d.meta?JSON.parse(d.meta):{}), dd_stop_ts: Date.now() });
        DB.updateDcaInstance.run(d.avg_buy_price, d.total_size, d.total_spent, d.iteration,
          'DD_STOPPED', null, dd, meta, Date.now(), null, dca_id);
        return { ok: false, reason: 'MAX_DD_HIT', dd };
      }
    }

    const buyUsdt = d.capital_per_buy;
    const buySize = buyUsdt / price;
    const newSize = d.total_size + buySize;
    const newSpent = d.total_spent + buyUsdt;
    const newAvg = newSpent / newSize;
    const newIter = d.iteration + 1;
    const nextBuyAt = Date.now() + (d.interval_hours * 3600000);

    DB.insertDcaIteration.run(dca_id, newIter, price, buySize, buyUsdt, Date.now());
    DB.updateDcaInstance.run(newAvg, newSize, newSpent, newIter, 'OPEN', nextBuyAt, dd,
      d.meta, Date.now(), null, dca_id);
    // FIX-WALLET C [17.05.2026]: Ledger-Eintrag DCA_BUY (defensiv: before=after, KEINE Wallet-Verschiebung)
    // E.3 [23.05.2026] mode-aware via WalletProvider
    try {
      const _mode = (typeof WalletProvider !== 'undefined' && WalletProvider._mode) ? WalletProvider._mode() : 'DEMO';
      const curT = WalletProvider ? WalletProvider.trading() : ((DemoEngine?.wallet?.trading) || 0);
      const curTot = WalletProvider ? WalletProvider.total() : ((DemoEngine?.wallet?.total) || 0);
      DB.insertLedger.run(Date.now(), 'DCA_BUY', buyUsdt,
        `DCA ${d.symbol} Iter ${newIter} @ ${price.toFixed(4)}`,
        dca_id, curT, curT, curTot, curTot, _mode);
    } catch(_) {}

    return { ok: true, dca_id, iteration: newIter, buy_price: price, buy_size: buySize,
      avg_buy_price: newAvg, total_size: newSize, total_spent: newSpent, dd };
  },

  // Wird im Cycle bei jedem Tick aufgerufen — prüft ob TP erreicht.
  checkExit(dca_id, currentPrice) {
    const d = DB.getDcaInstance.get(dca_id);
    if (!d || (d.status !== 'OPEN' && d.status !== 'DD_STOPPED')) return null;
    if (d.total_size <= 0 || !d.avg_buy_price) return { ok: false, reason: 'NO_POSITION' };
    const tpPrice = d.avg_buy_price * (1 + d.target_profit_pct);
    if (currentPrice >= tpPrice) {
      // FEE_WAHRHEIT [20.05.2026]: Fee-aware realized PnL für DCA
      // Vorher: (currentPrice - avg_buy_price) * total_size — ohne Fee
      // Jetzt: Gross - (BUY-Fees aus total_spent + SELL-Fees aus sellValue) * TAKER_FEE
      const _grossDca = (currentPrice - d.avg_buy_price) * d.total_size;
      const _sellValueDca = currentPrice * d.total_size;
      const _feesDca = (d.total_spent + _sellValueDca) * CFG.TAKER_FEE;
      const realizedPnl = _grossDca - _feesDca;
      const meta = JSON.stringify({ ...(d.meta?JSON.parse(d.meta):{}), tp_hit_price: currentPrice, realized_pnl: realizedPnl });
      DB.updateDcaInstance.run(d.avg_buy_price, d.total_size, d.total_spent, d.iteration,
        'CLOSED_TP', null, d.last_dd_pct, meta, Date.now(), Date.now(), dca_id);
      // REGIME_HOOK [20.05.2026]: DCA TP-Hit → strategy_regime_performance
      try {
        const _reg = (typeof Regime !== 'undefined' && Regime.regime) ? Regime.regime : 'UNKNOWN';
        const _durMin = Math.round((Date.now() - (d.created_at || Date.now())) / 60000);
        DB.db.prepare(`INSERT INTO strategy_regime_performance (ts, bot_type, regime, trade_id, pnl_usdt, duration_minutes, win) VALUES (?, ?, ?, ?, ?, ?, ?)`)
          .run(Date.now(), 'DCA', _reg, dca_id, realizedPnl, _durMin, realizedPnl > 0 ? 1 : 0);
      } catch(_) {}
      // PRIO5_FIX #2 [23.05.2026]: dca_iterations.pnl_usdt + exit_price + closed_at befüllen für alle Buys dieser Instanz.
      try {
        const its = DB.db.prepare(`SELECT id, buy_size, buy_price FROM dca_iterations WHERE dca_id = ?`).all(dca_id);
        const totalSize = its.reduce((s, x) => s + (x.buy_size || 0), 0);
        for (const it of its) {
          const itPnl = totalSize > 0 ? (it.buy_size / totalSize) * realizedPnl : 0;
          DB.db.prepare(`UPDATE dca_iterations SET pnl_usdt = ?, exit_price = ?, closed_at = ? WHERE id = ?`).run(itPnl, currentPrice, Date.now(), it.id);
        }
      } catch(_) {}
      // T1 BUG-6 [24.05.2026]: realizedPnL ins Wallet buchen (70/30-Split greift via applyPnL)
      // Vorher: TP-Hit erschien in strp + iterations, aber NICHT in demo_wallet.json → Reserve wuchs nicht
      try {
        if (typeof WalletProvider !== 'undefined' && WalletProvider.applyPnL) {
          const r = WalletProvider.applyPnL(realizedPnl, dca_id);
          try { Log.info('DCA_TP', `${d.symbol} TP-Hit @ ${currentPrice.toFixed(4)} realized +${realizedPnl.toFixed(2)} USDT → wallet ${r.ok ? 'OK newTotal='+r.newTotal?.toFixed(2) : 'FAIL '+r.reason}`); } catch(_) {}
        }
      } catch(e) { try { Log.warn('DCA_TP', 'applyPnL err: ' + e.message); } catch(_) {} }
      return { ok: true, exit: true, exit_price: currentPrice, realized_pnl: realizedPnl };
    }
    return { ok: true, exit: false, gap_to_tp: ((tpPrice - currentPrice) / currentPrice) };
  },

  // FIX 20 [26.05.2026 / DCA-Drift-Exit-Bug]: Inventory-Liquidation bei MANUAL/MAX_ITER-close.
  // Vorher: _close setzte nur status='CLOSED', Inventory stranded (730 USDT bei 5 hist. DCAs).
  // Jetzt: Mark-to-Market exit + realized_pnl via applyPnL (analog TP-Hit T1 BUG-6).
  // close_reason wird in status mit-eingebaut: CLOSED_MANUAL/CLOSED_MAX_ITER/CLOSED.
  _close(dca_id, reason, dPre) {
    const d = dPre || DB.getDcaInstance.get(dca_id);
    if (!d) return null;
    let realizedPnl = 0;
    let exitPrice = null;
    // Inventory liquidation: nur wenn total_size > 0 (sonst nichts zu verkaufen)
    if (d.total_size && d.total_size > 0) {
      try {
        const ticker = (Bitget && Bitget.priceCache && Bitget.priceCache[d.symbol]) || null;
        exitPrice = ticker ? Number(ticker.last || ticker.lastPr || ticker.price || 0) : null;
        if (exitPrice && exitPrice > 0 && d.avg_buy_price > 0) {
          const grossPnl = (exitPrice - d.avg_buy_price) * d.total_size;
          const sellValue = exitPrice * d.total_size;
          const fees = (d.total_spent + sellValue) * (CFG.TAKER_FEE || 0.0006);
          realizedPnl = grossPnl - fees;
          // Apply to wallet (analog T1 BUG-6 für TP-Hit)
          if (typeof WalletProvider !== 'undefined' && WalletProvider.applyPnL) {
            const r = WalletProvider.applyPnL(realizedPnl, dca_id);
            try { Log.info('DCA_LIQ', `${d.symbol} _close(${reason}) liq @ ${exitPrice.toFixed(4)} pnl=${realizedPnl.toFixed(2)} → wallet ${r.ok ? 'OK' : 'FAIL '+r.reason}`); } catch(_) {}
          }
        }
      } catch(e) { try { Log.warn('DCA_LIQ', `${d.symbol} liquidation err: ${e.message}`); } catch(_) {} }
    }
    const statusFinal = reason === 'MAX_ITERATIONS_REACHED' ? 'CLOSED_MAX_ITER'
                      : reason === 'MANUAL'                 ? 'CLOSED_MANUAL'
                      :                                       'CLOSED';
    const meta = JSON.stringify({
      ...(d.meta?JSON.parse(d.meta):{}),
      close_reason: reason,
      liquidated_at_price: exitPrice,
      realized_pnl: realizedPnl,
    });
    DB.updateDcaInstance.run(d.avg_buy_price, d.total_size, d.total_spent, d.iteration,
      statusFinal, null, d.last_dd_pct, meta, Date.now(), Date.now(), dca_id);
    return { dca_id, status: statusFinal, reason, realized_pnl: realizedPnl, exit_price: exitPrice };
  },

  closeDca(dca_id, reason='MANUAL') { return this._close(dca_id, reason); },

  getPerformance(dca_id) {
    const d = DB.getDcaInstance.get(dca_id);
    if (!d) return null;
    const its = DB.listDcaIterations.all(dca_id);
    return {
      dca_id, symbol: d.symbol, status: d.status,
      avg_buy_price: d.avg_buy_price,
      total_size: d.total_size, total_spent: d.total_spent,
      iteration: d.iteration, max_iterations: d.max_iterations,
      target_profit_pct: d.target_profit_pct, max_dd_pct: d.max_dd_pct,
      last_dd_pct: d.last_dd_pct,
      iterations: its
    };
  },

  countActive() { return DB.countDcaOpen.get()?.n || 0; },

  // Wird vom Cycle aufgerufen — fällige Käufe ausführen.
  tickDue(getPriceFn) {
    const due = DB.listDcaDue.all(Date.now());
    const results = [];
    for (const d of due) {
      try {
        const price = getPriceFn ? getPriceFn(d.symbol) : null;
        if (price) results.push(this.scheduledBuy(d.dca_id, price));
      } catch(e) { results.push({ ok:false, dca_id:d.dca_id, error:e.message }); }
    }
    return results;
  },

  snapshot() {
    const open = DB.listDcaOpen.all(20);
    return {
      ok: true,
      open_dcas: open.length,
      dcas: open.map(d => ({ dca_id: d.dca_id, symbol: d.symbol,
        iter: d.iteration, max: d.max_iterations,
        avg: d.avg_buy_price, total_size: d.total_size, tp_pct: d.target_profit_pct }))
    };
  }
};

// ─────────────────────────────────────────────────────────────────────────────
// InfinityGridBotMBT — Trailing-Grid (Multi-BotType E, 16.05.2026)
// Erweitert GridBotMBT: range_high wird dynamisch nach oben angehoben
// (für BULL_WEAK mit Schwankungen). range_low bleibt statisch.
// Speicherung in grid_instances mit bot_type='INFGRID'.
// DEMO=LIVE: Logik identisch in beiden Modi.
// ─────────────────────────────────────────────────────────────────────────────
const InfinityGridBotMBT = {
  CFG: {
    NUM_LEVELS_DEFAULT:    10,
    EXTEND_TRIGGER_PCT:    0.01,  // wenn Preis innerhalb 1% von range_high → extend
    EXTEND_BY_PCT:         0.05,  // anheben um 5% des originalen Range
    MAX_EXTENSIONS:        20,
    DOWN_BREAK_PCT:        0.05,
    MIN_LEVEL_USDT:        2.5,
  },
  _genId() { return `INFGRID_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,8)}`; },

  create({ symbol, range_low, range_high, num_levels, capital_pool, dry_run, mid_price }) {
    if (range_low >= range_high) throw new Error('range_low must be < range_high');
    const n = Math.max(4, Math.min(50, num_levels | 0 || this.CFG.NUM_LEVELS_DEFAULT));
    const cap = Math.max(0, +capital_pool || 0);
    const perLevel = cap / n;
    if (perLevel < this.CFG.MIN_LEVEL_USDT) throw new Error(`per_level ${perLevel.toFixed(2)} < MIN_LEVEL_USDT`);
    const grid_id = this._genId();
    const now = Date.now();
    const mid = +mid_price || ((range_low + range_high) / 2);
    const origRange = range_high - range_low;
    const meta = { dry_run: !!dry_run, bot_type:'INFGRID', orig_range: origRange,
      extensions: 0, max_extensions: this.CFG.MAX_EXTENSIONS, mid_at_create: mid };

    if (!dry_run) {
      DB.insertGridInstance.run(grid_id, 'INFGRID', symbol, range_low, range_high, n, cap, perLevel,
        'OPEN', 0, 0, 0, JSON.stringify(meta), now, now);
    }

    // PUNKT 2 [25.05.2026]: MATH-FIX gleich wie GridBotMBT — siehe Z.9017.
    const stepBase = origRange / (n + 1);
    const levels = [];
    for (let i = 1; i <= n; i++) {
      const price = range_low + stepBase * i;
      const side = price < mid ? 'BUY' : 'SELL';
      const sizeCoins = perLevel / price;  // FIX: USDT/Level → Coin-Quantity
      levels.push({ level: i, side, price, size: sizeCoins });
      if (!dry_run) DB.insertGridOrder.run(grid_id, i, side, price, sizeCoins, 0, null, null, now);
    }
    return { grid_id, bot_type: 'INFGRID', symbol, range_low, range_high,
      num_levels: n, capital_pool: cap, per_level: perLevel, levels, dry_run: !!dry_run };
  },

  onPriceUpdate(grid_id, price) {
    const g = DB.getGridInstance.get(grid_id);
    if (!g || g.status !== 'OPEN' || g.bot_type !== 'INFGRID') return null;
    if ((g.paused | 0) === 1) return { grid_id, status: 'PAUSED' };

    // P1 [2026-06-03]: TICK_MAINTENANCE-Gate (Hard-Safety only) — Strategy-Veto greift NICHT.
    if (typeof _FinalRouter !== 'undefined' && _FinalRouter) {
      try {
        const _gate = _FinalRouter.gateExecution({
          sourceBot:'INFGRID', symbol:g.symbol, direction:'BUY',
          selectedStrategy:'GRID', operation:'TICK_MAINTENANCE',
          db:(DB && DB.db) ? DB.db : null,
        });
        if (!_gate.ok) {
          try { Log.warn('FINAL_VETO', _gate.logLine); } catch(_){}
          return { grid_id, status:'BLOCKED', reason:_gate.vetoReason, fillCount:0 };
        }
      } catch(_){}
    }

    const meta = g.meta ? JSON.parse(g.meta) : {};
    const extensions = meta.extensions || 0;
    const maxExt = meta.max_extensions || this.CFG.MAX_EXTENSIONS;

    // Down-Break: schließe Grid wenn deutlich unter range_low (EXIT-Pfad — kein Strategy-Veto)
    const breakLo = g.range_low * (1 - this.CFG.DOWN_BREAK_PCT);
    if (price < breakLo) return this._close(grid_id, `DOWN_BREAK price=${price} lo=${breakLo.toFixed(2)}`);

    // P1: Extension = NEUE Exposition (höhere SELL-Order) → operation='EXTENSION' (Strategy-Veto greift)
    const extTrigger = g.range_high * (1 + this.CFG.EXTEND_TRIGGER_PCT);
    if (price >= g.range_high && extensions < maxExt) {
      let _extAllowed = true;
      if (typeof _FinalRouter !== 'undefined' && _FinalRouter) {
        try {
          const _gateExt = _FinalRouter.gateExecution({
            sourceBot:'INFGRID', symbol:g.symbol, direction:'BUY',
            selectedStrategy:'GRID', operation:'EXTENSION',
            db:(DB && DB.db) ? DB.db : null,
          });
          if (!_gateExt.ok) {
            _extAllowed = false;
            try { Log.warn('FINAL_VETO', _gateExt.logLine); } catch(_){}
          }
        } catch(_){}
      }
      if (_extAllowed) {
        const newHigh = g.range_high + (meta.orig_range || (g.range_high - g.range_low)) * this.CFG.EXTEND_BY_PCT;
        const newMeta = { ...meta, extensions: extensions + 1, last_extend_ts: Date.now(), last_extend_price: price };
        // Neue SELL-Order auf newHigh oberhalb Original-Range
        const newLevel = g.num_levels + extensions + 1;
        DB.insertGridOrder.run(grid_id, newLevel, 'SELL', newHigh, g.per_level, 0, null, null, Date.now());
        DB.updateGridInstance.run('OPEN', g.profit_acc, g.fills_acc, g.range_breaks, g.range_low, newHigh,
          JSON.stringify(newMeta), Date.now(), grid_id);
        return { grid_id, action: 'EXTENDED', new_range_high: newHigh, extensions: extensions + 1 };
      }
      // Wenn Extension blockiert: weiter zu Fill-Checks (kein early return — Maintenance läuft)
    }

    // Normales Grid-Fill-Verhalten (analog GridBotMBT, vereinfacht)
    const fills = [];
    let fillCount = 0;
    let profitDelta = 0;
    // P1: BUY_FILL = neue Long-Exposition → operation='BUY_FILL' (Strategy-Veto greift)
    let _buyFillAllowedInf = true;
    if (typeof _FinalRouter !== 'undefined' && _FinalRouter) {
      try {
        const _gateBuyInf = _FinalRouter.gateExecution({
          sourceBot:'INFGRID', symbol:g.symbol, direction:'BUY',
          selectedStrategy:'GRID', operation:'BUY_FILL',
          db:(DB && DB.db) ? DB.db : null,
        });
        if (!_gateBuyInf.ok) {
          _buyFillAllowedInf = false;
          try { Log.warn('FINAL_VETO', _gateBuyInf.logLine); } catch(_){}
        }
      } catch(_){}
    }
    const buy = _buyFillAllowedInf ? DB.getNextUnfilledBuy.get(grid_id, price) : null;
    if (buy) {
      DB.updateGridOrderFill.run(Date.now(), price, buy.id);
      fills.push({ ...buy, fill_price: price, type: 'BUY_FILL' });
      fillCount++;
      // FIX-WALLET C [17.05.2026]: Ledger-Eintrag (defensiv)
      try {
        const curT = (DemoEngine?.wallet?.trading) || 0;
        const curTot = (DemoEngine?.wallet?.total) || 0;
        DB.insertLedger.run(Date.now(), 'GRID_BUY', buy.size * price,
          `INFGRID ${g.symbol} L${buy.level} BUY @ ${price.toFixed(4)}`,
          grid_id, curT, curT, curTot, curTot, 'DEMO');
      } catch(_){}
    }
    const sell = DB.getNextUnfilledSell.get(grid_id, price);
    if (sell) {
      DB.updateGridOrderFill.run(Date.now(), price, sell.id);
      fills.push({ ...sell, fill_price: price, type: 'SELL_FILL' });
      fillCount++;
      // FIX-WALLET C [17.05.2026]: Ledger-Eintrag (defensiv)
      try {
        const curT = (DemoEngine?.wallet?.trading) || 0;
        const curTot = (DemoEngine?.wallet?.total) || 0;
        DB.insertLedger.run(Date.now(), 'GRID_SELL', sell.size * price,
          `INFGRID ${g.symbol} L${sell.level} SELL @ ${price.toFixed(4)}`,
          grid_id, curT, curT, curTot, curTot, 'DEMO');
      } catch(_){}
      // FEE_WAHRHEIT [20.05.2026]: hardcoded 0.5% raus, echte Preis-Diff minus Round-Trip-Fees
      // Vorher: profitDelta += sell.size * 0.005 (Phantasiezahl, ignorierte echte Marktbewegung)
      // INFGRID hat dynamische range_high, step wie GRID berechnen
      const _stepInf = (g.range_high - g.range_low) / (g.num_levels + 1);
      const _buyPriceInf = Math.max(0, sell.price - _stepInf);
      const _grossProfitInf = sell.size * (sell.price - _buyPriceInf);
      const _feesInf = sell.size * sell.price * 2 * CFG.TAKER_FEE;
      profitDelta += (_grossProfitInf - _feesInf);
    }
    if (fillCount > 0) {
      DB.updateGridInstance.run('OPEN', (g.profit_acc||0) + profitDelta, (g.fills_acc||0) + fillCount,
        g.range_breaks, g.range_low, g.range_high, g.meta, Date.now(), grid_id);
      // FIX 3 [25.05.2026]: 70/30-Split per Fill-Cycle (analog GRID).
      if (Math.abs(profitDelta) > 0.01) {
        try {
          if (typeof WalletProvider !== 'undefined' && WalletProvider.applyPnL) {
            const r = WalletProvider.applyPnL(profitDelta, grid_id);
            if (r && !r.ok) { try { Log.warn('INFGRID_PNL', `${g.symbol} applyPnL fail: ${r.reason}`); } catch(_) {} }
          }
        } catch(e) { try { Log.warn('INFGRID_PNL', `${g.symbol} applyPnL err: ${e.message}`); } catch(_) {} }
      }
      // REGIME_HOOK [20.05.2026]: INFGRID identisch zu GRID
      if (Math.abs(profitDelta) > 0.01) {
        try {
          const _reg = (typeof Regime !== 'undefined' && Regime.regime) ? Regime.regime : 'UNKNOWN';
          const _durMin = Math.round((Date.now() - (g.created_at || Date.now())) / 60000);
          DB.db.prepare(`INSERT INTO strategy_regime_performance (ts, bot_type, regime, trade_id, pnl_usdt, duration_minutes, win) VALUES (?, ?, ?, ?, ?, ?, ?)`)
            .run(Date.now(), 'INFGRID', _reg, grid_id, profitDelta, _durMin, profitDelta > 0 ? 1 : 0);
        } catch(_) {}
      }
    }
    return { grid_id, fills, fillCount, profitDelta, status: 'OPEN' };
  },

  _close(grid_id, reason) {
    const g = DB.getGridInstance.get(grid_id);
    if (!g) return null;
    const meta = JSON.stringify({ ...(g.meta?JSON.parse(g.meta):{}), close_reason: reason });
    DB.updateGridInstance.run('CLOSED', g.profit_acc, g.fills_acc, g.range_breaks, g.range_low, g.range_high, meta, Date.now(), grid_id);
    return { grid_id, status: 'CLOSED', reason };
  },

  closeGrid(grid_id, reason='MANUAL') { return this._close(grid_id, reason); },

  getPerformance(grid_id) {
    const g = DB.getGridInstance.get(grid_id);
    if (!g) return null;
    const orders = DB.listGridOrders.all(grid_id);
    const meta = g.meta ? JSON.parse(g.meta) : {};
    return {
      grid_id, bot_type: g.bot_type, symbol: g.symbol, status: g.status,
      profit_acc: g.profit_acc, fills_acc: g.fills_acc,
      range_low: g.range_low, range_high: g.range_high,
      extensions: meta.extensions || 0,
      total_orders: orders.length, filled_orders: orders.filter(o=>o.filled).length
    };
  },

  countActive() { return DB.countGridsOpen.get('INFGRID')?.n || 0; },

  snapshot() {
    const open = DB.listGridsOpen.all(20);
    const infs = open.filter(g => g.bot_type === 'INFGRID');
    return { ok: true, open_infgrids: infs.length, infgrids: infs.map(g => ({
      grid_id: g.grid_id, symbol: g.symbol, range:[g.range_low, g.range_high],
      profit: g.profit_acc, fills: g.fills_acc,
      extensions: (g.meta?JSON.parse(g.meta).extensions||0:0)
    }))};
  }
};

// T1 [15.05.2026] AUTO-NOTBREMSE — DailyLossEmergencyStop
// Periodisch checken ob dailyPnl < CFG.AUTO_NOTBREMSE_DAILY_LOSS_USDT (-15)
// Bei Trigger: AUTONOMOUS_DEMO disable + Telegram-Alarm.
// Cycle 60s. Persist: gefeuert-Flag in-memory (resettet bei Tageswechsel).
const DailyLossEmergencyStop = {
  enabled: true,
  intervalMs: 60000,
  bootDelay: 120000,
  timer: null,
  lastCheck: null,
  _triggeredDay: null,  // toDateString() — verhindert Doppel-Trigger pro Tag
  stats: { runs: 0, triggers: 0 },

  start() {
    if (this.timer) return;
    setTimeout(() => {
      this.tick();
      this.timer = setInterval(() => this.tick(), this.intervalMs);
    }, this.bootDelay);
    try { Log.boot('DailyLossEmergencyStop started (60s, threshold ' + (CFG.AUTO_NOTBREMSE_DAILY_LOSS_USDT || -15) + ' USDT)'); } catch(_) {}
  },

  stop() { if (this.timer) { clearInterval(this.timer); this.timer = null; } },

  tick() {
    if (!this.enabled) return;
    this.stats.runs++;
    this.lastCheck = Date.now();
    try {
      const today = new Date().toDateString();
      if (this._triggeredDay === today) return;  // schon gefeuert heute

      // KOMPLETT-FIX I [17.05.2026]: MBT-aware dailyPnl
      // Realized = SINGLE-Trades + DCA-TP-Hits + Grid-SELL-BUY-Delta
      // Trigger nur bei REALIZED-Loss < threshold (DCA-Unrealized darf nicht stoppen)
      let dailyPnl = 0;
      let realizedComponents = { single: 0, dca: 0, grid: 0 };
      try {
        if (typeof computeDailyPnLMBT === 'function') {
          const dp = computeDailyPnLMBT();
          dailyPnl = dp.realized.total;  // NUR realized (DCA-DD darf nicht triggern)
          realizedComponents = dp.realized;
        } else if (typeof DemoEngine !== 'undefined' && DemoEngine.wallet) {
          dailyPnl = Number(DemoEngine.wallet.dailyPnl || 0);  // Fallback alte Logik
        }
      } catch(_) {
        if (typeof DemoEngine !== 'undefined' && DemoEngine.wallet) {
          dailyPnl = Number(DemoEngine.wallet.dailyPnl || 0);
        }
      }
      const threshold = CFG.AUTO_NOTBREMSE_DAILY_LOSS_USDT || -15;

      if (dailyPnl < threshold) {
        // Trigger
        this.stats.triggers++;
        this._triggeredDay = today;
        const breakdown = `S=${realizedComponents.single.toFixed(2)}/D=${realizedComponents.dca.toFixed(2)}/G=${realizedComponents.grid.toFixed(2)}`;
        try { Log.warn('NOTBREMSE', `AUTO-DISABLE realized-dailyPnl=${dailyPnl.toFixed(2)} (${breakdown}) < ${threshold} USDT`); } catch(_) {}
        try {
          DB.db.prepare("INSERT OR REPLACE INTO bot_settings (key, value, updated_at) VALUES ('autonomous_demo_trades_enabled', 'false', ?)")
            .run(Date.now());
        } catch(e) { try { Log.warn('NOTBREMSE', 'DB write failed: ' + e.message); } catch(_){} }
        try {
          if (typeof TelegramAlarm !== 'undefined' && TelegramAlarm.alert) {
            TelegramAlarm.alert('CRITICAL', 'AUTO_NOTBREMSE',
              `🚨 realized-dailyPnl ${dailyPnl.toFixed(2)} USDT (${breakdown}) < ${threshold} — AUTONOMOUS_DEMO disabled`);
          }
        } catch(_) {}
        try {
          DB.db.prepare(
            'INSERT INTO consistency_log (ts, severity, check_name, issue, auto_fixed, details) VALUES (?,?,?,?,?,?)'
          ).run(Date.now(), 'CRITICAL', 'auto_notbremse',
                `realized-dailyPnl ${dailyPnl.toFixed(2)} (${breakdown}) < ${threshold}`, 1,
                JSON.stringify({ dailyPnl, threshold, components: realizedComponents }));
        } catch(_) {}
      }
    } catch(e) {
      try { Log.warn('NOTBREMSE', 'tick err: ' + e.message); } catch(_) {}
    }
  },

  snapshot() {
    return {
      enabled: this.enabled,
      lastCheck: this.lastCheck,
      triggeredToday: this._triggeredDay === new Date().toDateString(),
      threshold: CFG.AUTO_NOTBREMSE_DAILY_LOSS_USDT || -15,
      stats: { ...this.stats },
    };
  },
};

// ─────────────────────────────────────────────────────────────────────────────
// MBTTicker — Multi-BotType Tick-Loop (MBT-FIX D, 16.05.2026)
//
// PROBLEM: Im DemoEngine._cycle gibt es einen HOLD-Gate
//   `if (uScore.blocked || uScore.direction === 'HOLD') continue;`
// der MBT-Ticking für Symbole im HOLD-Status verhindert.
// → DCA-Instanzen hängen bei iteration=0, Grid-Fills werden verpasst.
//
// LÖSUNG: Separater Ticker (30s-Intervall), läuft INDEPENDENT vom Cycle.
// Iteriert offene grid_instances + dca_instances, tickt onPriceUpdate/
// scheduledBuy/checkExit pro Instanz. Universal Hard-Blocks (SHARPE_EXTREME
// < -3.0, MONTE_CARLO_VaR > 0.25) bleiben respektiert über pre-Tick-Check.
//
// CREATE bleibt in _cycle (Pipeline B), nur TICK ist im MBTTicker.
// ─────────────────────────────────────────────────────────────────────────────
const MBTTicker = {
  enabled: true,
  intervalMs: 30000,   // 30s
  bootDelay: 60000,    // 1min nach Boot
  timer: null,
  busy: false,
  stats: { ticks: 0, gridFills: 0, dcaBuys: 0, dcaTpHits: 0, blocked: 0, errors: 0 },
  _lastTick: 0,

  start() {
    if (this.timer) return;
    setTimeout(() => {
      this.timer = setInterval(() => this._tick().catch(()=>{}), this.intervalMs);
      try { Log.boot('MBTTicker gestartet (alle ' + (this.intervalMs/1000) + 's, MBT-Instances ticken unabhängig vom Cycle-HOLD-Gate)'); } catch(_){}
    }, this.bootDelay);
  },
  stop() { if (this.timer) { clearInterval(this.timer); this.timer = null; } },

  // Universal Hard-Block-Check: blockt MBT-Tick wenn Sym crash-Zone.
  // Quelle: Bitget.priceCache (Live-Preis OK), aber Sharpe-Calc braucht Candles.
  // Vereinfachung: prüfe das LETZTE aladdin_decisions für Symbol — ist es HOLD via SHARPE_EXTREME?
  // Wenn ja: skip Tick (keine neuen Buys/Fills) bis Sharpe sich erholt.
  _shouldBlockTick(symbol) {
    try {
      const row = DB.db.prepare(`
        SELECT decision, reason FROM aladdin_decisions
        WHERE symbol=? AND ts > ?
        ORDER BY ts DESC LIMIT 1
      `).get(symbol, Date.now() - 5 * 60 * 1000);  // letzte 5 Min
      if (!row) return false;
      if (row.decision !== 'HOLD') return false;
      const reason = String(row.reason || '');
      // Extrahiere Sharpe-Wert (falls vorhanden) für UI-Anzeige
      const sharpeMatch = reason.match(/SHARPE_EXTREME:(-?\d+\.?\d*)/);
      if (reason.includes('SHARPE_EXTREME')) return { reason: 'SHARPE_EXTREME', value: sharpeMatch ? sharpeMatch[1] : null };
      const mcMatch = reason.match(/MONTE_CARLO_VaR_TOO_HIGH:(-?\d+\.?\d*%)/);
      if (reason.includes('MONTE_CARLO_VaR_TOO_HIGH')) return { reason: 'MC_VaR', value: mcMatch ? mcMatch[1] : null };
      if (reason.includes('ANOMALY_DETECTED')) return { reason: 'ANOMALY', value: null };
      return false;
    } catch(_) { return false; }
  },

  async _tick() {
    if (!this.enabled || this.busy) return;
    this.busy = true;
    try {
      this.stats.ticks++;
      this._lastTick = Date.now();
      const priceCache = (typeof Bitget !== 'undefined') ? Bitget.priceCache : {};

      // ── GRID/INFGRID Ticking ──
      try {
        const grids = DB.listGridsOpen.all(50);
        for (const g of grids) {
          const tk = priceCache[g.symbol];
          if (!tk || !tk.last) continue;
          const price = +tk.last;
          // Universal Hard-Block-Check (skip Fills bei Crash)
          const block = this._shouldBlockTick(g.symbol);
          if (block) {
            this.stats.blocked++;
            continue;
          }
          try {
            const Bot = (g.bot_type === 'INFGRID') ? InfinityGridBotMBT : GridBotMBT;
            const r = Bot.onPriceUpdate(g.grid_id, price);
            if (r && r.fillCount > 0) {
              this.stats.gridFills += r.fillCount;
              Log.info('MBTTicker', `${g.symbol} ${g.bot_type} grid=${g.grid_id} fills=${r.fillCount}`);
            } else if (r && r.status === 'CLOSED') {
              Log.info('MBTTicker', `${g.symbol} ${g.bot_type} grid=${g.grid_id} CLOSED (${r.reason})`);
            }
          } catch(e) {
            this.stats.errors++;
            try { Log.warn('MBTTicker', `grid ${g.grid_id} tick err: ${e.message}`); } catch(_){}
          }
        }
      } catch(e) { this.stats.errors++; }

      // ── DCA Ticking ──
      try {
        const dcas = DB.listDcaOpen.all(50);
        for (const d of dcas) {
          const tk = priceCache[d.symbol];
          if (!tk || !tk.last) continue;
          const price = +tk.last;

          // MBT-UI D [16.05.2026]: paused = Buys aussetzen, TP-Check aber weiter
          const isPaused = (d.paused | 0) === 1;

          // TP-Check IMMER (verkauft bei Gewinn — kein Hard-Block-Skip, auch pausiert)
          try {
            const exit = DCABotMBT.checkExit(d.dca_id, price);
            if (exit && exit.exit) {
              this.stats.dcaTpHits++;
              Log.info('MBTTicker', `${d.symbol} DCA dca=${d.dca_id} TP_HIT @ ${price.toFixed(4)} realized=${exit.realized_pnl?.toFixed(2)}`);
              continue;
            }
          } catch(e) { this.stats.errors++; }

          if (isPaused) {
            // Pause hat Vorrang: wait_reason updaten
            try { DB.setDcaBlock.run('PAUSED_BY_USER', null, Date.now(), d.dca_id); } catch(_){}
            this.stats.blocked++;
            continue;
          }

          // Buy-Check NUR wenn nicht im Hard-Block
          if (d.next_buy_at && d.next_buy_at <= Date.now() && d.status === 'OPEN') {
            const block = this._shouldBlockTick(d.symbol);
            if (block) {
              // MBT-UI D [16.05.2026]: persistiere Block-Reason für UI-Anzeige
              try { DB.setDcaBlock.run(block.reason, block.value || null, Date.now(), d.dca_id); } catch(_){}
              this.stats.blocked++;
              continue;
            }
            try {
              const r = DCABotMBT.scheduledBuy(d.dca_id, price);
              if (r && r.ok) {
                this.stats.dcaBuys++;
                // Block-Reason aufräumen (Buy erfolgreich)
                try { DB.clearDcaBlock.run(d.dca_id); } catch(_){}
                Log.info('MBTTicker', `${d.symbol} DCA dca=${d.dca_id} BUY #${r.iteration} @ ${price.toFixed(4)} avg=${r.avg_buy_price.toFixed(4)} dd=${(r.dd*100).toFixed(1)}%`);
              } else if (r && r.reason === 'MAX_DD_HIT') {
                try { DB.setDcaBlock.run('MAX_DD_HIT', (r.dd*100).toFixed(2), Date.now(), d.dca_id); } catch(_){}
                Log.info('MBTTicker', `${d.symbol} DCA dca=${d.dca_id} DD_STOPPED dd=${(r.dd*100).toFixed(1)}%`);
              }
            } catch(e) {
              this.stats.errors++;
              try { Log.warn('MBTTicker', `dca ${d.dca_id} buy err: ${e.message}`); } catch(_){}
            }
          }
        }
      } catch(e) { this.stats.errors++; }
    } finally {
      this.busy = false;
    }
  },

  snapshot() {
    return {
      enabled: this.enabled,
      intervalMs: this.intervalMs,
      lastTick: this._lastTick,
      lastTickAgo: this._lastTick ? Date.now() - this._lastTick : null,
      busy: this.busy,
      stats: { ...this.stats },
    };
  }
};

// B.1 [14.05.2026] POSITION-STATE-DRIFT-DETECTOR
// Detection-only (NO silent-fix). Cycle 60s.
// Vergleicht RAM (DemoEngine.positions) vs DB (trades WHERE state=POSITION_ACTIVE).
// Pro-Position: Entry-Price numeric drift > 1% → Alert + AUTONOMOUS_DEMO pause.
// Kein Auto-Cleanup — bewusst getrennt von ConsistencyGuardian (Z.5273).
// ═════════════════════════════════════════════════════════════════════════════
const PositionStateDriftDetector = {
  enabled:    true,
  intervalMs: 60000,
  bootDelay:  150000,
  timer:      null,
  lastCheck:  null,
  lastDrift:  null,
  paused:     false,
  THRESHOLDS: {
    pricePctMax: 0.01,
    countDiffMax: 0,
  },
  stats: {
    runs: 0,
    drifts_detected: 0,
    pauses_triggered: 0,
    count_mismatches: 0,
    price_drifts: 0,
  },

  start() {
    if (this.timer) return;
    setTimeout(() => {
      this.tick();
      this.timer = setInterval(() => this.tick(), this.intervalMs);
    }, this.bootDelay);
    try { Log.boot('PositionStateDriftDetector started (60s interval, 2.5min boot delay)'); } catch(_){}
  },

  stop() {
    if (this.timer) { clearInterval(this.timer); this.timer = null; }
  },

  async tick() {
    if (!this.enabled) return;
    this.stats.runs++;
    this.lastCheck = Date.now();
    const findings = [];

    try {
      const ramPos = (typeof DemoEngine !== 'undefined' && DemoEngine.positions)
        ? Object.values(DemoEngine.positions) : [];
      const dbActive = (typeof Trades !== 'undefined' && Trades.getActive)
        ? Trades.getActive().filter(t => t.strategy && t.strategy.startsWith('DEMO_')) : [];

      const countDiff = Math.abs(ramPos.length - dbActive.length);
      if (countDiff > this.THRESHOLDS.countDiffMax) {
        findings.push({
          type: 'COUNT_DRIFT',
          ram: ramPos.length,
          db: dbActive.length,
          diff: countDiff,
        });
        this.stats.count_mismatches++;
      }

      for (const p of ramPos) {
        const db = dbActive.find(t => t.id === p.dbTradeId);
        if (!db) continue;
        if (!db.entry_price || !p.fillPrice) continue;
        const ramP = Number(p.fillPrice);
        const dbP = Number(db.entry_price);
        if (!ramP || !dbP) continue;
        const denom = Math.max(Math.abs(ramP), Math.abs(dbP));
        const pct = Math.abs(ramP - dbP) / denom;
        if (pct > this.THRESHOLDS.pricePctMax) {
          findings.push({
            type: 'PRICE_DRIFT',
            symbol: p.symbol,
            dbTradeId: p.dbTradeId,
            ramFill: ramP,
            dbEntry: dbP,
            pct: Number(pct.toFixed(6)),
          });
          this.stats.price_drifts++;
        }
      }

      this.lastDrift = findings.length > 0 ? findings : null;

      if (findings.length > 0) {
        this.stats.drifts_detected++;
        try {
          DB.db.prepare(
            'INSERT INTO consistency_log (ts, severity, check_name, issue, auto_fixed, details) VALUES (?,?,?,?,?,?)'
          ).run(Date.now(), 'CRITICAL', 'position_state_drift',
            findings.map(f => f.type).join(','), 0,
            JSON.stringify(findings).slice(0, 800));
        } catch(_) {}

        try {
          DB.db.prepare("INSERT OR REPLACE INTO bot_settings (key, value, updated_at) VALUES ('autonomous_demo_trades_enabled', 'false', ?)")
            .run(Date.now());
          this.paused = true;
          this.stats.pauses_triggered++;
          try { Log.warn('DRIFT', `AUTONOMOUS_DEMO paused: ${findings.length} finding(s)`); } catch(_) {}
        } catch(_) {}

        try {
          if (typeof TelegramAlarm !== 'undefined' && TelegramAlarm.alert) {
            const msg = `🚨 POSITION-STATE-DRIFT\n${findings.slice(0, 5).map(f => {
              if (f.type === 'COUNT_DRIFT') return `Count: RAM=${f.ram} vs DB=${f.db}`;
              return `${f.symbol}: RAM=${f.ramFill} vs DB=${f.dbEntry} (${(f.pct*100).toFixed(2)}%)`;
            }).join('\n')}\n→ AUTONOMOUS_DEMO paused`;
            TelegramAlarm.alert('CRITICAL', 'DRIFT_DETECTED', msg);
          }
        } catch(_) {}
      }
    } catch(e) {
      try { Log.warn('DriftDetector', `tick error: ${e.message}`); } catch(_) {}
    }
  },

  snapshot() {
    return {
      enabled: this.enabled,
      paused: this.paused,
      lastCheck: this.lastCheck,
      lastCheckAge_s: this.lastCheck ? Math.floor((Date.now() - this.lastCheck) / 1000) : null,
      lastDrift: this.lastDrift,
      thresholds: { ...this.THRESHOLDS },
      stats: { ...this.stats },
    };
  },
};


// ═════════════════════════════════════════════════════════════════════════════
// PROFIT-OPTIMIZER KI — Dynamische SL/TP/Sizing basierend auf echten Ergebnissen
// < 30 Trades: Festwerte (CFG). >= 30 Trades: KI optimiert. Bei Fehler: Fallback.
// ═════════════════════════════════════════════════════════════════════════════
const ProfitOptimizer = {
  enabled: true,
  minTrades: 30,
  lastCalc: null,
  calcInterval: 3600000, // 1h
  current: null, // aktuelle optimierte Werte

  // Grenzen — KI darf nie ausserhalb dieser Werte
  LIMITS: {
    atrSL:    { min: 1.0, max: 2.5 },
    atrTP:    { min: 1.8, max: 4.0 },
    trailing: { min: 0.01, max: 0.05 },
    sizePct:  { min: 0.03, max: 0.25 },
    minRR:    2.0,  // R/R nie unter 2:1
  },

  FEES: {
    maker: 0.0002,
    taker: 0.0006,
    slippage: 0.0005,
    total: 0.0008, // 0.08% round-trip (CFG.MAKER+TAKER)
  },

  // Hauptfunktion: Berechne optimale Werte aus Trade-Historie
  calculate() {
    try {
      const allTrades = DB.getAllTrades.all().filter(t => t.state === 'CLOSED' && t.realized_pnl !== null);
      if (allTrades.length < this.minTrades) {
        this.current = null;
        return { mode: 'FESTWERTE', reason: allTrades.length + '/' + this.minTrades + ' Trades', trades: allTrades.length };
      }

      // Letzte 100 Trades analysieren
      const recent = allTrades.slice(-100);
      const wins = recent.filter(t => t.realized_pnl > 0);
      const losses = recent.filter(t => t.realized_pnl < 0);
      const winRate = wins.length / recent.length;

      // Durchschnittliche Gewinn/Verlust Groessen
      const avgWin = wins.length > 0 ? wins.reduce((s, t) => s + t.realized_pnl, 0) / wins.length : 0;
      const avgLoss = losses.length > 0 ? Math.abs(losses.reduce((s, t) => s + t.realized_pnl, 0) / losses.length) : 1;
      const currentRR = avgLoss > 0 ? avgWin / avgLoss : 1;

      // Wie wurden Trades geschlossen?
      const exitReasons = {};
      recent.forEach(t => { const r = t.exit_reason || 'UNKNOWN'; exitReasons[r] = (exitReasons[r] || 0) + 1; });

      // SL zu oft getriggert? → SL weiter setzen
      const slHits = (exitReasons['STOP_LOSS'] || 0) / recent.length;
      // TP zu selten erreicht? → TP enger setzen
      const tpHits = (exitReasons['TAKE_PROFIT'] || 0) / recent.length;
      // Trailing zu frueh? → Trailing weiter
      const trailHits = (exitReasons['TRAILING_STOP'] || 0) / recent.length;
      // Zeit-Exits? → Trades laufen zu lang ohne Ergebnis
      const timeHits = (exitReasons['TIME_EXIT'] || 0) / recent.length;

      // Dynamische Anpassung
      let atrSL = CFG.ATR_STOP_MULT;
      let atrTP = CFG.ATR_TP_MULT;
      let trailing = CFG.TRAILING_PCT;

      // SL zu oft getriggert (> 40% aller Exits) → weiter
      if (slHits > 0.40) atrSL = Math.min(this.LIMITS.atrSL.max, atrSL + 0.3);
      // SL fast nie getriggert (< 15%) → enger (spart Verluste)
      if (slHits < 0.15 && losses.length > 3) atrSL = Math.max(this.LIMITS.atrSL.min, atrSL - 0.2);

      // TP zu selten erreicht (< 20%) → enger
      if (tpHits < 0.20 && wins.length > 3) atrTP = Math.max(this.LIMITS.atrTP.min, atrTP - 0.3);
      // TP oft erreicht (> 50%) → weiter (mehr rausholen)
      if (tpHits > 0.50) atrTP = Math.min(this.LIMITS.atrTP.max, atrTP + 0.3);

      // Trailing zu oft (> 30%) → weiter
      if (trailHits > 0.30) trailing = Math.min(this.LIMITS.trailing.max, trailing + 0.005);
      // Trailing fast nie → enger
      if (trailHits < 0.05 && wins.length > 5) trailing = Math.max(this.LIMITS.trailing.min, trailing - 0.003);

      // R/R Check: TP/SL muss >= 2.0 sein
      if (atrTP / atrSL < this.LIMITS.minRR) {
        atrTP = atrSL * this.LIMITS.minRR;
      }

      // Clamp
      atrSL = Math.max(this.LIMITS.atrSL.min, Math.min(this.LIMITS.atrSL.max, atrSL));
      atrTP = Math.max(this.LIMITS.atrTP.min, Math.min(this.LIMITS.atrTP.max, atrTP));
      trailing = Math.max(this.LIMITS.trailing.min, Math.min(this.LIMITS.trailing.max, trailing));

      // Sizing: basierend auf Win-Rate und R/R
      // Kelly Criterion: f = (WR * RR - (1-WR)) / RR
      const rr = atrTP / atrSL;
      const kelly = Math.max(0, (winRate * rr - (1 - winRate)) / rr);
      const sizePct = Math.max(this.LIMITS.sizePct.min, Math.min(this.LIMITS.sizePct.max, kelly * 0.5));

      // Expectancy berechnen
      const avgATR = 0.008; // ~0.8% fuer BTC 1H
      const tpPct = atrTP * avgATR;
      const slPct = atrSL * avgATR;
      const expectancy = winRate * (tpPct - this.FEES.total) - (1 - winRate) * (slPct + this.FEES.total);

      this.current = {
        atrSL: parseFloat(atrSL.toFixed(2)),
        atrTP: parseFloat(atrTP.toFixed(2)),
        trailing: parseFloat(trailing.toFixed(4)),
        sizePct: parseFloat(sizePct.toFixed(4)),
        rr: parseFloat(rr.toFixed(2)),
        winRate: parseFloat(winRate.toFixed(4)),
        expectancy: parseFloat(expectancy.toFixed(6)),
        kelly: parseFloat(kelly.toFixed(4)),
        exitProfile: exitReasons,
        avgWin: parseFloat(avgWin.toFixed(4)),
        avgLoss: parseFloat(avgLoss.toFixed(4)),
        trades: recent.length,
      };

      this.lastCalc = Date.now();

      Log.info('PROFIT_KI', 'Optimiert: SL=' + atrSL.toFixed(2) + ' TP=' + atrTP.toFixed(2) + ' Trail=' + (trailing*100).toFixed(1) + '% Size=' + (sizePct*100).toFixed(1) + '% RR=' + rr.toFixed(2) + ' WR=' + (winRate*100).toFixed(1) + '% Exp=' + (expectancy*10000).toFixed(1) + 'bps');

      return { mode: 'KI_OPTIMIERT', ...this.current };
    } catch (e) {
      Log.warn('PROFIT_KI', 'Fehler: ' + e.message + ' — Fallback auf Festwerte');
      this.current = null;
      return { mode: 'FESTWERTE', reason: 'Fehler: ' + e.message };
    }
  },

  // Getter: aktuelle Werte (KI oder Fallback)
  getATR_SL() { return this.current ? this.current.atrSL : CFG.ATR_STOP_MULT; },
  getATR_TP() { return this.current ? this.current.atrTP : CFG.ATR_TP_MULT; },
  getTrailing() { return this.current ? this.current.trailing : CFG.TRAILING_PCT; },
  getSizePct() { return this.current ? this.current.sizePct : null; },

  snapshot() {
    return {
      enabled: this.enabled,
      mode: this.current ? 'KI_OPTIMIERT' : 'FESTWERTE',
      current: this.current,
      lastCalc: this.lastCalc,
      minTrades: this.minTrades,
      limits: this.LIMITS,
      fees: this.FEES,
      fallback: { atrSL: CFG.ATR_STOP_MULT, atrTP: CFG.ATR_TP_MULT, trailing: CFG.TRAILING_PCT },
    };
  },

  // Periodisch neu berechnen
  start() {
    this.calculate();
    setInterval(() => this.calculate(), this.calcInterval);
    Log.boot('ProfitOptimizer-KI gestartet (Recalc alle ' + (this.calcInterval/60000) + 'min)');
  },
};



// ═════════════════════════════════════════════════════════════════════════════
// STALE ORDER CLEANER — Raeumt haengende Trades/Orders auf
// ═════════════════════════════════════════════════════════════════════════════
const StaleOrderCleaner = {
  timer: null,
  interval: 1800000, // 30min
  maxAgeHours: null, // wird aus CFG geladen
  cleaned: [],

  async run() {
    const maxAge = (CFG.MAX_HOLD_HOURS || 48) * 3600000;
    const now = Date.now();
    let count = 0;

    try {
      const active = Trades.getActive();
      for (const trade of active) {
        const age = now - (trade.created_at || 0);
        const ageH = (age / 3600000).toFixed(1);
        let doClose = null; // 'STALE_CLEANUP_TIME' | 'STALE_ORPHAN' | null

        if (age > maxAge) doClose = 'STALE_CLEANUP_TIME';
        else if (trade.strategy === 'DEMO_UNIFIED') {
          // STALE-FILE-FALLBACK [2026-05-07]: Pruefe RAM + File (gegen Drift-Bug)
          const inRAM = Object.values(DemoEngine.positions || {}).some(p => p.dbTradeId === trade.id);
          let inFile = false;
          if (!inRAM) {
            try {
              const fs = require('fs');
              const path = require('path');
              const fp = path.join(__dirname, DemoEngine._positionsFile);
              if (fs.existsSync(fp)) {
                const fileData = JSON.parse(fs.readFileSync(fp, 'utf8'));
                inFile = Object.values(fileData || {}).some(p => p.dbTradeId === trade.id);
              }
            } catch(_) {}
          }
          const inMemory = inRAM || inFile;
          if (!inMemory && age > 600000) {
            doClose = 'STALE_ORPHAN';
            try { Log.warn('STALE', 'ORPHAN-Trigger: '+trade.id+' (RAM='+inRAM+' File='+inFile+' age='+(age/60000).toFixed(0)+'min)'); } catch(_) {}
          }
        }
        if (!doClose) continue;

        try {
          // --- Echten Schluss-Preis holen (statt 0) ---
          let exitPrice = 0;
          try {
            const ticker = Bitget.priceCache && Bitget.priceCache[trade.symbol];
            if (ticker && ticker.last > 0) exitPrice = ticker.last;
            else {
              const t2 = await Bitget.fetchTicker(trade.symbol).catch(() => null);
              if (t2 && t2.last > 0) exitPrice = t2.last;
            }
          } catch(_){}
          if (!exitPrice && trade.entry_price) exitPrice = trade.entry_price; // Fallback: PnL=0

          // --- Echten PnL berechnen ---
          const entry = trade.entry_price || 0;
          const size  = trade.size || 0;
          const dir   = (trade.side === 'sell' || trade.side === 'SELL') ? -1 : 1;
          const gross = entry > 0 ? (dir * (exitPrice - entry) / entry) * size : 0;
          const fees  = size * (CFG.MAKER_FEE + CFG.TAKER_FEE);
          const pnl   = gross - fees;

          // Phase 3.8: Trades.close() macht alles - PnL-Berechnung, Wallet, PerfTracker, RL
          // Wir nutzen es statt eigener Buchung -> strategy_performance wird gefuellt
          try {
            Trades.close(trade.id, exitPrice, doClose);
            // In-memory DemoEngine-Position auch schliessen (falls noch da)
            if (trade.strategy === 'DEMO_UNIFIED' && !DemoEngine.liveMode) {
              let didDelete = false;
              for (const [pid, pos] of Object.entries(DemoEngine.positions||{})) {
                if (pos.dbTradeId === trade.id) { delete DemoEngine.positions[pid]; didDelete = true; break; }
              }
              // PERSIST-AFTER-DELETE-FIX [2026-05-07]: File-Persist nach Delete (gegen STALE_ORPHAN-Bug)
              if (didDelete) { try { _persistDemoPositions(); } catch(e) { try { Log.warn('POSITIONS_PERSIST', 'didDelete-persist fail: ' + e.message); } catch(_) {} } }
            }
          } catch(e){ try{Log.warn('STALE','close err: '+e.message);}catch(_){} }

          this.cleaned.unshift({ ts: now, id: trade.id, symbol: trade.symbol, reason: doClose, age: ageH + 'h', exitPrice, pnl });
          count++;
          Log.warn('STALE', 'Trade '+trade.symbol+' geschlossen ('+doClose+') age='+ageH+'h exit='+exitPrice.toFixed(4)+' pnl='+pnl.toFixed(4));

          // --- Live-Feed ---
          try { ActionStream.push('EXIT', trade.symbol, doClose+' (cleaner) PnL='+pnl.toFixed(4)+' USDT', { reason:doClose, pnl, exitPrice, cleaner:true }); } catch(_){}
        } catch(e){ try{Log.warn('StaleOrderCleaner','close err: '+e.message);}catch(_){} }
      }

      if (count > 0) TelegramBot.send('🧹 Stale Cleaner: '+count+' haengende Trades bereinigt (mit echten Preisen)');
      if (this.cleaned.length > 50) this.cleaned = this.cleaned.slice(0, 50);
    } catch (e) {
      Log.warn('STALE', 'Cleaner Fehler: ' + e.message);
    }

    return { cleaned: count, total: this.cleaned.length };
  },

  start() {
    if (this.timer) return;
    // Erster Run nach 60s (gibt DemoEngine Zeit zu starten)
    setTimeout(() => this.run(), 60000);
    this.timer = setInterval(() => this.run(), this.interval);
    Log.boot('StaleOrderCleaner gestartet (alle 30min)');
  },

  snapshot() {
    return {
      interval: this.interval,
      maxAge: (CFG.MAX_HOLD_HOURS || 48) + 'h',
      recentCleaned: this.cleaned.slice(0, 20),
      totalCleaned: this.cleaned.length,
    };
  },
};


// ═════════════════════════════════════════════════════════════════════════════
// ═════════════════════════════════════════════════════════════════════════════
// RISK TIER — Stufenweiser LIVE-Einstieg (SaintQuant-inspired).
// Inaktiv in DEMO (normale Demo-Statistik) -- wirkt nur in LIVE oder DryRun.
// Drei Tiers: SAFE -> STANDARD -> AGGRESSIVE mit auto-Promotion.
// ═════════════════════════════════════════════════════════════════════════════
const RiskTier = {
  TIERS: {
    TIER_SAFE: {
      label: 'SAFE', minSize: 5, maxSize: 20,
      maxDailyDDPct: 0.02, maxConcurrentPos: 2,
      promotionTrades: 50, promotionWinRate: 0.50,
    },
    TIER_STANDARD: {
      label: 'STANDARD', minSize: 10, maxSize: 50,
      maxDailyDDPct: 0.04, maxConcurrentPos: 4,
      promotionTrades: 100, promotionWinRate: 0.55,
    },
    TIER_AGGRESSIVE: {
      label: 'AGGRESSIVE', minSize: 20, maxSize: 200,
      maxDailyDDPct: 0.07, maxConcurrentPos: 6,
      promotionTrades: Infinity, promotionWinRate: 1.0,
    },
  },
  current: 'TIER_SAFE',
  history: [],
  dryRun: { active:false, simulatedDailyLoss:0, simulatedOpenPositions:0, log:[] },

  activeTier() { return this.TIERS[this.current] || this.TIERS.TIER_SAFE; },
  shouldApply() { return (DemoEngine && DemoEngine.liveMode) || this.dryRun.active; },

  maxPositions() {
    if (!this.shouldApply()) return Infinity;
    return this.activeTier().maxConcurrentPos;
  },

  checkDailyDD() {
    if (!this.shouldApply()) return true;
    const t = this.activeTier();
    const startCap = (DemoEngine.wallet && DemoEngine.wallet.startTotal) || 1000;
    const dailyPnl = this.dryRun.active ? -this.dryRun.simulatedDailyLoss : ((DemoEngine.wallet && DemoEngine.wallet.dailyPnl) || 0);
    const ddPct = dailyPnl / startCap;
    const ok = ddPct > -t.maxDailyDDPct;
    if (!ok && this.dryRun.active) this.dryRun.log.push({ t:Date.now(), event:'DD_BLOCK', ddPct, limit:-t.maxDailyDDPct });
    return ok;
  },

  capSize(proposedSize) {
    if (!this.shouldApply()) return proposedSize;
    const t = this.activeTier();
    const capped = Math.max(t.minSize, Math.min(proposedSize, t.maxSize));
    if (capped !== proposedSize) {
      try { Log.info('RISKTIER','Size '+proposedSize.toFixed(2)+' -> '+capped.toFixed(2)+' ('+t.label+')'); } catch(_){}
      try { ActionStream.push('INFO','RISKTIER','Size capped '+proposedSize.toFixed(2)+' -> '+capped.toFixed(2)+' ['+t.label+']', {from:proposedSize,to:capped,tier:t.label}); } catch(_){}
      if (this.dryRun.active) this.dryRun.log.push({ t:Date.now(), event:'SIZE_CAP', from:proposedSize, to:capped });
    }
    return capped;
  },

  checkPromotion() {
    const t = this.activeTier();
    if (t.promotionTrades === Infinity) return { promoted:false, reason:'max tier', current:this.current };
    const stats = (DemoEngine && DemoEngine.stats) || { trades:0, wins:0 };
    const wr = stats.trades > 0 ? (stats.wins || 0) / stats.trades : 0;
    if (stats.trades >= t.promotionTrades && wr >= t.promotionWinRate) {
      const nextMap = { TIER_SAFE:'TIER_STANDARD', TIER_STANDARD:'TIER_AGGRESSIVE' };
      const next = nextMap[this.current];
      if (next) {
        this.history.push({ ts:Date.now(), from:this.current, to:next, trades:stats.trades, wr });
        this.current = next;
        try { Log.info('RISKTIER','Promoted '+this.current+' (trades='+stats.trades+', WR='+(wr*100).toFixed(1)+'%)'); } catch(_){}
        try { TelegramBot.send('RiskTier UPGRADE: '+this.current+' (trades='+stats.trades+', WR='+(wr*100).toFixed(1)+'%)'); } catch(_){}
        return { promoted:true, to:next, trades:stats.trades, wr };
      }
    }
    return { promoted:false, current:this.current, trades:stats.trades, wr, required:t.promotionTrades, requiredWR:t.promotionWinRate };
  },

  setTier(name) {
    if (!this.TIERS[name]) return { error:'unknown tier: '+name+' (must be TIER_SAFE/TIER_STANDARD/TIER_AGGRESSIVE)' };
    this.history.push({ ts:Date.now(), from:this.current, to:name, manual:true });
    this.current = name;
    return { ok:true, current:name };
  },

  snapshot() {
    const t = this.activeTier();
    return {
      current: this.current, label: t.label, config: t,
      shouldApply: this.shouldApply(),
      mode: (DemoEngine && DemoEngine.liveMode) ? 'LIVE' : 'DEMO',
      dryRun: this.dryRun.active ? {
        active:true,
        simulatedDailyLoss: this.dryRun.simulatedDailyLoss,
        simulatedOpenPositions: this.dryRun.simulatedOpenPositions,
        log: this.dryRun.log.slice(-30),
      } : { active:false },
      history: this.history.slice(-10),
      tiers: Object.keys(this.TIERS),
    };
  },

  enableDryRun(opts) {
    opts = opts || {};
    this.dryRun.active = true;
    this.dryRun.simulatedDailyLoss = opts.simulatedDailyLoss || 0;
    this.dryRun.simulatedOpenPositions = opts.simulatedOpenPositions || 0;
    this.dryRun.log = [];
    try { Log.info('RISKTIER','DryRun AKTIVIERT (simDailyLoss='+this.dryRun.simulatedDailyLoss+', simOpenPos='+this.dryRun.simulatedOpenPositions+')'); } catch(_){}
    return this.snapshot();
  },
  disableDryRun() {
    this.dryRun.active = false;
    try { Log.info('RISKTIER','DryRun AUS'); } catch(_){}
    return this.snapshot();
  },
};

// WALLET PROVIDER — Single Source of Truth fuer Kapital.
// DEMO: virtuelles Kapital (DemoEngine.wallet).
// LIVE: echtes Bitget-Konto (Balance.usable, read-only).
// Zweck: kein Code soll jemals wieder direkt wallet.trading mutieren.
// ═════════════════════════════════════════════════════════════════════════════
const WalletProvider = {
  _mode() {
    return (DemoEngine && DemoEngine.liveMode) ? 'LIVE' : 'DEMO';
  },

  // ── Lesen — E.1 [23.05.2026] LiveWallet bevorzugt in LIVE ──
  total() {
    if (this._mode() === 'DEMO') {
      return (DemoEngine.wallet && DemoEngine.wallet.total) || 0;
    }
    if (_LiveWallet && _LiveWallet._initialized) return _LiveWallet.total();
    return (typeof Balance !== 'undefined' && Balance.usable) || 0;
  },

  trading() {
    let raw;
    if (this._mode() === 'DEMO') {
      raw = (DemoEngine.wallet && DemoEngine.wallet.trading) || 0;
    } else if (_LiveWallet && _LiveWallet._initialized) {
      raw = _LiveWallet.trading();
    } else {
      // BUNDLE 9 [2026-05-06]: Fallback bei Live aber LiveWallet noch nicht initialized
      const usable = (typeof Balance !== 'undefined' && Balance.usable) || 0;
      const reserve = (typeof Balance !== 'undefined' && Balance.reserve) || 0;
      raw = Math.max(0, usable - reserve);
    }
    if (CFG.TRADING_BUDGET_USDT != null && CFG.TRADING_BUDGET_USDT > 0) {
      return Math.min(raw, CFG.TRADING_BUDGET_USDT);
    }
    return raw;
  },

  reserve() {
    if (this._mode() === 'DEMO') {
      return (DemoEngine.wallet && DemoEngine.wallet.reserve) || 0;
    }
    if (_LiveWallet && _LiveWallet._initialized) return _LiveWallet.reserve();
    return (typeof Balance !== 'undefined' && Balance.reserve) || 0;
  },

  // ── Schreiben — E.1/E.2 [23.05.2026] Live-aware via LiveWallet ──
  debit(amount, reason, tradeId) {
    const mode = this._mode();
    // LIVE-Pfad: virtuelle Buchhaltung via LiveWallet
    if (mode === 'LIVE') {
      if (!_LiveWallet || !_LiveWallet.debit) return { ok: false, reason: 'LIVE_WALLET_NOT_LOADED' };
      const beforeT = _LiveWallet.trading();
      const beforeTot = _LiveWallet.total();
      const r = _LiveWallet.debit(amount, reason, tradeId);
      if (!r.ok) return r;
      try { DB.insertLedger.run(Date.now(),'DEBIT',amount,reason||null,tradeId||null,beforeT,_LiveWallet.trading(),beforeTot,_LiveWallet.total(),'LIVE'); } catch(e) { try { Log.warn('LEDGER_WRITE', 'LIVE DEBIT ledger-write fail: ' + e.message + ' amount=' + amount); } catch(_) {} }
      return { ok: true, mode: 'LIVE', newTrading: _LiveWallet.trading() };
    }
    // DEMO-Pfad (unverändert)
    if (!DemoEngine.wallet) return { ok:false, reason:'NO_WALLET' };
    const beforeT = DemoEngine.wallet.trading;
    const beforeTot = DemoEngine.wallet.total;
    DemoEngine.wallet.trading = Math.max(0, DemoEngine.wallet.trading - amount);
    DemoEngine.wallet.total = DemoEngine.wallet.reserve + DemoEngine.wallet.trading;
    try { DemoEngine._persistWallet(); } catch(e) { try { Log.warn('WALLET_PERSIST', 'LIVE-path persistWallet fail: ' + e.message); } catch(_) {} }
    try { DB.insertLedger.run(Date.now(),'DEBIT',amount,reason||null,tradeId||null,beforeT,DemoEngine.wallet.trading,beforeTot,DemoEngine.wallet.total,'DEMO'); } catch(_){}
    return { ok:true, mode:'DEMO', newTrading: DemoEngine.wallet.trading };
  },

  credit(amount, reason, tradeId) {
    const mode = this._mode();
    // LIVE-Pfad
    if (mode === 'LIVE') {
      if (!_LiveWallet || !_LiveWallet.credit) return { ok: false, reason: 'LIVE_WALLET_NOT_LOADED' };
      const beforeT = _LiveWallet.trading();
      const beforeTot = _LiveWallet.total();
      const r = _LiveWallet.credit(amount, reason, tradeId);
      if (!r.ok) return r;
      try { DB.insertLedger.run(Date.now(),'CREDIT',amount,reason||null,tradeId||null,beforeT,_LiveWallet.trading(),beforeTot,_LiveWallet.total(),'LIVE'); } catch(e) { try { Log.warn('LEDGER_WRITE', 'LIVE CREDIT ledger-write fail: ' + e.message + ' amount=' + amount); } catch(_) {} }
      return { ok: true, mode: 'LIVE', newTrading: _LiveWallet.trading() };
    }
    // DEMO-Pfad (unverändert)
    if (!DemoEngine.wallet) return { ok:false, reason:'NO_WALLET' };
    const beforeT_c = DemoEngine.wallet.trading;
    const beforeTot_c = DemoEngine.wallet.total;
    DemoEngine.wallet.trading = Math.max(0, DemoEngine.wallet.trading + amount);
    DemoEngine.wallet.total = DemoEngine.wallet.reserve + DemoEngine.wallet.trading;
    try { DemoEngine._persistWallet(); } catch(e) { try { Log.warn('WALLET_PERSIST', 'LIVE-path persistWallet fail: ' + e.message); } catch(_) {} }
    try { DB.insertLedger.run(Date.now(),'CREDIT',amount,reason||null,tradeId||null,beforeT_c,DemoEngine.wallet.trading,beforeTot_c,DemoEngine.wallet.total,'DEMO'); } catch(_){}
    return { ok:true, mode:'DEMO', newTrading: DemoEngine.wallet.trading };
  },

  // ── PnL anwenden (Split bei Gewinn dynamisch aus bot_settings, voller Abzug bei Verlust) ──
  // MEGA_RESERVE [21.05.2026]: Split-Ratio kommt aus bot_settings.reserve_split_ratio (Default CFG.RESERVE_RATIO=0.70).
  // Range 0.20-0.80 belegt durch Kelly-Fraktion-Recherche (25-50% prof. Praxis, +Safety-Buffer).
  applyPnL(pnl, tradeId) {
    const mode = this._mode();
    // E.1 [23.05.2026] LIVE-Pfad: via LiveWallet mit 70/30-Split aus bot_settings.reserve_split_ratio
    if (mode === 'LIVE') {
      if (!_LiveWallet || !_LiveWallet.applyPnL) return { ok: false, reason: 'LIVE_WALLET_NOT_LOADED' };
      // Read dynamic split-ratio aus bot_settings (gleich wie DEMO)
      let _rRatio = CFG.RESERVE_RATIO;
      try {
        const row = DB.db.prepare("SELECT value FROM bot_settings WHERE key='reserve_split_ratio'").get();
        if (row && row.value) {
          const v = parseFloat(row.value);
          if (isFinite(v) && v >= (CFG.RESERVE_SPLIT_MIN||0.2) && v <= (CFG.RESERVE_SPLIT_MAX||0.8)) _rRatio = v;
        }
      } catch(_) {}
      const beforeT_live = _LiveWallet.trading();
      const beforeTot_live = _LiveWallet.total();
      const r = _LiveWallet.applyPnL(pnl, tradeId, _rRatio);
      if (!r.ok) return r;
      try { DB.insertLedger.run(Date.now(),'PNL',pnl,'applyPnL 70/30 split',null,beforeT_live,_LiveWallet.trading(),beforeTot_live,_LiveWallet.total(),'LIVE'); } catch(e) { try { Log.warn('LEDGER_WRITE', 'LIVE PNL ledger-write fail: ' + e.message + ' pnl=' + pnl); } catch(_) {} }
      if (pnl > 0) {
        try {
          const reserveShare = pnl * _rRatio;
          // FIX 34 [26.05.2026 / Tag 22]: PROFIT_SPLIT_RESERVE ist Audit-Only (PNL-Eintrag oben hat schon wallet-movement).
          // before_total = after_total = sameval → delta=0 → kein double-count in FIX 7.1 real-delta-Methode.
          const _walletNow = _LiveWallet.total();
          DB.insertLedger.run(Date.now(),'PROFIT_SPLIT_RESERVE',reserveShare,'auto-split-on-profit (audit-only)',tradeId||null,null,null,_walletNow,_walletNow,'LIVE');
        } catch(_) {}
      }
      return { ok: true, mode: 'LIVE', pnl, newTotal: _LiveWallet.total() };
    }
    // DEMO-Pfad (unverändert)
    const beforeT_p = DemoEngine.wallet ? DemoEngine.wallet.trading : 0;
    const beforeTot_p = DemoEngine.wallet ? DemoEngine.wallet.total : 0;
    const beforeReserve_p = DemoEngine.wallet ? DemoEngine.wallet.reserve : 0;
    if (!DemoEngine.wallet) return { ok:false, reason:'NO_WALLET' };
    const w = DemoEngine.wallet;
    if (pnl > 0) {
      // MEGA_RESERVE: dynamische Ratio aus bot_settings, Fallback auf CFG.RESERVE_RATIO
      let _rRatio = CFG.RESERVE_RATIO;
      try {
        const row = DB.db.prepare("SELECT value FROM bot_settings WHERE key='reserve_split_ratio'").get();
        if (row && row.value) {
          const v = parseFloat(row.value);
          if (isFinite(v) && v >= (CFG.RESERVE_SPLIT_MIN||0.2) && v <= (CFG.RESERVE_SPLIT_MAX||0.8)) _rRatio = v;
        }
      } catch(_) {}
      const toReserve = pnl * _rRatio;
      const toTrading = pnl * (1 - _rRatio);
      w.reserve = (w.reserve||0) + toReserve;
      w.trading = (w.trading||0) + toTrading;
    } else {
      // AUDFIX_RESERVE_ROUTING: Reserve bleibt bei Verlust UNANGETASTET (Capital Preservation)
      w.trading = Math.max(0, (w.trading||0) + pnl);
    }
    // AUDFIX_RESERVE_ROUTING: Reserve-Hard-Check — darf bei Verlust NIE schrumpfen
    if (pnl <= 0 && w.reserve < beforeReserve_p - 0.001) {
      try {
        Log.warn('RESERVE_DRIFT', `Reserve schrumpfte bei Verlust: vor=${beforeReserve_p} nach=${w.reserve} pnl=${pnl}`);
        DB.db.prepare("INSERT INTO system_log (ts, level, module, msg, data) VALUES (datetime('now'), 'CRITICAL', 'reserve_routing', 'RESERVE_DRIFT_ON_LOSS', ?)")
          .run(JSON.stringify({ before: beforeReserve_p, after: w.reserve, pnl, tradeId }));
      } catch(_) {}
      // Defensive restore
      w.reserve = beforeReserve_p;
    }
    w.pnl      = (w.pnl||0) + pnl;
    w.dailyPnl = (w.dailyPnl||0) + pnl;
    w.total    = w.reserve + w.trading;
    if (w.total > (w.peakTotal||0)) w.peakTotal = w.total;
    try { DemoEngine._persistWallet(); } catch(e) { try { Log.warn('WALLET_PERSIST', 'LIVE-path persistWallet fail: ' + e.message); } catch(_) {} }
    try { DB.insertLedger.run(Date.now(),'PNL',pnl,'applyPnL 70/30 split',null,beforeT_p,DemoEngine.wallet.trading,beforeTot_p,DemoEngine.wallet.total,'DEMO'); } catch(_){}
    // Tier-Z Patch Z.2 [2026-05-12]: dedizierte Audit-Op fuer Reserve-Wachstum.
    // Nur bei profit > 0 — bei Verlust greift 70/30-Split nicht (siehe applyPnL-Doc).
    // Doppel-Entry-Buchhaltung: PNL-Op + PROFIT_SPLIT_RESERVE-Op fuer Forensik.
    if (pnl > 0) {
      try {
        const reserveShare = pnl * 0.70;
        // FIX 34 [26.05.2026 / Tag 22 / DEMO-Pfad]: PROFIT_SPLIT_RESERVE = Audit-Only.
        // PNL-Eintrag oben (Z.10546) hat schon den wallet-movement. Hier delta=0 (before==after) → kein double-count.
        const _walletNow = DemoEngine.wallet.total;
        DB.insertLedger.run(
          Date.now(), 'PROFIT_SPLIT_RESERVE', reserveShare,
          'auto-split-on-profit (audit-only)', tradeId || null,
          null, null, _walletNow, _walletNow, 'DEMO'
        );
      } catch(err) {
        Log.warn('WalletProvider', `PROFIT_SPLIT_RESERVE log failed: ${err.message}`);
      }
    }
    return { ok:true, mode:'DEMO', pnl, newTotal: w.total };
  },

  // ── Diagnose ──
  snapshot() {
    // FIX-WALLET D [17.05.2026]: MBT-Commitment berechnen (DCA total_spent + Grid net-investment)
    let mbtCommitted = 0;
    let mbtCount = 0;
    try {
      const dcaSum = DB.db.prepare("SELECT COALESCE(SUM(total_spent), 0) AS s, COUNT(*) AS c FROM dca_instances WHERE status IN ('OPEN','DD_STOPPED')").get();
      mbtCommitted += dcaSum.s || 0;
      mbtCount += dcaSum.c || 0;
    } catch(_){}
    try {
      // Grid net = BUY - SELL aus grid_orders der OPEN grids
      const gridNet = DB.db.prepare(`
        SELECT
          COALESCE(SUM(CASE WHEN go.side='BUY' THEN go.size * go.fill_price ELSE 0 END), 0)
          - COALESCE(SUM(CASE WHEN go.side='SELL' THEN go.size * go.fill_price ELSE 0 END), 0) AS net
        FROM grid_orders go JOIN grid_instances gi ON go.grid_id = gi.grid_id
        WHERE gi.status = 'OPEN' AND go.filled = 1
      `).get();
      mbtCommitted += Math.max(0, gridNet.net || 0);
      const gridCnt = DB.db.prepare("SELECT COUNT(*) AS c FROM grid_instances WHERE status='OPEN'").get();
      mbtCount += gridCnt.c || 0;
    } catch(_){}
    return {
      mode: this._mode(),
      total:   this.total(),
      trading: this.trading(),
      reserve: this.reserve(),
      // FIX-WALLET D [17.05.2026]: MBT-Felder additiv (Bot-Logik unverändert)
      mbtCommitted: Number(mbtCommitted.toFixed(2)),
      mbtCount,
      effectiveImMarkt: Number(mbtCommitted.toFixed(2)),  // Anzeige-Wert für Dashboard
      demoWallet: (this._mode()==='DEMO' && DemoEngine.wallet) ? {
        total: DemoEngine.wallet.total,
        trading: DemoEngine.wallet.trading,
        reserve: DemoEngine.wallet.reserve,
        pnl: DemoEngine.wallet.pnl,
        dailyPnl: DemoEngine.wallet.dailyPnl,
        peakTotal: DemoEngine.wallet.peakTotal,
      } : null,
      liveBalance: (this._mode()==='LIVE' && typeof Balance!=='undefined') ? {
        usable: Balance.usable,
        total: Balance.total,
      } : null,
      // E.1 [23.05.2026] LiveWallet snapshot
      liveWallet: (this._mode()==='LIVE' && _LiveWallet && _LiveWallet._initialized) ? _LiveWallet.snapshot() : null,
    };
  },
};

// ─────────────────────────────────────────────────────────────────────────────
// MBT-aware Helper-Funktionen (KOMPLETT-FIX A/C, 17.05.2026)
// Profi-Pattern: effectiveEquity = cash + reserve + mark-to-market(positions)
// ─────────────────────────────────────────────────────────────────────────────

// Mark-to-Market: unrealisierter PnL aller aktiven Positionen
function computeUnrealizedPnLMBT() {
  let unrealizedSingle = 0;
  let unrealizedDCA = 0;
  let unrealizedGrid = 0;
  const priceCache = (typeof Bitget !== 'undefined') ? Bitget.priceCache : {};
  // SINGLE: aus DemoEngine.positions
  try {
    for (const pos of Object.values(DemoEngine.positions || {})) {
      const tk = priceCache[pos.symbol];
      if (!tk || !tk.last) continue;
      const dir = pos.direction === 'BUY' ? 1 : -1;
      const coinQty = pos.size / pos.fillPrice;
      unrealizedSingle += dir * (tk.last - pos.fillPrice) * coinQty;
    }
  } catch(_) {}
  // DCA: pro aktive Instance (total_size × (current - avg_buy_price))
  try {
    const dcas = DB.listDcaOpen.all(50);
    for (const d of dcas) {
      const tk = priceCache[d.symbol];
      if (!tk || !tk.last || !d.avg_buy_price || !d.total_size) continue;
      unrealizedDCA += (tk.last - d.avg_buy_price) * d.total_size;
    }
  } catch(_) {}
  // GRID: profit_acc ist bereits akkumulierte Profit (geringe Mark-to-Market-Approximation)
  try {
    const grids = DB.listGridsOpen.all(50);
    for (const g of grids) {
      unrealizedGrid += g.profit_acc || 0;
    }
  } catch(_) {}
  return {
    single: Number(unrealizedSingle.toFixed(4)),
    dca: Number(unrealizedDCA.toFixed(4)),
    grid: Number(unrealizedGrid.toFixed(4)),
    total: Number((unrealizedSingle + unrealizedDCA + unrealizedGrid).toFixed(4)),
  };
}

// FIX 4 [25.05.2026]: zentrale DD-Formel — eine Wahrheit für KillSwitch+UI+Report+PerfTracker.
// Quelle: LEAN SecurityPortfolioManager.TotalPortfolioValue (eine Berechnung, keine Drift).
// Audit B1-2: 0.45pp Drift zwischen KillSwitch (eff.) und UI (wallet.total). Call-sites passen jetzt
// die einheitliche Equity-Quelle (effectiveTotal) ein; Formel zentral hier.
function _computeDrawdown(equity, peak) {
  if (!peak || peak <= 0 || !isFinite(peak) || !isFinite(equity)) return 0;
  return Math.max(0, (peak - equity) / peak);
}

// Effective Equity für DEMO: Wallet-Total + MBT-Commit + Mark-to-Market
function getEffectiveDemoEquity() {
  const dw = (DemoEngine && DemoEngine.wallet) || {};
  const cash = Number(dw.trading || 0);
  const reserve = Number(dw.reserve || 0);
  const total = Number(dw.total || 0);
  let mbtCommitted = 0;
  try {
    const dcaSum = DB.db.prepare("SELECT COALESCE(SUM(total_spent),0) AS s FROM dca_instances WHERE status IN ('OPEN','DD_STOPPED')").get();
    mbtCommitted += dcaSum.s || 0;
  } catch(_) {}
  try {
    // Block G+ PRIO 0 [26.05.2026]: Align mit /api/bots/dashboard — capital_pool statt order-net.
    // Vorher: SUM(buy.fill_price) - SUM(sell.fill_price) = 0 bei balanced grids → mbtCommitted unter-estimiert.
    // Jetzt: capital_pool (pre-allocated capital pro OPEN grid) — Source-of-Truth same wie UI.
    const gridSum = DB.db.prepare(`SELECT COALESCE(SUM(capital_pool), 0) AS pool FROM grid_instances WHERE status='OPEN'`).get();
    mbtCommitted += gridSum.pool || 0;
  } catch(_) {}
  // SINGLE-positions OPEN (gleiche Logik wie dashboard `investmentTotal`)
  let investmentTotal = 0;
  try {
    const inv = DB.db.prepare(`SELECT COALESCE(SUM(size*entry_price), 0) AS s FROM trades WHERE state IN ('OPEN','POSITION_ACTIVE')`).get();
    investmentTotal = inv.s || 0;
  } catch(_) {}
  // FIX [2026-06-05] EQUITY-BUG: SINGLE-Position-Capital für KillSwitch-Equity-Korrektur.
  // wallet.total wird beim Trade-Entry per DEBIT(size USDT) reduziert (DEMO Wallet-Model).
  // Profi-Pattern Net Liquidation: cash_after_debit + locked-in-position + unrealized PnL.
  // Vorher: HARD_KILL false-positive bei jeder neuen SINGLE-Position weil capital "verschwand".
  // Beweis: ATOM SHORT (DEBIT 79.16) → wallet 1061.90 → 982.74 → DD 14.6% > 12% MAX_DRAWDOWN.
  //         Mit singleCapital reverse: eq 982.74 + 79.16 = 1061.90 → DD 7.76% ✓.
  let singleCapital = 0;
  try {
    const sc = DB.db.prepare(`SELECT COALESCE(SUM(size), 0) AS s FROM trades WHERE state IN ('OPEN','POSITION_ACTIVE')`).get();
    singleCapital = sc.s || 0;
  } catch(_) {}
  const unrealized = computeUnrealizedPnLMBT();
  return {
    cash: Number(cash.toFixed(4)),
    reserve: Number(reserve.toFixed(4)),
    walletTotal: Number(total.toFixed(4)),
    mbtCommitted: Number(mbtCommitted.toFixed(4)),
    investmentTotal: Number(investmentTotal.toFixed(4)),  // Block G+ PRIO 0: SINGLE-positions OPEN
    singleCapital: Number(singleCapital.toFixed(4)),       // FIX 2026-06-05: SINGLE-Position USDT capital reserved
    unrealized,
    // AUDFIX_035 [18.05.2026] KillSwitch-Doppel-Count behoben (Option A) — DCA/Grid sind audit-only.
    // FIX 2026-06-05: SINGLE-Position-Capital additiv. wallet.total ist durch DEBIT(size USDT) bereits reduziert.
    // Net Liquidation = cash_after_debit + reserved-in-SINGLE-positions + unrealized PnL.
    // DCA/Grid sind weiter implizit in wallet.total (audit-only DCA_BUY/GRID_BUY).
    effectiveTotal: Number((total + singleCapital + unrealized.total).toFixed(4)),
    // Block G+ PRIO 0 [26.05.2026]: Im Markt = MBT-capital_pool + SINGLE-investmentTotal — matched UI dashboard
    effectiveImMarkt: Number((mbtCommitted + investmentTotal).toFixed(4)),
  };
}

// Daily PnL MBT-aware: realized aller BotTypes + unrealized
function computeDailyPnLMBT() {
  const startToday = (() => { const d=new Date(); d.setHours(0,0,0,0); return d.getTime(); })();
  let realizedSingle = 0;
  let realizedDca = 0;
  let realizedGrid = 0;
  // SINGLE: realized_pnl aus trades-Tabelle WHERE closed_at >= startToday
  try {
    const row = DB.db.prepare("SELECT COALESCE(SUM(realized_pnl),0) AS s FROM trades WHERE closed_at >= ? AND state IN ('CLOSED','POSITION_CLOSED')").get(startToday);
    realizedSingle = row.s || 0;
  } catch(_) {}
  // DCA: aus dca_instances WHERE status='CLOSED_TP' AND closed_at >= startToday — realized_pnl steckt im meta-JSON
  try {
    const rows = DB.db.prepare("SELECT meta FROM dca_instances WHERE status='CLOSED_TP' AND closed_at >= ?").all(startToday);
    for (const r of rows) {
      try {
        const m = JSON.parse(r.meta || '{}');
        if (typeof m.realized_pnl === 'number') realizedDca += m.realized_pnl;
      } catch(_) {}
    }
  } catch(_) {}
  // Grid: profit_acc Delta — approximiert über GRID_SELL-GRID_BUY ledger heute
  try {
    // NOTBREMSE_FIX [20.05.2026]: realizedGrid aus strategy_regime_performance.pnl_usdt
    // Vorher: SUM(GRID_SELL.amount) - SUM(GRID_BUY.amount) — Volumen-Delta, NICHT PnL!
    // Heute 11:02 hat das -144.85 ergeben (Volumen-Asymmetrie 489 SELLs vs 497 BUYs)
    // → False-Trigger der AUTO_NOTBREMSE. Echter Profit war +5.06 USDT (UNI profit_acc Δ).
    // Neue Quelle: REGIME_HOOK [10:43] schreibt echte Fee-aware PnL pro Fill.
    const row = DB.db.prepare(`
      SELECT COALESCE(SUM(pnl_usdt), 0) AS s
      FROM strategy_regime_performance
      WHERE bot_type IN ('GRID','INFGRID') AND ts >= ?
    `).get(startToday);
    realizedGrid = row.s || 0;
  } catch(_) {}
  const unrealized = computeUnrealizedPnLMBT();
  return {
    realized: {
      single: Number(realizedSingle.toFixed(4)),
      dca: Number(realizedDca.toFixed(4)),
      grid: Number(realizedGrid.toFixed(4)),
      total: Number((realizedSingle + realizedDca + realizedGrid).toFixed(4)),
    },
    unrealized,
    totalDailyImpact: Number((realizedSingle + realizedDca + realizedGrid + unrealized.total).toFixed(4)),
  };
}

// MBT-aware Trade-Stats (für StatsCore-Ergänzung)
function computeMBTStats() {
  let single = { trades: 0, wins: 0, losses: 0, pnl: 0 };
  let dca = { cycles: 0, tp_hits: 0, dd_stops: 0, realized_pnl: 0, active: 0, iterations_today: 0 };
  let grid = { instances: 0, active: 0, fills_buy: 0, fills_sell: 0, profit_acc: 0 };
  try {
    const r = DB.db.prepare("SELECT COUNT(*) AS c, SUM(CASE WHEN realized_pnl>0 THEN 1 ELSE 0 END) AS w, SUM(CASE WHEN realized_pnl<0 THEN 1 ELSE 0 END) AS l, COALESCE(SUM(realized_pnl),0) AS p FROM trades WHERE state IN ('CLOSED','POSITION_CLOSED') AND (bot_type='SINGLE' OR bot_type IS NULL)").get();
    single = { trades: r.c, wins: r.w || 0, losses: r.l || 0, pnl: r.p || 0 };
  } catch(_) {}
  try {
    const r = DB.db.prepare("SELECT COUNT(*) AS c FROM dca_instances").get();
    dca.cycles = r.c;
    const tp = DB.db.prepare("SELECT COUNT(*) AS c FROM dca_instances WHERE status='CLOSED_TP'").get();
    dca.tp_hits = tp.c;
    const dd = DB.db.prepare("SELECT COUNT(*) AS c FROM dca_instances WHERE status='DD_STOPPED'").get();
    dca.dd_stops = dd.c;
    const ac = DB.db.prepare("SELECT COUNT(*) AS c FROM dca_instances WHERE status IN ('OPEN','DD_STOPPED')").get();
    dca.active = ac.c;
    const it = DB.db.prepare("SELECT COUNT(*) AS c FROM dca_iterations WHERE buy_ts >= ?").get((()=>{const d=new Date();d.setHours(0,0,0,0);return d.getTime();})());
    dca.iterations_today = it.c;
    // realized aus meta
    const meta_rows = DB.db.prepare("SELECT meta FROM dca_instances WHERE status='CLOSED_TP'").all();
    for (const r of meta_rows) {
      try { const m = JSON.parse(r.meta||'{}'); if (typeof m.realized_pnl === 'number') dca.realized_pnl += m.realized_pnl; } catch(_){}
    }
  } catch(_) {}
  try {
    const r = DB.db.prepare("SELECT COUNT(*) AS c, SUM(CASE WHEN status='OPEN' THEN 1 ELSE 0 END) AS a, COALESCE(SUM(profit_acc),0) AS pa FROM grid_instances").get();
    grid.instances = r.c;
    grid.active = r.a || 0;
    grid.profit_acc = r.pa || 0;
    const fr = DB.db.prepare("SELECT side, COUNT(*) AS c FROM grid_orders WHERE filled=1 GROUP BY side").all();
    for (const x of fr) {
      if (x.side === 'BUY') grid.fills_buy = x.c;
      else if (x.side === 'SELL') grid.fills_sell = x.c;
    }
  } catch(_) {}
  return {
    single,
    dca: { ...dca, realized_pnl: Number(dca.realized_pnl.toFixed(4)) },
    grid: { ...grid, profit_acc: Number(grid.profit_acc.toFixed(4)) },
    totalTradingActivity: single.trades + dca.iterations_today + grid.fills_buy + grid.fills_sell,
  };
}

// ═════════════════════════════════════════════════════════════════════════════
// CapitalPool — Multi-BotType H (16.05.2026)
// Teilt das Trading-Kapital in Pools pro BotType auf.
// Pool-Anteile am Trading-Topf (CFG-konfigurierbar zur Laufzeit):
//   SINGLE_POOL   = 40%
//   GRID_POOL     = 25%
//   DCA_POOL      = 20%
//   INFGRID_POOL  = 15%
// Pro Pool ein max_active-Limit (gegen unbegrenzte Allokation).
// Snapshot-Endpoint /api/capitalpool/status.
// ═════════════════════════════════════════════════════════════════════════════
const CapitalPool = {
  ALLOC: {
    SINGLE:  0.40,
    GRID:    0.25,
    DCA:     0.20,
    INFGRID: 0.15,
  },
  LIMITS: {
    SINGLE:  { maxActive: 3, label: 'open_trades' },
    GRID:    { maxActive: 2, label: 'open_grids' },
    DCA:     { maxActive: 2, label: 'open_dcas' },
    INFGRID: { maxActive: 1, label: 'open_infgrids' },
  },

  _tradingBalance() {
    try { return WalletProvider.trading() || 0; } catch(_) { return 0; }
  },

  // Aktuell aktive Ressourcen pro BotType (aus DB)
  _activeCounts() {
    let single = 0;
    try { single = Trades.getActive().length; } catch(_) {}
    let grid = 0, dca = 0, inf = 0;
    try { grid = DB.countGridsOpen.get('GRID')?.n || 0; } catch(e) { try { Log.warn('SNAPSHOT_COUNT', 'grid-count fail: ' + e.message); } catch(_) {} }
    try { dca  = DB.countDcaOpen.get()?.n || 0; } catch(e) { try { Log.warn('SNAPSHOT_COUNT', 'dca-count fail: ' + e.message); } catch(_) {} }
    try { inf  = DB.countGridsOpen.get('INFGRID')?.n || 0; } catch(e) { try { Log.warn('SNAPSHOT_COUNT', 'inf-grid-count fail: ' + e.message); } catch(_) {} }
    return { SINGLE: single, GRID: grid, DCA: dca, INFGRID: inf };
  },

  // Pro Pool: balance/used/available + Limit-Belegung
  snapshot() {
    const tradingBalance = this._tradingBalance();
    const active = this._activeCounts();
    const pools = {};
    for (const bt of Object.keys(this.ALLOC)) {
      const ratio = this.ALLOC[bt];
      const balance = tradingBalance * ratio;
      const lim = this.LIMITS[bt];
      pools[bt] = {
        ratio,
        balance: +balance.toFixed(4),
        max_active: lim.maxActive,
        current_active: active[bt] || 0,
        available_slots: Math.max(0, lim.maxActive - (active[bt] || 0)),
        full: (active[bt] || 0) >= lim.maxActive,
        label: lim.label,
      };
    }
    return {
      ok: true,
      ts: Date.now(),
      trading_balance_total: tradingBalance,
      total_alloc_pct: Object.values(this.ALLOC).reduce((a,b)=>a+b,0),
      pools,
    };
  },

  // Darf der BotType jetzt allokieren? (max_active nicht überschritten + Balance > 0)
  canAllocate(botType) {
    if (!this.ALLOC[botType]) return { ok: false, reason: 'UNKNOWN_BOTTYPE' };
    // GLOBAL CAP [2026-06-06 Option A]: Slider gilt fuer ALLE Bot-Exposures zusammen.
    try {
      const _ex = getGlobalActiveExposure();
      const _lim = getEffectiveSlotLimit();
      if (_ex.total >= _lim) return { ok: false, reason: 'GLOBAL_CAP_EXCEEDED', activeTotal: _ex.total, limit: _lim };
    } catch(_) {}
    const snap = this.snapshot();
    const p = snap.pools[botType];
    if (!p) return { ok: false, reason: 'POOL_NOT_FOUND' };
    if (p.full) return { ok: false, reason: 'POOL_FULL', current: p.current_active, max: p.max_active };
    if (p.balance < 5) return { ok: false, reason: 'POOL_BALANCE_LOW', balance: p.balance };
    return { ok: true, balance: p.balance, available_slots: p.available_slots };
  },

  // Erlaube Laufzeit-Anpassung (z.B. via /api/capitalpool/set)
  setAllocation(alloc) {
    if (!alloc || typeof alloc !== 'object') throw new Error('alloc object required');
    let sum = 0;
    const out = {};
    for (const bt of Object.keys(this.ALLOC)) {
      const v = +alloc[bt];
      if (isNaN(v) || v < 0 || v > 1) throw new Error(`alloc.${bt} must be 0..1`);
      out[bt] = v;
      sum += v;
    }
    if (Math.abs(sum - 1.0) > 0.001) throw new Error(`alloc sum must be 1.0 (got ${sum.toFixed(3)})`);
    Object.assign(this.ALLOC, out);
    return this.snapshot();
  },
};

// ═════════════════════════════════════════════════════════════════════════════
// GLOBAL SLOT CAP [2026-06-06, Christian Option A] — Slider gilt fuer ALLE Bot-Exposures.
// activeTotal = SINGLE (trades POSITION_ACTIVE) + GRID + DCA + INFGRID.
// Genutzt von: concurrencyOk-Gate, SINGLE-Open-Gate, CapitalPool.canAllocate.
// Mode-neutral (PAPER == DRY_LIVE): zaehlt nur Bestand + Limit, kein Order-Send-Unterschied.
// ═════════════════════════════════════════════════════════════════════════════
function getGlobalActiveExposure() {
  let single = 0, grid = 0, dca = 0, inf = 0;
  try { single = DB.getActiveTrades.all().length; } catch(_) {}
  try { grid   = DB.countGridsOpen.get('GRID')?.n || 0; } catch(_) {}
  try { dca    = DB.countDcaOpen.get()?.n || 0; } catch(_) {}
  try { inf    = DB.countGridsOpen.get('INFGRID')?.n || 0; } catch(_) {}
  return { single, grid, dca, infgrid: inf, total: single + grid + dca + inf };
}
// Effektives Slot-Limit — identisch zu /api/slots/snapshot.effective (min User/RiskLadder/RiskTier).
function getEffectiveSlotLimit() {
  const user  = CFG.MAX_OPEN_TRADES;
  const rlMax = (typeof RiskLadder !== 'undefined') ? RiskLadder.maxTrades() : Infinity;
  const rtMax = (typeof RiskTier   !== 'undefined') ? RiskTier.maxPositions() : Infinity;
  return Math.min(user, rlMax, rtMax);
}

// ═════════════════════════════════════════════════════════════════════════════
// AUDFIX_TICKLOT [2026-05-18]: SymbolSpec-Cache + Tick/Lot-Rundung Pre-Send
// Elite-Standard: Nautilus, Freqtrade, LEAN — Bitget reject ohne korrekte Rundung
// ═════════════════════════════════════════════════════════════════════════════
const SymbolSpec = {
  _cache: new Map(),                // symbol → { tickSize, lotSize, minNotional, ts }
  TTL_MS: 6 * 60 * 60 * 1000,       // 6h Refresh
  async get(symbol) {
    const e = this._cache.get(symbol);
    if (e && Date.now() - e.ts < this.TTL_MS) return e;
    try {
      const r = await Bitget.publicGet('/api/v2/spot/public/symbols?symbol=' + encodeURIComponent(symbol));
      const arr = r?.data || [];
      const info = arr[0];
      if (!info) return null;
      // Bitget V2 fields: pricePrecision, quantityPrecision, quotePrecision, minTradeAmount
      const tickSize = info.priceScale ? Math.pow(10, -parseInt(info.priceScale)) : (info.priceTickSize ? parseFloat(info.priceTickSize) : 0.01);
      const lotSize = info.quantityScale ? Math.pow(10, -parseInt(info.quantityScale)) : (info.quantityTickSize ? parseFloat(info.quantityTickSize) : 0.0001);
      const minNotional = info.minTradeUSDT ? parseFloat(info.minTradeUSDT) : (info.minTradeAmount ? parseFloat(info.minTradeAmount) : 5);
      const spec = { tickSize, lotSize, minNotional, ts: Date.now(), raw: info };
      this._cache.set(symbol, spec);
      return spec;
    } catch(e) { try{Log.warn('SYMBOLSPEC',symbol+': '+e.message);}catch(_){} return null; }
  },
  roundSize(size, lotSize) {
    if (!lotSize || lotSize <= 0) return size;
    return Math.floor(size / lotSize) * lotSize;
  },
  roundPrice(price, tickSize) {
    if (!tickSize || tickSize <= 0) return price;
    return Math.round(price / tickSize) * tickSize;
  },
  // Konvenienz: Pre-Send-Check für ein Trade
  async normalize(symbol, sizeUSDT, price) {
    const spec = await this.get(symbol);
    if (!spec) return { ok: true, sizeUSDT, price, spec: null, note: 'NO_SPEC_FALLTHROUGH' };
    const roundedPrice = this.roundPrice(price, spec.tickSize);
    // sizeUSDT bleibt USDT-quote (Bitget akzeptiert beides bei market); Lot-Check über size in base = sizeUSDT/price
    const baseSize = roundedPrice > 0 ? sizeUSDT / roundedPrice : 0;
    const roundedBase = this.roundSize(baseSize, spec.lotSize);
    const roundedUSDT = roundedBase * roundedPrice;
    if (roundedUSDT < spec.minNotional) {
      return { ok: false, reason: 'MIN_NOTIONAL', minNotional: spec.minNotional, roundedUSDT, spec };
    }
    return { ok: true, sizeUSDT: roundedUSDT, sizeBase: roundedBase, price: roundedPrice, spec };
  },
  snapshot() {
    return { cached: this._cache.size, ttlMs: this.TTL_MS };
  },
};

// ═════════════════════════════════════════════════════════════════════════════
// AUDFIX_IDEMPOTENCY [2026-05-18]: OrderRegistry für clientOrderId-Idempotency
// Elite-Standard: Nautilus, Jesse, LEAN — verhindert Order-Duplikate bei Retry/Reconnect
// ═════════════════════════════════════════════════════════════════════════════
const OrderRegistry = {
  _map: new Map(),                  // clientOid → { ts, result, status }
  TTL_MS: 5 * 60 * 1000,            // 5 Min Lookup-Fenster
  MAX_ENTRIES: 5000,
  _genClientOid(symbol, direction, sizeUSDT, ts) {
    // UUID v4-ähnlich, aber deterministischer Hash-Anteil für Diagnose
    const t = ts || Date.now();
    const rand = crypto.randomBytes(6).toString('hex');
    return `NX-${symbol}-${direction}-${t}-${rand}`;
  },
  has(clientOid) {
    if (!clientOid) return false;
    const e = this._map.get(clientOid);
    if (!e) return false;
    if (Date.now() - e.ts > this.TTL_MS) {
      this._map.delete(clientOid);
      return false;
    }
    return true;
  },
  get(clientOid) {
    const e = this._map.get(clientOid);
    if (!e || Date.now() - e.ts > this.TTL_MS) return null;
    return e;
  },
  put(clientOid, result, status) {
    if (!clientOid) return;
    if (this._map.size >= this.MAX_ENTRIES) {
      // GC ältester Entries
      const keys = Array.from(this._map.keys()).slice(0, 500);
      for (const k of keys) this._map.delete(k);
    }
    this._map.set(clientOid, { ts: Date.now(), result, status: status || 'OK' });
  },
  snapshot() {
    return { size: this._map.size, ttlMs: this.TTL_MS, maxEntries: this.MAX_ENTRIES };
  },
};

// ═════════════════════════════════════════════════════════════════════════════
// EXECUTION ADAPTER — Einziger Unterschied zwischen DEMO und LIVE.
// DEMO: Realistische Fill-Simulation mit Live-Orderbook.
// LIVE: Echter Bitget-API-Call.
// Alles davor (Signal, Gate, Sizing) und danach (Exit, Wallet) ist gemeinsam.
// ═════════════════════════════════════════════════════════════════════════════
const ExecutionAdapter = {
  // Haupt-API: symbol, direction ('BUY'/'SELL'), sizeUSDT, referencePrice, opts
  async placeOrder(symbol, direction, sizeUSDT, referencePrice, opts) {
    opts = opts || {};
    // AUDFIX_TICKLOT: Pre-Send tick/lot/minNotional rounding (skip wenn opts.skipSpec=true für Tests)
    if (!opts.skipSpec) {
      try {
        const norm = await SymbolSpec.normalize(symbol, sizeUSDT, referencePrice);
        if (!norm.ok && norm.reason === 'MIN_NOTIONAL') {
          try { Log.warn('ADAPTER','SKIP_MIN_NOTIONAL '+symbol+' '+direction+' rounded='+norm.roundedUSDT+' < min='+norm.minNotional); } catch(_) {}
          return { ok: false, mode: 'SKIP', reason: 'MIN_NOTIONAL', sizeUSDT: norm.roundedUSDT, minNotional: norm.minNotional };
        }
        if (norm.ok && norm.spec) {
          sizeUSDT = norm.sizeUSDT;
          referencePrice = norm.price;
          opts._spec = norm.spec;
        }
      } catch(_) {}
    }
    // AUDFIX_IDEMPOTENCY: clientOid sicherstellen, Doppel-Send blockieren
    if (!opts.clientOid) opts.clientOid = OrderRegistry._genClientOid(symbol, direction, sizeUSDT);
    if (OrderRegistry.has(opts.clientOid)) {
      const prev = OrderRegistry.get(opts.clientOid);
      try { Log.warn('ADAPTER','IDEMPOTENCY duplicate clientOid='+opts.clientOid+' — returning cached'); } catch(_) {}
      return { ok: prev.result?.ok || false, mode: prev.result?.mode || 'CACHED', duplicate: true, clientOid: opts.clientOid, ...prev.result };
    }
    OrderRegistry.put(opts.clientOid, null, 'PENDING');
    const mode = (DemoEngine && DemoEngine.liveMode) ? 'LIVE' : 'DEMO';
    const t0 = Date.now();

    if (mode === 'DEMO') {
      return await this._simulateFill(symbol, direction, sizeUSDT, referencePrice, opts, t0);
    }
    return await this._liveFill(symbol, direction, sizeUSDT, referencePrice, opts, t0);
  },

  // ── DEMO: realistische Fill-Simulation
  async _simulateFill(symbol, direction, sizeUSDT, referencePrice, opts, t0) {
    try {
      // Latenz wie echter Bitget-Call (50-200ms)
      const latency = 50 + Math.floor(Math.random() * 150);
      await new Promise(r => setTimeout(r, latency));

      // Orderbook-basierte Slippage (wenn verfuegbar)
      let slipPct = 0.0002; // Fallback: 0.02%
      let partialFill = false;
      let fillSize = sizeUSDT;

      try {
        const ob = await Bitget.fetchOrderbook(symbol).catch(() => null);
        if (ob && ob.bids && ob.asks && ob.bids.length && ob.asks.length) {
          const book = direction === 'BUY' ? ob.asks : ob.bids;
          let remaining = sizeUSDT;
          let totalCost = 0;
          let totalQty = 0;
          for (const level of book) {
            const price = parseFloat(level[0]);
            const qty = parseFloat(level[1]);
            const levelUSDT = price * qty;
            if (remaining <= levelUSDT) {
              const q = remaining / price;
              totalQty += q;
              totalCost += remaining;
              remaining = 0;
              break;
            } else {
              totalQty += qty;
              totalCost += levelUSDT;
              remaining -= levelUSDT;
            }
          }
          if (remaining > 0) {
            // Nicht genug Orderbook-Tiefe - partial fill
            partialFill = true;
            fillSize = sizeUSDT - remaining;
          }
          if (totalQty > 0 && fillSize > 0) {
            const avgFillPrice = totalCost / totalQty;
            slipPct = Math.abs(avgFillPrice - referencePrice) / referencePrice;
          }
        }
      } catch(e) {
        try{ Log.warn('ADAPTER','orderbook slip calc err: '+e.message); }catch(_){}
      }

      // F20 [15.05.2026] SLIPPAGE-CAP — DEMO=LIVE: identisch in beiden Modi
      const _maxSlip = CFG.MAX_SLIPPAGE_PCT || 0.005;
      if (slipPct > _maxSlip) {
        try { Log.warn('ADAPTER', `DEMO slip ${(slipPct*100).toFixed(3)}% > MAX ${(_maxSlip*100).toFixed(2)}% — reject`); } catch(_){}
        return { ok: false, mode: 'DEMO', error: 'SLIPPAGE_TOO_HIGH', slippagePct: slipPct, maxSlippage: _maxSlip };
      }

      const fillPrice = direction === 'BUY'
        ? referencePrice * (1 + slipPct)
        : referencePrice * (1 - slipPct);

      const result = {
        ok: true,
        mode: 'DEMO',
        symbol, direction,
        sizeUSDT: fillSize,
        fillPrice,
        slippagePct: slipPct,
        latencyMs: latency,
        partialFill,
        orderId: 'DEMO_' + symbol + '_' + Date.now(),
        clientOid: opts.clientOid,
        t0, tEnd: Date.now(),
      };
      // AUDFIX_IDEMPOTENCY: in OrderRegistry persistieren
      try { OrderRegistry.put(opts.clientOid, result, 'FILLED'); } catch(_) {}

      try {
        ActionStream.push('ENTRY', symbol,
          'DEMO '+direction+' '+fillSize.toFixed(2)+' USDT @ '+fillPrice.toFixed(4)+' slip='+(slipPct*100).toFixed(3)+'% lat='+latency+'ms'+(partialFill?' PARTIAL':''),
          { mode:'DEMO', direction, size:fillSize, fillPrice, slippagePct:slipPct, latencyMs:latency, partialFill });
      } catch(_){}

      return result;
    } catch(e) {
      try{ Log.warn('ADAPTER','sim err: '+e.message); }catch(_){}
      return { ok:false, mode:'DEMO', error: e.message };
    }
  },

  // ── LIVE: echter Bitget-Call
  async _liveFill(symbol, direction, sizeUSDT, referencePrice, opts, t0) {
    // Block T+ [27.05.2026]: HARD TEST-ONLY-GUARD — innermost veto in Live-Fill-Pfad.
    if (_TestOnlyGuard) {
      try {
        const _gv = _TestOnlyGuard.validateLiveOrder(CFG, (typeof DB!=='undefined'&&DB.db)?DB.db:null, {
          source:'ExecutionAdapter._liveFill', symbol, side:direction, size:sizeUSDT, mode:CFG.DEPLOY_MODE,
        });
        if (!_gv.ok) {
          try { Log.warn('TEST_ONLY', _TestOnlyGuard.formatBlockLog(_gv.ctx)); } catch(_){}
          return { ok:false, blocked:true, reason:'TEST_ONLY_MODE_ACTIVE', ctx:_gv.ctx };
        }
      } catch(_){}
    }
    try {
      // C.3 [14.05.2026] DRY_LIVE: echte Bitget-API für Connectivity-Test, ABER kein placeSportOrder.
      // Aktivierung NUR mit separater Christian-F2 via POST /api/deploy {mode:'DRY_LIVE'}.
      if (CFG.DEPLOY_MODE === 'DRY_LIVE') {
        // Echte API-Latenz simulieren: ticker + orderbook fetchen (Bitget public-API)
        const ticker = await Bitget.fetchTicker(symbol).catch(() => null);
        const ob = await Bitget.fetchOrderbook(symbol).catch(() => null);
        let slipPct = 0.0002;
        try {
          if (ob && ob.bids && ob.asks) {
            const book = direction === 'BUY' ? ob.asks : ob.bids;
            if (book.length) {
              const avg = book.slice(0, 5).reduce((s, l) => s + parseFloat(l[0]), 0) / Math.min(5, book.length);
              if (referencePrice > 0) slipPct = Math.abs(avg - referencePrice) / referencePrice;
            }
          }
        } catch(_) {}
        // F20 [15.05.2026] SLIPPAGE-CAP DRY_LIVE — DEMO=LIVE-konform
        const _maxSlipDry = CFG.MAX_SLIPPAGE_PCT || 0.005;
        if (slipPct > _maxSlipDry) {
          try { Log.warn('DRY_LIVE', `${symbol} slip ${(slipPct*100).toFixed(3)}% > MAX — reject`); } catch(_){}
          return { ok: false, mode: 'DRY_LIVE', error: 'SLIPPAGE_TOO_HIGH', slippagePct: slipPct, maxSlippage: _maxSlipDry };
        }
        const fillPrice = direction === 'BUY' ? referencePrice * (1 + slipPct) : referencePrice * (1 - slipPct);
        try { Log.info('DRY_LIVE', `${symbol} ${direction} ${sizeUSDT.toFixed(2)} USDT @ ${fillPrice.toFixed(4)} slip=${(slipPct*100).toFixed(3)}% (no order placed)`); } catch(_){}
        return {
          ok: true, mode: 'DRY_LIVE',
          symbol, direction, sizeUSDT, fillPrice, slippagePct: slipPct,
          latencyMs: Date.now() - t0, partialFill: false,
          orderId: 'DRY_LIVE_' + symbol + '_' + Date.now(),
          t0, tEnd: Date.now(),
        };
      }

      if (!CFG.API_KEY) return { ok:false, mode:'LIVE', error:'NO_API_KEY' };

      // F20 [15.05.2026] SLIPPAGE PRE-FLIGHT CHECK — DEMO=LIVE konsistent
      // // LIVE-ONLY: vor placeSportOrder Orderbook-Estimate, reject bei estimated > MAX
      try {
        const _obPre = await Bitget.fetchOrderbook(symbol).catch(() => null);
        if (_obPre && _obPre.bids && _obPre.asks && _obPre.bids.length && _obPre.asks.length) {
          const book = direction === 'BUY' ? _obPre.asks : _obPre.bids;
          let rem = sizeUSDT, totalCost = 0, totalQty = 0;
          for (const lvl of book) {
            const p = parseFloat(lvl[0]), q = parseFloat(lvl[1]);
            const lvlUSDT = p * q;
            if (rem <= lvlUSDT) { totalQty += rem / p; totalCost += rem; rem = 0; break; }
            else { totalQty += q; totalCost += lvlUSDT; rem -= lvlUSDT; }
          }
          if (totalQty > 0) {
            const estSlip = Math.abs((totalCost / totalQty) - referencePrice) / referencePrice;
            const _maxSlipLive = CFG.MAX_SLIPPAGE_PCT || 0.005;
            if (estSlip > _maxSlipLive) {
              try { Log.warn('ADAPTER', `LIVE PRE-FLIGHT slip ${(estSlip*100).toFixed(3)}% > MAX — reject`); } catch(_){}
              return { ok: false, mode: 'LIVE', error: 'SLIPPAGE_TOO_HIGH', estimatedSlippage: estSlip, maxSlippage: _maxSlipLive };
            }
          }
        }
      } catch(_) {}

      const order = await Bitget.placeSportOrder(symbol, direction.toLowerCase(), sizeUSDT, 'market', null, opts.clientOid);
      if (!order || order.code !== '00000') {
        return { ok:false, mode:'LIVE', error: (order && order.msg) || 'ORDER_REJECTED' };
      }
      const orderId = order.data && order.data.orderId;

      // Echten Fill holen (2s warten)
      await new Promise(r => setTimeout(r, 2000));
      let fillPrice = referencePrice;
      let fillSize = sizeUSDT;
      let partialFill = false;
      try {
        const detail = await Bitget.get('/api/v2/spot/trade/orderInfo?orderId=' + orderId);
        if (detail && detail.data) {
          const od = Array.isArray(detail.data) ? detail.data[0] : detail.data;
          if (od.priceAvg && parseFloat(od.priceAvg) > 0) fillPrice = parseFloat(od.priceAvg);
          if (od.baseVolume && parseFloat(od.baseVolume) > 0) fillSize = parseFloat(od.baseVolume) * fillPrice;
          const status = od.state || od.status || '';
          if (status.includes('partial')) partialFill = true;
        }
      } catch(e) {
        try{ Log.warn('ADAPTER','fill-check err: '+e.message); }catch(_){}
      }

      const slipPct = referencePrice > 0 ? Math.abs(fillPrice - referencePrice) / referencePrice : 0;
      const result = {
        ok: true, mode:'LIVE',
        symbol, direction,
        sizeUSDT: fillSize,
        fillPrice, slippagePct: slipPct,
        latencyMs: Date.now() - t0,
        partialFill,
        orderId,
        clientOid: opts.clientOid,
        t0, tEnd: Date.now(),
      };
      // AUDFIX_IDEMPOTENCY: in OrderRegistry persistieren
      try { OrderRegistry.put(opts.clientOid, result, 'FILLED'); } catch(_) {}
      try {
        ActionStream.push('ENTRY', symbol,
          'LIVE '+direction+' '+fillSize.toFixed(2)+' USDT @ '+fillPrice.toFixed(4)+' slip='+(slipPct*100).toFixed(3)+'% order='+orderId+(partialFill?' PARTIAL':''),
          { mode:'LIVE', direction, size:fillSize, fillPrice, slippagePct:slipPct, orderId, partialFill });
      } catch(_){}
      return result;
    } catch(e) {
      try{ Log.warn('ADAPTER','live err: '+e.message); }catch(_){}
      return { ok:false, mode:'LIVE', error: e.message };
    }
  },

  // Diagnose/Snapshot
  snapshot() {
    return {
      currentMode: (DemoEngine && DemoEngine.liveMode) ? 'LIVE' : 'DEMO',
      apiKeySet: !!CFG.API_KEY,
      deployMode: CFG.DEPLOY_MODE,
    };
  },
};

const ActionStream = {
  MAX: 500,
  events: [],
  push(type, module, msg, data) {
    try {
      const ev = {
        ts: Date.now(),
        time: new Date().toLocaleTimeString('de-DE', {hour:'2-digit',minute:'2-digit',second:'2-digit'}),
        type: type || 'INFO',
        module: module || '',
        msg: String(msg || '').slice(0, 200),
        data: data || null,
      };
      this.events.unshift(ev);
      if (this.events.length > this.MAX) this.events.length = this.MAX;
    } catch(_) {}
  },
  snapshot(limit, typeFilter) {
    let list = this.events;
    if (typeFilter && typeFilter.length) list = list.filter(e => typeFilter.includes(e.type));
    return list.slice(0, limit || 100);
  },
  stats() {
    const by = {};
    for (const e of this.events) by[e.type] = (by[e.type]||0) + 1;
    return { total: this.events.length, byType: by, oldestTs: this.events.length ? this.events[this.events.length-1].ts : null };
  }
};

const DBJanitor = {
  timer: null,
  interval: 1800000,
  pending: {},
  PENDING_TTL: 86400000,
  history: [],
  // Tier-Z Patch Z.4 [2026-05-12]: Mute-Suppression-Pattern.
  // _alertedIds Set verhindert dass gleicher Datenmuell wiederholt gemeldet wird.
  // _muted=true blockt alle Alerts (CRITICAL/EMERGENCY laufen weiter via TelegramAlarm).
  // _alertedIds wird taeglich 04:00 + bei pending=0 nach erfolgreichem Cleanup geleert.
  _alertedIds: new Set(),
  _muted: true,           // Default: an (Dedup-Filter aktiv) — Christian's Spec
  _lastResetDay: -1,

  alert(cl, msg) {
    // Auto-Reset taeglich 04:00 Local (Janitor-Loop laeuft alle 30 Min, ein Lauf trifft typisch)
    const now = new Date();
    const dayKey = now.getFullYear()*10000 + (now.getMonth()+1)*100 + now.getDate();
    if (now.getHours() === 4 && this._lastResetDay !== dayKey) {
      this._alertedIds.clear();
      this._lastResetDay = dayKey;
      Log.info('JANITOR', 'Auto-Reset alertedIds (04:00 daily)');
    }
    // Christian's Spec: "Default mute on, neue IDs bypassen mute".
    // Semantisch: mute=true = Set-basierter Dedup aktiv (1x pro Signatur).
    //             mute=false = kein Dedup, jeder Scan-Lauf sendet alle Cluster.
    // Dedup-Key: reason + symbol + where-Klausel (stabil ueber Scans, NICHT cl.id mit Timestamp)
    const key = String(cl.reason || '') + '|' + String(cl.symbol || '') + '|' + String(cl.where || '');
    if (this._muted && this._alertedIds.has(key)) return { skipped: true, reason: 'DEDUP' };
    this._alertedIds.add(key);
    try {
      TelegramAlarm.warn('JANITOR', msg, { id: cl.id, count: cl.count });
      return { sent: true, key };
    } catch(e) {
      try { Log.warn('JANITOR','telegram err: '+e.message); } catch(_){}
      return { sent: false, error: e.message };
    }
  },

  resetAlerts() {
    const n = this._alertedIds.size;
    this._alertedIds.clear();
    return { cleared: n };
  },

  muteStatus() {
    return { muted: this._muted, alertedIds: this._alertedIds.size, pending: Object.keys(this.pending).length };
  },

  async scan() {
    const clusters = [];
    try {
      const dupes = DB.db.prepare(`
        SELECT symbol, entry_price, exit_price, pnl, exit_reason, direction, strategy,
               COUNT(*) as n, MIN(ts) as min_ts, MAX(ts) as max_ts
        FROM strategy_performance
        WHERE COALESCE(is_backtest,0)=0
        GROUP BY symbol, entry_price, exit_price, pnl, exit_reason, direction, strategy
        HAVING n >= 100 AND (max_ts - min_ts) < 300000
      `).all();
      for (const d of dupes) {
        clusters.push({
          id: 'DUPE_'+d.symbol+'_'+d.exit_reason+'_'+d.min_ts,
          reason: 'DUPLICATE_FLOOD',
          count: d.n,
          symbol: d.symbol, exit_reason: d.exit_reason,
          timeWindow: ((d.max_ts-d.min_ts)/1000).toFixed(0)+'s',
          avgPnl: d.pnl,
          where: "symbol='"+d.symbol+"' AND exit_reason='"+d.exit_reason+"' AND entry_price="+d.entry_price+" AND exit_price="+d.exit_price+" AND ts BETWEEN "+d.min_ts+" AND "+d.max_ts
        });
      }

      const longKill = DB.db.prepare(`
        SELECT COUNT(*) as n, GROUP_CONCAT(DISTINCT symbol) as symbols
        FROM strategy_performance
        WHERE exit_reason='KILL_SWITCH' AND hold_ms > 86400000 AND COALESCE(is_backtest,0)=0
      `).get();
      if (longKill && longKill.n > 0) {
        clusters.push({
          id: 'LONGKILL_'+Date.now(),
          reason: 'KILL_SWITCH_UNPLAUSIBLE_HOLD',
          count: longKill.n,
          symbol: longKill.symbols,
          where: "exit_reason='KILL_SWITCH' AND hold_ms > 86400000"
        });
      }

      const zeroExit = DB.db.prepare(`
        SELECT COUNT(*) as n, GROUP_CONCAT(DISTINCT exit_reason) as reasons
        FROM strategy_performance
        WHERE exit_price=0 AND exit_reason NOT IN ('CLEANUP_STALE','STALE_CLEANUP_TIME','STALE_ORPHAN') AND COALESCE(is_backtest,0)=0
      `).get();
      if (zeroExit && zeroExit.n > 0) {
        clusters.push({
          id: 'ZEROEXIT_'+Date.now(),
          reason: 'ZERO_EXIT_PRICE_NONSTALE',
          count: zeroExit.n,
          exit_reasons: zeroExit.reasons,
          where: "exit_price=0 AND exit_reason NOT IN ('CLEANUP_STALE','STALE_CLEANUP_TIME','STALE_ORPHAN')"
        });
      }
    } catch(e) {
      try{Log.warn('JANITOR','scan err: '+e.message);}catch(_){}
    }

    for (const cl of clusters) {
      if (this.pending[cl.id]) continue;
      this.pending[cl.id] = Object.assign({}, cl, { detectedAt: Date.now() });
      const msg = 'Janitor findet Datenmuell:\nID: '+cl.id+'\nGrund: '+cl.reason+'\nEintraege: '+cl.count+'\nSymbol: '+(cl.symbol||'-')+'\n\nApprove: /janitor_approve '+cl.id+'\nReject: /janitor_reject '+cl.id;
      this.alert(cl, msg);  // Tier-Z Z.4: mit Mute-Suppression
    }

    const now = Date.now();
    for (const id of Object.keys(this.pending)) {
      if (now - this.pending[id].detectedAt > this.PENDING_TTL) {
        this.history.unshift(Object.assign({}, this.pending[id], { result:'EXPIRED', ts:now }));
        delete this.pending[id];
      }
    }
    if (this.history.length > 100) this.history.length = 100;

    return { clusters: clusters.length, pending: Object.keys(this.pending).length, details: clusters };
  },

  approve(id) {
    const cl = this.pending[id];
    if (!cl) return { error: 'Unbekannte Janitor-ID: '+id };
    try {
      // Phase-4 [2026-05-11]: defensive Schicht — DELETE NIEMALS Backtest-Rows.
      // Scan filtert schon, aber falls cl.where breit ausfällt: explizit absichern.
      const res = DB.db.prepare('DELETE FROM strategy_performance WHERE ('+cl.where+') AND COALESCE(is_backtest,0)=0').run();
      this.history.unshift(Object.assign({}, cl, { result:'APPROVED', deleted: res.changes, ts: Date.now() }));
      delete this.pending[id];
      try { TelegramBot.send('Janitor: '+res.changes+' Eintraege geloescht ('+cl.reason+')'); } catch(_){}
      Log.info('JANITOR','Approved '+id+': deleted '+res.changes);
      return { ok:true, deleted: res.changes };
    } catch(e) {
      try{Log.warn('JANITOR','approve err: '+e.message);}catch(_){}
      return { error: e.message };
    }
  },

  reject(id) {
    const cl = this.pending[id];
    if (!cl) return { error: 'Unbekannte Janitor-ID: '+id };
    this.history.unshift(Object.assign({}, cl, { result:'REJECTED', ts: Date.now() }));
    delete this.pending[id];
    try { TelegramBot.send('Janitor: '+id+' abgelehnt'); } catch(_){}
    return { ok:true };
  },

  start() {
    if (this.timer) return;
    setTimeout(() => this.scan(), 60000);
    this.timer = setInterval(() => this.scan(), this.interval);
    Log.boot('DBJanitor gestartet (alle 30min)');
  },

  snapshot() {
    return {
      interval: this.interval,
      pending: Object.values(this.pending),
      pendingCount: Object.keys(this.pending).length,
      history: this.history.slice(0, 20),
    };
  },
};

const TelegramAlarm = {
  LEVELS:{INFO:0,WARN:1,CRITICAL:2,EMERGENCY:3},
  EMOJIS:{INFO:'ℹ️',WARN:'⚠️',CRITICAL:'🚨',EMERGENCY:'🔴'},
  recentAlarms:{}, DEDUP_MS:900000,
  auditTrail:[],
  pendingAcks:{}, ESCALATION_MS:600000,
  // Welle 1 Patch A [2026-05-12]: Mute-Toggle (in-memory, resettet bei Restart).
  // 'off' = alle Levels durch | 'on'/'critical' = nur CRITICAL+EMERGENCY durch.
  // AuditTrail + DB-Log werden auch im Mute-Zustand geschrieben.
  muteLevel: 'off',
  setMute(level){
    const norm = String(level||'').toLowerCase();
    if (norm === 'off' || norm === 'on' || norm === 'critical' || norm === 'status') {
      if (norm !== 'status') this.muteLevel = (norm === 'critical') ? 'on' : norm;
      return { ok:true, muteLevel: this.muteLevel };
    }
    return { ok:false, error: 'INVALID_LEVEL', allowed: ['off','on','critical','status'] };
  },
  async alert(level,module,message,data={}){
    const key=level+':'+module+':'+message.slice(0,50);const now=Date.now();
    if(this.recentAlarms[key]&&now-this.recentAlarms[key]<this.DEDUP_MS)return{sent:false,reason:'DUPLICATE'};
    this.recentAlarms[key]=now;
    const entry={ts:now,time:new Date().toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit',second:'2-digit'}),level,module,message,data:JSON.stringify(data).slice(0,200)};
    this.auditTrail.unshift(entry);if(this.auditTrail.length>200)this.auditTrail.pop();
    try{DB.insertLog.run(now,'TG_'+level,module,message,JSON.stringify(data).slice(0,500));}catch(e){ try{Log.warn('TelegramAlarm','err: '+e.message);}catch(_){} }
    // Welle 1 Patch A: Mute-Check (CRITICAL+EMERGENCY ignorieren Mute-Status)
    if (this.muteLevel === 'on' && level !== 'CRITICAL' && level !== 'EMERGENCY') {
      return { sent: false, reason: 'MUTED', level, module };
    }
    const prefix=level==='EMERGENCY'?'🔴🔴 NOTFALL 🔴🔴':level==='CRITICAL'?'🚨 KRITISCH':level==='WARN'?'⚠️ WARNUNG':'ℹ️ INFO';
    let msg=prefix+'\n'+entry.time+' | '+module+'\n━━━━━━━━━━━━━━━━━━━━\n'+message;
    if(data.action)msg+='\nAktion: '+data.action;
    if(level==='CRITICAL'||level==='EMERGENCY'){
      const ackId='ACK-'+now;this.pendingAcks[ackId]={...entry,ackId,escalated:false};
      msg+='\n\n/ack '+ackId+' zum Bestätigen';
      // Eskalation nur 1x, nicht wiederholt
      if(!this._lastEscalation || Date.now()-this._lastEscalation > this.ESCALATION_MS) { setTimeout(()=>this.checkEscalation(ackId),this.ESCALATION_MS); }
    }
    try{const r=await TelegramBot.send(msg);return(r&&r.sent)?{sent:true,messageId:r.messageId}:{sent:false,reason:(r&&r.reason)||'UNKNOWN'};}catch(e){try{Log.warn('TELEGRAM','alert failed: '+e.message);}catch(e){ try{Log.warn('TelegramAlarm','err: '+e.message);}catch(_){} } return{sent:false,reason:e.message};}
  },
  info(m,msg,d){return this.alert('INFO',m,msg,d);},
  warn(m,msg,d){return this.alert('WARN',m,msg,d);},
  critical(m,msg,d){return this.alert('CRITICAL',m,msg,d);},
  emergency(m,msg,d){return this.alert('EMERGENCY',m,msg,d);},
  checkEscalation(ackId){
    const a=this.pendingAcks[ackId];if(!a||a.acknowledged)return;
    if(!a.escalated){a.escalated=true;
      TelegramBot.send('🔴🔴 ESKALATION\nAlarm nicht bestätigt!\n'+a.module+': '+a.message+'\n\n⚠️ Safe Mode aktiviert\n/ack '+ackId);
      try{if(DemoEngine.running && DemoEngine.wallet && DemoEngine.wallet.trading < 0){DemoEngine.running=false;Log.warn('SAFE_MODE','DemoEngine gestoppt — Wallet negativ');} else { Log.info('SAFE_MODE','Wallet OK — DemoEngine läuft weiter'); }}catch(e){ try{Log.warn('TelegramAlarm','err: '+e.message);}catch(_){} }
    }
  },
  acknowledge(ackId){
    const a=this.pendingAcks[ackId];if(!a)return{error:'Unbekannt'};
    a.acknowledged=true;a.ackedAt=Date.now();
    if(a.escalated&&!DemoEngine.running){DemoEngine.start(DemoEngine.wallet?.total||1000);TelegramBot.send('✅ Bestätigt — DemoEngine gestartet');}
    else TelegramBot.send('✅ Alarm bestätigt: '+a.module);
    return{ok:true,ackId};
  },
  snapshot(){return{auditTrail:this.auditTrail.slice(0,30),pendingAcks:Object.values(this.pendingAcks).filter(a=>!a.acknowledged).length,totalAlarms:this.auditTrail.length,levels:{info:this.auditTrail.filter(a=>a.level==='INFO').length,warn:this.auditTrail.filter(a=>a.level==='WARN').length,critical:this.auditTrail.filter(a=>a.level==='CRITICAL').length,emergency:this.auditTrail.filter(a=>a.level==='EMERGENCY').length}};}
};

const AutonomousRepair = {
  enabled:true, timer:null, scanInterval:300000, history:[], pendingFix:null, errorBaseline:0,
  KNOWN_FIXES: {
    'WebSocket closed':     {type:'AUTO',action:'WS_RECONNECT',desc:'WebSocket reconnect'},
    'ECONNRESET':           {type:'AUTO',action:'API_RETRY',desc:'API retry'},
    'ECONNREFUSED':         {type:'AUTO',action:'API_RETRY',desc:'API retry'},
    'ETIMEDOUT':            {type:'AUTO',action:'API_RETRY',desc:'Timeout retry'},
    'Candle fetch failed':  {type:'AUTO',action:'CACHE_CLEAR',desc:'Cache clear'},
    'SQLITE_BUSY':          {type:'AUTO',action:'DB_RETRY',desc:'DB retry'},
    'SQLITE_LOCKED':        {type:'AUTO',action:'DB_RETRY',desc:'DB lock retry'},
    'heap out of memory':   {type:'AUTO',action:'PM2_RESTART',desc:'Memory — restart'},
    'Maximum call stack':   {type:'AUTO',action:'PM2_RESTART',desc:'Stack overflow'},
    'Cannot read prop':     {type:'ASK',action:'NULL_CHECK',desc:'Null/Undefined'},
    'is not a function':    {type:'ASK',action:'TYPE_ERROR',desc:'Typ-Fehler'},
    'is not defined':       {type:'ASK',action:'REF_ERROR',desc:'Variable fehlt'},
    'EPERM':                {type:'AUTO',action:'IGNORE',desc:'Harmlos'},
  },
  async monitor() {
    const issues=[],now=Date.now();
    try{const logs=DB.db.prepare("SELECT * FROM system_log WHERE level='ERROR' AND ts > ? ORDER BY ts DESC LIMIT 20").all(now-this.scanInterval);
      if(logs.length>0){const msgs=logs.map(l=>l.message||l.msg||'');[...new Set(msgs.map(m=>m.slice(0,80)))].forEach(err=>{issues.push({type:'ERROR_LOG',severity:logs.length>10?'HIGH':'MEDIUM',message:err,count:msgs.filter(m=>m.includes(err.slice(0,30))).length});});}
    }catch(_){}
    try{const mb=process.memoryUsage().heapUsed/1024/1024;if(mb>800)issues.push({type:'MEMORY',severity:'HIGH',message:'Heap: '+mb.toFixed(0)+'MB'});}catch(_){}
    try{if(DemoEngine.running&&DemoEngine.stats.scans>20&&DemoEngine.stats.trades===0){const m=(now-(DemoEngine.stats.startedAt||now))/60000;if(m>120)issues.push({type:'NO_TRADES',severity:'MEDIUM',message:DemoEngine.stats.scans+' Scans, 0 Trades'});}}catch(_){}
    try{DB.db.prepare('SELECT 1').get();}catch(e){issues.push({type:'DB_ERROR',severity:'CRITICAL',message:'DB nicht lesbar'});
      TelegramAlarm.emergency('DB', 'Datenbank nicht lesbar — sofort pruefen');}
    try{if(DemoEngine.wallet&&DemoEngine.wallet.trading<0)issues.push({type:'WALLET_NEG',severity:'HIGH',message:'Wallet Trading negativ: '+DemoEngine.wallet.trading.toFixed(2)});
        if(DemoEngine.wallet.trading<0) TelegramAlarm.critical('WALLET', 'Demo Wallet Trading negativ: ' + DemoEngine.wallet.trading.toFixed(2));
      if(DemoEngine.wallet&&Math.abs(DemoEngine.wallet.total-DemoEngine.wallet.reserve-DemoEngine.wallet.trading)>0.01)issues.push({type:'WALLET_DRIFT',severity:'HIGH',message:'Wallet Drift'});}catch(_){}
    try{const re=DB.db.prepare("SELECT COUNT(*) as n FROM system_log WHERE level='ERROR' AND ts > ?").get(now-300000)?.n||0;
      const oe=DB.db.prepare("SELECT COUNT(*) as n FROM system_log WHERE level='ERROR' AND ts > ? AND ts < ?").get(now-600000,now-300000)?.n||0;
      if(re>5&&oe>0&&re>oe*2){issues.push({type:'ERROR_SPIKE',severity:'HIGH',message:'Errors x2: '+re});
      TelegramAlarm.warn('MONITOR', 'Error-Rate verdoppelt: ' + re + ' in 5min');}}catch(_){}
    return issues;
  },
  diagnose(issue) {
    for(const[p,f]of Object.entries(this.KNOWN_FIXES)){if(issue.message&&issue.message.includes(p))return{known:true,pattern:p,fixType:f.type,action:f.action,description:f.desc,severity:issue.severity};}
    const m=(issue.message||'').toLowerCase();let c='UNKNOWN';
    if(m.includes('typeerror'))c='TYPE';else if(m.includes('not defined'))c='REF';else if(m.includes('syntax'))c='SYNTAX';else if(m.includes('timeout'))c='NET';else if(m.includes('sqlite'))c='DB';
    return{known:false,category:c,fixType:issue.severity==='CRITICAL'?'ASK':'ANALYZE',severity:issue.severity,description:'Unbekannt: '+c};
  },
  async repair(d) {
    if(d.fixType==='AUTO'){switch(d.action){
      case 'WS_RECONNECT':try{Bitget._connectInFlight=false;Bitget.connectWS&&Bitget.connectWS();}catch(_){}return{applied:true,action:d.action,auto:true};
      case 'API_RETRY':try{await Bitget.fetchTicker('BTCUSDT');}catch(_){}return{applied:true,action:d.action,auto:true};
      case 'CACHE_CLEAR':try{Bitget.priceCache={};}catch(_){}return{applied:true,action:d.action,auto:true};
      case 'DB_RETRY':try{DB.db.prepare('SELECT 1').get();}catch(_){}return{applied:true,action:d.action,auto:true};
      case 'PM2_RESTART':Log.warn('ARS','PM2 Restart');TelegramBot.send('ARS: PM2 Restart\n'+d.description);setTimeout(()=>process.exit(0),10000);return{applied:true,action:d.action,auto:true};
      case 'IGNORE':return{applied:false,action:'IGNORE',auto:true};}}
    if(d.fixType==='ASK'){this.pendingFix={diagnosis:d,ts:Date.now(),status:'PENDING'};TelegramBot.send('ARS Fix noetig\n'+d.description+'\n/approve oder /reject');return{applied:false,action:'WAITING',pending:true};}
    return{applied:false};
  },
  async testFix(){const t={syntax:true,logic:true};try{require('child_process').execSync('node --check '+process.env.HOME+'/NEXUS_CLEAN/server.js',{timeout:10000});}catch(_){t.syntax=false;}
    t.logic=typeof UnifiedScore.compute==='function'&&typeof Trades.close==='function';return{passed:t.syntax&&t.logic,tests:t};},
  async metaDecide(d,r,t){const v={sec:SecurityKI.snapshot().status==='OK',test:t?t.passed:true};let dec;if(d.fixType==='AUTO'&&r.applied)dec='AUTO_APPLIED';else if(d.fixType==='ASK')dec='WAITING_HUMAN';else if(t&&!t.passed)dec='REJECTED';else dec='NO_ACTION';return{decision:dec,votes:v};},
  async cycle(){try{const issues=await this.monitor();if(!issues.length)return;
    try{this.errorBaseline=DB.db.prepare("SELECT COUNT(*) as n FROM system_log WHERE level='ERROR' AND ts > ?").get(Date.now()-300000)?.n||0;}catch(_){}
    for(const i of issues){if(this.history.find(h=>h.issue?.type===i.type&&Date.now()-h.ts<1800000))continue;
      const d=this.diagnose(i),r=await this.repair(d),t=r.applied?await this.testFix():null,m=await this.metaDecide(d,r,t);
      this.history.unshift({ts:Date.now(),time:new Date().toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'}),issue:i,diagnosis:{known:d.known,pattern:d.pattern,action:d.action},repair:{applied:r.applied,action:r.action,auto:r.auto},test:t,meta:m});
      if(this.history.length>100)this.history.pop();}}catch(e){Log.warn('ARS',e.message);}},
  handleApproval(ok){if(!this.pendingFix)return{error:'Kein Fix'};this.pendingFix.status=ok?'APPROVED':'REJECTED';const r={...this.pendingFix};this.pendingFix=null;return r;},
  start(){if(this.timer)return;this.timer=setInterval(()=>this.cycle(),this.scanInterval);setTimeout(()=>this.cycle(),30000);Log.boot('ARS gestartet');},
  snapshot(){return{enabled:this.enabled,pendingFix:this.pendingFix,recentHistory:this.history.slice(0,20),stats:{totalScans:this.history.length,autoFixes:this.history.filter(h=>h.repair?.auto&&h.repair?.applied).length,humanFixes:this.history.filter(h=>h.meta?.decision==='WAITING_HUMAN').length,rejected:this.history.filter(h=>h.meta?.decision?.startsWith('REJECTED')).length},knownPatterns:Object.keys(this.KNOWN_FIXES).length};}
};

const SecurityKI = {
  enabled:true, scanInterval:300000, timer:null, lastScan:null, alerts:[], fileHashes:{},
  async checkFiles() {
    const crypto=require('crypto'), fs2=require('fs');
    const files=[process.env.HOME+'/NEXUS_CLEAN/server.js', process.env.HOME+'/NEXUS_CLEAN/.env'];
    const results=[];
    for (const f of files) {
      try {
        const hash=crypto.createHash('sha256').update(fs2.readFileSync(f)).digest('hex').slice(0,16);
        const prev=this.fileHashes[f];
        if (prev&&prev!==hash) { results.push({file:f.split('/').pop(),status:'CHANGED',prev,now:hash,severity:'HIGH'}); this._alert('FILE_CHANGED',f.split('/').pop()+' veraendert','HIGH'); }
        else results.push({file:f.split('/').pop(),status:'OK',hash});
        this.fileHashes[f]=hash;
      } catch(e) { results.push({file:f.split('/').pop(),status:'ERROR',error:'Nicht lesbar'}); }
    }
    return results;
  },
  async checkProcesses() {
    try {
      const ps=require('child_process').execSync('ps aux',{timeout:5000}).toString();
      const nodeProcs=ps.split('\n').filter(l=>l.includes('node')&&!l.includes('grep'));
      const suspicious=nodeProcs.filter(l=>!l.includes('nexus')&&!l.includes('NEXUS')&&!l.includes('pm2')&&!l.includes('PM2')&&!l.includes('node_modules')&&!l.includes('npm')&&!l.includes('.pm2')&&!l.includes('fix_')&&!l.includes('Desktop')&&!l.includes('server.js')&&!l.includes('christianheilig')&&l.trim()).map(l=>({process:l.trim().slice(0,100),status:'UNKNOWN'}));
      if (suspicious.length>0) this._alert('UNKNOWN_PROCESS',suspicious.length+' unbekannte Prozesse','MEDIUM');
      return {total:nodeProcs.length,suspicious,status:suspicious.length===0?'OK':'WARNING'};
    } catch(e) { return {total:0,suspicious:[],status:'CHECK_FAILED'}; }
  },
  async checkConnections() {
    try {
      const ns=require('child_process').execSync('netstat -an 2>/dev/null || ss -tun 2>/dev/null',{timeout:5000}).toString();
      const est=ns.split('\n').filter(l=>l.includes('ESTABLISHED')||l.includes('ESTAB'));
      return {connections:est.length,blocked:[],status:'OK'};
    } catch(e) { return {connections:0,blocked:[],status:'CHECK_FAILED'}; }
  },
  _alert(type,message,severity) {
    this.alerts.unshift({ts:Date.now(),type,message,severity,time:new Date().toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})});
    if (this.alerts.length>100) this.alerts.pop();
    Log.warn('SECURITY_KI',type+': '+message);
    if (severity==='HIGH'||severity==='CRITICAL') TelegramAlarm.critical('SECURITY', type+': '+message); if(false) TelegramBot.send('\u{1F6E1} SECURITY: '+type+'\n'+message);
  },
  async fullScan() {
    const files=await this.checkFiles(), procs=await this.checkProcesses(), conns=await this.checkConnections();
    this.lastScan=Date.now();
    return {ok:files.every(f=>f.status==='OK')&&procs.status==='OK'&&conns.status==='OK', files,processes:procs,connections:conns,alerts:this.alerts.slice(0,20),lastScan:this.lastScan};
  },
  start() { if(this.timer)return; this.fullScan(); this.timer=setInterval(()=>this.fullScan(),this.scanInterval); Log.boot('Security-KI gestartet'); },
  snapshot() { return {enabled:this.enabled,lastScan:this.lastScan,alertCount:this.alerts.length,recentAlerts:this.alerts.slice(0,10),status:this.alerts.filter(a=>a.severity==='HIGH'&&Date.now()-a.ts<3600000).length>0?'ALARM':'OK'}; }
};

const UpdateKI = {
  currentVersion:'v9.0', gitCommit:null, lastCheck:null, updateHistory:[], rollbackAvailable:false,
  async checkVersion() {
    const {execSync}=require('child_process');
    try {
      const commit=execSync('cd '+process.env.HOME+'/NEXUS_CLEAN && git log --oneline -1',{timeout:5000, stdio:['pipe','pipe','pipe']}).toString().trim();
      const branch=execSync('cd '+process.env.HOME+'/NEXUS_CLEAN && git branch --show-current',{timeout:5000, stdio:['pipe','pipe','pipe']}).toString().trim();
      const status=execSync('cd '+process.env.HOME+'/NEXUS_CLEAN && git status --porcelain',{timeout:5000, stdio:['pipe','pipe','pipe']}).toString().trim();
      this.gitCommit=commit.split(' ')[0]; this.lastCheck=Date.now();
      const backups=parseInt(execSync('ls '+process.env.HOME+'/NEXUS_CLEAN/server.js.* 2>/dev/null | wc -l',{timeout:5000}).toString().trim());
      this.rollbackAvailable=backups>0;
      return {version:this.currentVersion,commit,branch,dirty:status.length>0,uncommittedChanges:status?status.split('\n').length:0,rollbackAvailable:this.rollbackAvailable,backupCount:backups,lastCheck:this.lastCheck};
    } catch(e) { return {version:this.currentVersion,error:'Git Check fehlgeschlagen'}; }
  },
  async syntaxCheck() {
    try { require('child_process').execSync('node --check '+process.env.HOME+'/NEXUS_CLEAN/server.js',{timeout:10000}); return {ok:true}; }
    catch(e) { return {ok:false}; }
  },
  snapshot() { return {version:this.currentVersion,gitCommit:this.gitCommit,lastCheck:this.lastCheck,rollbackAvailable:this.rollbackAvailable,updateHistory:this.updateHistory.slice(0,20)}; }
};

