app.get('/api/blocked/stats', (req,res) => {
  try {
    const period = String(req.query.period || 'today').toLowerCase();
    let fromMs;
    if (period === 'today') {
      const d = new Date(); d.setHours(0,0,0,0); fromMs = d.getTime();
    } else if (period === '24h') {
      fromMs = Date.now() - 24*3600*1000;
    } else if (period === '7d') {
      fromMs = Date.now() - 7*24*3600*1000;
    } else if (period === 'all') {
      fromMs = 0;
    } else {
      fromMs = Date.now() - 24*3600*1000;
    }
    const countsReal = DB.countBlockedSinceByReasonReal.all(fromMs);
    const countsTheo = DB.countBlockedSinceByReasonTheoretical.all(fromMs);
    const real = Object.fromEntries(countsReal.map(r => [r.block_reason, r.n]));
    const theo = Object.fromEntries(countsTheo.map(r => [r.block_reason, r.n]));
    const totalReal = countsReal.reduce((s, r) => s + Number(r.n || 0), 0);
    const totalTheo = countsTheo.reduce((s, r) => s + Number(r.n || 0), 0);
    const recentReal = DB.getBlockedSinceReal.all(fromMs, 10);
    const recentTheo = DB.getBlockedSinceTheoretical.all(fromMs, 10);
    const mapRow = r => ({
      ts: r.ts, symbol: r.symbol, direction: r.intended_direction,
      reason: r.block_reason, unifiedScore: r.unified_score,
      unifiedConfidence: r.unified_confidence, brainConfidence: r.brain_confidence,
      theoretical: !!r.theoretical_block,
    });
    res.json({
      ts: Date.now(),
      period,
      from: fromMs,
      // total bleibt als Summe für Backward-Compat, aber echt+theoretisch
      total: totalReal + totalTheo,
      real:        { total: totalReal, byReason: real, byVeto: real.BRAIN_VETO_NO_CONSENSUS || 0, byFloor: real.FLOOR_THRESHOLD || 0 },
      theoretical: { total: totalTheo, byReason: theo, byFloor: theo.FLOOR_THRESHOLD || 0 },
      // Legacy-Felder für UI-Backward-Compat
      byFloor: (real.FLOOR_THRESHOLD || 0),
      byVeto:  (real.BRAIN_VETO_NO_CONSENSUS || 0),
      recentReal:        recentReal.map(mapRow),
      recentTheoretical: recentTheo.map(mapRow),
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// FIX-WALLET E [17.05.2026]: Combined-Vetos zeigt log_only (blocked_trades)
// UND echte Hard-Blocks (aladdin_decisions.vetos) zusammen.
// Gibt UI eine vollständige Wirklichkeit statt nur FLOOR_THRESHOLD.
app.get('/api/vetos/combined', (req,res) => {
  try {
    const period = String(req.query.period || '24h').toLowerCase();
    let fromMs;
    if (period === 'today') { const d=new Date(); d.setHours(0,0,0,0); fromMs=d.getTime(); }
    else if (period === '12h') fromMs = Date.now() - 12*3600*1000;
    else if (period === '6h')  fromMs = Date.now() - 6*3600*1000;
    else if (period === '7d')  fromMs = Date.now() - 7*24*3600*1000;
    else if (period === 'all') fromMs = 0;
    else fromMs = Date.now() - 24*3600*1000;

    // Quelle 1: blocked_trades (log_only + active)
    const logOnly = DB.db.prepare(`
      SELECT block_reason, COUNT(*) AS cnt,
             SUM(CASE WHEN theoretical_block=1 THEN 1 ELSE 0 END) AS theoretical,
             SUM(CASE WHEN theoretical_block=0 THEN 1 ELSE 0 END) AS real_blocks
      FROM blocked_trades
      WHERE ts > ?
      GROUP BY block_reason
      ORDER BY cnt DESC
    `).all(fromMs);

    // Quelle 2: aladdin_decisions.vetos (echte Hard-Blocks im Brain-Pfad)
    const hardBlocks = DB.db.prepare(`
      SELECT
        CASE
          WHEN vetos LIKE '%SHARPE_EXTREME%' THEN 'SHARPE_EXTREME'
          WHEN vetos LIKE '%BAYESIAN_BEAR%'  THEN 'BAYESIAN_BEAR'
          WHEN vetos LIKE '%BAYESIAN_BULL%'  THEN 'BAYESIAN_BULL'
          WHEN vetos LIKE '%MONTE_CARLO_VaR%' THEN 'MONTE_CARLO_VaR'
          WHEN vetos LIKE '%ANOMALY%'        THEN 'ANOMALY'
          WHEN vetos LIKE '%BTC_DROP%'       THEN 'BTC_DROP'
          WHEN vetos LIKE '%KILL_SWITCH%'    THEN 'KILL_SWITCH'
          WHEN vetos = '[]' OR vetos IS NULL THEN 'NO_VETO'
          ELSE 'OTHER'
        END AS veto_type,
        COUNT(*) AS cnt
      FROM aladdin_decisions
      WHERE ts > ?
      GROUP BY veto_type
      ORDER BY cnt DESC
    `).all(fromMs);

    const totalDecisions = hardBlocks.reduce((s,r) => s + (r.cnt||0), 0);
    const hardBlockTotal = hardBlocks.filter(r => r.veto_type !== 'NO_VETO')
                                     .reduce((s,r) => s + (r.cnt||0), 0);

    // Top-Echter-Veto: Hard-Block > log_only-Real > log_only-Theo
    const topHard = hardBlocks.filter(r => r.veto_type !== 'NO_VETO')[0];
    const topReal = logOnly.find(r => r.real_blocks > 0);
    const topTheo = logOnly[0];
    const topActual = topHard ? { source: 'hard_block', ...topHard }
                    : topReal ? { source: 'log_only_real', ...topReal }
                    : topTheo ? { source: 'log_only_theoretical', ...topTheo }
                    : null;

    res.json({
      ts: Date.now(),
      period,
      from: fromMs,
      hardBlocks: {
        source: 'aladdin_decisions.vetos',
        note: 'Echte Hard-Blocks im AladdinBrain-Decision-Flow',
        total_decisions: totalDecisions,
        total_hard_blocks: hardBlockTotal,
        no_veto: hardBlocks.find(r => r.veto_type === 'NO_VETO')?.cnt || 0,
        byReason: Object.fromEntries(hardBlocks.filter(r => r.veto_type !== 'NO_VETO').map(r => [r.veto_type, r.cnt])),
      },
      logOnly: {
        source: 'blocked_trades',
        note: 'Telemetry-Logs (theoretical=1) + echte Blocks (theoretical=0)',
        byReason: Object.fromEntries(logOnly.map(r => [r.block_reason, { total: r.cnt, real: r.real_blocks, theoretical: r.theoretical }])),
      },
      top_actual_veto: topActual,
    });
  } catch(e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

