// D (Phase 2) [15.05.2026] NEWS-FEED Endpoint (für Frontend-Tab)
// // DEMO=LIVE: identisch — RSS-Feed ist deploy-agnostisch
app.get('/api/news/feed', (req,res) => {
  try {
    const limit = Math.min(parseInt(req.query.limit) || 50, 200);
    const coinFilter = String(req.query.coin || '').toUpperCase();
    const sentimentFilter = String(req.query.sentiment || ''); // 'positive', 'negative', 'neutral', ''
    const sinceParam = parseInt(req.query.since) || 0;
    const since = sinceParam || (Date.now() - 24*3600*1000);

    let q = "SELECT id, ts, source, title, url, pub_date, risk_score, neg_score, pos_score, alert_flag, symbols_json FROM news_feed WHERE ts > ?";
    const params = [since];
    if (coinFilter) {
      q += " AND (title LIKE ? OR symbols_json LIKE ?)";
      params.push('%'+coinFilter.replace('USDT','')+'%', '%'+coinFilter+'%');
    }
    if (sentimentFilter === 'positive') q += " AND pos_score > neg_score AND pos_score > 0.2";
    else if (sentimentFilter === 'negative') q += " AND neg_score > pos_score AND neg_score > 0.2";
    else if (sentimentFilter === 'neutral') q += " AND ABS(pos_score - neg_score) < 0.2";
    q += " ORDER BY ts DESC LIMIT ?";
    params.push(limit);
    const rows = DB.db.prepare(q).all(...params);

    const items = rows.map(r => {
      const sentiment = r.pos_score > r.neg_score && r.pos_score > 0.2 ? 'positive'
                      : r.neg_score > r.pos_score && r.neg_score > 0.2 ? 'negative'
                      : 'neutral';
      let symbols = [];
      try { symbols = r.symbols_json ? JSON.parse(r.symbols_json) : []; } catch(_) {}
      return {
        id: r.id, ts: r.ts, source: r.source, title: r.title, url: r.url,
        pubDate: r.pub_date, riskScore: r.risk_score, alertFlag: !!r.alert_flag,
        posScore: r.pos_score, negScore: r.neg_score,
        sentiment, symbols,
      };
    });

    res.json({ ok: true, count: items.length, since, items });
  } catch(e) { res.status(500).json({ error: e.message }); }
});
