// B.3 [14.05.2026] V9-REPLAY-ENDPOINT
// Liefert alle Voter-Decisions + Schwellen + Blocks im Zeitfenster eines Trades.
app.get('/api/v9/replay', (req, res) => {
  const tradeId = req.query.trade_id;
  if (!tradeId) return res.status(400).json({ error: 'trade_id required' });
  const winMs = Math.min(parseInt(req.query.window_ms || '300000'), 3600000);
  try {
    const trade = DB.db.prepare('SELECT * FROM trades WHERE id=?').get(tradeId);
    if (!trade) return res.status(404).json({ error: 'trade not found', trade_id: tradeId });
    const sym = trade.symbol;
    const tEntry = trade.created_at;
    const tExit = trade.closed_at || Date.now();
    const tBefore = tEntry - winMs;
    const tAfter = tExit + winMs;

    const consensus = DB.db.prepare(
      'SELECT id, ts, symbol, hardstop_blocked, hardstop_reason, brain_decision, brain_confidence, ' +
      'unified_direction, unified_confidence, regime, final_decision, final_confidence, final_reason, mode ' +
      'FROM consensus_decisions WHERE symbol=? AND ts BETWEEN ? AND ? ORDER BY ts'
    ).all(sym, tBefore, tAfter);

    const aladdin = DB.db.prepare(
      'SELECT id, ts, symbol, decision, confidence, position_pct, consensus, vetos, reason, ' +
      'unified_dir, unified_conf, read_only ' +
      'FROM aladdin_decisions WHERE symbol=? AND ts BETWEEN ? AND ? ORDER BY ts'
    ).all(sym, tBefore, tAfter);

    const blocks = DB.db.prepare(
      'SELECT id, ts, symbol, intended_direction, block_reason, unified_score, unified_confidence, ' +
      'brain_decision, brain_confidence, brain_reason, market_price, theoretical_block ' +
      'FROM blocked_trades WHERE symbol=? AND ts BETWEEN ? AND ? ORDER BY ts'
    ).all(sym, tBefore, tAfter);

    const ledger = DB.db.prepare(
      'SELECT id, ts, op, amount, reason FROM wallet_ledger ' +
      'WHERE (reason LIKE ? OR ts BETWEEN ? AND ?) ORDER BY ts'
    ).all('%' + tradeId + '%', tEntry, tExit);

    const consistency = DB.db.prepare(
      'SELECT id, ts, severity, check_name, issue, auto_fixed, details ' +
      'FROM consistency_log WHERE ts BETWEEN ? AND ? ORDER BY ts'
    ).all(tBefore, tAfter);

    res.json({
      trade,
      window: { tBefore, tEntry, tExit, tAfter, durationMs: tExit - tEntry, windowExtMs: winMs },
      consensus_decisions: consensus,
      aladdin_decisions: aladdin,
      blocked_trades: blocks,
      wallet_ledger: ledger,
      consistency_log: consistency,
      summary: {
        consensusCount: consensus.length,
        aladdinCount: aladdin.length,
        blockedCount: blocks.length,
        ledgerCount: ledger.length,
        consistencyEvents: consistency.length,
      },
    });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

