// ── PHASE 4 [2026-05-04]: Aladdin Brain Dashboard API ──
app.get('/api/aladdin/snapshot', (req,res) => {
  try {
    const snap = AladdinBrain.snapshot();
    const recentRows = DB.db.prepare(`
      SELECT a.* FROM aladdin_decisions a
      INNER JOIN (
        SELECT symbol, MAX(ts) as max_ts FROM aladdin_decisions GROUP BY symbol
      ) b ON a.symbol = b.symbol AND a.ts = b.max_ts
      ORDER BY a.ts DESC LIMIT 10
    `).all();
    const symbolDecisions = recentRows.map(r => {
      let families = {};
      try { families = JSON.parse(r.families || '{}'); } catch(_) {}
      return {
        symbol: r.symbol,
        decision: r.decision,
        confidence: r.confidence,
        positionPct: r.position_pct,
        consensus: r.consensus,
        families,
        unifiedDir: r.unified_dir,
        agrees: r.unified_dir === r.decision,
        ts: r.ts,
      };
    });
    const tradeable = symbolDecisions.filter(d => d.decision !== 'HOLD' && d.confidence > 0);
    tradeable.sort((a,b) => b.confidence - a.confidence);
    const topSignal = tradeable[0] || null;
    res.json({ ok:true, snap, symbolDecisions, topSignal });
  } catch(e) {
    res.json({ ok:false, error:e.message });
  }
});

