// Block S A6 [27.05.2026]: Veto-Stats Aggregation für Dashboard.
app.get('/api/router/veto-stats', (req,res) => {
  try {
    if (!_FinalRouter) return res.json({ ok:false, error:'router not loaded' });
    const hours = Math.min(parseInt(req.query.hours) || 24, 168);
    const since = Date.now() - hours * 3600 * 1000;
    const rows = DB.db.prepare(`SELECT symbol, decision, confidence FROM aladdin_decisions WHERE ts > ?`).all(since);
    const stats = { total: rows.length, by_veto: {}, by_symbol: {}, allowed: 0, blocked: 0, analysis_only: 0 };
    for (const r of rows) {
      const fr = _FinalRouter.finalize({decision:r.decision,confidence:r.confidence}, r.symbol, {db:DB.db, selectedStrategy:'TREND'});
      if (fr.tradeAllowed) stats.allowed++;
      else stats.blocked++;
      if (fr.vetoReason === 'ANALYSIS_ONLY') stats.analysis_only++;
      const reason = fr.vetoReason || 'OK';
      stats.by_veto[reason] = (stats.by_veto[reason] || 0) + 1;
      if (!stats.by_symbol[r.symbol]) stats.by_symbol[r.symbol] = { total:0, allowed:0, blocked:0, vetos:{} };
      stats.by_symbol[r.symbol].total++;
      if (fr.tradeAllowed) stats.by_symbol[r.symbol].allowed++;
      else { stats.by_symbol[r.symbol].blocked++; stats.by_symbol[r.symbol].vetos[reason] = (stats.by_symbol[r.symbol].vetos[reason]||0)+1; }
    }
    res.json({ ok:true, window_hours:hours, ...stats });
  } catch(e) { res.json({ ok:false, error:e.message }); }
});

// P8 [14.05.2026] BRAIN-COCKPIT-V2 — bundled state für UI-V2
// Bug 4 [15.05.2026]: response enthält jetzt latestRow.regime (DB-Spalte)
app.get('/api/brain-cockpit/state', (req,res) => {
  try {
    const symbol = req.query.symbol;
    const historyLimit = Math.min(parseInt(req.query.limit)||20, 100);

    // Aktuelle Decision (last) — wenn symbol angegeben, gefiltert
    const latestRow = symbol
      ? DB.db.prepare("SELECT * FROM aladdin_decisions WHERE symbol=? ORDER BY ts DESC LIMIT 1").get(symbol)
      : DB.db.prepare("SELECT * FROM aladdin_decisions ORDER BY ts DESC LIMIT 1").get();

    let families = null;
    let voters = null;
    if (latestRow && latestRow.families) {
      try { families = JSON.parse(latestRow.families); } catch(_) {}
    }
    if (families) {
      // Voter-Bars: pro Familie dir/score/conf
      voters = Object.entries(families).map(([name, fam]) => ({
        name,
        dir: fam.dir || 'NEUTRAL',
        score: Number(fam.score || 0),
        conf: Number(fam.conf || 0),
        active: fam.active || 0,
      }));
    }

    // Konsens-Counts aus voters
    let consensus = { buy: 0, sell: 0, neutral: 0, hold: 0 };
    if (voters) {
      voters.forEach(v => {
        const d = String(v.dir).toUpperCase();
        if (d === 'BUY') consensus.buy++;
        else if (d === 'SELL') consensus.sell++;
        else if (d === 'HOLD') consensus.hold++;
        else consensus.neutral++;
      });
    }

    // Decision-History (last N, optional gefiltert)
    const historyRows = symbol
      ? DB.db.prepare("SELECT ts, symbol, decision, confidence, unified_dir FROM aladdin_decisions WHERE symbol=? ORDER BY ts DESC LIMIT ?").all(symbol, historyLimit)
      : DB.db.prepare("SELECT ts, symbol, decision, confidence, unified_dir FROM aladdin_decisions ORDER BY ts DESC LIMIT ?").all(historyLimit);
    const history = historyRows.map(r => ({
      ts: r.ts, symbol: r.symbol, decision: r.decision,
      confidence: r.confidence, unifiedDir: r.unified_dir,
      agrees: r.unified_dir === r.decision,
    }));

    // Mode
    const mode = (CFG && CFG.BRAIN_MODE) || 'shadow';

    // Brain-Snapshot stats
    const snap = AladdinBrain.snapshot ? AladdinBrain.snapshot() : null;

    // Block S A6 [27.05.2026]: rawSignal vs finalDecision (router-overlay).
    let _router = null;
    if (latestRow && _FinalRouter) {
      try {
        const fr = _FinalRouter.finalize(
          { decision: latestRow.decision, confidence: latestRow.confidence },
          latestRow.symbol,
          { db: DB.db, selectedStrategy: 'TREND' }
        );
        _router = {
          rawSignal: fr.rawSignal,
          finalDecision: fr.finalDecision,
          selectedStrategy: fr.selectedStrategy,
          vetoReason: fr.vetoReason,
          symbolConfig: fr.symbolConfig,
          pairContext: fr.pairContext,
          tradeAllowed: fr.tradeAllowed,
          vetoTag: _FinalRouter.vetoTag(fr),
        };
      } catch(_) {}
    }

    res.json({
      ok: true,
      ts: Date.now(),
      symbol: latestRow ? latestRow.symbol : null,
      mode,
      regime: latestRow ? latestRow.regime : null,
      decision: latestRow ? {
        decision: latestRow.decision,
        confidence: latestRow.confidence,
        positionPct: latestRow.position_pct,
        unifiedDir: latestRow.unified_dir,
        unifiedConf: latestRow.unified_conf,
        agrees: latestRow.unified_dir === latestRow.decision,
        reason: latestRow.reason,
        regime: latestRow.regime,
        ts: latestRow.ts,
      } : null,
      router: _router,
      voters,
      consensus,
      familyWeights: (snap && snap.familyWeights) || null,
      history,
      stats: snap ? snap.stats : null,
    });
  } catch(e) {
    res.json({ ok: false, error: e.message });
  }
});

