// ── KILL SWITCH ──
// AUDFIX_E002 [18.05.2026]: Kill + Kill-Reset durch Token + Audit abgesichert.
// /api/kill — Manual-HARD-KILL (Bot stoppt Trading). Token-pflichtig, aber kein Confirm
//             (NOT-AUS-Knopf, soll schnell funktionieren — UI hat eigene confirm()).
// /api/kill/reset — KillSwitch-Reset: REENABLES TRADING + umgeht 12% DD-Schutz!
//                   → Token + Confirm-Phrase Pflicht.
app.post('/api/kill', requireDeployToken, (req,res) => {
  try {
    const ip = String(req.ip || req.connection?.remoteAddress || 'unknown');
    try {
      DB.insertLog.run(Date.now(), 'CRITICAL', 'kill_endpoint',
        `Manual HARD KILL requested`,
        JSON.stringify({ ip, oldMode: KillSwitch.mode }));
    } catch(_) { return res.status(500).json({ error: 'audit_failed' }); }
    KillSwitch._hardKill('MANUAL', { ip });
    res.json({ ok: true, mode: KillSwitch.mode });
  } catch(e) { return res.status(500).json({ error: 'internal' }); }
});
app.post('/api/kill/reset', requireDeployToken, (req,res) => {
  try {
    const confirm = String(req.body?.confirm || '');
    if (confirm !== 'I_UNDERSTAND_KILL_RESET_REENABLES_TRADING') {
      return res.status(400).json({ error: 'confirm_required' });
    }
    const ip = String(req.ip || req.connection?.remoteAddress || 'unknown');
    try {
      DB.insertLog.run(Date.now(), 'CRITICAL', 'kill_reset_endpoint',
        `KillSwitch RESET requested — Trading wird wieder erlaubt`,
        JSON.stringify({ ip, oldMode: KillSwitch.mode, triggers: KillSwitch.triggers.slice(-3) }));
    } catch(_) { return res.status(500).json({ error: 'audit_failed' }); }
    KillSwitch.reset();
    res.json({ ok: true, mode: KillSwitch.mode });
  } catch(e) { return res.status(500).json({ error: 'internal' }); }
});

