// AUDFIX_B001 [18.05.2026]: manuelle Approval bei HARD-DRIFT.
// Aktiviert HARD-fix nach manueller Christian-Bestätigung.
app.post('/api/recon/approve', requireDeployToken, (req,res) => {
  try {
    const confirm = String(req.body?.confirm || '');
    if (confirm !== 'I_APPROVE_RECON_HARD_FIX') {
      return res.status(400).json({ error: 'confirm_required' });
    }
    if (!DemoEngine || !DemoEngine.wallet) return res.status(500).json({ error: 'no_wallet' });
    const w = DemoEngine.wallet;
    const oldTotal = w.total;
    const newTotal = w.reserve + w.trading;
    const drift = Math.abs(oldTotal - newTotal);
    if (drift < 0.01) return res.json({ ok: true, msg: 'no_drift_to_fix', drift });
    try {
      DB.insertLog.run(Date.now(), 'CRITICAL', 'recon_correction',
        `HARD-DRIFT manuell approved drift=${drift.toFixed(4)}`,
        JSON.stringify({ drift, oldTotal, newTotal, reserve: w.reserve, trading: w.trading, action: 'MANUAL_APPROVED' }));
    } catch(_) { return res.status(500).json({ error: 'audit_failed' }); }
    w.total = newTotal;
    try { DemoEngine._persistWallet(); } catch(_){}
    try { DB.db.prepare("INSERT OR REPLACE INTO bot_settings (key, value, updated_at) VALUES ('autonomous_demo_trades_enabled', 'true', ?)").run(Date.now()); } catch(_){}
    return res.json({ ok: true, drift, oldTotal, newTotal, autonomous_resumed: true });
  } catch(e) { return res.status(500).json({ error: 'internal' }); }
});

