// ── MBT-UI D [16.05.2026]: Action-Endpoints für DCA Force/Pause/Resume ──
app.post('/api/dcambt/force_buy/:dca_id', requireDeployToken, (req,res) => {
  try {
    const d = DB.getDcaInstance.get(req.params.dca_id);
    if (!d) return res.status(404).json({ok:false,error:'NOT_FOUND'});
    if (d.status !== 'OPEN' && d.status !== 'DD_STOPPED') return res.status(400).json({ok:false,error:'DCA_NOT_OPEN'});
    const tk = Bitget.priceCache[d.symbol];
    if (!tk || !tk.last) return res.status(503).json({ok:false,error:'NO_PRICE_CACHE'});
    // Bypass-Block-Check vorenthalten — Force ist explizite User-Aktion in DEMO.
    // Aber: Universal Hard-Block (SHARPE_EXTREME etc.) BLEIBT respektiert.
    const block = MBTTicker._shouldBlockTick(d.symbol);
    if (block) return res.status(409).json({ok:false,error:'BLOCKED_BY_ALADDIN', reason: block.reason, value: block.value});
    const r = DCABotMBT.scheduledBuy(d.dca_id, +tk.last);
    if (r && r.ok) {
      try { DB.clearDcaBlock.run(d.dca_id); } catch(_){}
      try { Log.info('DCA', `Force-Buy ${d.symbol} ${d.dca_id} #${r.iteration} @ ${(+tk.last).toFixed(4)} (user-triggered)`); } catch(_){}
      return res.json({ok:true, ...r});
    }
    res.status(400).json({ok:false, error: r?.reason || 'BUY_FAILED', detail: r});
  } catch(e) { res.status(500).json({ok:false,error:e.message}); }
});
app.post('/api/dcambt/pause/:dca_id', requireDeployToken, (req,res) => {
  try {
    const d = DB.getDcaInstance.get(req.params.dca_id);
    if (!d) return res.status(404).json({ok:false,error:'NOT_FOUND'});
    DB.setDcaPaused.run(1, Date.now(), req.params.dca_id);
    try { DB.setDcaBlock.run('PAUSED_BY_USER', null, Date.now(), req.params.dca_id); } catch(_){}
    try { Log.info('DCA', `Paused ${d.symbol} ${d.dca_id} (user)`); } catch(_){}
    res.json({ok:true, dca_id:req.params.dca_id, paused:true});
  } catch(e) { res.status(500).json({ok:false,error:e.message}); }
});
app.post('/api/dcambt/resume/:dca_id', requireDeployToken, (req,res) => {
  try {
    const d = DB.getDcaInstance.get(req.params.dca_id);
    if (!d) return res.status(404).json({ok:false,error:'NOT_FOUND'});
    DB.setDcaPaused.run(0, Date.now(), req.params.dca_id);
    try { DB.clearDcaBlock.run(req.params.dca_id); } catch(_){}
    try { Log.info('DCA', `Resumed ${d.symbol} ${d.dca_id} (user)`); } catch(_){}
    res.json({ok:true, dca_id:req.params.dca_id, paused:false});
  } catch(e) { res.status(500).json({ok:false,error:e.message}); }
});

