// Phase 6 Teil 5 Erweiterung [15.05.2026]: PM2 sub-bot process lifecycle
// Erlaubte sub-bot IDs sind via ecosystem.config.js definiert (allowlist gegen injection).
const ALLOWED_SUB_BOTS = ['nexus_sub_1', 'nexus_sub_2'];
const { exec: _exec } = require('child_process');
function _pm2Action(action, name) {
  return new Promise((resolve) => {
    if (!ALLOWED_SUB_BOTS.includes(name)) {
      return resolve({ ok: false, error: 'NOT_ALLOWED', allowed: ALLOWED_SUB_BOTS });
    }
    const cmd = action === 'start'
      ? `pm2 start ecosystem.config.js --only ${name}`
      : action === 'stop'
        ? `pm2 stop ${name}`
        : action === 'delete'
          ? `pm2 delete ${name}`
          : null;
    if (!cmd) return resolve({ ok: false, error: 'BAD_ACTION' });
    _exec(cmd, { cwd: __dirname, timeout: 10000 }, (err, stdout, stderr) => {
      if (err) return resolve({ ok: false, error: err.message, stderr: stderr.slice(0, 500) });
      resolve({ ok: true, action, name, stdout: stdout.slice(-500) });
    });
  });
}
app.post('/api/farm/start/:botId', requireDeployToken, async (req,res) => res.json(await _pm2Action('start', req.params.botId)));
app.post('/api/farm/stop/:botId',  requireDeployToken, async (req,res) => res.json(await _pm2Action('stop',  req.params.botId)));
app.get('/api/farm/processes', (req,res) => {
  _exec('pm2 jlist', { timeout: 5000 }, (err, stdout) => {
    if (err) return res.status(500).json({ ok:false, error:err.message });
    try {
      const list = JSON.parse(stdout);
      const subs = list.filter(p => ALLOWED_SUB_BOTS.includes(p.name)).map(p => ({
        name: p.name, pid: p.pid, status: p.pm2_env && p.pm2_env.status,
        uptime: p.pm2_env && p.pm2_env.pm_uptime, restarts: p.pm2_env && p.pm2_env.restart_time,
        mem: p.monit && p.monit.memory, cpu: p.monit && p.monit.cpu,
      }));
      res.json({ ok:true, subs, allowed: ALLOWED_SUB_BOTS });
    } catch(e) { res.status(500).json({ ok:false, error:e.message }); }
  });
});
