// AUDFIX_E005 [18.05.2026]: scripts/execute mit Token + Confirm-Phrase abgesichert.
// CUSTOM_SCRIPT_AUDIT_PASSED=false → Sandbox-Escape-Risiko bis isolated-vm Audit komplett.
// UI ruft diesen Endpoint NICHT direkt auf — Schutz nur für direkte API-Zugriffe.
app.post('/api/scripts/execute', requireDeployToken, (req,res) => {
  try {
    const confirm = String(req.body?.confirm || '');
    if (confirm !== 'I_UNDERSTAND_EXECUTING_SCRIPT_CAN_BREAK_BOT') {
      return res.status(400).json({ error: 'confirm_required' });
    }
    const ip = String(req.ip || req.connection?.remoteAddress || 'unknown');
    const code = req.body && req.body.code;
    try {
      DB.insertLog.run(
        Date.now(), 'CRITICAL', 'scripts_execute_endpoint',
        `Custom-Script execute requested (len=${code ? code.length : 0})`,
        JSON.stringify({ ip, code_len: code ? code.length : 0, audit_passed: CFG.CUSTOM_SCRIPT_AUDIT_PASSED })
      );
    } catch(_) { return res.status(500).json({ error: 'audit_failed' }); }
    const r = CustomScripting.execute(code);
    res.status(r.ok ? 200 : (r.kind === 'DISABLED' || r.kind === 'LIB_MISSING' ? 503 : 400)).json(r);
  } catch(e) {
    try { Log.warn('SCRIPTS', 'internal error in /api/scripts/execute'); } catch(_) {}
    return res.status(500).json({ error: 'internal' });
  }
});
app.get('/api/scripts/list', (req,res) => res.json({ ok:true, scripts: CustomScripting.list() }));
