// PHASE 3 X3 — Portfolio Backtest
app.post('/api/backtest/portfolio', requireDeployToken, async (req,res) => {
  try {
    const symbols = (req.body?.symbols || ['BTCUSDT','ETHUSDT','SOLUSDT']);
    const granularity = req.body?.granularity || '1day';
    const candles = req.body?.candles || 30;
    const capitalPer = Number(req.body?.capitalPerSymbol) || 1000;
    const results = [];
    for (const sym of symbols) {
      try {
        const r = await TickBacktest.run(sym, granularity, candles, 'ema_cross', capitalPer, 0.1, 0.02, 0.04, 1, 0, false);
        results.push({ symbol: sym, profit_factor: r?.profit_factor || 0, win_rate: r?.win_rate || 0, pnl: r?.pnl || 0, trades: r?.trades_count || 0 });
      } catch(e) { results.push({ symbol: sym, error: e.message }); }
      await new Promise(r => setTimeout(r, 200));
    }
    const totalPnl = results.reduce((s, r) => s + (r.pnl || 0), 0);
    const totalTrades = results.reduce((s, r) => s + (r.trades || 0), 0);
    const avgPF = results.length ? results.reduce((s, r) => s + (r.profit_factor || 0), 0) / results.length : 0;
    res.json({ ok: true, symbols, granularity, results, summary: { totalPnl, totalTrades, avgProfitFactor: Number(avgPF.toFixed(3)) } });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// PHASE 3 X4 — Monte Carlo Simulation (Trade-History Bootstrap)
app.get('/api/montecarlo/run', (req,res) => {
  try {
    const N = Math.min(parseInt(req.query.n) || 1000, 10000);
    const horizonTrades = Math.min(parseInt(req.query.horizon) || 100, 500);
    // Daten: realisierte PnLs der letzten Trades
    const rows = DB.db.prepare(
      "SELECT realized_pnl FROM trades WHERE state IN ('CLOSED','POSITION_CLOSED') AND realized_pnl IS NOT NULL ORDER BY closed_at DESC LIMIT 200"
    ).all();
    const pnls = rows.map(r => r.realized_pnl);
    if (pnls.length < 5) return res.json({ ok: false, error: 'Need at least 5 closed trades for Monte Carlo', haveTrades: pnls.length });
    const startCapital = 1000;
    const finalEquities = [];
    const maxDDs = [];
    for (let sim = 0; sim < N; sim++) {
      let eq = startCapital;
      let runningPeak = startCapital;
      let maxDD = 0;
      for (let i = 0; i < horizonTrades; i++) {
        // Bootstrap: zufällig aus pnls ziehen
        eq += pnls[Math.floor(Math.random() * pnls.length)];
        if (eq > runningPeak) runningPeak = eq;
        const dd = runningPeak > 0 ? (runningPeak - eq) / runningPeak : 0;
        if (dd > maxDD) maxDD = dd;
      }
      finalEquities.push(eq);
      maxDDs.push(maxDD);
    }
    finalEquities.sort((a, b) => a - b);
    maxDDs.sort((a, b) => a - b);
    const p5  = finalEquities[Math.floor(N * 0.05)];
    const p50 = finalEquities[Math.floor(N * 0.50)];
    const p95 = finalEquities[Math.floor(N * 0.95)];
    const ruinProb = finalEquities.filter(e => e <= 0).length / N;
    const dd_p5  = maxDDs[Math.floor(N * 0.05)];
    const dd_p50 = maxDDs[Math.floor(N * 0.50)];
    const dd_p95 = maxDDs[Math.floor(N * 0.95)];
    res.json({
      ok: true, simulations: N, horizonTrades, startCapital, samplesFromTrades: pnls.length,
      equity: { p5: Number(p5.toFixed(2)), p50: Number(p50.toFixed(2)), p95: Number(p95.toFixed(2)) },
      maxDrawdownPct: {
        p5: Number((dd_p5 * 100).toFixed(2)),
        p50: Number((dd_p50 * 100).toFixed(2)),
        p95: Number((dd_p95 * 100).toFixed(2)),
      },
      ruinProbability: Number(ruinProb.toFixed(4)),
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

