// PHASE 5 Teil 1 — Visual Trade Debugger
app.get('/api/debug/trade/:id', (req,res) => {
  try {
    const tradeId = req.params.id;
    const trade = DB.db.prepare('SELECT * FROM trades WHERE id=?').get(tradeId);
    if (!trade) return res.status(404).json({ error: 'trade not found' });
    const tBefore = (trade.created_at || 0) - 30 * 60 * 1000; // 30min vor Entry
    const tAfter  = (trade.closed_at || Date.now()) + 30 * 60 * 1000;
    // Candle-Cache für Symbol
    const candles = DB.db.prepare(
      'SELECT ts, open, high, low, close, vol FROM candle_cache WHERE symbol=? AND granularity=? AND ts BETWEEN ? AND ? ORDER BY ts ASC'
    ).all(trade.symbol, '1h', tBefore, tAfter);
    // Decision-Context
    const decisions = DB.db.prepare(
      "SELECT ts, decision, confidence, regime, families, reason FROM aladdin_decisions WHERE symbol=? AND ts BETWEEN ? AND ? ORDER BY ts ASC"
    ).all(trade.symbol, tBefore, tAfter);
    res.json({
      ok: true, trade, candles, decisions,
      markers: {
        entry: { ts: trade.created_at, price: trade.entry_price, type: 'ENTRY' },
        exit: trade.closed_at ? { ts: trade.closed_at, price: trade.exit_price, type: 'EXIT', reason: trade.exit_reason } : null,
      },
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// PHASE 5 Teil 3 — Long-Horizon Walk-Forward (12+ Monate)
// WFFIX [15.05.2026]: Default-Defaults auf 4h granularity + größere Windows.
// Root-Cause: TickBacktest startet trading-loop bei i=50 (EMA-Burn-In);
//   alte Defaults (testCandles=30, granularity=1day) → 0 Iterationen, test_pf=0.
// Fix: 4h-Granularität (6× mehr Candles), train=240, test=90.
// Siehe docs/WF_DIAGNOSIS.md. Override via body bleibt möglich (legacy 1day).
app.post('/api/backtest/walkforward12m', requireDeployToken, async (req,res) => {
  try {
    const months = Math.min(parseInt(req.body?.months) || 12, 24);
    const symbol = req.body?.symbol || 'BTCUSDT';
    const granularity = req.body?.granularity || '4h';
    // Body-Override hat Vorrang; Defaults: 4h granularity, train=240 (40d), test=90 (15d)
    // Burn-In im TickBacktest ist i=50 → testCandles muss deutlich darüber liegen,
    // damit nach Burn-In genug Trading-Iterationen für Signal-Hits bleiben.
    const trainCandles = Math.max(60, parseInt(req.body?.trainCandles) || 480);  // 80d @ 4h
    const testCandles  = Math.max(60, parseInt(req.body?.testCandles)  || 240);  // 40d @ 4h (190 Iter nach Burn-In)
    const result = await TrainingBridge.runWalkForward({
      symbol, granularity, strategy: req.body?.strategy || 'ema_cross',
      trainCandles, testCandles,
    });
    res.json({ ok: true, period: `${months}M`, granularity, trainCandles, testCandles, ...result });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

