// P3 [15.05.2026]: Long/Short-Ratio-Tracker (Marathon-Effekt-Sichtbarkeit)
app.get('/api/marathon/long-short', (req,res) => {
  try {
    const MARATHON_TS = 1778812920000;  // 2026-05-15 08:42 UTC+2
    const hoursBack = Math.min(parseInt(req.query.hours) || 24, 168);
    const since = Date.now() - hoursBack * 3600 * 1000;
    const bucketMs = 15 * 60 * 1000;

    const rows = DB.db.prepare(
      'SELECT created_at AS ts, side FROM trades WHERE created_at > ? ORDER BY created_at ASC'
    ).all(since);

    const buckets = {};
    for (const r of rows) {
      const b = Math.floor(r.ts / bucketMs) * bucketMs;
      if (!buckets[b]) buckets[b] = { ts: b, buy: 0, sell: 0, total: 0 };
      if (r.side === 'buy') buckets[b].buy++;
      else if (r.side === 'sell') buckets[b].sell++;
      buckets[b].total++;
    }
    const series = Object.values(buckets).sort((a, b) => a.ts - b.ts);

    // Aggregate vor/nach Marathon
    const preRows = rows.filter(r => r.ts < MARATHON_TS);
    const postRows = rows.filter(r => r.ts >= MARATHON_TS);
    const pre = {
      buy: preRows.filter(r => r.side === 'buy').length,
      sell: preRows.filter(r => r.side === 'sell').length,
      total: preRows.length,
    };
    const post = {
      buy: postRows.filter(r => r.side === 'buy').length,
      sell: postRows.filter(r => r.side === 'sell').length,
      total: postRows.length,
    };
    pre.buyRatio = pre.total > 0 ? pre.buy / pre.total : 0;
    pre.sellRatio = pre.total > 0 ? pre.sell / pre.total : 0;
    post.buyRatio = post.total > 0 ? post.buy / post.total : 0;
    post.sellRatio = post.total > 0 ? post.sell / post.total : 0;

    res.json({
      ok: true,
      marathonDeploy: MARATHON_TS,
      hoursBack,
      bucketMinutes: 15,
      series,
      pre,
      post,
      shift: {
        buyDelta: post.buyRatio - pre.buyRatio,
        sellDelta: post.sellRatio - pre.sellRatio,
        interpretation: post.sellRatio > pre.sellRatio + 0.2
          ? 'SELL-Bias gestiegen (T3-Symmetrie-Effekt)'
          : post.sellRatio < pre.sellRatio - 0.2
          ? 'BUY-Bias gestiegen'
          : 'Ratio stabil',
      },
    });
  } catch (e) {
    res.json({ ok: false, error: e.message });
  }
});
