// C.3 [14.05]: Health-Endpoint fuer externen Cron-Watchdog (C.2).
// KEIN DB-Touch, KEIN Modul-State-Touch — antwortet nur wenn Event-Loop responsiv.
// Bei CPU-Block oder Hang wuerde HTTP timeout — genau das was Cron-Watchdog erkennt.
app.get('/api/health', (req, res) => {
  res.set('Cache-Control', 'no-store');
  try {
    const wsReady = (typeof Bitget !== 'undefined' && Bitget.wsReady === true);
    const mem = process.memoryUsage();
    const uptimeS = Math.floor(process.uptime());
    // FIX 8 [26.05.2026]: echter Brain-Heartbeat (_lastDecideTs-basiert) statt ws_ready-Mirror.
    // Threshold 30s = ~35 decide-Cycles bei ~1.16 decides/sec. ws_ready bleibt orthogonal verfügbar.
    const lastDecideTs = (typeof AladdinBrain !== 'undefined' && AladdinBrain._lastDecideTs) || 0;
    const brainAgeMs   = lastDecideTs > 0 ? (Date.now() - lastDecideTs) : Infinity;
    const brainAlive   = brainAgeMs < 30000;
    res.json({
      ok: true,
      uptime_s: uptimeS,
      ws_ready: wsReady,
      pid: process.pid,
      mem_heap_mb: Math.round(mem.heapUsed / 1024 / 1024),
      mem_rss_mb: Math.round(mem.rss / 1024 / 1024),
      ts: Date.now(),
      brain_alive: brainAlive,
      brain_last_decide_ms_ago: brainAgeMs === Infinity ? null : brainAgeMs,
    });
  } catch(e) {
    // Bewusst KEIN 500 — Cron-Watchdog soll bei jedem non-200 escalieren
    res.json({ ok: false, error: e.message });
  }
});
