// F14 [15.05.2026] REGIME-TIMELINE — Strategy-Switch-Visualizer
// // DEMO=LIVE: identisch in beiden Modi (read-only Regime-Historie)
// Endpoint-Name: '/api/regime-timeline' (vermeidet Konflikt mit /api/regime/:symbol)
app.get('/api/regime-timeline', (req, res) => {
  try {
    const hours = Math.min(parseInt(req.query.hours) || 24, 168);
    const since = Date.now() - hours * 3600 * 1000;
    const bucketMs = Math.max(60000, Math.floor((hours * 3600 * 1000) / 200));  // ~200 buckets
    const rows = DB.db.prepare(
      'SELECT ts, regime FROM consensus_decisions WHERE ts > ? AND regime IS NOT NULL ORDER BY ts ASC'
    ).all(since);
    if (!rows.length) return res.json({ ok: true, hours, buckets: [], summary: {} });
    // Bucket per dominant regime
    const buckets = {};
    for (const r of rows) {
      const b = Math.floor(r.ts / bucketMs) * bucketMs;
      if (!buckets[b]) buckets[b] = {};
      buckets[b][r.regime] = (buckets[b][r.regime] || 0) + 1;
    }
    const series = Object.keys(buckets).sort().map(b => {
      const reg = buckets[b];
      // Dominant regime in bucket
      let dominant = null, max = 0;
      for (const [k, v] of Object.entries(reg)) {
        if (v > max) { max = v; dominant = k; }
      }
      return { ts: Number(b), regime: dominant, count: max, all: reg };
    });
    // Switches zählen (consecutive different regime)
    let switches = 0;
    for (let i = 1; i < series.length; i++) {
      if (series[i].regime !== series[i - 1].regime) switches++;
    }
    // Regime-Distribution gesamt
    const dist = {};
    for (const r of rows) dist[r.regime] = (dist[r.regime] || 0) + 1;
    res.json({
      ok: true, hours, totalDecisions: rows.length,
      buckets: series, switches,
      distribution: dist,
      summary: { dominantRegime: Object.entries(dist).sort((a,b)=>b[1]-a[1])[0]?.[0] || null },
    });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// F18 [15.05.2026] EQUITY-HISTORY (aus wallet_ledger Demo-Wallet rekonstruiert)
// // DEMO=LIVE: read-only, kein deploy_mode-Filter (aktuell Demo + zukünftig LIVE)
app.get('/api/equity/history', (req,res) => {
  try {
    const period = String(req.query.period || '24h').toLowerCase();
    const periodMap = { '1h': 3600000, '24h': 86400000, '7d': 604800000, '30d': 2592000000, 'all': 0 };
    const sinceMs = periodMap[period] !== undefined ? periodMap[period] : 86400000;
    const cutoff = sinceMs > 0 ? Date.now() - sinceMs : 0;
    const rows = DB.db.prepare(
      'SELECT ts, op, after_total, after_trading FROM wallet_ledger WHERE ts > ? ORDER BY ts ASC'
    ).all(cutoff);
    // Equity = after_total pro Zeitpunkt
    const series = rows.map(r => ({ ts: r.ts, equity: r.after_total, trading: r.after_trading, op: r.op }));
    // Aggregat
    const eqs = series.map(s => s.equity).filter(v => Number.isFinite(v));
    const min = eqs.length ? Math.min(...eqs) : 0;
    const max = eqs.length ? Math.max(...eqs) : 0;
    const first = eqs[0] || 0;
    const last = eqs[eqs.length - 1] || 0;
    const ddPct = max > 0 ? ((max - min) / max) * 100 : 0;
    res.json({
      ok: true, period, sincePoints: series.length, cutoff,
      series, summary: {
        firstEquity: Number(first.toFixed(2)),
        lastEquity:  Number(last.toFixed(2)),
        minEquity:   Number(min.toFixed(2)),
        maxEquity:   Number(max.toFixed(2)),
        changeUSDT:  Number((last - first).toFixed(2)),
        changePct:   first > 0 ? Number((((last - first) / first) * 100).toFixed(2)) : 0,
        maxDrawdownPct: Number(ddPct.toFixed(2)),
      },
    });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── DEPLOY MODE — AUDFIX_044 + AUDFIX_073 [18.05.2026] ──
// Auth-Middleware (DRY): requireDeployToken
//   - Token-Check via X-Deploy-Token vs process.env.DEPLOY_TOKEN (constant-time)
//   - Confirm-Phrase wenn req.body.requiresConfirm true ODER pfad-spezifisch (in route geprüft)
//   - Audit-Eintrag in system_log
//   - Fail-secure: 4xx/5xx ohne Detail-Leak
//   - Token NIE in Logs / Response
const DEPLOY_CONFIRM_PHRASE = 'I_UNDERSTAND_LIVE_MEANS_REAL_MONEY';
function requireDeployToken(req, res, next) {
  try {
    // T0.6 [24.05.2026] User-Toggle aus bot_settings (Default AUS = bypass)
    // Anti-Brick: KillSwitch/NotBremse/FLOOR laufen unabhängig (siehe T0.6.3)
    try {
      const row = DB.db.prepare("SELECT value FROM bot_settings WHERE key='deploy_token_required'").get();
      const required = row ? (row.value === 'true') : false;  // Default AUS
      if (!required) return next();  // Bypass wenn user-toggle OFF
    } catch(_) { /* fallback to legacy strict check */ }
    const expected = process.env.DEPLOY_TOKEN || '';
    const provided = String(req.headers['x-deploy-token'] || '');
    if (!expected || expected.length < 16) {
      return res.status(403).json({ error: 'forbidden' });
    }
    try {
      const a = Buffer.from(expected);
      const b = Buffer.from(provided);
      if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
        return res.status(403).json({ error: 'forbidden' });
      }
    } catch(_) {
      return res.status(403).json({ error: 'forbidden' });
    }
    return next();
  } catch(_) {
    return res.status(500).json({ error: 'internal' });
  }
}
// Audit-Helper — schreibt VOR State-Switch. Bei Fehler → caller MUSS abbrechen.
function auditModeChange(module, oldMode, newMode, req, extra) {
  const ip = String(req.ip || req.connection?.remoteAddress || 'unknown');
  const ua = String(req.headers['user-agent'] || 'unknown').slice(0, 200);
  const data = { old_mode: oldMode, new_mode: newMode, ip, user_agent: ua };
  if (extra && typeof extra === 'object') Object.assign(data, extra);
  DB.insertLog.run(
    Date.now(), 'CRITICAL', module,
    `mode_change ${oldMode} -> ${newMode}`,
    JSON.stringify(data)
  );
}

app.post('/api/deploy', requireDeployToken, (req,res) => {
  const VALID_MODES = ['PAPER','DRY_LIVE','LIVE_RESTRICTED','LIVE_FULL'];
  const REQUIRES_CONFIRM = ['DRY_LIVE','LIVE_RESTRICTED','LIVE_FULL'];
  try {
    const newMode = String(req.body?.mode || '');
    if (!VALID_MODES.includes(newMode)) {
      return res.status(400).json({ error: 'invalid_mode' });
    }
    // Block T+ Mini [27.05.2026]: HARD TEST-ONLY-GUARD — /api/deploy LIVE targets blocked
    if (_TestOnlyGuard) {
      const _mv = _TestOnlyGuard.validateModeSwitch(CFG, (DB&&DB.db)?DB.db:null, newMode);
      if (!_mv.ok) {
        try { Log.warn('TEST_ONLY', _TestOnlyGuard.LOG_TAG + ' /api/deploy target=' + newMode + ' blocked'); } catch(_){}
        return res.status(423).json({ error:'TEST_ONLY_MODE_ACTIVE', reason:_mv.reason, target:newMode, blocked:true });
      }
    }
    if (REQUIRES_CONFIRM.includes(newMode)) {
      const confirm = String(req.body?.confirm || '');
      if (confirm !== DEPLOY_CONFIRM_PHRASE) {
        return res.status(400).json({ error: 'confirm_required' });
      }
    }
    const oldMode = CFG.DEPLOY_MODE;
    try { auditModeChange('deploy_endpoint', oldMode, newMode, req); }
    catch(_) { return res.status(500).json({ error: 'audit_failed' }); }
    process.env.DEPLOY_MODE = newMode;
    CFG.DEPLOY_MODE = newMode;
    try { NoTrade.gates.deployModeAllows = REQUIRES_CONFIRM.includes(newMode); } catch(_) {}
    try { Log.warn('DEPLOY', `Mode-change ${oldMode} -> ${newMode}`); } catch(_) {}
    return res.json({ ok: true, mode: newMode, from: oldMode });
  } catch(e) {
    try { Log.warn('DEPLOY', 'internal error in /api/deploy handler'); } catch(_) {}
    return res.status(500).json({ error: 'internal' });
  }
});

