app.post('/api/backtest/tick', requireDeployToken, async (req,res) => {
  const { symbol='BTCUSDT', granularity='5m', limit=500, strategy='full',
          capital=1000, posSize=0.1, slPct=0.02, tpPct=0.04, leverage=1 } = req.body;
  const result = await TickBacktest.run(symbol, granularity, limit, strategy, capital, posSize, slPct, tpPct, leverage);
  // Interne Felder strippen (zu groß fuer JSON-Antwort)
  if (result && !result.error) {
    delete result._candles_for_training;
    if (result.trades_list && result.trades_list.length > 100) {
      result.trades_list = result.trades_list.slice(-100); // nur letzte 100
    }
  }
  res.json(result);
});


