// ── PAPER TRACKER API ───────────────────────────────────────────────────────
// X5 (Phase 2) [15.05.2026] Paper-Performance konsolidiert
// // DEMO-ONLY: PaperTracker arbeitet auf Demo-Trade-Daten
app.get('/api/paper/performance', (req,res) => {
  try {
    const period = String(req.query.period || '24h');
    const periodMap = { '1h': 3600000, '24h': 86400000, '7d': 604800000, '30d': 2592000000, 'all': 0 };
    const sinceMs = periodMap[period] !== undefined ? periodMap[period] : 86400000;
    const cutoff = sinceMs > 0 ? Date.now() - sinceMs : 0;

    // Datenquelle: aladdin_perf + trades (CLOSED). Demo-trades dominieren.
    const trades = DB.db.prepare(
      "SELECT realized_pnl, created_at, closed_at FROM trades WHERE state IN ('CLOSED','POSITION_CLOSED') AND closed_at > ? AND closed_at IS NOT NULL ORDER BY closed_at ASC"
    ).all(cutoff);
    const n = trades.length;
    if (n === 0) return res.json({ ok:true, period, trades_count:0, note: 'Keine geschlossenen Trades im Zeitraum' });

    const wins = trades.filter(t => t.realized_pnl > 0).length;
    const losses = trades.filter(t => t.realized_pnl < 0).length;
    const wr = wins / n;
    const total_pnl = trades.reduce((s,t) => s + (t.realized_pnl||0), 0);
    const avg_pnl = total_pnl / n;
    const avg_hold_min = trades.reduce((s,t) => s + ((t.closed_at||0)-(t.created_at||0)), 0) / n / 60000;
    // Max-DD aus equity-curve
    let runningPeak = 0, maxDD = 0, eq = 0;
    for (const t of trades) {
      eq += (t.realized_pnl||0);
      if (eq > runningPeak) runningPeak = eq;
      const dd = runningPeak - eq;
      if (dd > maxDD) maxDD = dd;
    }
    const maxDDPct = Math.abs(total_pnl) > 0 ? (maxDD / Math.max(Math.abs(runningPeak), Math.abs(total_pnl))) * 100 : 0;
    // Sharpe approx (per-trade): avg_pnl / stddev_pnl (annualisiert nicht trivial bei sporadischen Trades)
    const meanPnl = avg_pnl;
    const variance = trades.reduce((s,t) => s + Math.pow((t.realized_pnl||0)-meanPnl, 2), 0) / n;
    const stdDev = Math.sqrt(variance);
    const sharpe = stdDev > 0 ? meanPnl / stdDev : 0;
    // Profit-Factor: sum_wins / abs(sum_losses)
    const sumWins = trades.filter(t => t.realized_pnl > 0).reduce((s,t) => s + t.realized_pnl, 0);
    const sumLosses = Math.abs(trades.filter(t => t.realized_pnl < 0).reduce((s,t) => s + t.realized_pnl, 0));
    const profit_factor = sumLosses > 0 ? sumWins / sumLosses : (sumWins > 0 ? Infinity : 0);

    res.json({
      ok: true, period, trades_count: n, wins, losses,
      win_rate: Number(wr.toFixed(4)),
      total_pnl: Number(total_pnl.toFixed(3)),
      avg_pnl: Number(avg_pnl.toFixed(4)),
      avg_hold_min: Number(avg_hold_min.toFixed(1)),
      max_dd_pct: Number(maxDDPct.toFixed(2)),
      sharpe: Number(sharpe.toFixed(3)),
      profit_factor: Number(profit_factor.toFixed(3)),
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});
