// VISION Verschaltung [16.05.2026]: Strategy-Performance aggregate (per strategy, per regime, per symbol)
app.get('/api/strategies5/performance', (req,res) => {
  try {
    const days = Math.max(1, Math.min(90, parseInt(req.query.days) || 30));
    const rows = DB.db.prepare(`
      SELECT
        strategy,
        regime,
        symbol,
        COUNT(*) as trades,
        SUM(CASE WHEN pnl>0 THEN 1 ELSE 0 END) as wins,
        ROUND(AVG(CASE WHEN pnl>0 THEN 1.0 ELSE 0.0 END), 4) as win_rate,
        ROUND(SUM(pnl), 4) as total_pnl,
        ROUND(AVG(pnl), 4) as avg_pnl,
        ROUND(MIN(pnl), 4) as worst_pnl,
        datetime(MAX(ts)/1000,'unixepoch') as last_trade
      FROM strategy_performance
      WHERE is_backtest=0 AND ts > (strftime('%s','now') - ?) * 1000
      GROUP BY strategy, regime, symbol
      ORDER BY total_pnl DESC
    `).all(days * 86400);
    // Auto-Disable-Logic: pro (strategy, regime) → wenn ≥20 Trades + WR<40% → flag
    const autoDisable = rows
      .filter(r => r.trades >= 20 && r.win_rate < 0.40)
      .map(r => ({ strategy: r.strategy, regime: r.regime, symbol: r.symbol, win_rate: r.win_rate, trades: r.trades }));
    res.json({ ok:true, days, rows, auto_disable_candidates: autoDisable });
  } catch(e) { res.status(500).json({ ok:false, error:e.message }); }
});
