// ── UI Pipeline A [16.05.2026]: /api/positions/active mit bot_type + strategy_name + bot_details ──
// Quellen: DemoEngine.positions (in-memory) + trades.bot_type / trades.strategy (DB)
//          + grid_instances / dca_instances für Live-Details
// Fallback: bot_type === 'SINGLE' wenn NULL (Rückwärtskompatibilität).
app.get('/api/positions/active', (req,res) => {
  try {
    const items = [];
    // 1. SINGLE-Trades: DemoEngine.positions enriched
    for (const [id, pos] of Object.entries(DemoEngine.positions)) {
      const livePrice = Bitget.priceCache[pos.symbol]?.last || pos.fillPrice;
      const dir = pos.direction === 'BUY' ? 1 : -1;
      const coinQty = pos.size / pos.fillPrice;
      const unrealizedPnl = dir * (livePrice - pos.fillPrice) * coinQty;
      const pnlPct = pos.fillPrice > 0 ? dir * (livePrice - pos.fillPrice) / pos.fillPrice * 100 : 0;

      // bot_type + strategy aus DB lookup (über trades.id wenn pos.dbTradeId existiert)
      let botType = 'SINGLE', strategyName = 'UNIFIED';
      if (pos.dbTradeId) {
        try {
          const row = DB.db.prepare('SELECT bot_type, strategy FROM trades WHERE id=?').get(pos.dbTradeId);
          if (row) {
            botType = row.bot_type || 'SINGLE';
            // strategy format: DEMO_<BOTTYPE>_<STRAT> oder DEMO_<STRAT> (legacy)
            if (row.strategy) {
              const parts = row.strategy.replace(/^DEMO_/, '').split('_');
              if (parts.length >= 2 && ['SINGLE','GRID','DCA','INFGRID','CONSERVATIVE'].includes(parts[0])) {
                botType = botType || parts[0];
                strategyName = parts.slice(1).join('_');
              } else {
                strategyName = row.strategy.replace(/^DEMO_/, '');
              }
            }
          }
        } catch(_) {}
      }

      items.push({
        id, symbol: pos.symbol, side: pos.direction, size: pos.size,
        entry_price: pos.fillPrice, live_price: livePrice,
        unrealizedPnl: +unrealizedPnl.toFixed(4), pnlPct: +pnlPct.toFixed(2),
        age_min: Math.round((Date.now() - pos.openedAt) / 60000),
        opened_at: pos.openedAt,
        bot_type: botType,
        strategy_name: strategyName,
        bot_details: {},
        meta_regime: pos.meta_regime || null,
        type_kind: 'TRADE',
      });
    }
    // 2. GRID/INFGRID-Instanzen
    try {
      const grids = DB.listGridsOpen.all(50);
      for (const g of grids) {
        const orders = DB.listGridOrders.all(g.grid_id);
        const filled = orders.filter(o => o.filled).length;
        const meta = g.meta ? (() => { try { return JSON.parse(g.meta); } catch(_) { return {}; } })() : {};
        items.push({
          id: g.grid_id, symbol: g.symbol, side: 'GRID',
          size: g.capital_pool, entry_price: meta.mid_at_create || null,
          live_price: Bitget.priceCache[g.symbol]?.last || null,
          unrealizedPnl: g.profit_acc || 0, pnlPct: 0,
          age_min: Math.round((Date.now() - g.created_at) / 60000),
          opened_at: g.created_at,
          bot_type: g.bot_type,           // 'GRID' oder 'INFGRID'
          strategy_name: 'GRID_TRADE',
          bot_details: {
            grid_id: g.grid_id,
            range_low: g.range_low, range_high: g.range_high,
            levels_total: g.num_levels, levels_filled: filled,
            fills_acc: g.fills_acc, range_breaks: g.range_breaks,
            per_level: g.per_level,
            extensions: meta.extensions || 0,
            paused: (g.paused | 0) === 1,
          },
          meta_regime: null,
          type_kind: g.bot_type,
        });
      }
    } catch(e) { /* table missing → skip */ }
    // 3. DCA-Instanzen
    try {
      const dcas = DB.listDcaOpen.all(50);
      for (const d of dcas) {
        items.push({
          id: d.dca_id, symbol: d.symbol, side: 'DCA',
          size: d.total_spent, entry_price: d.avg_buy_price,
          live_price: Bitget.priceCache[d.symbol]?.last || null,
          unrealizedPnl: 0, pnlPct: 0,
          age_min: Math.round((Date.now() - d.created_at) / 60000),
          opened_at: d.created_at,
          bot_type: 'DCA',
          strategy_name: 'DCA_ACCUMULATE',
          bot_details: {
            dca_id: d.dca_id,
            iteration: d.iteration, max_iterations: d.max_iterations,
            avg_buy_price: d.avg_buy_price, total_size: d.total_size,
            total_spent: d.total_spent,
            target_profit_pct: d.target_profit_pct, max_dd_pct: d.max_dd_pct,
            interval_hours: d.interval_hours, last_dd_pct: d.last_dd_pct,
            status: d.status,
          },
          meta_regime: null,
          type_kind: 'DCA',
        });
      }
    } catch(e) { /* table missing → skip */ }

    res.json({
      ts: Date.now(),
      total: items.length,
      by_type: items.reduce((acc, it) => { acc[it.bot_type] = (acc[it.bot_type] || 0) + 1; return acc; }, {}),
      total_unrealized_pnl: +items.reduce((s, it) => s + (it.unrealizedPnl || 0), 0).toFixed(4),
      positions: items,
    });
  } catch(e) {
    res.status(500).json({ ok:false, error: e.message });
  }
});

