// Atomic switch with deploy mode update
app.post('/api/mode/switch', requireDeployToken, (req,res) => {
  try {
    const { target, force } = req.body || {};
    if (!['DEMO','LIVE'].includes(target)) {
      return res.status(400).json({ error: 'invalid_target' });
    }
    if (target === 'LIVE') {
      // Block T+ [27.05.2026]: HARD TEST-ONLY-GUARD
      if (_TestOnlyGuard) {
        const _mv = _TestOnlyGuard.validateModeSwitch(CFG, (DB&&DB.db)?DB.db:null, 'LIVE_FULL');
        if (!_mv.ok) {
          try { Log.warn('TEST_ONLY', _TestOnlyGuard.LOG_TAG + ' mode switch to LIVE_FULL blocked'); } catch(_){}
          return res.status(423).json({ error:'TEST_ONLY_MODE_ACTIVE', reason:_mv.reason, blocked:true });
        }
      }
      const confirm = String(req.body?.confirm || '');
      if (confirm !== DEPLOY_CONFIRM_PHRASE) {
        return res.status(400).json({ error: 'confirm_required' });
      }
    }
    const oldMode = CFG.DEPLOY_MODE;
    const newTargetMode = (target === 'LIVE') ? 'LIVE_FULL' : 'PAPER';
    try { auditModeChange('mode_switch_endpoint', oldMode, newTargetMode, req, { target, force: !!force }); }
    catch(_) { return res.status(500).json({ error: 'audit_failed' }); }
    let result;
    if (target === 'LIVE') {
      result = DemoEngine.switchToLive({ force: !!force });
      if (result.ok) CFG.DEPLOY_MODE = 'LIVE_FULL';
    } else {
      result = DemoEngine.switchToDemo();
      if (result.ok) CFG.DEPLOY_MODE = 'PAPER';
    }
    return res.json(result);
  } catch(e) {
    try { Log.warn('DEPLOY', 'internal error in /api/mode/switch'); } catch(_) {}
    return res.status(500).json({ error: 'internal' });
  }
});

