// ═══════════════════════════════════════════════════════════════════
// PIONEX-UI BACKEND [2026-05-08]: Hauptkachel + Trade-Karten Daten
// ═══════════════════════════════════════════════════════════════════

// /api/bots/dashboard - Daten fuer Hauptkachel V4
app.get('/api/bots/dashboard', (req, res) => {
  try {
    const wallet = DemoEngine.wallet || {};
    const positions = Object.values(DemoEngine.positions || {});
    const tickerCache = Bitget.priceCache || {};
    
    // Investment Total = Summe aller offenen Positions
    let investmentTotal = 0;
    let unrealizedPnl = 0;
    
    positions.forEach(pos => {
      const size = Number(pos.size || 0);
      const entry = Number(pos.fillPrice || pos.entry_price || 0);
      const sideLC = String(pos.direction || pos.side || 'buy').toLowerCase();
      
      investmentTotal += size;
      
      const ticker = tickerCache[pos.symbol];
      if (ticker && entry > 0) {
        const last = Number(ticker.last || ticker.price || entry);
        const dir = sideLC === 'sell' ? -1 : 1;
        const pnlPct = dir * (last - entry) / entry;
        unrealizedPnl += pnlPct * size;
      }
    });
    
    // Realized PnL aus Trades-DB (nur echte Trade-Reasons, keine Wallet-Resets/Cleanups)
    let realizedPnl = 0;
    let realizedToday = 0;
    let tradesTotal = 0;
    let wins = 0;
    let losses = 0;
    
    // Phase-2 [2026-05-11]: zentrale StatsCore statt eigener SQL-Query (Konsistenz mit Telegram/LIVE-Gate)
    try {
      const sc = StatsCore.getStats();
      realizedPnl   = sc.totalPnl;
      tradesTotal   = sc.total;
      wins          = sc.wins;
      losses        = sc.losses;
      realizedToday = sc.today.pnl;
    } catch(_) {}

    // AUTONOM-AUDIT-FIX C [17.05.2026]: realizedToday MBT-aware (Grid+DCA dazu)
    try {
      if (typeof computeDailyPnLMBT === 'function') {
        const dp = computeDailyPnLMBT();
        // realizedToday wird aus SC.today.pnl (SINGLE) plus DCA+Grid ergänzt
        realizedToday = dp.realized.total;
      }
    } catch(_) {}

    const winRate = tradesTotal > 0 ? (wins / tradesTotal) : 0;
    const totalPnl = realizedPnl + unrealizedPnl;
    
    // 24h Activity (Trades + DCA-Iter + Grid-Fills pro Stunde)
    // AUTONOM-AUDIT-FIX C [17.05.2026]: MBT-aware (vorher nur SINGLE-Trades → 0 wenn keine SINGLE)
    const activity24h = new Array(24).fill(0);
    const activity24hBreakdown = { single: 0, dca: 0, grid: 0 };
    try {
      const now = Date.now();
      const dayAgo = now - 86400000;
      // SINGLE: trades.created_at
      const recentSingle = DB.db.prepare(
        "SELECT created_at FROM trades WHERE created_at > ?"
      ).all(dayAgo);
      recentSingle.forEach(t => {
        const hoursAgo = Math.floor((now - t.created_at) / 3600000);
        if (hoursAgo >= 0 && hoursAgo < 24) activity24h[23 - hoursAgo]++;
      });
      activity24hBreakdown.single = recentSingle.length;
      // DCA: dca_iterations.buy_ts
      const recentDCA = DB.db.prepare(
        "SELECT buy_ts FROM dca_iterations WHERE buy_ts > ?"
      ).all(dayAgo);
      recentDCA.forEach(t => {
        const hoursAgo = Math.floor((now - t.buy_ts) / 3600000);
        if (hoursAgo >= 0 && hoursAgo < 24) activity24h[23 - hoursAgo]++;
      });
      activity24hBreakdown.dca = recentDCA.length;
      // GRID: grid_orders.fill_ts (BUY+SELL fills)
      const recentGrid = DB.db.prepare(
        "SELECT fill_ts FROM grid_orders WHERE fill_ts > ?"
      ).all(dayAgo);
      recentGrid.forEach(t => {
        const hoursAgo = Math.floor((now - t.fill_ts) / 3600000);
        if (hoursAgo >= 0 && hoursAgo < 24) activity24h[23 - hoursAgo]++;
      });
      activity24hBreakdown.grid = recentGrid.length;
    } catch(_) {}
    
    // System-Status
    const wsStatus = (Bitget.wsReady === true) ? 'connected' : 'disconnected';
    let watchdogStatus = null; try { if (WSWatchdog && WSWatchdog.snapshot) watchdogStatus = WSWatchdog.snapshot(); } catch(_) {}
    const brainStats = (typeof AladdinBrain !== 'undefined' && AladdinBrain.snapshot) 
      ? AladdinBrain.snapshot().stats 
      : null;
    const guardianStats = (typeof PositionGuardian !== 'undefined' && PositionGuardian.snapshot)
      ? PositionGuardian.snapshot()
      : null;
    
    // Regime
    const regime = (typeof Regime !== 'undefined' && Regime.regime) ? Regime.regime : 'UNKNOWN';
    const regimeConf = (typeof Regime !== 'undefined' && Regime.confidence) ? Regime.confidence : 0;
    
    // Wallet-Flow
    // FIX-WALLET D [17.05.2026]: MBT-Commitment + MBT-Counts
    let mbtCommitted = 0;
    let mbtDcaCount = 0, mbtGridCount = 0, mbtInfgridCount = 0;
    try {
      const dcaSum = DB.db.prepare("SELECT COALESCE(SUM(total_spent),0) AS s, COUNT(*) AS c FROM dca_instances WHERE status IN ('OPEN','DD_STOPPED')").get();
      mbtCommitted += dcaSum.s || 0;
      mbtDcaCount = dcaSum.c || 0;
    } catch(_){}
    try {
      // PRIO5_FIX #3 [23.05.2026]: GRID-Committed via capital_pool statt order-net.
      // Vorher: SUM(buy.fill_price) - SUM(sell.fill_price) = 0 bei balanced grid (alle buys mit sells gematched).
      // Echte committed capital = capital_pool jeder OPEN-grid (Pre-allocated Kapital im Grid).
      const gridSum = DB.db.prepare(`
        SELECT COALESCE(SUM(capital_pool), 0) AS pool, bot_type, COUNT(*) as c
        FROM grid_instances WHERE status='OPEN' GROUP BY bot_type
      `).all();
      let totalGridCapital = 0;
      gridSum.forEach(r => {
        totalGridCapital += r.pool || 0;
        if (r.bot_type === 'GRID') mbtGridCount = r.c;
        else if (r.bot_type === 'INFGRID') mbtInfgridCount = r.c;
      });
      mbtCommitted += totalGridCapital;
    } catch(_){}
    const mbtActiveTotal = mbtDcaCount + mbtGridCount + mbtInfgridCount;
    const imMarktCombined = investmentTotal + mbtCommitted;

    const walletFlow = {
      bitgetAvailable: (Balance && Balance.usable) ? Balance.usable : 0, // Live-Balance
      tradingTopf:     wallet.trading || wallet.total || 0,
      reserveSafe:     wallet.reserve || 0,
      imMarkt:         imMarktCombined,                                          // FIX D: SINGLE + MBT
      imMarktSingle:   Number(investmentTotal.toFixed(2)),                       // FIX D: nur SINGLE
      imMarktMBT:      Number(mbtCommitted.toFixed(2)),                          // FIX D: nur MBT
      imMarktPct:      (wallet.total > 0) ? (imMarktCombined / wallet.total) : 0,
    };

    res.json({
      ok: true,
      ts: Date.now(),
      mode: DemoEngine.mode || 'PAPER',
      // FIX 28 [26.05.2026 / Bug C1+C2+C3]: ENGINE-Wahrheit als Top-Level-Felder.
      // Vorher: portfolio.displayReserve (virtuell, inkl pending realized profit) widersprach wallet.reserve
      // (engine-Wahrheit, nur reale split). UI nutzte mal A, mal B → Widersprüche.
      // Jetzt: KLAR getrennt — engine.* = was Bot wirklich nutzt, portfolio.display* = UI-virtuell.
      engine: {
        reserve: Number((wallet.reserve || 0).toFixed(4)),     // ENGINE-Wahrheit (was Bot nutzt)
        trading: Number((wallet.trading || 0).toFixed(4)),
        total:   Number((wallet.total   || 0).toFixed(4)),
        peakTotal: Number((wallet.peakTotal || 0).toFixed(4)),
        unrealized_mbt: (() => { try { const u = computeUnrealizedPnLMBT(); return Number((u.total || 0).toFixed(4)); } catch(_) { return 0; } })(),
        effectiveTotal: (() => { try { const eq = getEffectiveDemoEquity(); return Number((eq.effectiveTotal || 0).toFixed(4)); } catch(_) { return 0; } })(),
      },
      portfolio: {
        // AUTONOM-AUDIT-FIX C [17.05.2026]: investmentTotal MBT-aware (war nur SINGLE → 0)
        investmentTotal: Number(imMarktCombined.toFixed(2)),
        investmentTotalSingle: Number(investmentTotal.toFixed(2)),
        investmentTotalMBT: Number(mbtCommitted.toFixed(2)),
        // KAPITAL_FIX BUG4+5 [23.05.2026]: realizedPnl + unrealizedPnl jetzt MBT-aware (Grid+INFGRID+DCA).
        // Vorher: nur SINGLE-StatsCore → zeigte 0 trotz +276 Backfill.
        unrealizedPnl:   (() => { try { const u = (typeof computeUnrealizedPnLMBT === 'function') ? computeUnrealizedPnLMBT() : null; return Number(((u && u.total) || unrealizedPnl).toFixed(2)); } catch(_) { return Number(unrealizedPnl.toFixed(2)); } })(),
        unrealizedPct:   imMarktCombined > 0 ? Number((unrealizedPnl / imMarktCombined * 100).toFixed(2)) : 0,
        // FIX 2 [25.05.2026]: FALSE_MATH-Filter — siehe Audit Bereich 1 HIGH-2.
        // strp-Einträge mit notes LIKE 'FALSE_MATH%' sind aus dem alten size-Unit-Bug (Punkt-2-Fix).
        // Sum würde sonst 2148.97 statt ehrlicher 12.57 zeigen.
        realizedPnl:     (() => { try { const grdAll = DB.db.prepare("SELECT COALESCE(SUM(pnl_usdt),0) AS s FROM strategy_regime_performance WHERE bot_type IN ('GRID','INFGRID') AND (notes IS NULL OR notes NOT LIKE 'FALSE_MATH%')").get().s || 0; return Number((realizedPnl + grdAll).toFixed(2)); } catch(_) { return Number(realizedPnl.toFixed(2)); } })(),
        realizedPnlSingle: Number(realizedPnl.toFixed(2)),
        realizedToday:   Number(realizedToday.toFixed(2)),
        totalPnl:        Number(totalPnl.toFixed(2)),
        // WALLET-DISPLAY-FIX [23.05.2026]: Grid-PnL sichtbar machen (Engine unverändert)
        // FIX 2 [25.05.2026]: +FALSE_MATH-Filter
        realizedGrid:    (() => { try { return Number((DB.db.prepare("SELECT COALESCE(SUM(pnl_usdt),0) AS s FROM strategy_regime_performance WHERE ts > (SELECT CAST(value AS INTEGER) FROM bot_settings WHERE key='reset_day_zero_at') AND bot_type IN ('GRID','INFGRID') AND (notes IS NULL OR notes NOT LIKE 'FALSE_MATH%')").get().s || 0).toFixed(2)); } catch(_) { return 0; } })(),
        realizedAllSinceReset: (() => { try { return Number((DB.db.prepare("SELECT COALESCE(SUM(pnl_usdt),0) AS s FROM strategy_regime_performance WHERE ts > (SELECT CAST(value AS INTEGER) FROM bot_settings WHERE key='reset_day_zero_at') AND (notes IS NULL OR notes NOT LIKE 'FALSE_MATH%')").get().s || 0).toFixed(2)); } catch(_) { return 0; } })(),
        // KAPITAL_FIX BUG1 [23.05.2026]: totalEquity nur noch nicht-realisierten Teil zur Wallet addieren.
        // Vorher: wallet (1276 nach Backfill) + realized (276) + imMarkt (150) = 1702 → DOPPELT.
        // Neu: wallet (1276) + pendingRealize (nur strp WHERE realized_at IS NULL) + imMarkt (150) = 1426.
        totalEquity:     (() => {
          try {
            // FIX 2: +FALSE_MATH-Filter
            let strpQuery = "SELECT COALESCE(SUM(pnl_usdt),0) AS s FROM strategy_regime_performance WHERE ts > (SELECT CAST(value AS INTEGER) FROM bot_settings WHERE key='reset_day_zero_at') AND (notes IS NULL OR notes NOT LIKE 'FALSE_MATH%')";
            try {
              const hasRealizedAt = DB.db.prepare("SELECT 1 FROM pragma_table_info('strategy_regime_performance') WHERE name='realized_at'").get();
              if (hasRealizedAt) strpQuery += " AND realized_at IS NULL";
            } catch(_) {}
            const r = DB.db.prepare(strpQuery).get();
            const pendingOnly = r.s || 0;
            return Number(((wallet.total || 1000) + pendingOnly + imMarktCombined).toFixed(2));
          } catch(_) { return Number((wallet.total || 1000).toFixed(2)); }
        })(),
        dayZeroAt:       (() => { try { return Number(DB.db.prepare("SELECT value FROM bot_settings WHERE key='reset_day_zero_at'").get().value); } catch(_) { return 0; } })(),
        // STUFE_A.1 [23.05.2026]: Virtuelle Display-Aufteilung der realized Profits (Engine unverändert).
        // Logik: SOLL-Reserve = wallet.reserve + realized × ratio, SOLL-Trading = wallet.trading + realized × (1-ratio)
        // Bot tradet weiter auf wallet.trading (engine-Wahrheit). Hier nur Anzeige für Christian.
        ...((() => {
          try {
            // FIX 2: +FALSE_MATH-Filter — displayReserve/displayTrading basieren auf CLEAN strp
            let strpQuery = "SELECT COALESCE(SUM(pnl_usdt),0) AS s FROM strategy_regime_performance WHERE ts > (SELECT CAST(value AS INTEGER) FROM bot_settings WHERE key='reset_day_zero_at') AND (notes IS NULL OR notes NOT LIKE 'FALSE_MATH%')";
            try {
              const hasRealizedAt = DB.db.prepare("SELECT 1 FROM pragma_table_info('strategy_regime_performance') WHERE name='realized_at'").get();
              if (hasRealizedAt) strpQuery += " AND realized_at IS NULL";
            } catch(_) {}
            const r = DB.db.prepare(strpQuery).get();
            const realized = r.s || 0;
            const ratioRow = DB.db.prepare("SELECT value FROM bot_settings WHERE key='reserve_split_ratio'").get();
            const ratio = ratioRow ? parseFloat(ratioRow.value) : (CFG.RESERVE_RATIO || 0.70);
            const wTrad = wallet.trading || 0;
            const wRes = wallet.reserve || 0;
            return {
              displayReserve:  Number((wRes + realized * ratio).toFixed(2)),
              displayTrading:  Number((wTrad + realized * (1 - ratio)).toFixed(2)),
              displaySplitRatio: ratio,
              pendingRealize:  Number(realized.toFixed(2)),
              isVirtual: realized > 0.01,
            };
          } catch(_) { return { displayReserve: wallet.reserve || 0, displayTrading: wallet.trading || 0, displaySplitRatio: 0.70, pendingRealize: 0, isVirtual: false }; }
        })()),
      },
      stats: {
        tradesTotal,
        wins,
        losses,
        winRate: Number((winRate * 100).toFixed(1)),
        activeTrades: positions.length + mbtActiveTotal,                         // FIX D: SINGLE + MBT
        activeSingle:  positions.length,                                         // FIX D
        activeDCA:     mbtDcaCount,                                              // FIX D
        activeGrid:    mbtGridCount,                                             // FIX D
        activeInfgrid: mbtInfgridCount,                                          // FIX D
        maxSlots: CFG.MAX_OPEN_TRADES,
        // DEMO_KACHEL_FIX [23.05.2026]: All-bot-type aggregierte Stats für Display
        // Vorher: StatsCore.getStats() liefert nur SINGLE → Demo-Kachel zeigte 0 Trades/0% WR
        ...((() => {
          try {
            const grdRows = DB.db.prepare("SELECT COUNT(*) n, SUM(CASE WHEN pnl_usdt>0 THEN 1 ELSE 0 END) w FROM strategy_regime_performance WHERE bot_type='GRID'").get();
            const infgRows = DB.db.prepare("SELECT COUNT(*) n, SUM(CASE WHEN pnl_usdt>0 THEN 1 ELSE 0 END) w FROM strategy_regime_performance WHERE bot_type='INFGRID'").get();
            const dcaCountRow = DB.db.prepare("SELECT COUNT(*) n FROM dca_iterations").get();
            const dcaWinsRow = DB.db.prepare("SELECT COUNT(*) n FROM dca_iterations WHERE pnl_usdt > 0").get();
            const tradesGrid = grdRows.n || 0;
            const tradesInfgrid = infgRows.n || 0;
            const tradesDca = dcaCountRow.n || 0;
            const tradesSingle = tradesTotal || 0;
            const winsAll = (wins || 0) + (grdRows.w || 0) + (infgRows.w || 0) + (dcaWinsRow.n || 0);
            const tradesAll = tradesSingle + tradesGrid + tradesInfgrid + tradesDca;
            const lossesAll = tradesAll - winsAll;
            const winRateAll = tradesAll > 0 ? Number((winsAll / tradesAll * 100).toFixed(1)) : 0;
            // FIX 29 [26.05.2026 / Bug C4]: Capital-weighted Win-Rate (statt count-weighted).
            // count-weighted überschätzt durch GRID-Mikro-Fills (~$0.04 avg) vs SINGLE-Trades (~$50 avg).
            // Gewichtung mit avg-trade-size pro Typ aus Live-Daten: SINGLE×50 / GRID×0.04 / DCA×20 (LdP-Style Capital-at-Risk).
            const W_SINGLE = 50, W_GRID = 0.04, W_DCA = 20;
            const weightedWinsAll  = (wins||0) * W_SINGLE + (grdRows.w||0) * W_GRID + (infgRows.w||0) * W_GRID + (dcaWinsRow.n||0) * W_DCA;
            const weightedTradesAll = tradesSingle * W_SINGLE + tradesGrid * W_GRID + tradesInfgrid * W_GRID + tradesDca * W_DCA;
            const winRateWeighted = weightedTradesAll > 0 ? Number((weightedWinsAll / weightedTradesAll * 100).toFixed(1)) : 0;
            return {
              tradesGrid, tradesInfgrid, tradesDca, tradesSingle, tradesAll, winsAll, lossesAll,
              winRateAll,           // Naive Mix-WR (kann durch GRID-Mikro inflate werden)
              winRateWeighted,      // FIX 29: Capital-weighted (gerechte Sicht für UI)
              winRateSingle: tradesSingle > 0 ? Number(((wins||0) / tradesSingle * 100).toFixed(1)) : 0,
              winRateGrid: (tradesGrid+tradesInfgrid) > 0 ? Number((((grdRows.w||0)+(infgRows.w||0)) / (tradesGrid+tradesInfgrid) * 100).toFixed(1)) : 0,
              winRateDca: tradesDca > 0 ? Number(((dcaWinsRow.n||0) / tradesDca * 100).toFixed(1)) : 0,
            };
          } catch(_) { return { tradesGrid:0, tradesInfgrid:0, tradesDca:0, tradesSingle:tradesTotal||0, tradesAll:tradesTotal||0, winsAll:wins||0, lossesAll:losses||0, winRateAll:0, winRateWeighted:0, winRateSingle:0, winRateGrid:0, winRateDca:0 }; }
        })()),
        // T9.2 [24.05.2026]: Differenzierte Win-Rate auf 4 Ebenen — verhindert dass Grid-Mikro-Fills
        // (avg +$0.04, fast immer profitabel) den Eindruck "99.5% Win-Rate" erzeugen.
        breakdown: ((() => {
          try {
            const singleClosed = DB.db.prepare("SELECT COUNT(*) n, SUM(CASE WHEN realized_pnl>0 THEN 1 ELSE 0 END) w FROM trades WHERE state='CLOSED'").get();
            const singleOpen   = DB.db.prepare("SELECT COUNT(*) n FROM trades WHERE state='POSITION_ACTIVE'").get();
            const dcaClosed    = DB.db.prepare("SELECT COUNT(*) n, SUM(CASE WHEN status='CLOSED_TP' THEN 1 ELSE 0 END) w FROM dca_instances WHERE status LIKE 'CLOSED%'").get();
            const dcaOpen      = DB.db.prepare("SELECT COUNT(*) n FROM dca_instances WHERE status='OPEN'").get();
            const gridClosed   = DB.db.prepare("SELECT COUNT(*) n, SUM(CASE WHEN profit_acc>0 THEN 1 ELSE 0 END) w FROM grid_instances WHERE status='CLOSED'").get();
            const gridOpen     = DB.db.prepare("SELECT COUNT(*) n FROM grid_instances WHERE status='OPEN'").get();
            // FIX 2: +FALSE_MATH-Filter für T9.2-breakdown
            const fills        = DB.db.prepare("SELECT COUNT(*) n, COALESCE(SUM(pnl_usdt),0) p, COALESCE(AVG(pnl_usdt),0) a FROM strategy_regime_performance WHERE bot_type IN ('GRID','INFGRID') AND (notes IS NULL OR notes NOT LIKE 'FALSE_MATH%')").get();
            const realized     = DB.db.prepare("SELECT COALESCE(SUM(pnl_usdt),0) p FROM strategy_regime_performance WHERE (notes IS NULL OR notes NOT LIKE 'FALSE_MATH%')").get();
            const sc = singleClosed.n || 0, sw = singleClosed.w || 0;
            const dc = dcaClosed.n || 0,    dw = dcaClosed.w || 0;
            const gc = gridClosed.n || 0,   gw = gridClosed.w || 0;
            return {
              single:       { closed: sc, open: singleOpen.n || 0, wins: sw, losses: sc - sw, winRate: sc > 0 ? Number((sw/sc*100).toFixed(1)) : null },
              dcaInstance:  { closed: dc, open: dcaOpen.n   || 0, wins: dw, losses: dc - dw, winRate: dc > 0 ? Number((dw/dc*100).toFixed(1)) : null },
              gridInstance: { closed: gc, open: gridOpen.n  || 0, wins: gw, losses: gc - gw, winRate: gc > 0 ? Number((gw/gc*100).toFixed(1)) : null },
              gridFills:    { total: fills.n || 0, sumPnl: Number((fills.p).toFixed(2)), avgPnl: Number((fills.a).toFixed(4)) },
              pnlRealizedTotal: Number(realized.p.toFixed(2)),
            };
          } catch(e) { return null; }
        })()),
      },
      wallet: walletFlow,
      activity24h,
      activity24hBreakdown,
      system: {
        ws: wsStatus,
        watchdog: watchdogStatus,
        brain: brainStats,
        guardian: guardianStats,
        regime,
        regimeConf,
      },
    });
  } catch(e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

// /api/bots/positions/live - Daten fuer Trade-Karten C
app.get('/api/bots/positions/live', (req, res) => {
  try {
    const positions = Object.values(DemoEngine.positions || {});
    const tickerCache = Bitget.priceCache || {};
    const wallet = DemoEngine.wallet || {};
    const totalTopf = wallet.total || 1;
    
    const cards = positions.map(pos => {
      const tradeId  = pos.dbTradeId || pos.tradeId;
      const symbol   = pos.symbol;
      const sideLC   = String(pos.direction || pos.side || 'buy').toLowerCase();
      const entry    = Number(pos.fillPrice || 0);
      const size     = Number(pos.size || 0);
      const openedAt = Number(pos.openedAt || pos.created_at || Date.now());
      const ageMin   = Math.floor((Date.now() - openedAt) / 60000);
      
      // Live-Preis
      const ticker   = tickerCache[symbol] || {};
      const livePrice = Number(ticker.last || ticker.price || entry);
      
      // PnL berechnen
      const dir = sideLC === 'sell' ? -1 : 1;
      const pnlPct = entry > 0 ? dir * (livePrice - entry) / entry : 0;
      const pnlUsdt = pnlPct * size;
      
      // SL/TP aus ExitEngine.tpslLevels (falls da)
      let stopLoss = pos.stopLoss;
      let takeProfit = pos.takeProfit;
      let trailHigh = pos.trailHigh;
      let profile = pos.sltp ? pos.sltp.profile : null;
      let riskReward = pos.sltp ? pos.sltp.riskReward : null;
      
      try {
        if (typeof ExitEngine !== 'undefined' && ExitEngine.tpslLevels[tradeId]) {
          const lvl = ExitEngine.tpslLevels[tradeId];
          stopLoss = lvl.stopLoss;
          takeProfit = lvl.takeProfit;
          trailHigh = lvl.trailHigh;
          if (!profile && lvl.profile) profile = lvl.profile;
          if (!riskReward && lvl.riskReward) riskReward = lvl.riskReward;
        }
      } catch(_) {}
      
      // Position-Verlauf (wo zwischen SL und TP ist Live-Preis)
      let positionInRange = 0.5; // 0 = SL, 0.5 = Entry, 1 = TP
      if (stopLoss && takeProfit) {
        if (sideLC === 'buy') {
          const range = takeProfit - stopLoss;
          if (range > 0) positionInRange = (livePrice - stopLoss) / range;
        } else {
          const range = stopLoss - takeProfit;
          if (range > 0) positionInRange = (stopLoss - livePrice) / range;
        }
        positionInRange = Math.max(0, Math.min(1, positionInRange));
      }
      
      // Phase 1+2+3 Status
      const phaseStatus = {
        brainDrop:     'idle',  // idle / armed / triggered
        volSpike:      'idle',
        breakEven:     'idle',
        profitLock1:   'idle',
        profitLock2:   'idle',
        profitLock3:   'idle',
      };
      
      try {
        // Break-Even aktiviert?
        const lvl = ExitEngine.tpslLevels[tradeId];
        if (lvl && lvl.breakEvenActivated) phaseStatus.breakEven = 'triggered';
        else if (pnlPct >= 0.003) phaseStatus.breakEven = 'armed'; // kurz vor Trigger
        
        // Profit-Lock-Stufen
        const stage = (lvl && lvl.profitLockStage) || 0;
        if (stage >= 1) phaseStatus.profitLock1 = 'triggered';
        else if (pnlPct >= 0.008) phaseStatus.profitLock1 = 'armed';
        if (stage >= 2) phaseStatus.profitLock2 = 'triggered';
        else if (pnlPct >= 0.018) phaseStatus.profitLock2 = 'armed';
        if (stage >= 3) phaseStatus.profitLock3 = 'triggered';
        else if (pnlPct >= 0.028) phaseStatus.profitLock3 = 'armed';
        
        // Brain-Drop armed wenn Position alt genug
        if (ageMin >= 5) phaseStatus.brainDrop = 'armed';
      } catch(_) {}
      
      // Brain-Konsens-Vergleich
      let brainConsensus = { open: null, now: null, dropPct: 0 };
      try {
        if (DB && DB.db) {
          const openBrain = DB.db.prepare(
            "SELECT consensus FROM aladdin_decisions WHERE symbol=? AND ts BETWEEN ? AND ? ORDER BY ts DESC LIMIT 1"
          ).get(symbol, openedAt - 120000, openedAt + 120000);
          const recentBrain = DB.db.prepare(
            "SELECT consensus FROM aladdin_decisions WHERE symbol=? AND ts > ? ORDER BY ts DESC LIMIT 1"
          ).get(symbol, Date.now() - 600000);
          
          brainConsensus.open = openBrain ? openBrain.consensus : null;
          brainConsensus.now  = recentBrain ? recentBrain.consensus : null;
          
          // Drop berechnen
          const parse = (s) => {
            if (!s) return null;
            const m = String(s).match(/(\d+)B\/(\d+)S\/(\d+)N/);
            return m ? { buy: +m[1], sell: +m[2] } : null;
          };
          const o = parse(brainConsensus.open);
          const n = parse(brainConsensus.now);
          if (o && n) {
            const sideKey = sideLC === 'sell' ? 'sell' : 'buy';
            brainConsensus.dropPct = Math.max(0, (o[sideKey] - n[sideKey])) / 5;
          }
        }
      } catch(_) {}
      
      // UI Pipeline B [16.05.2026]: bot_type + strategy_name aus trades-Tabelle
      let botType = 'SINGLE', strategyName = 'UNIFIED';
      try {
        if (tradeId) {
          const row = DB.db.prepare('SELECT bot_type, strategy FROM trades WHERE id=?').get(tradeId);
          if (row) {
            botType = row.bot_type || 'SINGLE';
            if (row.strategy) {
              const parts = row.strategy.replace(/^DEMO_/, '').split('_');
              if (parts.length >= 2 && ['SINGLE','GRID','DCA','INFGRID','CONSERVATIVE'].includes(parts[0])) {
                if (!row.bot_type) botType = parts[0];
                strategyName = parts.slice(1).join('_');
              } else {
                strategyName = row.strategy.replace(/^DEMO_/, '');
              }
            }
          }
        }
      } catch(_) {}

      return {
        tradeId,
        symbol,
        side: sideLC.toUpperCase(),
        entry,
        livePrice,
        size,
        sizePctOfTopf: Number((size / totalTopf * 100).toFixed(1)),
        ageMin,
        stopLoss,
        takeProfit,
        trailHigh,
        profile,
        riskReward,
        // UI Pipeline B [16.05.2026]:
        bot_type: botType,
        strategy_name: strategyName,
        type_kind: 'TRADE',
        pnl: {
          usdt: Number(pnlUsdt.toFixed(2)),
          pct: Number((pnlPct * 100).toFixed(2)),
        },
        positionInRange: Number(positionInRange.toFixed(3)),
        phaseStatus,
        brainConsensus: {
          open: brainConsensus.open,
          now: brainConsensus.now,
          dropPct: Number((brainConsensus.dropPct * 100).toFixed(0)),
        },
      };
    });

    // UI Pipeline B [16.05.2026]: GRID/INFGRID/DCA-Karten ergänzen
    try {
      const grids = DB.listGridsOpen.all(50);
      for (const g of grids) {
        const orders = DB.listGridOrders.all(g.grid_id);
        const filled = orders.filter(o => o.filled).length;
        const meta = g.meta ? (() => { try { return JSON.parse(g.meta); } catch(_) { return {}; } })() : {};
        const live = (Bitget.priceCache[g.symbol] || {}).last || meta.mid_at_create || 0;
        cards.push({
          tradeId: g.grid_id,
          symbol: g.symbol,
          side: g.bot_type,
          entry: meta.mid_at_create || 0,
          livePrice: live,
          size: g.capital_pool,
          sizePctOfTopf: Number(((g.capital_pool || 0) / totalTopf * 100).toFixed(1)),
          ageMin: Math.floor((Date.now() - g.created_at) / 60000),
          stopLoss: g.range_low,
          takeProfit: g.range_high,
          trailHigh: null,
          profile: g.bot_type,
          riskReward: null,
          bot_type: g.bot_type,
          strategy_name: 'GRID_TRADE',
          type_kind: g.bot_type,
          bot_details: {
            grid_id: g.grid_id,
            range_low: g.range_low, range_high: g.range_high,
            levels_total: g.num_levels, levels_filled: filled,
            fills_acc: g.fills_acc, range_breaks: g.range_breaks,
            per_level: g.per_level,
            extensions: meta.extensions || 0,
            paused: (g.paused | 0) === 1,
          },
          pnl: { usdt: Number((g.profit_acc || 0).toFixed(2)), pct: 0 },
          positionInRange: null,  // MBT-UI D: kein Standard-50% Balken
          phaseStatus: {},
          brainConsensus: (() => {
            try {
              const recent = DB.db.prepare("SELECT consensus FROM aladdin_decisions WHERE symbol=? ORDER BY ts DESC LIMIT 1").get(g.symbol);
              return { open: null, now: recent ? recent.consensus : null, dropPct: 0 };
            } catch(_) { return { open: null, now: null, dropPct: 0 }; }
          })(),
        });
      }
    } catch(_) {}
    try {
      const dcas = DB.listDcaOpen.all(50);
      for (const d of dcas) {
        const live = (Bitget.priceCache[d.symbol] || {}).last || d.avg_buy_price || 0;
        const isPreFirstBuy = (d.iteration === 0 || !d.avg_buy_price);
        const displayEntry = isPreFirstBuy ? live : d.avg_buy_price;
        const displayTP = isPreFirstBuy
          ? (live ? live * (1 + d.target_profit_pct) : null)
          : (d.avg_buy_price ? d.avg_buy_price * (1 + d.target_profit_pct) : null);
        const nextBuyInMin = d.next_buy_at
          ? Math.max(0, Math.round((d.next_buy_at - Date.now()) / 60000))
          : null;
        // MBT-UI D [16.05.2026]: positionInRange ehrlich berechnen
        let positionInRange = null;
        if (!isPreFirstBuy && d.avg_buy_price && live && displayTP) {
          // 0 = Avg, 1 = TP. Live darunter → 0 oder negativ-clamped.
          const range = displayTP - d.avg_buy_price;
          if (range > 0) positionInRange = Math.max(0, Math.min(1, (live - d.avg_buy_price) / range));
        }
        // MBT-UI D [16.05.2026]: Brain-Lookup per Symbol (zuletzt aladdin_decisions)
        let brainConsensus = { open: null, now: null, dropPct: 0 };
        try {
          const recent = DB.db.prepare(
            "SELECT consensus, decision, confidence FROM aladdin_decisions WHERE symbol=? ORDER BY ts DESC LIMIT 1"
          ).get(d.symbol);
          if (recent) {
            brainConsensus.now = recent.consensus || (recent.decision + ' conf=' + (recent.confidence||0).toFixed(2));
          }
          // "open" für DCA bedeutet: Brain zur Zeit der ersten Iteration
          if (!isPreFirstBuy) {
            const firstIter = DB.db.prepare("SELECT buy_ts FROM dca_iterations WHERE dca_id=? ORDER BY iteration ASC LIMIT 1").get(d.dca_id);
            if (firstIter) {
              const openBrain = DB.db.prepare(
                "SELECT consensus FROM aladdin_decisions WHERE symbol=? AND ts BETWEEN ? AND ? ORDER BY ts DESC LIMIT 1"
              ).get(d.symbol, firstIter.buy_ts - 120000, firstIter.buy_ts + 120000);
              brainConsensus.open = openBrain ? openBrain.consensus : null;
            }
          }
        } catch(_){}
        // MBT-UI D [16.05.2026]: wait_reason aus DB
        const waitReason = d.last_block_reason;
        const waitSinceMin = d.last_block_ts ? Math.round((Date.now() - d.last_block_ts) / 60000) : null;
        cards.push({
          tradeId: d.dca_id,
          symbol: d.symbol,
          side: 'DCA',
          entry: displayEntry,
          livePrice: live,
          size: d.total_spent || (d.capital_per_buy * d.max_iterations),
          sizePctOfTopf: Number((((d.total_spent || d.capital_per_buy * d.max_iterations) || 0) / totalTopf * 100).toFixed(1)),
          ageMin: Math.floor((Date.now() - d.created_at) / 60000),
          stopLoss: null,        // DCA hat keinen klassischen SL — Frontend rendert "—"
          takeProfit: displayTP,
          trailHigh: null,
          profile: 'DCA',
          riskReward: null,
          bot_type: 'DCA',
          strategy_name: 'DCA_ACCUMULATE',
          type_kind: 'DCA',
          bot_details: {
            dca_id: d.dca_id,
            iteration: d.iteration, max_iterations: d.max_iterations,
            avg_buy_price: d.avg_buy_price, total_size: d.total_size,
            total_spent: d.total_spent,
            target_profit_pct: d.target_profit_pct, max_dd_pct: d.max_dd_pct,
            interval_hours: d.interval_hours, last_dd_pct: d.last_dd_pct,
            status: d.status,
            is_pre_first_buy: isPreFirstBuy,
            next_buy_in_min: nextBuyInMin,
            capital_per_buy: d.capital_per_buy,
            paused: (d.paused | 0) === 1,
            // MBT-UI D [16.05.2026]: Wait-Reason für UI
            // P1.1 [2026-06-03]: Router/Strategy-Sources getrennt zeigen (nicht stale "AladdinBrain")
            wait_reason: waitReason,
            wait_value: d.last_block_value,
            wait_since_min: waitSinceMin,
            wait_source: waitReason
              ? (waitReason === 'PAUSED_BY_USER' ? 'User'
                : (String(waitReason).startsWith('STRATEGY_')
                   || String(waitReason).startsWith('ROUTER_')
                   || waitReason === 'ANALYSIS_ONLY'
                   || waitReason === 'PAIR_REQUIRED'
                   || waitReason === 'NOT_IN_TRADING_UNIVERSE') ? 'Router'
                : 'AladdinBrain')
              : null,
          },
          pnl: {
            usdt: d.avg_buy_price && live ? Number(((live - d.avg_buy_price) * d.total_size).toFixed(2)) : 0,
            pct: d.avg_buy_price && live ? Number((((live - d.avg_buy_price) / d.avg_buy_price) * 100).toFixed(2)) : 0,
          },
          positionInRange: positionInRange,  // null bei iter=0 → Frontend zeigt Banner
          phaseStatus: {},
          brainConsensus,
        });
      }
    } catch(_) {}

    res.json({
      ok: true,
      ts: Date.now(),
      count: cards.length,
      by_type: cards.reduce((acc, c) => { acc[c.bot_type] = (acc[c.bot_type] || 0) + 1; return acc; }, {}),
      cards,
    });
  } catch(e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});


