// T8.1.5 [24.05.2026] Multi-Exchange Config Endpoints (AES-256-GCM via lib/encryption)
// Namespace: /api/exchange-config/* (vermeidet Konflikt mit /api/exchanges/list für Price-Compare)
const _encryption = (() => {
  try { return require('./lib/encryption.js'); } catch(_) { return null; }
})();
function _t8GetAllExchanges() {
  try {
    return DB.db.prepare(`SELECT exchange, tier, enabled, connection_status, latency_ms, last_test_ts, last_test_result,
      CASE WHEN api_key_enc IS NOT NULL THEN 1 ELSE 0 END as has_key
      FROM exchange_config ORDER BY tier, exchange`).all();
  } catch(_) { return []; }
}
function _t8AuditLog(exchange, action, success, msg) {
  try {
    DB.db.prepare(`INSERT INTO system_log (ts, level, module, msg, data) VALUES (?,?,?,?,?)`).run(
      Date.now(), success ? 'INFO' : 'WARN', 'exchange_config',
      `${exchange}: ${action} ${success ? 'OK' : 'FAIL'}${msg ? ' — ' + msg : ''}`,
      JSON.stringify({ exchange, action, success, ts: Date.now() })
    );
  } catch(_) {}
}
app.get('/api/exchange-config/list', (req, res) => {
  try {
    res.json({ ok: true, exchanges: _t8GetAllExchanges() });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});
app.get('/api/exchange-config/status', (req, res) => {
  // Polling-Endpoint (alle 30s vom UI)
  try {
    const rows = _t8GetAllExchanges();
    const summary = {
      total: rows.length,
      configured: rows.filter(r => r.has_key === 1).length,
      connected: rows.filter(r => r.connection_status === 'connected').length,
      errors: rows.filter(r => r.connection_status === 'error').length,
    };
    // T8.3 [24.05.2026] Hybrid-Status: woher kommen die aktiven Bitget-Keys?
    const bitget_key_source = global.BITGET_KEY_SOURCE || 'unknown';
    res.json({ ok: true, summary, exchanges: rows, bitget_key_source });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});
app.post('/api/exchange-config/test', requireDeployToken, async (req, res) => {
  // Phase-1 Stub: nur Bitget hat echten Test, andere returnen "stub-ok" für UI-Verifikation
  try {
    const { exchange, api_key, api_secret, passphrase } = req.body || {};
    if (!exchange || !api_key || !api_secret) return res.status(400).json({ ok: false, error: 'exchange, api_key, api_secret required' });
    const valid = ['bitget','binance','coinbase','kraken','okx','bybit','kucoin','mexc','gate','bitfinex','htx','cryptocom'];
    if (!valid.includes(exchange)) return res.status(400).json({ ok: false, error: 'unknown exchange' });
    const t0 = Date.now();
    let result = { ok: true, status: 'stub', latency_ms: 0, msg: 'Phase-1 stub: real test in Phase 2' };
    if (exchange === 'bitget' && api_key && api_secret) {
      // Bitget hat echten Test-Pfad — Public-Server-Time-Call als Lebenszeichen
      try {
        const url = 'https://api.bitget.com/api/v2/public/time';
        const r = await axios.get(url, { timeout: 5000 });
        if (r && r.data && (r.data.code === '00000' || r.data.serverTime || r.data.data)) {
          result = { ok: true, status: 'connected', latency_ms: Date.now() - t0, msg: 'Bitget public-api reachable' };
        } else {
          result = { ok: false, status: 'error', latency_ms: Date.now() - t0, msg: 'unexpected response' };
        }
      } catch (e) {
        result = { ok: false, status: 'error', latency_ms: Date.now() - t0, msg: 'API unreachable' };
      }
    }
    _t8AuditLog(exchange, 'test', result.ok, result.msg);
    res.json(result);
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});
app.post('/api/exchange-config/save', requireDeployToken, async (req, res) => {
  try {
    if (!_encryption) return res.status(500).json({ ok: false, error: 'encryption module not loaded' });
    const { exchange, api_key, api_secret, passphrase } = req.body || {};
    if (!exchange || !api_key || !api_secret) return res.status(400).json({ ok: false, error: 'exchange, api_key, api_secret required' });
    const valid = ['bitget','binance','coinbase','kraken','okx','bybit','kucoin','mexc','gate','bitfinex','htx','cryptocom'];
    if (!valid.includes(exchange)) return res.status(400).json({ ok: false, error: 'unknown exchange' });
    // Encrypt
    const ek = _encryption.encrypt(api_key);
    const es = _encryption.encrypt(api_secret);
    const ep = passphrase ? _encryption.encrypt(passphrase) : null;
    if (!ek.ciphertext || !es.ciphertext) {
      _t8AuditLog(exchange, 'save', false, 'encrypt failed');
      return res.status(500).json({ ok: false, error: 'encryption failed' });
    }
    // Pro Wert eigenes IV/Tag — wir speichern key+iv+tag concat als JSON in api_key_enc
    const _packed = (e) => e ? JSON.stringify({ ct: e.ciphertext, iv: e.iv, tag: e.tag }) : null;
    DB.db.prepare(`INSERT OR REPLACE INTO exchange_config
      (exchange, tier, enabled, api_key_enc, api_secret_enc, passphrase_enc, last_test_ts, last_test_result, connection_status, latency_ms, added_at, updated_at)
      VALUES (?, COALESCE((SELECT tier FROM exchange_config WHERE exchange=?), 1), 1, ?, ?, ?, ?, ?, ?, ?, COALESCE((SELECT added_at FROM exchange_config WHERE exchange=?), ?), ?)`)
      .run(exchange, exchange, _packed(ek), _packed(es), _packed(ep), Date.now(), 'saved', 'configured', 0, exchange, Date.now(), Date.now());
    _t8AuditLog(exchange, 'save', true, 'keys persisted (encrypted)');
    res.json({ ok: true, exchange, status: 'saved', key_masked: _encryption.mask(api_key) });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});
app.post('/api/exchange-config/delete', requireDeployToken, (req, res) => {
  try {
    const { exchange, confirm } = req.body || {};
    if (!exchange) return res.status(400).json({ ok: false, error: 'exchange required' });
    // Bitget braucht extra-Confirm wegen Default-Exchange-Status
    if (exchange === 'bitget' && confirm !== 'YES_DELETE_BITGET') {
      return res.status(400).json({ ok: false, error: 'BITGET_REQUIRES_CONFIRM', hint: "POST with confirm:'YES_DELETE_BITGET'" });
    }
    // Wipe encrypted columns (keep row for tier-info)
    DB.db.prepare(`UPDATE exchange_config SET api_key_enc=NULL, api_secret_enc=NULL, passphrase_enc=NULL, iv=NULL, auth_tag=NULL,
      enabled=0, connection_status=NULL, latency_ms=NULL, updated_at=? WHERE exchange=?`).run(Date.now(), exchange);
    _t8AuditLog(exchange, 'delete', true, 'keys wiped');
    res.json({ ok: true, exchange, status: 'deleted' });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});
// Bitget-Migration-Status (T8.1.6 vorbereitend)
app.get('/api/exchange-config/migration-status', (req, res) => {
  try {
    const bitgetRow = DB.db.prepare("SELECT api_key_enc FROM exchange_config WHERE exchange='bitget'").get();
    const hasDbKeys = !!(bitgetRow && bitgetRow.api_key_enc);
    const envHasKeys = !!(process.env.BITGET_API_KEY && process.env.BITGET_SECRET_KEY);
    res.json({
      ok: true,
      bitget_in_db: hasDbKeys,
      bitget_in_env: envHasKeys,
      migration_needed: envHasKeys && !hasDbKeys,
      migration_complete: hasDbKeys,
      using_fallback: envHasKeys && !hasDbKeys,
    });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});
app.post('/api/exchange-config/migrate-bitget', requireDeployToken, async (req, res) => {
  // T8.1.6: .env → DB, AES-encrypt, mark migrated
  try {
    if (!_encryption) return res.status(500).json({ ok: false, error: 'encryption not loaded' });
    if (!process.env.BITGET_API_KEY || !process.env.BITGET_SECRET_KEY) {
      return res.status(400).json({ ok: false, error: 'BITGET_API_KEY/SECRET not in .env' });
    }
    const ek = _encryption.encrypt(process.env.BITGET_API_KEY);
    const es = _encryption.encrypt(process.env.BITGET_SECRET_KEY);
    const ep = process.env.BITGET_PASSPHRASE ? _encryption.encrypt(process.env.BITGET_PASSPHRASE) : null;
    const _packed = (e) => e ? JSON.stringify({ ct: e.ciphertext, iv: e.iv, tag: e.tag }) : null;
    DB.db.prepare(`UPDATE exchange_config SET api_key_enc=?, api_secret_enc=?, passphrase_enc=?, enabled=1, connection_status='migrated_from_env', updated_at=? WHERE exchange='bitget'`)
      .run(_packed(ek), _packed(es), _packed(ep), Date.now());
    _t8AuditLog('bitget', 'migrate', true, 'migrated from .env to DB');
    res.json({ ok: true, msg: 'Bitget keys migrated to DB (.env entry remains for now — user can remove manually)' });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

