app.post('/api/anomaly/settings', (req,res) => {
  try {
    const b = req.body || {};
    const updates = [];
    if (b.threshold_z !== undefined) {
      const v = parseFloat(b.threshold_z);
      if (!isFinite(v) || v < 3 || v > 10) return res.status(400).json({ error:'threshold_z 3-10' });
      DB.db.prepare("INSERT OR REPLACE INTO bot_settings (key, value, updated_at) VALUES ('anomaly_threshold_z', ?, ?)").run(v.toString(), Date.now());
      updates.push(`threshold_z=${v}`);
    }
    if (b.cluster_min_symbols !== undefined) {
      const v = parseInt(b.cluster_min_symbols);
      if (!isFinite(v) || v < 2 || v > 20) return res.status(400).json({ error:'cluster_min_symbols 2-20' });
      DB.db.prepare("INSERT OR REPLACE INTO bot_settings (key, value, updated_at) VALUES ('anomaly_cluster_min_symbols', ?, ?)").run(v.toString(), Date.now());
      updates.push(`cluster_min=${v}`);
    }
    if (b.retrigger_minutes !== undefined) {
      const v = parseInt(b.retrigger_minutes);
      if (!isFinite(v) || v < 5 || v > 240) return res.status(400).json({ error:'retrigger_minutes 5-240' });
      DB.db.prepare("INSERT OR REPLACE INTO bot_settings (key, value, updated_at) VALUES ('anomaly_retrigger_minutes', ?, ?)").run(v.toString(), Date.now());
      updates.push(`retrigger_min=${v}`);
    }
    try { Log.info('ANOMALY_SETTINGS', updates.join(', ')); } catch(_) {}
    res.json({ ok:true, updates, current: AnomalyDetector._settings() });
  } catch(e) { res.status(500).json({ ok:false, error: e.message }); }
});

