// ── SLOT-STEUERUNG (Tier 1b.1) ──────────────────────────────────────────
// Christian-Direktive 11.05.2026: Slot-Wert nicht persistiert (wie Budget),
// Default 5 bei Restart. Smart-Empfehlung defensiv (kleines Kapital → wenige Slots).
function _suggestSlots(capital) {
  if (capital < 300)    return { slots: 2,  rationale: '< 300 USDT — sehr defensiv, 2 Slots' };
  if (capital < 800)    return { slots: 3,  rationale: '300-800 USDT — vorsichtig, 3 Slots' };
  if (capital < 2000)   return { slots: 5,  rationale: '800-2000 USDT — Standard, 5 Slots' };
  if (capital < 10000)  return { slots: 8,  rationale: '2-10k USDT — diversifiziert, 8 Slots' };
  if (capital < 50000)  return { slots: 12, rationale: '10-50k USDT — Skalierung, 12 Slots' };
  return { slots: 15, rationale: '> 50k USDT — Vollausbau, 15 Slots' };
}

app.get('/api/slots/snapshot', (req,res) => {
  const user = CFG.MAX_OPEN_TRADES;
  const rlMax = (typeof RiskLadder !== 'undefined') ? RiskLadder.maxTrades() : Infinity;
  const rtMax = (typeof RiskTier   !== 'undefined') ? RiskTier.maxPositions() : Infinity;
  const effective = Math.min(user, rlMax, rtMax);
  let reason = 'user setting';
  if (effective === rlMax && rlMax < user) reason = 'RiskLadder limit (Drawdown-basiert)';
  else if (effective === rtMax && rtMax < user) reason = 'RiskTier limit (Live-Restricted-Modus)';
  const capital = (DemoEngine && DemoEngine.wallet) ? (DemoEngine.wallet.total || 0) : 0;
  const active = (typeof Trades !== 'undefined') ? Trades.getActive().length : 0;
  // GLOBAL CAP [2026-06-06 Option A]: Gesamt-Exposure-Breakdown + capExceeded
  const _ex = (typeof getGlobalActiveExposure === 'function')
    ? getGlobalActiveExposure()
    : { single: active, grid: 0, dca: 0, infgrid: 0, total: active };
  res.json({
    current:   user,
    effective: effective,
    active:    active,
    activeTotal:   _ex.total,
    activeSingle:  _ex.single,
    activeDCA:     _ex.dca,
    activeGrid:    _ex.grid,
    activeInfgrid: _ex.infgrid,
    capExceeded:   _ex.total >= effective,
    limits: {
      user:       user,
      riskLadder: Number.isFinite(rlMax) ? rlMax : null,
      riskTier:   Number.isFinite(rtMax) ? rtMax : null,
    },
    reason:    reason,
    min:       CFG.MIN_SLOTS,
    max:       CFG.MAX_SLOTS,
    capital:   capital,
    suggested: _suggestSlots(capital),
  });
});

