// WALLET RECONCILER V2 — MBT-aware (FIX 7 [26.05.2026])
// Quellen: LEAN SecurityPortfolioManager.TotalPortfolioValue (curl raw .cs Z.430-475),
//          Nautilus portfolio.pyx balances_locked + realized_pnls/unrealized_pnls (curl raw),
//          AUDFIX_035 in-code note (wallet.total enthält MBT implizit via 0-Movement Audit-Ledger).
// Audit-Trail-Methode (Option B) + effective-Total-Konsistenz (Option C Hybrid).
// autoFix BEWUSST DEAKTIVIERT — V2-Validierung erst nach 7d stabilem Run.
// Schwelle 2.0 USDT (rounding-tolerant, ledger-Float realistisch).
const WalletReconciler = {
  lastCheck: null, lastDrift: 0, alertThreshold: 2.0,
  check(autoFix) {
    const w = DemoEngine && DemoEngine.wallet;
    if (!w) return { error: 'no wallet' };
    const startTotal = w.startTotal || 1000;
    const reserve = w.reserve || 0;
    const istTotal = w.total || 0;
    const istTrading = w.trading || 0;

    // ── Real-Delta-Methode (FIX 7.1 [26.05.2026]): nutze (after_total - before_total)
    //    Filtert audit-only Ops (GRID_BUY/SELL, DCA_BUY, INITIAL_SPLIT_CORRECTION, GRID_CLOSE_PROFIT
    //    mit before==after) AUTOMATISCH — kein Whitelist nötig.
    // ── Filter ts >= resetAt, da Day-Zero-Reset wallet direkt manipuliert hat ohne ledger-Eintrag.
    const resetAt = (w._day_zero_reset && w._day_zero_reset.ts) || 0;
    let ledgerNet = 0;
    try {
      const r = DB.db.prepare(`
        SELECT COALESCE(SUM(after_total - before_total), 0) AS net
        FROM wallet_ledger
        WHERE ts >= ?
          AND after_total IS NOT NULL
          AND before_total IS NOT NULL
      `).get(resetAt);
      ledgerNet = (r && r.net) || 0;
    } catch(_) {}

    const sollTotalLedger = startTotal + ledgerNet;
    const driftLedger = istTotal - sollTotalLedger;

    // ── Effective-Equity-Konsistenz (LEAN-Style, matcht KillSwitch + Dashboard)
    let effectiveTotal = istTotal;
    let mbtUnrealized = 0;
    try {
      if (typeof getEffectiveDemoEquity === 'function') {
        const eq = getEffectiveDemoEquity();
        effectiveTotal = eq.effectiveTotal;
        mbtUnrealized = (eq.unrealized && eq.unrealized.total) || 0;
      }
    } catch(_) {}

    this.lastCheck = Date.now();
    this.lastDrift = driftLedger;

    const result = {
      ts: this.lastCheck,
      mode: 'V2_MBT_AWARE',
      startTotal,
      ledgerNet:        Math.round(ledgerNet * 100) / 100,
      sollTotal:        Math.round(sollTotalLedger * 100) / 100,
      istTotal:         Math.round(istTotal * 100) / 100,
      drift:            Math.round(driftLedger * 100) / 100,
      effectiveTotal:   Math.round(effectiveTotal * 100) / 100,
      mbtUnrealized:    Math.round(mbtUnrealized * 100) / 100,
      reserve:          Math.round(reserve * 100) / 100,
      trading:          Math.round(istTrading * 100) / 100,
      consistent:       Math.abs(driftLedger) < this.alertThreshold,
    };

    if (!result.consistent) {
      try { Log.warn('RECON','V2 DRIFT '+result.drift.toFixed(2)+' USDT (soll='+result.sollTotal.toFixed(2)+' ist='+result.istTotal.toFixed(2)+' eff='+result.effectiveTotal.toFixed(2)+')'); } catch(_){}
      try { ActionStream.push('ERROR','RECON','Wallet-Drift V2 '+result.drift.toFixed(2)+' USDT',result); } catch(_){}
      // autoFix DEAKTIVIERT in V2 — separater PR nach 7d Stabilität
    }
    return result;
  },
  snapshot() { return { lastCheck:this.lastCheck, lastDrift:this.lastDrift, alertThreshold:this.alertThreshold, mode:'V2_MBT_AWARE' }; },
};
setInterval(() => { try { WalletReconciler.check(false); } catch(_){} }, 30*60*1000);
app.get('/api/recon/check', (req,res) => res.json(WalletReconciler.check(false)));

