app.post('/api/meta-label/predict', (req, res) => {
  try {
    if (!_MetaLabelCls) return res.json({ ok: false, error: 'meta_label_classifier module not loaded' });
    if (!_MetaLabelCls.isAvailable()) return res.json({ ok: false, error: 'classifier_not_available', loadError: _MetaLabelCls.loadError() });
    const body = req.body || {};
    // Accept either explicit features[10] OR brain-shaped object
    let feat;
    if (Array.isArray(body.features) && body.features.length === 10) {
      feat = body.features;
    } else {
      feat = _MetaLabelCls.featuresFromBrain({
        scores: body.scores || {},
        decisionConf: body.decisionConf,
        unifiedConf: body.unifiedConf,
        regime: body.regime || 'NEUTRAL',
      });
    }
    const prob = _MetaLabelCls.predictProba(feat);
    const mod  = _MetaLabelCls.modulator(prob);
    res.json({ ok: true, features: feat, prob, modulator: mod });
  } catch(e) { res.json({ ok: false, error: e.message }); }
});

