// FIX 23 [26.05.2026 / Tag 16 / Phase 3]: HRP-Allocation Snapshot
// Nutzt CorrelationEngine + VaREngine (per-Symbol var) als Inputs.
app.get('/api/hrp/snapshot', async (req,res) => {
  if (!_HRP) return res.json({ ok: false, error: 'HRP module not loaded' });
  try {
    // Block I Item 1 [27.05.2026]: Default-Liste auf aktuelle 12er-Liste (was Brain scant).
    // Cache-First: wenn keine custom-Query AND RiskSizing._hrpCache frisch (<10min) → cache zurück (kein live-recompute).
    const defaultSymbols = (typeof CFG !== 'undefined' && Array.isArray(CFG.AUTO_SYMBOLS) && CFG.AUTO_SYMBOLS.length)
      ? CFG.AUTO_SYMBOLS.join(',')
      : 'BTCUSDT,ETHUSDT,SOLUSDT,BNBUSDT,NEARUSDT,SUIUSDT,XRPUSDT,DOGEUSDT,ADAUSDT,LINKUSDT,TONUSDT,AVAXUSDT';
    const symbols = (req.query.symbols || defaultSymbols).split(',');
    const days = Math.min(parseInt(req.query.days) || 30, 90);
    // Cache-First (only if default-symbols + days=30)
    if (!req.query.symbols && days === 30 && typeof RiskSizing !== 'undefined' && RiskSizing._hrpCache && RiskSizing._hrpCacheTs) {
      const ageMs = Date.now() - RiskSizing._hrpCacheTs;
      if (ageMs < 600000 && RiskSizing._hrpCache.n >= 2 && RiskSizing._hrpCache.weights) {
        return res.json({ ok: true, days, ...RiskSizing._hrpCache, source: 'BG_CACHE', age_ms: ageMs });
      }
    }
    // Correlation Matrix
    let corrData = null;
    if (typeof CorrelationEngine !== 'undefined' && CorrelationEngine.compute) {
      corrData = await CorrelationEngine.compute(symbols, days);
    }
    if (!corrData || !corrData.matrix) {
      return res.json({ ok: false, error: 'CorrelationEngine returned no matrix' });
    }
    // Variance per Symbol via VaREngine (already per-Symbol cache after FIX 10)
    const variances = {};
    for (const s of symbols) {
      try {
        const v = await VaREngine.calculate(s);
        // VaR95 ≈ 1.645 * σ → σ ≈ varPct / 1.645 → var = σ²
        const sigma = (v && v.varPct) ? Math.max(0.001, v.varPct / 1.645) : 0.02;
        variances[s] = sigma * sigma;
      } catch(_) { variances[s] = 0.02 * 0.02; } // default ~2% std
    }
    const matrixData = { symbols: corrData.symbols || symbols, matrix: corrData.matrix };
    const result = _HRP.fromMatrix(matrixData, variances);
    res.json({ ok: true, days, ...result, variances });
  } catch(e) { res.status(500).json({ error: e.message }); }
});
