// AUDFIX_ETF_CSV [2026-05-18]: ETF-Flows CSV Import
app.post('/api/etf-flows/import', requireDeployToken, (req, res) => {
  try {
    const csv = req.body?.csv || (typeof req.body === 'string' ? req.body : null);
    if (!csv) return res.status(400).json({ error: 'CSV-Body fehlt' });
    const lines = String(csv).split(/\r?\n/).filter(l => l.trim());
    if (lines.length < 2) return res.status(400).json({ error: 'Mindestens 2 Zeilen (Header + Daten)' });

    const header = lines[0].toLowerCase().split(',').map(h => h.trim());
    const dateIdx = header.findIndex(h => h.includes('date'));
    const flowIdx = header.findIndex(h => h.includes('flow') || h.includes('net'));
    const sourceIdx = header.findIndex(h => h.includes('source'));
    if (dateIdx < 0 || flowIdx < 0) return res.status(400).json({ error: 'Header braucht "date" und "flow" Spalten' });

    let imported = 0, updated = 0;
    const errors = [];
    const stmt = DB.db.prepare(`INSERT INTO etf_flows (ts, net_flow_usd, source, flow_date) VALUES (?, ?, ?, ?)
      ON CONFLICT(flow_date) DO UPDATE SET net_flow_usd=excluded.net_flow_usd, source=excluded.source, ts=excluded.ts`);

    // Index auf flow_date für ON CONFLICT
    try { DB.db.exec(`CREATE UNIQUE INDEX IF NOT EXISTS idx_etf_flow_date ON etf_flows(flow_date)`); } catch(_){}

    for (let i = 1; i < lines.length; i++) {
      const cols = lines[i].split(',').map(c => c.trim());
      if (cols.length < 2) continue;
      const dateStr = cols[dateIdx];
      const flowMM = parseFloat(cols[flowIdx]);
      const sourceName = sourceIdx >= 0 ? (cols[sourceIdx] || 'manual_csv') : 'manual_csv';
      if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) { errors.push(`Zeile ${i+1}: ungültiges Datum "${dateStr}"`); continue; }
      const today = new Date().toISOString().slice(0,10);
      if (dateStr > today) { errors.push(`Zeile ${i+1}: Future-Datum ${dateStr}`); continue; }
      if (!Number.isFinite(flowMM)) { errors.push(`Zeile ${i+1}: ungültiger Flow "${cols[flowIdx]}"`); continue; }
      const flowUSD = flowMM * 1e6;
      const ts = new Date(dateStr + 'T00:00:00Z').getTime();
      try {
        stmt.run(ts, flowUSD, sourceName, dateStr);
        imported++;
      } catch(e) { errors.push(`Zeile ${i+1}: ${e.message.slice(0,80)}`); }
    }

    Log.info('ETF_IMPORT', `${imported} flows imported, ${errors.length} errors`);
    res.json({ ok: true, imported, errors, total_lines: lines.length - 1 });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});
