// MEGA-FINALE [2026-05-19]: Outcome-Eval-Statistik für KI-Dash Tab
app.get('/api/shadow/outcome-stats', (req,res) => {
  try {
    const hours = parseInt(req.query.hours) || 24;
    const since = Date.now() - hours * 3600 * 1000;
    const rows = DB.db.prepare(`SELECT model_name,
        COUNT(*) AS total,
        SUM(CASE WHEN actual_outcome IS NOT NULL AND is_correct != -1 THEN 1 ELSE 0 END) AS evaluated,
        SUM(CASE WHEN is_correct = 1 THEN 1 ELSE 0 END) AS correct,
        SUM(CASE WHEN is_correct = -1 THEN 1 ELSE 0 END) AS not_evaluable
      FROM shadow_predictions WHERE ts > ? GROUP BY model_name`).all(since);
    const lastEval = DB.db.prepare(`SELECT MAX(outcome_evaluated_at) AS ts FROM shadow_predictions WHERE outcome_evaluated_at IS NOT NULL`).get();
    const overall = DB.db.prepare(`SELECT COUNT(*) AS total,
        SUM(CASE WHEN actual_outcome IS NOT NULL AND is_correct != -1 THEN 1 ELSE 0 END) AS evaluated,
        SUM(CASE WHEN is_correct = -1 THEN 1 ELSE 0 END) AS not_evaluable
      FROM shadow_predictions`).get();
    res.json({
      ok: true,
      hours,
      perModel: rows.map(r => ({
        model: r.model_name, total: r.total, evaluated: r.evaluated,
        correct: r.correct, not_evaluable: r.not_evaluable,
        accuracy: r.evaluated > 0 ? +(r.correct / r.evaluated).toFixed(4) : null,
      })),
      overall,
      lastEvalTs: lastEval ? lastEval.ts : null,
      lastEvalLocal: lastEval && lastEval.ts ? new Date(lastEval.ts).toLocaleString('de-DE') : null,
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

