app.get('/api/aladdin/sentiment', async (req,res) => {
  // FIX 18 [26.05.2026]: NewsSentiment.fetch returnt KEINE 'items' property mehr (alte CryptoPanic-API tot).
  // Neue Pipeline liest aus news_feed-DB + liefert {riskScore, signal:'HIGH_RISK/NORMAL', alerts, intelScore, ...}
  // Endpoint mapped Aggregat-Score zu BUY/SELL/NEUTRAL für Brain-Konsum (Contrarian: news-risk = SELL bias).
  try {
    const news = await NewsSentiment.fetch().catch(() => null);
    if (!news) {
      res.json({ score: 0, signal: 'NEUTRAL', count: 0, news: [] });
      return;
    }
    const riskScore = Number(news.riskScore || 30);
    const postCount = Number(news.postCount || 0);
    const intelScore = Number(news.intelScore || 0); // -1..+1 (negative = bearish, positive = bullish)
    let signal = 'NEUTRAL';
    let score = 0;
    if (postCount < 5) {
      // Zu wenig Sample → NEUTRAL
      signal = 'NEUTRAL'; score = 0;
    } else if (intelScore <= -0.05) {
      signal = 'SELL'; score = Math.min(0.85, Math.abs(intelScore) * 8);
    } else if (intelScore >= 0.05) {
      signal = 'BUY';  score = Math.min(0.85, intelScore * 8);
    } else if (riskScore >= 75) {
      signal = 'SELL'; score = 0.60;
    } else if (riskScore >= 55) {
      signal = 'SELL'; score = 0.35;
    } else if (riskScore <= 15) {
      signal = 'BUY';  score = 0.30;
    }
    res.json({
      score, signal, count: postCount,
      riskScore, intelScore,
      news: (news.alerts || []).slice(0, 10).map(a => ({ title: a.title, source: a.source, risk: a.risk })),
    });
  } catch(e) { res.json({ error:'Verarbeitung fehlgeschlagen', details: e.message }); }
});

