          const so = DB.db.prepare("SELECT COUNT(*) n FROM trades WHERE state='POSITION_ACTIVE'").get();
          const dc = DB.db.prepare("SELECT COUNT(*) n, SUM(CASE WHEN status='CLOSED_TP' THEN 1 ELSE 0 END) w FROM dca_instances WHERE status LIKE 'CLOSED%'").get();
          const gc = DB.db.prepare("SELECT COUNT(*) n, SUM(CASE WHEN profit_acc>0 THEN 1 ELSE 0 END) w FROM grid_instances WHERE status='CLOSED'").get();
