          await this.send(`*💸 PENDING REALIZE*\nTotal: ${p.total.toFixed(2)} USDT\nDryRun: ${_MBTProfitRealizer._dry_run}\n${p.perBot ? p.perBot.map(r => r.bot_type+': '+r.total).join('\n') : ''}`);
