            const dcas = DB.db.prepare("SELECT symbol FROM dca_instances WHERE status='OPEN'").all().map(d => `${d.symbol}/DCA`).join(',');
            const grds = DB.db.prepare("SELECT symbol, bot_type FROM grid_instances WHERE status='OPEN'").all().map(g => `${g.symbol}/${g.bot_type}`).join(',');
            posStr = [sing, dcas, grds].filter(Boolean).join(' · ') || 'keine';
