// V35-COCKPIT [2026-05-13]: SHADOW-CYCLE
// Ruft alle 8s UnifiedScore + Brain + Consensus für aktive Symbole
// OHNE einen Trade zu öffnen. Nur für Live-Beobachtung im Cockpit.
// Skipped wenn AutoEngine läuft (sonst Doppel-Compute).
// ═════════════════════════════════════════════════════════════════════════════
const ShadowCycle = {
  enabled: true,
  intervalMs: 8000,
  timer: null,
  // Block H STEP 2 [26.05.2026]: Symbol-Expansion 7→12 für ML/HRP-Diversität.
  // Auswahl: alle Bitget-listed mit ≥1M USDT 24h-Volumen (Verifiziert via api.bitget.com).
  // RAUS: ATOMUSDT (270K vol — niedrigstes der alten Liste, plus Cosmos-Cluster mit NEAR doppelt).
  // NEU:  XRP DOGE ADA LINK TON AVAX — Diversifikation in Payment / Retail / DeFi / Oracle / Ecosystem / Subnet.
  symbols: ['BTCUSDT','ETHUSDT','SOLUSDT','BNBUSDT','NEARUSDT','SUIUSDT','XRPUSDT','DOGEUSDT','ADAUSDT','LINKUSDT','TONUSDT','AVAXUSDT'],
  busy: false,
  totalCycles: 0,

  start() {
    if (this.timer) return;
    this.timer = setInterval(() => this._tick(), this.intervalMs);
    Log.boot('ShadowCycle gestartet (alle ' + (this.intervalMs/1000) + 's, ' + this.symbols.length + ' Symbole)');
  },
  stop() {
    if (this.timer) { clearInterval(this.timer); this.timer = null; }
  },
  async _tick() {
    if (!this.enabled || this.busy) return;
    try { if (typeof AutoEngine !== 'undefined' && AutoEngine.enabled) return; } catch(_){}
    this.busy = true;
    try {
      for (const symbol of this.symbols) {
        try {
          const candles = await Bitget.fetchCandles(symbol, '1h', 100).catch(()=>null);
          if (!candles || candles.length < 30) continue;
          // Block N Abschnitt 1 [27.05.2026]: CUSUM Event-Driven Sampling.
          // Brain entscheidet nur bei signifikanten Markt-Events (h = 2σ pro Coin).
          // Bei kein-Event: skip Brain-Compute (Compute-Reduktion -80%).
          if (typeof _CUSUM !== 'undefined' && _CUSUM && CFG.CUSUM_FILTER_ENABLED) {
            const lastPrice = Number(candles[candles.length-1].close);
            const lastTs = Number(candles[candles.length-1].ts);
            // Auto-Kalibrierung beim ersten Symbol-tick
            const st = _CUSUM.snapshot(symbol);
            if (!st || st.totalTicks === 0) {
              const closes = candles.map(c => Number(c.close));
              const h = _CUSUM.calibrateThreshold(closes);
              _CUSUM.initSymbol(symbol, h);
              try { Log.info('CUSUM', `${symbol} init threshold=${(h*100).toFixed(3)}%`); } catch(_){}
            }
            const cur = _CUSUM.update(symbol, lastPrice, lastTs);
            if (!cur.event) {
              // Kein Event → skip Brain-Decide für diesen Symbol (Compute spar)
              continue;
            }
          }
          const orderbook = await Bitget.fetchOrderbook(symbol).catch(()=>null);
          const uScore = await UnifiedScore.compute(symbol, candles, orderbook).catch(()=>null);
          if (!uScore) continue;
          let brainResult = null;
          try { brainResult = await AladdinBrain.decide(symbol, candles, orderbook, uScore); } catch(_){}
          const hs = HardStops.check(symbol, uScore);
          const decision = ConsensusEngine.decide({
            symbol, hardstop: hs, brainResult, unifiedResult: uScore,
            aladdinDecisionId: brainResult && brainResult._dbId,
          });
          BrainStream.broadcast({
            type: 'decision',
            ts: Date.now(),
            symbol,
            hardstop: hs,
            brain: brainResult ? {
              decision: brainResult.decision,
              confidence: brainResult.confidence,
              families: brainResult.families,
              consensus: brainResult.consensus,
              vetos: brainResult.vetos,
            } : null,
            unified: {
              direction: uScore.direction,
              confidence: uScore.confidence,
              unifiedScore: uScore.unifiedScore,
              sourcesUsed: uScore.sourcesUsed,
            },
            regime: (typeof Regime !== 'undefined') ? { regime: Regime.regime, confidence: Regime.confidence } : null,
            consensus: decision,
            mode: (CFG && CFG.BRAIN_MODE) || 'shadow',
          });
          this.totalCycles++;
        } catch(e) {
          try { Log.warn('ShadowCycle', symbol + ' fail: ' + e.message); } catch(_){}
        }
        await new Promise(r => setTimeout(r, 80));
      }
    } finally {
      this.busy = false;
    }
    // UI Pipeline C [16.05.2026]: Position-Snapshot inkl. bot_type/strategy via WS broadcasten
    try { this._broadcastPositions(); } catch(_) {}
  },
  // UI Pipeline C [16.05.2026]: Broadcaster für position_snapshot (alle 8s mit Shadow-Cycle)
  _broadcastPositions() {
    if (!BrainStream.wss || BrainStream.clients.size === 0) return;
    // Sammele aktive Positionen (SINGLE + GRID + INFGRID + DCA) — gleiche Quellen wie /api/positions/active
    const items = [];
    try {
      for (const [id, pos] of Object.entries(DemoEngine.positions || {})) {
        let botType = 'SINGLE', strategyName = 'UNIFIED';
        if (pos.dbTradeId) {
          try {
            const row = DB.db.prepare('SELECT bot_type, strategy FROM trades WHERE id=?').get(pos.dbTradeId);
            if (row) {
              botType = row.bot_type || 'SINGLE';
              if (row.strategy) {
                const parts = row.strategy.replace(/^DEMO_/, '').split('_');
                if (parts.length >= 2 && ['SINGLE','GRID','DCA','INFGRID','CONSERVATIVE'].includes(parts[0])) {
                  botType = botType || parts[0];
                  strategyName = parts.slice(1).join('_');
                } else {
                  strategyName = row.strategy.replace(/^DEMO_/, '');
                }
              }
            }
          } catch(_) {}
        }
        items.push({ id, symbol: pos.symbol, bot_type: botType, strategy_name: strategyName, type_kind: 'TRADE' });
      }
    } catch(_) {}
    try {
      const grids = DB.listGridsOpen.all(50);
      for (const g of grids) items.push({ id: g.grid_id, symbol: g.symbol, bot_type: g.bot_type, strategy_name: 'GRID_TRADE', type_kind: g.bot_type });
    } catch(_) {}
    try {
      const dcas = DB.listDcaOpen.all(50);
      for (const d of dcas) items.push({ id: d.dca_id, symbol: d.symbol, bot_type: 'DCA', strategy_name: 'DCA_ACCUMULATE', type_kind: 'DCA' });
    } catch(_) {}
    BrainStream.broadcast({
      type: 'positions_snapshot',
      ts: Date.now(),
      total: items.length,
      by_type: items.reduce((acc, it) => { acc[it.bot_type] = (acc[it.bot_type] || 0) + 1; return acc; }, {}),
      items,
    });
  },
  snapshot() {
    return {
      enabled: this.enabled,
      intervalMs: this.intervalMs,
      symbols: this.symbols,
      totalCycles: this.totalCycles,
      busy: this.busy,
      clients: BrainStream.clients.size,
    };
  },
};

