              Log.info('HMM', `state=${reg.state} conf=${reg.confidence.toFixed(3)} obs=ret:${obs.log_return_24h.toFixed(3)} vol:${obs.volatility_atr_pct.toFixed(3)} dd:${obs.drawdown_pct.toFixed(3)}${bfStr}`);
