// ===== P3_CHECKPOINT_OWNER ===== Bot ist alleiniger Checkpointer (P3)
(() => {
  if (typeof DB === 'undefined' || !DB.db) return;
  try { DB.db.pragma('busy_timeout = 10000'); } catch (_) {}
  try { DB.db.pragma('wal_autocheckpoint = 0'); } catch (_) {}
  if (globalThis._botPaused === undefined) globalThis._botPaused = false;
  try { const _bt=DB.db.pragma('busy_timeout',{simple:true}); const _ac=DB.db.pragma('wal_autocheckpoint',{simple:true}); DB.insertLog && DB.insertLog.run(Date.now(),'INFO','checkpoint_owner','P3.1 runtime pragmas busy_timeout='+_bt+' wal_autocheckpoint='+_ac,''); } catch(_){}
  const fs = require('fs'); const path = require('path');
  const WAL = path.join(__dirname, 'nexus.db-wal');
  const MB = 1024 * 1024, WARN = 64 * MB, HIGH = 256 * MB;
  const log = (lvl, msg) => { try { DB.insertLog && DB.insertLog.run(Date.now(), lvl, 'checkpoint_owner', msg, ''); } catch (_) {} };
  const t = setInterval(() => {
    try {
      let sz = 0; try { sz = fs.statSync(WAL).size; } catch (_) {}
      try { DB.db.pragma('wal_checkpoint(PASSIVE)'); } catch (_) {}
      if (sz > HIGH) { if (globalThis._botPaused) { try { DB.db.pragma('wal_checkpoint(RESTART)'); } catch (_) {} } else log('WARN', 'WAL ' + ((sz/MB)|0) + 'MB > HIGH ohne Pause — INCIDENT'); }
      else if (sz > WARN) log('INFO', 'WAL ' + ((sz/MB)|0) + 'MB');
    } catch (_) {}
  }, 30000);
  if (t.unref) t.unref();
})();
